// Content for Equal Partners (node g55, ages 22+, Chapter 7): NEW v2 build to GDD 55 (mechanic-embodying), the
// EQUAL-HOME heart of Chapter 7: the most unequal place in most lives is the home. 84 researched, India-grounded
// scenarios across see-the-load → helping-vs-owning → share-it-fairly → two-careers → keep-it-equal →
// tools-and-help, each encoded as one of the shared v2 play actions (branch / strike-rewrite / sort / reflect /
// role-play / match / spot): no binary "tap the right card". Lead: branch (your move), strike-rewrite (bust the
// myth), role-play (say it). The signature move reframes a man's role from "helping" to OWNING an equal share
// the planning and remembering (the invisible mental load), not just the handed-out chores. Five+ themes: see the
// whole load (surface the invisible mental & care work), helping vs owning (the core reframe), share it fairly
// (an explicit, fair split of chores, care & money-time), two careers (dual-career fairness; whose job "flexes"
// shouldn't default to gender), keep it equal (renegotiate as life changes), tools/help. Everyone gains: an equal
// home is happier and healthier for both. Even-handed, engages men as equal OWNERS, never anti-men, and never
// shames any current arrangement; where inequality becomes coercive control it is named as abuse and routed to
// Respect at Home (g56) and help (181, 1091, 112). Builds on Equalize (g26); sets up Equal Parents (g62). India
// has one of the world's largest unpaid-care gaps: women do ~2.6× more unpaid care than men even in dual-income
// homes: and in-laws / joint families often reinforce gendered expectations. gameId "equal-partners".
import type { V2GameConfig, Scenario } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  {"id":"ep-001","cat":"see-the-load","type":"strike-rewrite","hook":"\"The mental load isn't real work.\"","myth":{"un":"The mental load isn't real work.","re":"Planning, remembering, anticipating and keeping track is real, exhausting cognitive labour.","why":"Invisible work is still work, and it tires you out."},"relearn":"The mental load, planning and remembering, is real, exhausting cognitive labour.","persona":"Pooja","source":"mental load is real"},
  {"id":"ep-002","cat":"see-the-load","type":"sort","hook":"Sort: a visible chore, or the invisible mental load?","items":[{"id":"a","text":"Washing the dishes"},{"id":"b","text":"Remembering everyone's appointments"},{"id":"c","text":"Cooking dinner"},{"id":"d","text":"Noticing the milk's running out"},{"id":"e","text":"Sweeping the floor"},{"id":"f","text":"Keeping track of when school fees are due"}],"bins":[{"id":"visible","label":"Visible chore","valence":"neutral"},{"id":"mental","label":"Mental load","valence":"uhoh"}],"key":{"a":"visible","b":"mental","c":"visible","d":"mental","e":"visible","f":"mental"},"relearn":"Dishes, cooking and sweeping are visible chores; remembering dates and noticing needs is the invisible mental load.","persona":"any","source":"visible vs invisible"},
  {"id":"ep-003","cat":"see-the-load","type":"spot","hook":"Spot the two mental-load tasks hiding behind 'simple' chores.","scene":[{"id":"a","text":"Knowing what groceries are needed and when","trick":true},{"id":"b","text":"Physically carrying the bags home","trick":false},{"id":"c","text":"Tracking which bills are due this month","trick":true},{"id":"d","text":"Chopping the vegetables for dinner","trick":false},{"id":"e","text":"Wiping down the kitchen counter","trick":false}],"why":"Knowing what's needed and tracking bills is the invisible mental load; carrying bags, chopping and wiping are the visible parts.","relearn":"Knowing what's needed and tracking it is the mental load behind 'simple' chores.","persona":"any","source":"hidden load"},
  {"id":"ep-004","cat":"see-the-load","type":"strike-rewrite","hook":"\"We split the chores 50/50, so our home is equal.\"","myth":{"un":"We split the chores 50/50, so we're equal.","re":"Visible chores are only part of it; the invisible mental load has to be shared too.","why":"You can split tasks and still leave all the managing to one person."},"relearn":"Splitting visible chores isn't enough; the invisible mental load must be shared too.","persona":"any","source":"chores aren't the whole load"},
  {"id":"ep-005","cat":"see-the-load","type":"sort","hook":"Sort: an unseen load on one person, or genuinely shared?","items":[{"id":"a","text":"One person plans every meal and list"},{"id":"b","text":"Both notice what the home needs"},{"id":"c","text":"One person remembers all the dates"},{"id":"d","text":"Both track the bills together"},{"id":"e","text":"One person holds the whole calendar"},{"id":"f","text":"Both anticipate what's running low"}],"bins":[{"id":"unseen","label":"Unseen load on one","valence":"uhoh"},{"id":"shared","label":"Genuinely shared","valence":"pos"}],"key":{"a":"unseen","b":"shared","c":"unseen","d":"shared","e":"unseen","f":"shared"},"relearn":"One person planning, remembering and holding the calendar is an unseen load; both noticing and tracking is shared.","persona":"any","source":"who carries it"},
  {"id":"ep-006","cat":"see-the-load","type":"strike-rewrite","hook":"\"Housework and childcare are naturally the woman's job.\"","myth":{"un":"Housework and childcare are naturally the woman's job.","re":"They're shared work; nothing about them is 'naturally' gendered.","why":"Capability at home has nothing to do with gender."},"relearn":"Housework and childcare are shared work, not 'naturally' the woman's job.","persona":"any","source":"not naturally gendered"},
  {"id":"ep-007","cat":"see-the-load","type":"branch","persona":"Karthik","source":"learning to see it","hook":"Pooja's been up late most nights this month, ticking through a list on her phone.","steps":[{"prompt":"It's a quiet Sunday, and you sense she's carrying more than you realised. What do you do?","options":[{"text":"Ask her to walk you through everything she tracks in a day","then":"She lists things you'd never noticed, from extended-family calls to festival planning.","best":true},{"text":"Offer to do more chores this week","then":"You do more chores, but the planning and remembering stay entirely with her."},{"text":"Decide it's balanced since you do your bit already","then":"Pooja says nothing, but the gap between your bit and her load stays invisible to you."},{"text":"Ask your mother if this sounds normal for a household","then":"Your mother says it's normal, and you learn nothing about your own home."}],"why":"Asking her to walk you through it is the only way to actually see the invisible load."},{"prompt":"A week later, Pooja skips lunch, buried in errands. What do you do?","options":[{"text":"Write down everything she's holding, together","then":"The list runs to two pages, and now both of you can see all of it.","best":true},{"text":"Remind her to eat lunch tomorrow","then":"She smiles, but the actual pile of tasks stays unwritten and invisible."},{"text":"Tell her she should manage her time better","then":"Pooja's face tightens. The problem was never her time management."},{"text":"Suggest she hire domestic help for a few hours","then":"Help might take some tasks, but you still haven't seen what it would even cover."}],"why":"Writing the full list down together turns a vague sense of overload into something you can fix."},{"prompt":"That weekend, Pooja asks what will actually change now. What do you do?","options":[{"text":"Pick two whole areas to take over completely, tracking included","then":"Pooja looks relieved. Two real things are finally off her plate.","best":true},{"text":"Say you'll help more with whatever comes up","then":"You pitch in here and there, but she's still deciding what needs doing."},{"text":"Suggest splitting everything exactly down the middle by task count","then":"Some of your tasks take five minutes; some of hers take an hour of tracking."},{"text":"Feel guilty and apologise a lot","then":"Pooja appreciates it, but nothing she's carrying actually moves."}],"why":"Owning whole areas, tracking included, is what turns seeing the load into actually sharing it."}],"debrief":"The first step to fairness is genuinely seeing the whole load, visible and invisible.","relearn":"Ask your partner to show you the full, invisible load; you can't share what you can't see."},
  {"id":"ep-008","cat":"see-the-load","type":"strike-rewrite","hook":"\"In a dual-income home, the housework must already be even.\"","myth":{"un":"In a dual-income home the housework is even.","re":"Even in dual-income homes, women typically do far more unpaid care, often around 2.6 times as much.","why":"Earning equally rarely means sharing the home equally."},"relearn":"Even in dual-income homes, women usually do far more unpaid care; it isn't automatically even.","persona":"Sneha","source":"the dual-income gap"},
  {"id":"ep-009","cat":"see-the-load","type":"spot","hook":"Spot the two signs that the load is unequal.","scene":[{"id":"a","text":"One partner has to be asked for everything","trick":true},{"id":"b","text":"Both just notice and act on their own","trick":false},{"id":"c","text":"One partner is the household 'manager'","trick":true},{"id":"d","text":"Both keep their own eye on the calendar","trick":false},{"id":"e","text":"Either one can start a chore unprompted","trick":false}],"why":"Having to be asked, and one person being the lone 'manager', signal an unequal load; both noticing and acting doesn't.","relearn":"If one partner is the 'manager' who must ask the other, the load is unequal.","persona":"any","source":"signs of imbalance"},
  {"id":"ep-010","cat":"see-the-load","type":"sort","hook":"Sort: emotional/mental labour, or a physical task?","items":[{"id":"a","text":"Worrying whether a child is okay"},{"id":"b","text":"Mopping the floor"},{"id":"c","text":"Keeping the peace with in-laws"},{"id":"d","text":"Taking out the rubbish"},{"id":"e","text":"Anticipating what relatives will need at a visit"},{"id":"f","text":"Hanging the washing to dry"}],"bins":[{"id":"mental","label":"Mental/emotional labour","valence":"uhoh"},{"id":"physical","label":"Physical task","valence":"neutral"}],"key":{"a":"mental","b":"physical","c":"mental","d":"physical","e":"mental","f":"physical"},"relearn":"Worrying about a child and anticipating relatives' needs is emotional labour; mopping and rubbish are physical tasks.","persona":"any","source":"emotional labour"},
  {"id":"ep-011","cat":"see-the-load","type":"branch","persona":"any","source":"make it visible","hook":"You've been guessing at how much Sameer actually manages at home, and you want to stop guessing.","steps":[{"prompt":"You and Sameer sit down to finally map out the home's full workload. What do you do?","options":[{"text":"List everything together, including the invisible planning","then":"The list fills two pages, half of it stuff neither of you had said out loud before.","best":true},{"text":"List only the chores you can both see","then":"The list looks short and manageable, and misses most of what's actually exhausting."},{"text":"Let Sameer make the list since he's more organised","then":"The list reflects what he notices, which isn't the same as what's really carried."},{"text":"Skip the list and just try to split things evenly by feel","then":"Neither of you can agree what evenly even means without seeing it written down."}],"why":"Listing everything together, including the invisible planning, is what makes the real load visible."},{"prompt":"A few days later, you notice jobs like booking the gas cylinder that aren't clearly either of yours. What do you do?","options":[{"text":"Ask whose job it's quietly been to remember each one","then":"You realise one of you has been silently tracking almost all of it.","best":true},{"text":"Split those jobs evenly by number","then":"The count looks fair, but some items take five minutes and others an hour of tracking."},{"text":"Leave the unclear ones for whoever notices first","then":"In practice, the same person keeps noticing first, every time."},{"text":"Decide they're too minor to bother splitting","then":"The minor items quietly stay exactly where they always were."}],"why":"Asking who's been remembering each task, not just counting tasks, shows the real imbalance."},{"prompt":"That weekend, you and Sameer sit down to divide up the home's jobs. What do you do?","options":[{"text":"Assign whole areas, including the tracking, to each of you","then":"Each of you now owns real domains, not just a pile of scattered tasks.","best":true},{"text":"Take turns picking tasks one by one","then":"It feels fair in the moment, but nobody ends up owning the remembering for anything."},{"text":"Agree to carry on as before, now that you've talked","then":"Talking felt good, but the same person keeps carrying the same load."},{"text":"Let Sameer choose first since he's better at deciding these things","then":"He picks the easier, more visible items, and the tracking-heavy ones stay unclaimed."}],"why":"Assigning whole owned areas, tracking included, is what turns a visible list into a fair split."}],"debrief":"Writing down the full load, visible and invisible, is how a couple finally sees what's really being carried.","relearn":"List everything together, including the invisible work, to see the full load."},
  {"id":"ep-012","cat":"see-the-load","type":"match","hook":"Match each kind of home work to an example.","pairs":[{"left":"Physical chore","right":"Cooking and cleaning"},{"left":"Mental load","right":"Planning and remembering"},{"left":"Emotional labour","right":"Keeping the peace, caring"},{"left":"Anticipating","right":"Noticing what will run low"},{"left":"Coordinating","right":"Lining up everyone's schedules"}],"relearn":"Chores, mental load, emotional labour, anticipating and coordinating are all real, different parts of running a home.","persona":"any","source":"kinds of work"},
  {"id":"ep-013","cat":"see-the-load","type":"reflect","hook":"Lensy: once you can see the invisible load, you can't unsee it, and you can finally share it. Powerful?","prompt":"What do you think?","options":["Yes","I see it now","Can't unsee it"],"affirm":"Seeing the invisible load is the breakthrough; you can't share fairly what you couldn't see.","relearn":"Once you see the invisible load, you can finally share it fairly.","persona":"any","source":"seeing it"},
  {"id":"ep-014","cat":"helping-vs-owning","type":"strike-rewrite","hook":"\"Helping with the chores means I'm sharing the load equally.\"","myth":{"un":"Helping with the chores means I share the load equally.","re":"'Helping' leaves your partner as the manager who notices and delegates; true equality is owning a domain.","why":"A helper waits to be told; an owner runs it."},"relearn":"'Helping' leaves your partner managing; true equality is owning a domain, not just helping.","persona":"Karthik","source":"helping vs owning"},
  {"id":"ep-015","cat":"helping-vs-owning","type":"strike-rewrite","hook":"\"If I do the task when asked, I've done my share.\"","myth":{"un":"If I do the task when asked, I've done my share.","re":"Being asked means your partner is still carrying the mental load; owning means doing it without being asked.","why":"The asking is itself the unequal work."},"relearn":"Doing a task when asked isn't equal; owning means noticing and doing it unprompted.","persona":"Karthik","source":"without being asked"},
  {"id":"ep-016","cat":"helping-vs-owning","type":"branch","persona":"Karthik","source":"own a domain","hook":"You want to genuinely take an equal share of the house, not just pitch in when asked.","steps":[{"prompt":"It's Sunday and the flat needs sorting before guests arrive tonight. What do you do?","options":[{"text":"Work out what's needed yourself, then start","then":"You have it sorted before Pooja even wakes up.","best":true},{"text":"Text Pooja to ask what she wants done first","then":"She sends the usual list, same as always."},{"text":"Wait for her to start, then jump in beside her","then":"You end up trailing her from room to room."},{"text":"Suggest ordering food so nobody has to clean","then":"The mess stays, and the guests see it tonight."}],"why":"Working it out yourself, not waiting for a list, is what owning actually looks like."},{"prompt":"That evening Pooja mentions the week ahead looks hectic. What do you do?","options":[{"text":"Ask her to walk you through what she tracks","then":"She reels off insurance renewals, warranty dates and the fridge list; you write it down.","best":true},{"text":"Tell her to relax. You'll handle whatever comes up","then":"She smiles, but doesn't quite believe it'll last."},{"text":"Say you already do plenty and deserve some credit","then":"She looks tired and lets it go, but nothing changes."},{"text":"Suggest she make a chore chart for you both","then":"She sighs; another list is one more thing for her to build."}],"why":"Asking to see the whole load, not offering to help, is how you actually learn it."},{"prompt":"A month on, your mother asks if you're still 'helping Pooja' at home. What do you say?","options":[{"text":"Say it's not helping. It's your house to run too","then":"Your mother pauses, then says your father never saw it that way.","best":true},{"text":"Say you help far more than your father ever did","then":"Your mother laughs and agrees, and 'helping' stays the word for it."},{"text":"Change the subject before it gets awkward","then":"The question just sits there, unanswered."},{"text":"Joke that Pooja trained you well","then":"Everyone laughs, and Pooja is cast as the one in charge."}],"why":"Calling it yours to run, not helping, is what makes the change real to your family."}],"debrief":"Owning whole domains, not waiting for instructions, is what actually shares the mental load.","relearn":"Own whole domains end-to-end: notice, plan, do, rather than waiting to be told."},
  {"id":"ep-017","cat":"helping-vs-owning","type":"role-play","persona":"Karthik","source":"reframing it","hook":"Your partner keeps thanking you for 'helping', and you want to reframe it.","setup":"Tonight, the laundry's folded and put away before she even asks.","steps":[{"prompt":"Pooja says: \"Thanks so much for helping with the laundry today.\"","options":[{"text":"\"This isn't me helping. It's mine to run now.\"","then":"Pooja smiles. \"Oh. Okay, that's nice to hear.\"","best":true},{"text":"\"No problem, happy to help out.\"","then":"Pooja nods. \"You're so good to me.\""},{"text":"\"It's fine. I don't mind doing it sometimes.\"","then":"Pooja says, \"Still, thank you.\""},{"text":"\"You don't have to thank me every time.\"","then":"Pooja looks unsure. \"Sorry, I didn't mean anything by it.\""}],"why":"Naming it as yours to run, not a favour, is what actually shifts how she sees it."},{"prompt":"Pooja asks: \"So should I still check if the whites need a second wash?\"","options":[{"text":"\"No need. I've got the whole thing covered now.\"","then":"Pooja pauses. \"Okay. That'll take some getting used to.\"","best":true},{"text":"\"Sure, just let me know if something looks off.\"","then":"Pooja nods. \"Okay, I'll keep an eye then.\""},{"text":"\"Just for the first month, till I get the hang of it.\"","then":"Pooja says, \"Okay. I'll keep checking for now, then.\""},{"text":"\"I'll ask you if I'm ever unsure.\"","then":"Pooja says, \"Alright, so I'm still the one with the answers.\""}],"why":"Telling her not to check anymore is what actually lifts the watching, not just the washing."},{"prompt":"Pooja's sister says: \"She's so lucky you help with the laundry.\"","options":[{"text":"\"It's not helping her. Laundry's my job too.\"","then":"The sister laughs. \"Fine. Your job, not a favour.\"","best":true},{"text":"\"Thanks. I do what I can to lighten her load.\"","then":"The sister smiles. \"Such a good husband.\""},{"text":"\"She taught me well, so she gets the credit.\"","then":"The sister laughs. \"Trained him, did you, Pooja?\""},{"text":"\"Ask Pooja. She's the laundry expert.\"","then":"The sister turns to Pooja. \"So you're still the expert, then.\""}],"why":"Calling it your job, not a favour, is what makes the ownership real outside the house too."}],"relearn":"Reframe 'helping' as owning: 'this is mine to run. You shouldn't have to manage it.'"},
  {"id":"ep-018","cat":"helping-vs-owning","type":"sort","hook":"Sort: owning a share, or just helping?","items":[{"id":"a","text":"Running the laundry without prompting"},{"id":"b","text":"Doing it only when reminded"},{"id":"c","text":"Tracking and restocking groceries yourself"},{"id":"d","text":"Waiting for a list to be handed to you"},{"id":"e","text":"Booking the car service before it's due"},{"id":"f","text":"Driving only where she's planned to go"}],"bins":[{"id":"owns","label":"Owning","valence":"pos"},{"id":"helps","label":"Just helping","valence":"uhoh"}],"key":{"a":"owns","b":"helps","c":"owns","d":"helps","e":"owns","f":"helps"},"relearn":"Running and tracking things yourself is owning; doing them only when reminded is just helping.","persona":"any","source":"owning vs helping"},
  {"id":"ep-019","cat":"helping-vs-owning","type":"branch","persona":"any","source":"remove the reminding","hook":"You realise Divya still has to remind you about your own share of the household tasks.","steps":[{"prompt":"She texts asking if you remembered the electricity bill again. What do you do?","options":[{"text":"Build your own system to track due dates","then":"You stop needing her nudge, and she notices the silence.","best":true},{"text":"Say sorry, and pay it right now","then":"You pay it, but she'll likely have to remind you again next month."},{"text":"Ask her to just keep sending reminders","then":"The reminding becomes a fixed part of her week."},{"text":"Tell her you had it under control anyway","then":"The bill gets paid late, and she's the one who notices."}],"why":"Building your own tracking system removes the need for her to remember for you."},{"prompt":"A week later, she brings up the bill reminders again. What do you do?","options":[{"text":"Ask what else she still tracks for you","then":"She lists insurance, rent, and three subscriptions you didn't know existed.","best":true},{"text":"Say the bill's paid now, so there's nothing to worry about","then":"She drops it, and still sets her own reminder for next month."},{"text":"Promise to keep improving on your own","then":"Nothing changes about what's actually on her list."},{"text":"Suggest she trust you completely from now on","then":"She wants to, but old habits of checking are hard to drop."}],"why":"Asking what she still tracks is the only way to actually take all of it off her plate."},{"prompt":"Months later, Divya mentions she still keeps a backup note of every due date. What do you do?","options":[{"text":"Ask her to hand the note over, and take those dates on","then":"She hesitates, then forwards it and deletes her copy.","best":true},{"text":"Tell her to keep it, just in case you slip","then":"She keeps it, and checks it every month before you do."},{"text":"Copy her dates into your phone and leave her note as is","then":"Your alarms work, and every new date still reaches her note first."},{"text":"Tell her it's time she trusted you with this","then":"She says she'll try, and keeps the note anyway."}],"why":"Taking over the master list, not just the reminders, is what ends her remembering for you."}],"debrief":"If your partner still has to remind you, you've taken the task but not the mental load; own the remembering too.","relearn":"Take over the remembering, not just the doing; the reminding is part of the load."},
  {"id":"ep-020","cat":"helping-vs-owning","type":"strike-rewrite","hook":"\"Asking him to remember things is just nagging.\"","myth":{"un":"Asking him to remember things is nagging.","re":"The need to remind is itself the unequal mental load; owning removes the need to remind.","why":"It's not nagging if he simply owned it."},"relearn":"The need to remind is the unequal mental load; owning removes it, it's not nagging.","persona":"Pooja","source":"not nagging"},
  {"id":"ep-021","cat":"helping-vs-owning","type":"role-play","persona":"Karthik","source":"taking it over","hook":"You want to offer to fully own a part of the home, not just help.","setup":"Pooja mentions she's behind on groceries again this week.","steps":[{"prompt":"Pooja says: \"I still haven't figured out dinner for tomorrow.\"","options":[{"text":"\"Let me take groceries and dinner planning fully.\"","then":"Pooja looks surprised. \"Really? The whole thing?\"","best":true},{"text":"\"Tell me what to get and I'll pick it up.\"","then":"Pooja says, \"Okay, give me a second to make a list.\""},{"text":"\"We'll figure dinner out together tonight.\"","then":"Pooja says, \"Sure, but I'll still plan the rest of the week.\""},{"text":"\"Order something. That solves tomorrow's dinner, at least.\"","then":"Pooja shrugs. \"That's tomorrow sorted, not the rest of it.\""}],"why":"Offering to take the whole domain, not just tonight's dinner, is what actually lifts the load."},{"prompt":"The next day, Pooja says: \"The groceries for the rest of the week still need sorting.\"","options":[{"text":"\"Walk me through it once. Then it's mine for good.\"","then":"Pooja relaxes. \"Okay, let's do that this weekend.\"","best":true},{"text":"\"I'll figure it out as I go.\"","then":"Pooja hesitates. \"I might have to double check for a while, then.\""},{"text":"\"You keep the list going. It's easier that way.\"","then":"Pooja says, \"So I'm still the one who knows what we need.\""},{"text":"\"I'll just buy whatever looks useful.\"","then":"Pooja laughs. \"That's going to be an interesting week.\""}],"why":"Asking her to walk you through it once is how the domain becomes truly yours, not a guess."},{"prompt":"A month later, Pooja says: \"My grocery list is still on my phone. Do we keep it there?\"","options":[{"text":"\"Send it to me once. After that I'll run it.\"","then":"Pooja hesitates. \"Okay. I'll delete mine after, then.\"","best":true},{"text":"\"Keep a copy in case I forget something.\"","then":"Pooja nods. \"So I'm still the backup list.\""},{"text":"\"If it helps you feel calmer, go ahead.\"","then":"Pooja smiles. \"It does. But then I'm tracking it again.\""},{"text":"\"Honestly, you'd probably keep it better than me.\"","then":"Pooja frowns. \"So it's still mine to keep, then?\""}],"why":"Taking her list once and running it yourself is what lets her stop holding it just in case."}],"relearn":"Offer to fully own a domain so your partner doesn't have to think about it at all."},
  {"id":"ep-022","cat":"helping-vs-owning","type":"branch","persona":"Karthik","source":"good guy who helps","hook":"You're the 'good guy who helps' at home, but Pooja still seems exhausted every evening.","steps":[{"prompt":"She comes home and sinks into the sofa without a word. What do you do?","options":[{"text":"Ask her to show you everything she's carrying today","then":"She lists three things you didn't even know were happening.","best":true},{"text":"Remind her how much you already helped with today","then":"She nods, too tired to explain what you're still missing."},{"text":"Make her tea and let her rest, without asking anything","then":"It's kind, but tomorrow looks exactly the same."},{"text":"Suggest she's overreacting to a normal day","then":"She goes quiet, and the evening ends flat."}],"why":"Asking what she's carrying, not listing your help, is what actually finds the real load."},{"prompt":"That Saturday, you watch a full day at home unfold, task by task. What do you do?","options":[{"text":"Take full ownership of two of those areas tonight","then":"She visibly relaxes, and one worry actually leaves her head.","best":true},{"text":"Say you'll help with those when she needs it","then":"She nods, already mentally re-adding herself to the list."},{"text":"Tell her you didn't realise, and feel bad about it","then":"She shrugs it off, still holding the same list alone."},{"text":"Suggest hiring more help around the house","then":"More help arrives, but she's still the one managing it."}],"why":"Taking full ownership of real areas, not just sympathy, is what lightens her actual load."},{"prompt":"Two weeks later, she's up past midnight finishing the week's to-do list. What do you do?","options":[{"text":"Ask which parts of that list could be yours to run","then":"She hands you the bills and the groceries. \"Those. All of it.\"","best":true},{"text":"Tell her to leave it and come to bed","then":"She comes to bed, and finishes the list at six the next morning."},{"text":"Offer to do a few items off it tomorrow","then":"She ticks a few for you, and the list is still hers to write."},{"text":"Point out how much you've already done this week","then":"She says she knows, and keeps writing."}],"why":"Asking which parts you can run, not just easing her night, is what moves real load off her."}],"debrief":"A partner exhausted despite your 'help' means the mental load is still entirely theirs; own domains to fix it.","relearn":"If your partner's still exhausted, helping isn't enough; own real domains."},
  {"id":"ep-023","cat":"helping-vs-owning","type":"reflect","hook":"Lensy: the real shift is from 'how can I help you?' to 'this is simply mine'. Feel the difference?","prompt":"What do you think?","options":["Yes","Mine to own","Big difference"],"affirm":"'This is mine' instead of 'how can I help?' is the whole shift that actually shares the load.","relearn":"The shift is from 'how can I help?' to 'this is mine to own'.","persona":"any","source":"the shift"},
  {"id":"ep-024","cat":"helping-vs-owning","type":"sort","hook":"Sort: lifts your partner's mental load, or leaves it on them?","items":[{"id":"a","text":"Owning a task start to finish"},{"id":"b","text":"Asking 'what should I do?'"},{"id":"c","text":"Remembering it yourself"},{"id":"d","text":"Needing constant reminders"},{"id":"e","text":"Noticing what's needed unprompted"},{"id":"f","text":"Waiting to be handed a list"}],"bins":[{"id":"lifts","label":"Lifts the load","valence":"pos"},{"id":"leaves","label":"Leaves it on them","valence":"uhoh"}],"key":{"a":"lifts","b":"leaves","c":"lifts","d":"leaves","e":"lifts","f":"leaves"},"relearn":"Owning start-to-finish and remembering it yourself lifts the load; asking what to do and needing reminders leaves it.","persona":"any","source":"lift the load"},
  {"id":"ep-025","cat":"share-it-fairly","type":"branch","persona":"any","source":"explicit split","hook":"You and Aditya keep almost having this conversation and never quite finishing it.","steps":[{"prompt":"You and Aditya want to finally divide the home load fairly. What do you do?","options":[{"text":"Sit down and agree an explicit, owned split","then":"You leave the table with a clear list, not just a feeling.","best":true},{"text":"Trust it'll balance out naturally over time","then":"Nothing gets assigned, and the jobs quietly keep settling on one of you."},{"text":"Let it fall where it always has","then":"The same old pattern continues, now with your explicit blessing."},{"text":"Ask a friend how their household splits things","then":"Their split tells you nothing about what actually works for you two."}],"why":"An explicit, agreed split replaces guesswork with something you can both point back to."},{"prompt":"A few days later, you notice jobs like the purifier service have no clear owner. What do you do?","options":[{"text":"Assign each unclaimed task to one of you, clearly","then":"By the end, every one of those jobs has a named owner.","best":true},{"text":"Agree you'll both keep an eye on those","then":"Both keeping an eye usually means neither of you actually does."},{"text":"Leave them for whoever has time that week","then":"Some weeks, nobody has time, and the task just doesn't happen."},{"text":"Decide they're too small to bother assigning","then":"The small tasks quietly pile up on whoever always ends up doing them."}],"why":"Giving every task a clear owner is what makes the split actually explicit, not just mostly done."},{"prompt":"A week later, Aditya asks if the way you've divided things is actually working. What do you do?","options":[{"text":"Check honestly, and adjust anything that's already slipping","then":"You catch one task drifting back and fix it before it becomes a habit.","best":true},{"text":"Say it feels fine without really checking","then":"It sounds reassuring, but you haven't actually looked closely."},{"text":"Say it's his job to notice if something's off","then":"It quietly puts the checking itself back on just one person."},{"text":"Avoid the question since it might start an argument","then":"The one slipping task keeps slipping, unnamed."}],"why":"Actually checking, honestly, is what keeps an agreed split from quietly drifting apart."},{"prompt":"A month in, a friend asks how you and Aditya decide who does what at home. What do you do?","options":[{"text":"Say which jobs have a named owner, and which don't yet","then":"Your friend admits they've never named owners at all, and wants to try.","best":true},{"text":"Say you've both just got much better at communicating lately","then":"It sounds nice, but it doesn't explain how anything actually gets decided."},{"text":"Say Aditya finally stepped up","then":"It makes fairness sound like his favour, not something you two agree."},{"text":"Say it all just works itself out between you","then":"Your friend nods, and neither of you learns how it's actually done."}],"why":"Being honest about what's clearly owned, and what isn't yet, keeps the focus on agreeing it."}],"debrief":"Fairness comes from an explicit, agreed division, not from unspoken defaults.","relearn":"Make an explicit, agreed split of owned domains, not an assumed one."},
  {"id":"ep-026","cat":"share-it-fairly","type":"sort","hook":"Sort: a fair way to divide the load, or an unfair default?","items":[{"id":"a","text":"Dividing by owned domains, agreed together"},{"id":"b","text":"Whatever the woman 'naturally' picks up"},{"id":"c","text":"Accounting for paid and unpaid hours"},{"id":"d","text":"Whoever earns less does it all"},{"id":"e","text":"Splitting the planning, not just chores"},{"id":"f","text":"Leaving the managing to one person"}],"bins":[{"id":"fair","label":"Fair","valence":"pos"},{"id":"unfair","label":"Unfair default","valence":"neg"}],"key":{"a":"fair","b":"unfair","c":"fair","d":"unfair","e":"fair","f":"unfair"},"relearn":"Agreed owned domains, counting all hours and splitting the planning is fair; defaulting to the woman, the lower-earner or one manager isn't.","persona":"any","source":"fair vs default"},
  {"id":"ep-027","cat":"share-it-fairly","type":"role-play","persona":"any","source":"opening the talk","hook":"The home's chores and planning have quietly become mostly yours to track.","setup":"Tonight, Rohan settles onto the couch beside you.","steps":[{"prompt":"Rohan asks: \"You look tired. What's up?\"","options":[{"text":"\"I want to split things fairly, including the invisible stuff.\"","then":"Rohan puts his phone down. \"Okay, let's actually do that.\"","best":true},{"text":"\"I'm just tired from the week, nothing you need to worry about tonight.\"","then":"He nods and lets it go. Nothing changes."},{"text":"\"You never notice how much I'm doing.\"","then":"Rohan looks stung. \"That's not fair. I do plenty.\""},{"text":"\"It's nothing. I'll manage like always.\"","then":"He shrugs, relieved, and the evening moves on."}],"why":"Naming the plan directly opens the real conversation, instead of hinting at it."},{"prompt":"A few days later, you're both scrambling before guests arrive because nothing got planned. Rohan asks: \"What would actually help here?\"","options":[{"text":"\"The planning and remembering, not just the visible chores.\"","then":"\"Oh. I hadn't thought about that part,\" he says, thinking it over.","best":true},{"text":"\"Just help more whenever you notice something needs doing.\"","then":"\"Sure,\" he says, and waits to be asked, like before."},{"text":"\"Forget it. It's not worth explaining.\"","then":"He shrugs and the conversation drops again."},{"text":"\"You should just notice it yourself.\"","then":"\"How, if you don't tell me?\" he asks, a little defensive."}],"why":"Naming the mental load itself, not just the tasks, is what he needs to hear."},{"prompt":"That weekend, another thing slips through the cracks. Rohan asks: \"Okay, so what do we actually do about this?\"","options":[{"text":"\"Let's map out everything, visible and invisible, together.\"","then":"\"Deal,\" he says. \"Let's do it this weekend.\"","best":true},{"text":"\"I'll keep holding the list, and just tell you what's needed.\"","then":"\"Sure,\" he says, still leaving you as the one who has to ask."},{"text":"\"Whatever feels fair to you is fine.\"","then":"He looks unsure. \"I don't actually know what that is.\""},{"text":"\"I'll think about it and get back to you.\"","then":"The conversation stalls again, half finished."}],"why":"Mapping it together, right now, turns the talk into an actual plan."}],"relearn":"Open the fair-split conversation, including the invisible work."},
  {"id":"ep-028","cat":"share-it-fairly","type":"branch","persona":"any","source":"split the invisible too","hook":"Naveen proudly showed his cousin your chore chart last week.","steps":[{"prompt":"Your chores look evenly split with Naveen, but you're holding all the planning. What do you do?","options":[{"text":"Ask to reassign some of the planning and remembering too","then":"Naveen looks a little surprised. \"I hadn't thought of that as separate.\"","best":true},{"text":"Call it even since the chores are split","then":"It's technically true, and it leaves the actual exhausting part entirely with you."},{"text":"Quietly resent it instead of raising it","then":"Nothing changes, and the resentment just keeps building."},{"text":"Ask him to do a few more chores instead","then":"More chores land on him, but the planning stays with you regardless."}],"why":"Naming the planning as its own thing to split is what a fair division actually needs."},{"prompt":"A few days later, Naveen notices you seem stretched and asks what's keeping you so busy. What do you do?","options":[{"text":"Walk him through a full week of what you track","then":"By the end, he sees a list far longer than who does the dishes.","best":true},{"text":"Say it's basically remembering things","then":"It's true but vague, and doesn't really land as something he can take."},{"text":"Say he should already know if he paid attention","then":"Naveen looks defensive instead of curious."},{"text":"Say it's too much to explain right now","then":"The conversation stalls, and he's left guessing what 'busy' means."}],"why":"Showing a full week of tracking makes 'the planning' concrete enough to actually reassign."},{"prompt":"The next weekend, Naveen says he wants to take more off your plate, not just chores. What do you do?","options":[{"text":"Hand over two whole planning areas, fully","then":"He takes them on properly, tracking included, not just the doing.","best":true},{"text":"Let him pick the easiest few to start","then":"He picks the lightest ones, and the heaviest tracking stays with you."},{"text":"Keep the planning yourself since you're used to it","then":"The reassignment stalls before it's even begun."},{"text":"Split each planning item in half between you","then":"Half-owned tracking means you're both still half-remembering everything."}],"why":"Handing over whole areas, not just easy pieces, is what actually rebalances the planning."},{"prompt":"A few weeks later, Naveen asks how the planning feels on your side now. What do you do?","options":[{"text":"Go through who's tracking what now, together, item by item","then":"Between you, you spot two items still sitting only with you, and move one.","best":true},{"text":"Say it's fine, since he's clearly trying","then":"His trying is real, but nobody checks what's still sitting with you."},{"text":"Say you'd rather keep an eye on it quietly yourself","then":"Watching quietly is still you doing the tracking, just less visibly."},{"text":"Say you don't want to start another big talk about it","then":"Whatever's slipping stays unnamed, and unfixed."}],"why":"Going through who tracks what, together, catches the planning that's quietly stayed with you."}],"debrief":"A fair split must include the planning and remembering, not just the visible tasks.","relearn":"Reassign the planning and remembering too, not just the visible chores."},
  {"id":"ep-029","cat":"share-it-fairly","type":"sort","hook":"Sort: counts toward a fair share, or gets ignored?","items":[{"id":"a","text":"Hours of paid work"},{"id":"b","text":"Hours of unpaid home work"},{"id":"c","text":"The mental load carried"},{"id":"d","text":"Only the visible chores"},{"id":"e","text":"Emotional labour for the family"},{"id":"f","text":"Just whatever's noticed in passing"}],"bins":[{"id":"counts","label":"Should count","valence":"pos"},{"id":"ignored","label":"Often ignored","valence":"neg"}],"key":{"a":"counts","b":"counts","c":"counts","d":"ignored","e":"counts","f":"ignored"},"relearn":"Paid hours, unpaid hours, the mental load and emotional labour should all count; counting only visible chores ignores most of it.","persona":"any","source":"what counts"},
  {"id":"ep-030","cat":"share-it-fairly","type":"branch","persona":"any","source":"fair not identical","hook":"Imran's professional exams start next week, and the house still runs on your usual split.","steps":[{"prompt":"He'll be studying most evenings for a month. What do you do?","options":[{"text":"Adjust the split fairly for now, and agree to revisit later","then":"Imran relaxes, relieved it's temporary and named, not just assumed.","best":true},{"text":"Keep the usual split, exams or not","then":"Imran ends up cramming chores between study sessions, exhausted."},{"text":"Take on everything without saying anything","then":"You're quietly carrying double, and nobody's actually agreed to that."},{"text":"Tell him to manage his time better","then":"Imran goes quiet, and his study nights get even shorter."}],"why":"Adjusting for the season, with an agreed date to revisit, keeps it fair without being rigid."},{"prompt":"Two weeks into his exams, Imran asks how the house is going for you. What do you do?","options":[{"text":"Say honestly what's getting heavy, and tweak it together","then":"You adjust one task, and it immediately feels more sustainable.","best":true},{"text":"Say you're managing fine, no need to change anything","then":"You're not really fine. You just don't want to add to his stress."},{"text":"Say it's temporary anyway, so it doesn't matter","then":"Temporary or not, you're still carrying it right now."},{"text":"Say it can wait until his exams are over","then":"Weeks of quiet strain pile up before anyone addresses it."}],"why":"Naming what's heavy now, even mid-exams, keeps the load from quietly becoming unsustainable."},{"prompt":"Exams end, and Imran asks how you should split things now. What do you do?","options":[{"text":"Set an actual date this week to sit down and redo it","then":"You both sit down before the old habits quietly reset without discussion.","best":true},{"text":"Say you'll just ease back into it naturally","then":"Nothing's decided, and small clashes over chores start creeping in."},{"text":"Say you'd rather not make it a formal thing","then":"Weeks pass, and the old habits quietly settle back in unasked."},{"text":"Say he should decide since he asked","then":"It quietly hands the whole decision, and its timing, to just one of you."}],"why":"Setting an actual date to revisit is what turns later into something that actually happens."},{"prompt":"A few weeks later, you both notice some exam-month habits worked better than the old ones. What do you do?","options":[{"text":"Keep the parts that worked, and rebalance the rest fairly","then":"You end up with a split that fits better than the old one ever did.","best":true},{"text":"Just go straight back to exactly how it was before","then":"You lose a few changes that had actually been working well."},{"text":"Keep the exam-month split exactly as it is, permanently","then":"What suited a busy month doesn't quite suit ordinary life."},{"text":"Let it stay unclear and see what happens","then":"Without a decision, old habits and new ones both start colliding."}],"why":"Keeping what worked and rebalancing the rest shows fair isn't identical. It's what actually fits."}],"debrief":"Fair doesn't always mean identical; it flexes with each person's real capacity, and is revisited.","relearn":"Adjust the split fairly for each season, and revisit it; fair isn't always identical."},
  {"id":"ep-031","cat":"share-it-fairly","type":"role-play","persona":"Pooja","source":"renegotiating","hook":"The split you and Karthik agreed a year ago has quietly become mostly yours.","setup":"Tonight, you decide it's time to raise it.","steps":[{"prompt":"Karthik asks: \"You've seemed off lately. Everything okay?\"","options":[{"text":"\"I think our split has drifted. Can we rebalance it?\"","then":"He puts down his cup. \"Drifted how? Tell me.\"","best":true},{"text":"\"I'm just tired. It's nothing.\"","then":"He nods and goes back to his phone."},{"text":"\"You've quietly stopped doing your share of things lately, honestly.\"","then":"Karthik stiffens. \"That's not fair. I still do things.\""},{"text":"\"Forget it. I'll just keep managing it.\"","then":"He looks relieved and doesn't ask further."}],"why":"Naming the drift plainly, without blame, opens the talk without a fight."},{"prompt":"A few days later, Karthik notices bills piling up unopened. He asks: \"What's actually on your plate right now?\"","options":[{"text":"\"The groceries, the bills, the remembering. All of it.\"","then":"He looks surprised. \"I thought we were splitting the bills.\"","best":true},{"text":"\"Nothing specific, just a feeling.\"","then":"He shrugs. \"Then what should I actually change?\""},{"text":"\"You'd know exactly what's on my plate if you paid closer attention.\"","then":"\"I'm trying to,\" he says, sounding a little defensive."},{"text":"\"Never mind. It's not worth listing.\"","then":"The conversation stalls before it starts."}],"why":"A specific list gives him something real to actually pick up."},{"prompt":"A few days later, Karthik asks: \"Okay, so what do we actually do about all this?\"","options":[{"text":"\"Let's redo the split now, and check in on it monthly.\"","then":"\"Deal,\" he says, and pulls out his phone to set a reminder.","best":true},{"text":"\"Just try to remember from now on.\"","then":"He nods, but nothing about the routine actually changes."},{"text":"\"I'll tell you whenever it slips again.\"","then":"\"Sure,\" he says, leaving you the one keeping watch."},{"text":"\"It's fine as long as you actually stick to it this time.\"","then":"He agrees, but nothing is actually written down."}],"why":"A redo plus a standing check-in catches drift, instead of relying on memory or hope."}],"relearn":"Raise a drifted split without blame and rebalance it."},
  {"id":"ep-032","cat":"share-it-fairly","type":"match","hook":"Match the fairness move to what it does.","pairs":[{"left":"List everything together","right":"Makes the load visible"},{"left":"Assign owned domains","right":"Shares the mental load"},{"left":"Revisit regularly","right":"Keeps it fair over time"},{"left":"Count all the hours","right":"Counts the invisible work"},{"left":"Agree shared standards","right":"Stops hidden re-work"}],"relearn":"Listing, assigning domains, revisiting, counting hours and agreeing standards each move you toward a fair, shared home.","persona":"any","source":"fairness moves"},
  {"id":"ep-033","cat":"share-it-fairly","type":"sort","hook":"Sort: an agreement that lasts, or one that quietly fails?","items":[{"id":"a","text":"Clear, owned responsibilities"},{"id":"b","text":"Vague 'we'll both pitch in'"},{"id":"c","text":"A regular check-in"},{"id":"d","text":"Assuming it'll just work out"},{"id":"e","text":"A written-down split"},{"id":"f","text":"Whoever cares more does more"}],"bins":[{"id":"lasts","label":"Lasts","valence":"pos"},{"id":"fails","label":"Quietly fails","valence":"neg"}],"key":{"a":"lasts","b":"fails","c":"lasts","d":"fails","e":"lasts","f":"fails"},"relearn":"Clear owned responsibilities, check-ins and a written split last; vague pitching-in, assumptions and 'whoever cares more' quietly fail.","persona":"any","source":"what lasts"},
  {"id":"ep-034","cat":"share-it-fairly","type":"branch","persona":"any","source":"within the joint family","hook":"Sunday lunches at the joint family home follow rules nobody ever wrote down.","steps":[{"prompt":"Your joint family clearly expects the home tasks to fall to Aisha. What do you do?","options":[{"text":"Agree between yourselves to hold your own fair split","then":"Aisha looks relieved you're naming it together, not leaving it to her alone.","best":true},{"text":"Quietly try to help Aisha more without saying anything","then":"You pitch in, but the family's expectation of her stays exactly as it was."},{"text":"Default to what relatives expect for now","then":"The days settle back into the old pattern, unquestioned."},{"text":"Tell Aisha to push back on the relatives herself","then":"It leaves her alone to fight an expectation that's really about both of you."}],"why":"Agreeing your own split together, as a couple, is what actually holds against family defaults."},{"prompt":"At a family lunch, your aunt asks Aisha to serve while the men sit. What do you do?","options":[{"text":"Get up and serve alongside her, calmly","then":"Your aunt pauses, then makes room without another word.","best":true},{"text":"Stay seated but tell Aisha you'll make it up to her later","then":"The moment passes with her still the only one serving."},{"text":"Stay seated. It's just one lunch","then":"One lunch becomes the pattern the family expects going forward."},{"text":"Whisper to Aisha to just get it over with quickly","then":"It asks her to absorb the moment rather than sharing it."}],"why":"Getting up yourself, in the moment, is what makes the fair arrangement visible, not just agreed at home."},{"prompt":"That evening, your father says kitchen work at family lunches is for the women. What do you do?","options":[{"text":"Say calmly that you and Aisha share the home","then":"Your father looks unconvinced, but doesn't argue further.","best":true},{"text":"Laugh it off and change the subject","then":"The comment stands unanswered, and nothing's actually corrected."},{"text":"Say it's honestly not a big deal either way","then":"It sounds easygoing, and quietly lets his rule stand."},{"text":"Ask him not to bring it up in front of Aisha","then":"It manages his comfort instead of actually answering him."}],"why":"Naming it plainly as shared is what protects the arrangement, even under direct pushback."},{"prompt":"Before the next family lunch, Aisha asks if you'll back her up if it happens again. What do you do?","options":[{"text":"Say yes, and plan together what you'll each do on the day","then":"Aisha exhales, glad she won't be handling your family alone.","best":true},{"text":"Say it's probably best not to make a scene","then":"Aisha nods slowly, bracing to handle it on her own again."},{"text":"Say you'll step in only if it gets really bad","then":"Aisha isn't sure what 'really bad' means, or when you'd act."},{"text":"Say she's better at handling your relatives than you are","then":"It leaves her managing your family's expectations on her own."}],"why":"Planning it together means Aisha isn't left to face your family's expectations by herself."}],"debrief":"Couples can hold a fair arrangement together even amid traditional joint-family expectations.","relearn":"As a couple, hold your own fair arrangement within family expectations."},
  {"id":"ep-035","cat":"two-careers","type":"strike-rewrite","hook":"\"Her career is the one that should flex for the home.\"","myth":{"un":"Her career is the one that should flex for the home.","re":"Whose career flexes shouldn't default to gender; both careers count equally.","why":"His job isn't automatically more important."},"relearn":"Whose career flexes shouldn't default to gender; both careers count equally.","persona":"any","source":"whose career flexes"},
  {"id":"ep-036","cat":"two-careers","type":"strike-rewrite","hook":"\"His job is the 'real' one; hers is a backup.\"","myth":{"un":"His job is the real one; hers is a backup.","re":"Both partners' careers are real and matter; neither is automatically secondary.","why":"Treating one as a 'backup' devalues a whole person's work."},"relearn":"Both partners' careers are real and matter; neither is automatically a backup.","persona":"any","source":"both careers real"},
  {"id":"ep-037","cat":"two-careers","type":"branch","persona":"any","source":"deciding fairly","hook":"Priya's father falls ill, and someone's work will need to flex to help care for him.","steps":[{"prompt":"You both quietly assume it'll be her job that flexes. What do you do?","options":[{"text":"Stop and decide together, based on fairness","then":"You both pause and actually look at both jobs honestly.","best":true},{"text":"Let her offer to take the lead, since it's her father","then":"Priya offers before you even ask, and the default holds quietly."},{"text":"Assume your job is harder to step back from","then":"Priya nods, already expecting to be the one who flexes."},{"text":"Wait and see how busy the week gets","then":"The week gets busy, and by default, it's her time that gives."}],"why":"Deciding together, not assuming, is what actually makes the choice fair."},{"prompt":"A week in, the strain is starting to show on whoever's been flexing. What do you do?","options":[{"text":"Compare real flexibility and deadlines","then":"You realise your job actually has more room to flex right now.","best":true},{"text":"Compare who earns more money this particular year","then":"Her salary is lower, so her flexing starts to look like the cheaper choice."},{"text":"Compare whose boss seems stricter","then":"It becomes a guessing game about bosses, and real deadlines never come up."},{"text":"Skip the comparison. Gut feeling says her","then":"Her time keeps giving, and nobody has checked whether yours could."}],"why":"Weighing the real facts of both careers, not gut defaults, is what fairness needs."},{"prompt":"It's clear by now that your schedule has more room to flex than hers. What do you do?","options":[{"text":"Take the lead on caregiving yourself","then":"Priya looks relieved, and her work stays steady through the crisis.","best":true},{"text":"Split it evenly anyway, whatever the schedules show","then":"You both flex some, but what the schedules show gets set aside."},{"text":"Suggest hiring help instead of either of you flexing","then":"Help eases things, but someone still has to manage and decide."},{"text":"Let Priya decide, since it's her family","then":"Priya ends up choosing to flex anyway, out of habit."}],"why":"Following through on what the schedules actually showed is what makes the fairness real."}],"debrief":"When a career must flex, deciding fairly together beats the default assumption that it's hers.","relearn":"Decide whose work flexes together, on fairness, not by gender default."},
  {"id":"ep-038","type":"sort","persona":"any","source":"supporting both","hook":"Sort: supports both careers, or quietly sidelines one?","items":[{"id":"a","text":"Both partners' ambitions taken seriously"},{"id":"b","text":"Assuming she'll scale back"},{"id":"c","text":"Sharing the home so both can work"},{"id":"d","text":"Treating his promotion as the priority"},{"id":"e","text":"Taking turns on whose work flexes"},{"id":"f","text":"Calling her job the one to drop first"}],"bins":[{"id":"supports","label":"Supports both","valence":"pos"},{"id":"sidelines","label":"Sidelines one","valence":"neg"}],"key":{"a":"supports","b":"sidelines","c":"supports","d":"sidelines","e":"supports","f":"sidelines"},"relearn":"Taking both ambitions seriously, sharing the home and taking turns supports both careers; scaling her back, his-first and her-drops-first sideline one.","cat":"two-careers"},
  {"id":"ep-039","cat":"two-careers","type":"strike-rewrite","hook":"\"Whoever earns more shouldn't have to do home work.\"","myth":{"un":"Whoever earns more shouldn't do home work.","re":"Earning more doesn't exempt anyone from the home; the load is shared regardless of pay.","why":"Income doesn't buy you out of partnership."},"relearn":"Earning more doesn't exempt you from home work; the load is shared regardless of pay.","persona":"any","source":"earning isn't an exemption"},
  {"id":"ep-040","cat":"two-careers","type":"branch","persona":"any","source":"taking turns","hook":"Aisha's been offered a big project that means long hours for the next few months.","steps":[{"prompt":"She hesitates to say yes, worried about the home. What do you do?","options":[{"text":"Tell her to take it. Cover more at home","then":"Aisha's face lights up. \"Really? You'd do that?\"","best":true},{"text":"Say it's her call. You'll manage somehow","then":"She says yes, unsure how much support she'll actually get."},{"text":"Point out your own work is already demanding","then":"Aisha hesitates, but decides to take the project anyway."},{"text":"Suggest she ask for a smaller role instead","then":"She considers shrinking her ambition to keep the peace."}],"why":"Actively offering to step up is what makes her opportunity actually possible."},{"prompt":"The project's first big week arrives, and evenings get chaotic. What do you do?","options":[{"text":"Take over dinner and the evening","then":"Aisha comes home to a settled house and exhales properly for the first time in days.","best":true},{"text":"Wait for her to tell you what's needed","then":"She texts instructions from her desk, still managing from afar."},{"text":"Order food and hope that covers it","then":"It covers dinner, but nothing else gets handled."},{"text":"Remind her you're also tired from work","then":"Aisha feels guilty on top of exhausted."}],"why":"Owning the evening outright, not waiting for instructions, is real support."},{"prompt":"The project wraps up, and Aisha wants to know how you're both doing. What do you do?","options":[{"text":"Say you'd like a turn too","then":"\"Deal,\" she says. \"Your turn's coming. I promise.\"","best":true},{"text":"Say you're fine. Don't worry about it","then":"The idea of your own turn quietly gets shelved."},{"text":"Say the whole thing was exhausting, honestly","then":"Aisha feels a flash of guilt for taking the opportunity."},{"text":"Say nothing, and hope she offers on her own","then":"Weeks pass, and your turn never quite comes up."}],"why":"Naming your own turn keeps it a genuine back and forth, not one-sided support."}],"debrief":"Equal partners take turns supporting each other's careers, rather than one always coming first.","relearn":"Step up at home so your partner's career can grow, as they would for yours."},
  {"id":"ep-041","type":"spot","persona":"any","source":"fairness move","hook":"Spot the two lines where her career is the one always made to give way.","scene":[{"id":"a","text":"\"We take turns on whose work flexes.\"","trick":false},{"id":"b","text":"\"Hers always gives way, that's just easier.\"","trick":true},{"id":"c","text":"\"We back each other's ambitions.\"","trick":false},{"id":"d","text":"\"Her career bends; mine's the fixed one.\"","trick":true},{"id":"e","text":"\"Either of us can be the one who moves.\"","trick":false}],"why":"'Hers always gives way' and 'her career bends, mine's fixed' both make her the one to flex by default. Fair partners take turns.","relearn":"Taking turns and backing each other is fair; always making hers give way isn't.","cat":"two-careers"},
  {"id":"ep-042","cat":"two-careers","type":"reflect","hook":"Lensy: when both careers are truly valued, the home arrangement follows fairly. Agree?","prompt":"What do you think?","options":["Yes","Both valued","Follows fairly"],"affirm":"Valuing both careers equally is the foundation; a fair home arrangement flows from it.","relearn":"When both careers are truly valued equally, a fair home arrangement follows.","persona":"any","source":"both valued"},
  {"id":"ep-043","cat":"keep-it-equal","type":"branch","persona":"Nisha","source":"renegotiate at change (sets up g62)","hook":"A new baby is about to massively change the home workload you share with Vikram.","steps":[{"prompt":"A week from the due date, you haven't discussed how night-time care will split. What do you do?","options":[{"text":"Sit down now and deliberately plan the split","then":"You both leave with a rough plan, before the chaos starts.","best":true},{"text":"Assume you'll figure it out once the baby's here","then":"The due date passes, and there's still no plan in place."},{"text":"Ask your mother to stay and help for a few weeks","then":"Extra hands help, but the split between you two stays unclear."},{"text":"Wait for Vikram to bring up how he wants to split it","then":"Vikram assumes you'll say if you need him, and stays quiet."}],"why":"Planning the split deliberately, before the chaos starts, is what keeps it from defaulting to you."},{"prompt":"The baby's two weeks old, and everyone assumes you're handling the nights. What do you do?","options":[{"text":"Bring up sharing the night-time care fairly","then":"He takes his share of the night care, tired but steady.","best":true},{"text":"Just handle the nights yourself. It's easier while you're both new","then":"'Easier for now' quietly becomes the ongoing pattern."},{"text":"Wait to see if he offers on his own","then":"He doesn't offer, and the default holds without either of you naming it."},{"text":"Ask your mother to help with the harder nights","then":"Help arrives, but Vikram's nights stay untouched."}],"why":"Speaking up rather than letting default assumptions take over is what keeps it equal from the start."},{"prompt":"At six weeks, you realise you're also doing all the appointment tracking. What do you do?","options":[{"text":"Name the drift and hand him the tracking","then":"He takes it on, and the load actually rebalances.","best":true},{"text":"Keep tracking it. You're already across the details","then":"Being 'already across it' becomes the reason it stays yours."},{"text":"Mention it once and hope he picks it up","then":"He means to, but nothing actually changes."},{"text":"Decide it's not worth a conversation this early","then":"The tracking quietly becomes assumed to be yours."}],"why":"Naming the drift plainly, not hoping he notices, is what actually moves the tracking to him."},{"prompt":"At three months, you're due back at work next month. What do you do?","options":[{"text":"Redo the split with Vikram before you go back","then":"You map out mornings, nights and sick days together before your first day back.","best":true},{"text":"Assume the current routine will stretch to fit","then":"Your first week back, the routine collapses and the gaps land on you."},{"text":"Plan to cut your hours, since you're the mother","then":"Your career quietly becomes the one that flexes, without a real discussion."},{"text":"Wait for Vikram to suggest how to handle it","then":"He waits too, assuming you've already got a plan in mind."}],"why":"Redoing the split before you go back is what keeps the next change from landing on you by default."}],"debrief":"Big life changes like a baby are exactly when equality must be deliberately renegotiated.","relearn":"Renegotiate the split deliberately around big changes like a baby."},
  {"id":"ep-044","cat":"keep-it-equal","type":"strike-rewrite","hook":"\"Once we agree a split, it's sorted forever.\"","myth":{"un":"Once we agree a split, it's sorted forever.","re":"Equality is renegotiated as life changes; it's an ongoing conversation, not a one-time deal.","why":"Life keeps shifting the workload."},"relearn":"Equality is renegotiated as life changes; it's an ongoing conversation, not one-time.","persona":"any","source":"ongoing conversation"},
  {"id":"ep-045","cat":"keep-it-equal","type":"role-play","persona":"any","source":"check-ins","hook":"You want to set up regular check-ins on how the load is shared.","setup":"You bring it up with Rehan over chai on a quiet Sunday.","steps":[{"prompt":"Rehan asks: \"What made you want to talk about this now?\"","options":[{"text":"\"Nothing's wrong. I'd like us to check in monthly.\"","then":"Rehan says, \"Sure. That actually sounds useful.\"","best":true},{"text":"\"Nothing specific. Just thought it might be good.\"","then":"Rehan says, \"Okay, if you think it's needed.\""},{"text":"\"Because you never notice when things slide.\"","then":"Rehan frowns. \"I do notice. But okay, I'm listening.\""},{"text":"\"Honestly, I saw it suggested somewhere online.\"","then":"Rehan says, \"Okay, if you think it's worth trying.\""}],"why":"Proposing a clear monthly check-in, before anything's wrong, is what actually gets it started."},{"prompt":"Rehan asks: \"What would that actually involve?\"","options":[{"text":"\"Just what's felt fair and what hasn't, honestly.\"","then":"Rehan says, \"Okay, that sounds manageable.\"","best":true},{"text":"\"Whatever's annoying me that particular week.\"","then":"Rehan says, \"So it's mostly complaints, then.\""},{"text":"\"We'll figure it out when we get there.\"","then":"Rehan says, \"That sounds a bit vague to commit to.\""},{"text":"\"Mostly just the big stuff, not small things.\"","then":"Rehan says, \"So small drifts don't really count?\""}],"why":"Naming honestly what's felt fair, not just complaints, keeps the check-in useful and calm."},{"prompt":"A few weeks later, Rehan asks: \"Should we actually set a regular time for this?\"","options":[{"text":"\"Let's actually set a time, even monthly.\"","then":"Rehan nods. \"Okay, let's put it on the calendar properly.\"","best":true},{"text":"\"We can just talk when something comes up.\"","then":"Rehan says, \"So we're back to waiting for a problem.\""},{"text":"\"Let's see if we even remember to do it.\"","then":"Rehan says, \"Okay. Let's just see, I guess.\""},{"text":"\"You pick a time. You're better with the calendar.\"","then":"Rehan says, \"Okay, but then it's mine to chase each month.\""}],"why":"Setting a real time, not waiting for a problem, is what makes the habit actually reliable."}],"relearn":"Propose regular check-ins to keep the load fair and adjust drift early."},
  {"id":"ep-046","cat":"keep-it-equal","type":"branch","persona":"Pooja","source":"catching drift","hook":"Your fair split has slowly slipped back to old patterns.","steps":[{"prompt":"You notice you're the one packing the bags again, every single trip. What do you do?","options":[{"text":"Name it gently and ask to rebalance this week","then":"Karthik pauses. \"You're right. I hadn't noticed.\"","best":true},{"text":"Just keep packing. It's faster than explaining","then":"The pattern holds, unnamed, for another month."},{"text":"Drop hints about being tired of packing","then":"The hints land softly, and nothing actually changes."},{"text":"Pack half and leave the rest for him to notice","then":"He doesn't notice, and the bag stays half done."}],"why":"Naming the drift plainly, without blame, is what actually starts the rebalance."},{"prompt":"A few days later, Karthik brings it up himself and asks what exactly has slipped. What do you do?","options":[{"text":"Walk him through the specific tasks","then":"He nods slowly. \"I didn't realise it was that many.\"","best":true},{"text":"Say it's just a feeling, hard to pin down","then":"Without specifics, the conversation goes nowhere clear."},{"text":"Tell him he should just pay more attention","then":"He gets defensive instead of actually hearing it."},{"text":"Say never mind. It's not a big deal","then":"The drift stays exactly where it was."}],"why":"Naming the specific tasks, not a vague feeling, is what he can actually act on."},{"prompt":"A month later, you think about how the split's been going. What do you do?","options":[{"text":"Suggest a short monthly check on the split","then":"Karthik agrees. \"That actually makes sense to do regularly.\"","best":true},{"text":"Wait and see how the next few weeks go","then":"A few weeks pass, and the old pattern settles in without a word."},{"text":"Keep a private tally of who does what","then":"The tally grows, and so does the resentment you haven't shared."},{"text":"Say you'll raise it whenever it slips","then":"It slips during a busy week, and you're too tired to raise it."}],"why":"Suggesting a regular check-in is what stops the next drift from sneaking back unnoticed."}],"debrief":"Fairness drifts back to old patterns unless couples notice and rebalance regularly.","relearn":"Notice when the split slips back, and rebalance it without blame."},
  {"id":"ep-047","cat":"keep-it-equal","type":"reflect","hook":"Lensy: an equal home is happier, less resentful and healthier for both of you. Worth building?","prompt":"What do you think?","options":["Yes","Happier for both","Worth it"],"affirm":"Equal homes are genuinely happier and less resentful; the effort pays off for both partners.","relearn":"An equal home is happier, less resentful and healthier for both partners.","persona":"any","source":"everyone gains"},
  {"id":"ep-048","cat":"keep-it-equal","type":"reflect","hook":"Lensy: a child who grows up seeing equal parents learns it as normal. Worth modelling?","prompt":"What do you think?","options":["Yes","Model it","Normal for them"],"affirm":"Children who see equal parents grow up expecting equality; you model the future by living it.","relearn":"Children who see equal parents learn equality as normal; modelling it matters.","persona":"any","source":"modelling for kids"},
  {"id":"ep-049","cat":"keep-it-equal","type":"role-play","persona":"any","source":"noticing and offering","hook":"Divya's taken on more of the house this month, and you've noticed.","setup":"Tonight over dinner, you decide to say something.","steps":[{"prompt":"Divya says: \"I don't even know what I did today. It's all a blur.\"","options":[{"text":"\"You've been carrying more. Let me take the grocery runs.\"","then":"She looks up, surprised. \"That would really help. Thank you for noticing.\"","best":true},{"text":"\"I'll help more this weekend if you need me to.\"","then":"She shrugs. \"Maybe. I don't really know what I'd hand over.\""},{"text":"\"I've noticed, but work's mad for me too right now.\"","then":"Divya's jaw tightens. \"So it's a competition now?\""},{"text":"\"I'll get to it once my week calms down.\"","then":"She looks tired. \"That's what you said last month too.\""}],"why":"Naming it and offering something specific tells her you actually see the extra load."},{"prompt":"A few days later, Divya says: \"The internet bill's due and I keep forgetting to check it.\"","options":[{"text":"\"Send me the login. I'll own paying it from now on.\"","then":"She smiles and forwards the login right away. \"One less thing to track.\"","best":true},{"text":"\"I'll pay it. Just remind me next month.\"","then":"She nods. \"Okay, but you'll actually need reminding.\""},{"text":"\"Can't you just set an autopay reminder?\"","then":"Divya sighs. \"Setting that up is also a job, you know.\""},{"text":"\"That's such a small thing. Don't stress about it.\"","then":"She looks tired. \"It adds up though.\""}],"why":"Taking the whole bill, tracking included, means she stops having to remember it for you."},{"prompt":"The next Sunday, Divya says: \"It's been one of those weeks.\"","options":[{"text":"\"It has. Let's look at what's piled up.\"","then":"She exhales. \"Yes. Let's actually look at it.\" You reshuffle two chores that night.","best":true},{"text":"\"I know. Want me to order dinner so you don't have to cook tonight?\"","then":"She smiles a little. \"That would help tonight.\" Tomorrow's pile stays where it was."},{"text":"\"Same here. Work's been mad for me too.\"","then":"She goes quiet again, and the moment passes."},{"text":"\"You should say something if it's too much.\"","then":"Divya looks away. \"I shouldn't have to ask.\""}],"why":"Offering to look at the whole pile together, not one task, actually rebalances it."}],"relearn":"Notice when your partner's carrying more, and offer to take some back."},
  {"id":"ep-050","cat":"keep-it-equal","type":"branch","persona":"Saxena","source":"before it festers","hook":"Resentment about the unequal load is starting to hurt your relationship.","steps":[{"prompt":"You've started snapping at small things that aren't really about the small thing. What do you do?","options":[{"text":"Name the real issue directly, kindly, before it grows","then":"Your partner pauses, surprised, and asks you to say more.","best":true},{"text":"Keep snapping and hope they eventually notice why","then":"The small fights continue, and the real issue stays hidden."},{"text":"Bottle it up further to keep the peace","then":"The peace holds on the surface, and the resentment keeps building."},{"text":"Vent to a friend instead of your partner","then":"It feels better briefly, and nothing changes at home."}],"why":"Naming the real issue directly, before it grows, is what protects the relationship."},{"prompt":"Your partner asks what's actually been bothering you. What do you do?","options":[{"text":"Describe the load honestly, without piling on blame","then":"They listen, uncomfortable but engaged, and ask what would help.","best":true},{"text":"List every unfair thing from the last year","then":"The list overwhelms them, and they get defensive instead of hearing it."},{"text":"Downplay it now that you've been asked","then":"The moment to actually say it passes."},{"text":"Say they should already know what's wrong","then":"They're left guessing, and the real issue stays unnamed."}],"why":"Describing the load honestly, without piling on, is what makes it possible for them to actually hear it."},{"prompt":"Weeks later, during a busy week, you feel the snapping start again. What do you do?","options":[{"text":"Name what's bothering you early, before it builds","then":"You both course correct quickly, before it turns into resentment.","best":true},{"text":"Let it slide. Busy weeks are always like this","then":"It quietly builds the same way it did before."},{"text":"Bring up every old grievance at once","then":"A small moment turns into a much bigger fight than it needed to."},{"text":"Blame the busy week and plan a weekend away","then":"The trip is lovely, and the load at home is exactly as it was."}],"why":"Catching it early is what keeps resentment from setting in again."}],"debrief":"Unaddressed load-inequality breeds resentment; naming and fixing it protects the partnership.","relearn":"Address load-unfairness kindly before resentment damages the relationship."},
  {"id":"ep-051","cat":"tools-and-help","type":"match","hook":"Match the tool to what it helps with.","pairs":[{"left":"A full load inventory","right":"Seeing the invisible work"},{"left":"An owned-domains split","right":"Sharing the mental load"},{"left":"A monthly check-in","right":"Keeping it fair over time"},{"left":"A turn-taking flex rule","right":"Backing both careers"},{"left":"A 'who-decides' map","right":"Sharing the decisions"}],"relearn":"A load inventory, an owned-domains split, a check-in, a flex rule and a decision map each move a home toward fairness.","persona":"any","source":"the tools"},
  {"id":"ep-052","cat":"tools-and-help","type":"sort","hook":"Sort: moves the home toward equal, or keeps it unequal?","items":[{"id":"a","text":"Owning domains end-to-end"},{"id":"b","text":"'Helping' when asked"},{"id":"c","text":"Sharing the mental load"},{"id":"d","text":"One person managing it all"},{"id":"e","text":"A no-blame check-in"},{"id":"f","text":"Waiting to be reminded"}],"bins":[{"id":"equal","label":"Toward equal","valence":"pos"},{"id":"unequal","label":"Keeps unequal","valence":"neg"}],"key":{"a":"equal","b":"unequal","c":"equal","d":"unequal","e":"equal","f":"unequal"},"relearn":"Owning domains, sharing the mental load and a check-in move toward equal; 'helping' when asked, one manager and waiting to be reminded keep it unequal.","persona":"any","source":"toward equal"},
  {"id":"ep-053","cat":"tools-and-help","type":"reflect","hook":"Lensy: this isn't about men vs women, it's about a fairer, happier home for both. Agree?","prompt":"What do you think?","options":["Yes","For both","Not men vs women"],"affirm":"An equal home isn't a battle of the sexes; it's a better life for everyone in it.","relearn":"An equal home isn't men vs women; it's fairer and happier for both.","persona":"Karthik","source":"for everyone"},
  {"id":"ep-054","cat":"tools-and-help","type":"strike-rewrite","hook":"\"An equal home is just a women's demand and a loss for men.\"","myth":{"un":"An equal home is a women's demand and a loss for men.","re":"An equal home is happier and healthier for everyone; men gain deeper connection and a fairer life too.","why":"Fairness lifts both partners, not one at the other's cost."},"relearn":"An equal home gains everyone; men get deeper connection and a fairer life, not a loss.","persona":"Karthik","source":"men gain too"},
  {"id":"ep-055","cat":"tools-and-help","type":"role-play","persona":"any","source":"supporting a friend","hook":"Ritu says she feels crazy for being exhausted when her husband says he helps so much.","setup":"You meet for coffee, and she finally opens up.","steps":[{"prompt":"Ritu says: \"Maybe I'm just bad at managing everything.\"","options":[{"text":"\"That's the mental load, and it's real work.\"","then":"Ritu looks up. \"Wait, that has a name?\"","best":true},{"text":"\"You just need a better system, honestly.\"","then":"Ritu nods, but quietly feels like she's failed at organising."},{"text":"\"That's just how marriage is, unfortunately.\"","then":"Ritu's shoulders sink further. \"So this is just it, then.\""},{"text":"\"He does help a lot though, doesn't he?\"","then":"Ritu goes quiet, feeling less sure she's even allowed to complain."}],"why":"Naming the mental load tells her the exhaustion is real, not a personal failing."},{"prompt":"A little later, Ritu asks: \"So what am I even supposed to want here?\"","options":[{"text":"\"A partner who owns half, not just helps.\"","then":"\"I never thought to ask for that,\" she says quietly.","best":true},{"text":"\"Just ask him to help out more often.\"","then":"\"I already ask,\" she says. \"That's the exhausting part.\""},{"text":"\"Whatever makes him comfortable, probably.\"","then":"Ritu looks discouraged, like even wanting more feels wrong."},{"text":"\"You'll figure it out eventually.\"","then":"She nods, but looks just as lost as before."}],"why":"Naming owning, not helping, gives her the actual thing worth asking for."},{"prompt":"Ritu asks: \"How do I even bring this up without starting a fight?\"","options":[{"text":"\"Try mapping it all out together, calmly.\"","then":"\"That actually sounds doable,\" Ritu says, sitting up a little.","best":true},{"text":"\"Just tell him exactly how tired you are.\"","then":"\"I have,\" she says. \"He just says he's tired too.\""},{"text":"\"Wait until he offers to help more.\"","then":"Ritu looks tired just imagining the wait."},{"text":"\"Maybe don't bring it up at all for now.\"","then":"She nods, but the exhaustion clearly hasn't gone anywhere."}],"why":"A calm, concrete first step gives her somewhere real to start."}],"relearn":"Name the mental load with a struggling friend and share what helps."},
  {"id":"ep-056","cat":"tools-and-help","type":"reflect","hook":"Lensy: when inequality at home becomes control or coercion, that's abuse, and there's help. Clear?","prompt":"What do you think?","options":["Yes","That's abuse","Help exists"],"affirm":"Inequality that tips into control or coercion is abuse, not just unfairness, and help is there (see Respect at Home).","relearn":"When home inequality becomes control or coercion, that's abuse, and help exists.","persona":"any","source":"links to g56/help"},
  {"id":"ep-057","cat":"tools-and-help","type":"match","hook":"Match the need to the route.","pairs":[{"left":"A drifted, unfair split","right":"A fair-split renegotiation"},{"left":"Coercive control over money/home","right":"Respect at Home & help"},{"left":"A struggling partnership","right":"A couples counsellor"},{"left":"A partner blind to the load","right":"A shared load inventory"},{"left":"A career always sidelined","right":"A two-careers rebalance"}],"relearn":"Drifted split: renegotiate. Coercive control: Respect at Home. Struggling pair: a counsellor. Blindness: an inventory. Sidelined career: rebalance.","persona":"any","source":"routes"},
  {"id":"ep-058","cat":"tools-and-help","type":"spot","hook":"Spot the two messages that entrench the default (the red flags).","scene":[{"id":"a","text":"\"Let's share the invisible load too\"","trick":false},{"id":"b","text":"\"You're better at the home stuff\"","trick":true},{"id":"c","text":"\"I'll own this, you don't manage it\"","trick":false},{"id":"d","text":"\"Just tell me what you need done\"","trick":true},{"id":"e","text":"\"You shouldn't have to remind me\"","trick":false}],"why":"'You're better at home stuff' and 'just tell me' keep her managing; sharing the invisible load and owning a domain build equality.","relearn":"'You're better at it' and 'just tell me' entrench the default; sharing the load and owning a domain build an equal home.","persona":"any","source":"building messages"},
  {"id":"ep-059","cat":"tools-and-help","type":"match","hook":"Match each 'equal partners' idea to what it changes.","pairs":[{"left":"See the invisible load","right":"You can share it"},{"left":"Own, don't just help","right":"You lift the load"},{"left":"Both careers count","right":"Neither sidelined"},{"left":"Renegotiate as life changes","right":"It stays fair"},{"left":"Check in regularly","right":"Drift gets caught"}],"relearn":"See the load to share it, own to lift it, value both careers, renegotiate to stay fair, check in to catch drift.","persona":"any","source":"carry home"},
  {"id":"ep-060","cat":"see-the-load","type":"branch","persona":"Karthik","source":"act on awareness","hook":"A list you and Pooja made last week is still sitting on the kitchen table.","steps":[{"prompt":"After finally seeing the full list, you realise the home was never really balanced. What do you do?","options":[{"text":"Sit with it and ask Pooja what would actually help first","then":"She looks relieved you're asking, and says she'll think about what matters most.","best":true},{"text":"Apologise a lot and promise to try much harder from now on","then":"Pooja appreciates the apology, but nothing concrete has actually changed yet."},{"text":"Point out you've always worked long hours too","then":"Pooja's face closes. It starts to feel like a competition again."},{"text":"Say you'll think about it and bring it up later","then":"Later never quite comes, and the imbalance stays exactly where it was."}],"why":"Asking what would actually help, not just apologising, is what turns awareness into change."},{"prompt":"A few days later, Pooja says the daily grocery ordering drains her most. What do you do?","options":[{"text":"Take over the grocery ordering fully, starting today","then":"She notices immediately. It's the first real shift in weeks.","best":true},{"text":"Tell her you've genuinely been meaning to get around to it","then":"She's heard that before, and it doesn't land the same way twice."},{"text":"Suggest ordering the groceries together each week","then":"It's kinder than before, but she's still the one who knows what's needed."},{"text":"Ask her to just be a bit more patient","then":"Pooja sighs. Patience isn't what's missing here."}],"why":"Actually starting the specific change is what proves the awareness was real."},{"prompt":"At a family dinner, your brother jokes that men who do housework are 'well trained'. What do you do?","options":[{"text":"Say honestly that you'd been missing half the load at home","then":"Your brother goes quiet, then admits he might be missing his own.","best":true},{"text":"Laugh it off and change the subject","then":"The moment passes, and nothing about it gets named out loud."},{"text":"Say Pooja probably exaggerates how much she does","then":"It turns the joke on Pooja, and hides the load you'd just seen."},{"text":"Say you just do what you're asked, nothing more","then":"It quietly tells the table the home is still hers to manage."}],"why":"Admitting what you'd been missing, honestly, makes the change mean something beyond your home."}],"debrief":"Seeing the imbalance is uncomfortable, but acting on it, not getting defensive, is what fixes it.","relearn":"Take new awareness of the imbalance seriously and act, rather than getting defensive."},
  {"id":"ep-061","cat":"helping-vs-owning","type":"sort","hook":"Sort: truly owning it, or still a helper?","items":[{"id":"a","text":"You handle the school admin entirely"},{"id":"b","text":"You do school runs when reminded"},{"id":"c","text":"You plan and book the holidays"},{"id":"d","text":"You wait to be told the plan"},{"id":"e","text":"You track and pay the fees yourself"},{"id":"f","text":"You sign forms once she's filled them"}],"bins":[{"id":"owns","label":"Owning","valence":"pos"},{"id":"helper","label":"Still a helper","valence":"uhoh"}],"key":{"a":"owns","b":"helper","c":"owns","d":"helper","e":"owns","f":"helper"},"relearn":"Handling admin and planning entirely is owning; doing things only when reminded or told is still helping.","persona":"any","source":"owner or helper"},
  {"id":"ep-062","cat":"share-it-fairly","type":"reflect","hook":"Lensy: fairness at home isn't a one-off settlement, it's a habit you keep choosing. Agree?","prompt":"What do you think?","options":["Yes","A habit","Keep choosing"],"affirm":"A fair home is a habit of ongoing fairness, chosen again and again, not a single settlement.","relearn":"Fairness at home is an ongoing habit, not a one-off settlement.","persona":"any","source":"a habit"},
  {"id":"ep-063","cat":"two-careers","type":"role-play","persona":"Karthik","source":"valuing her career","hook":"Pooja keeps quietly rearranging her plans around your work, without you ever asking her to.","setup":"Tonight she cancels something of her own again.","steps":[{"prompt":"Pooja says: \"It's fine. Your meeting's more important anyway.\"","options":[{"text":"\"Your career matters as much as mine.\"","then":"Pooja pauses. \"I don't think I've heard you say that before.\"","best":true},{"text":"\"Thanks, I really appreciate that.\"","then":"She nods, and the pattern quietly repeats next week too."},{"text":"\"Well, this meeting is pretty big.\"","then":"Pooja shrinks a little further into the default."},{"text":"\"You don't have to keep doing that.\"","then":"\"Okay,\" she says, but nothing about the pattern actually changes."}],"why":"Naming that her career matters equally is what actually interrupts the default."},{"prompt":"A few days later, a similar moment comes up. Pooja asks: \"What happens if our plans clash again?\"","options":[{"text":"\"Then we decide together, not by default.\"","then":"\"Together,\" she repeats, like she's testing the word.","best":true},{"text":"\"We'll figure it out when it happens.\"","then":"The vague answer leaves the default quietly intact."},{"text":"\"Mine will probably still come first, honestly.\"","then":"Pooja's face falls slightly, confirming what she'd assumed."},{"text":"\"You're more flexible, so it'll be you.\"","then":"Pooja sighs. \"That's exactly the assumption I mean.\""}],"why":"Naming a real joint decision, not a default, is what makes the promise concrete."},{"prompt":"A month later, Pooja says: \"Something's actually clashing this time. What do we do?\"","options":[{"text":"\"Let's sit down and weigh both events fairly.\"","then":"You compare honestly, and this time hers wins out.","best":true},{"text":"\"Mine still takes priority, I think.\"","then":"Pooja goes along with it, the old pattern holding once more."},{"text":"\"You decide, whichever works.\"","then":"She ends up choosing yours anyway, out of habit."},{"text":"\"Let's just flip a coin to keep it simple.\"","then":"The coin decides what the conversation should have."}],"why":"Actually weighing it together, and following through, is what makes the words real."}],"relearn":"Affirm that your partner's career matters as much as yours; don't default to one."},
  {"id":"ep-064","type":"sort","hook":"Sort: keeps a home equal over years, or lets it slide?","items":[{"id":"a","text":"Regular, honest check-ins"},{"id":"b","text":"Assuming it's fine forever"},{"id":"c","text":"Adjusting around big changes"},{"id":"d","text":"Ignoring slow drift"},{"id":"e","text":"Offering when a partner carries more"},{"id":"f","text":"Defending instead of rebalancing"}],"bins":[{"id":"keeps","label":"Keeps it equal","valence":"pos"},{"id":"slides","label":"Lets it slide","valence":"neg"}],"key":{"a":"keeps","b":"slides","c":"keeps","d":"slides","e":"keeps","f":"slides"},"relearn":"Check-ins, adjusting at change and offering keep a home equal; assuming it's fine, ignoring drift and defending let it slide.","persona":"any","source":"over the years","cat":"keep-it-equal"},
  {"id":"ep-065","cat":"see-the-load","type":"strike-rewrite","hook":"\"If she doesn't complain, the load must be fair.\"","myth":{"un":"If she doesn't complain, the load must be fair.","re":"Many carry the load silently to avoid conflict; no complaint doesn't mean it's fair.","why":"Silence can be exhaustion, not contentment."},"relearn":"No complaint doesn't mean it's fair; many carry the load silently.","persona":"any","source":"silence isn't fairness"},
  {"id":"ep-066","cat":"helping-vs-owning","type":"branch","persona":"Karthik","source":"stop asking what to do","hook":"You catch yourself saying 'just tell me what to do' about the home, again.","steps":[{"prompt":"Pooja is making the weekend list like always. What do you do instead?","options":[{"text":"Stop and figure out what's needed yourself, right now","then":"She stops halfway, surprised you're already on it.","best":true},{"text":"Ask her to read the list out loud so you can help","then":"You help with her list, but it's still her list."},{"text":"Wait quietly until she hands you a task","then":"She hands you one, same as every other weekend."},{"text":"Offer to do 'whatever's easiest' for you","then":"She ends up giving you the easy jobs and keeping the rest."}],"why":"Working out what's needed yourself, before she lists it, is what stops the asking."},{"prompt":"Your friend asks how you two split the weekend chores. What do you say?","options":[{"text":"Say you're trying to notice things without being told","then":"Your friend seems surprised it's even something to try.","best":true},{"text":"Say Pooja finally trained you properly","then":"Your friend laughs. The change gets credited to Pooja, not to you."},{"text":"Say you still ask sometimes. It's easier","then":"Your friend nods. Next weekend, you're asking again."},{"text":"Change the subject. It feels awkward to explain","then":"The moment passes, and nothing about the pattern gets named."}],"why":"Naming it as your own change, not her training, is what makes it stick."},{"prompt":"The balcony plants need repotting and nobody's mentioned it yet. What do you do?","options":[{"text":"Notice it yourself and get it sorted this weekend","then":"Pooja doesn't even realise it needed doing until it's done.","best":true},{"text":"Wait to see if Pooja notices it first","then":"She notices, like always, and it becomes her job again."},{"text":"Mention it to her so she can add it to a list","then":"She adds it to her mental list, not yours."},{"text":"Leave it. It's not urgent","then":"The plants wilt a little more before anyone acts."}],"why":"Noticing without being told, even for small things, is what owning actually means."}],"debrief":"'Just tell me what to do' keeps your partner as the manager; figuring it out yourself is owning.","relearn":"Replace 'just tell me what to do' with figuring out what's needed yourself."},
  {"id":"ep-067","cat":"share-it-fairly","type":"branch","persona":"any","source":"share the worst too","hook":"You and Meher finally sat down to write out everything that needs doing.","steps":[{"prompt":"Going through the list, Meher's ended up with most of the unpleasant tasks. What do you do?","options":[{"text":"Point it out and take on a fair share of those too","then":"Meher looks surprised, then relieved someone else noticed first.","best":true},{"text":"Offer to take on one of the nicer tasks instead","then":"It sounds helpful, but the unpleasant ones stay untouched."},{"text":"Let her keep the worst of it. She's used to it","then":"Meher's face falls slightly at being handed the same old pattern."},{"text":"Say unpleasant is subjective. Everyone dislikes something","then":"It dodges the actual imbalance sitting right there on the list."}],"why":"Naming and taking a fair share of the unpleasant tasks too is what makes a split genuinely fair."},{"prompt":"Meher mentions cleaning the bathroom is the task she dreads most. What do you do?","options":[{"text":"Take it on fully, scrubbing and all, from this week","then":"She looks genuinely relieved, like a weight actually lifted.","best":true},{"text":"Offer to alternate, but only the quick weekly wipe-down","then":"The scrubbing and the drain still stay hers, every single week."},{"text":"Suggest hiring help just for that one task","then":"A hired hand would do the scrubbing, but whose job it is until then stays unanswered."},{"text":"Say you'll try to remember to help sometimes","then":"Sometimes leaves the dread mostly hers, most weeks."}],"why":"Taking the dreaded job on fully, the worst parts included, is what evens the unpleasant load."},{"prompt":"A few weeks later, the bathroom is due for its deep clean. What do you do?","options":[{"text":"Do it yourself, properly, without being asked","then":"Meher comes home to a clean bathroom and doesn't have to think about it.","best":true},{"text":"Ask Meher if she'd mind doing this one, just this once","then":"She agrees, and the dreaded job slides back to her."},{"text":"Mention how much you'd hate doing it before you start","then":"It turns a fair share into a favour she's meant to thank you for."},{"text":"Leave it a few more days and see if it's really needed","then":"Meher notices first, and quietly does it herself again."}],"why":"Doing the dreaded job yourself, unasked and without fuss, is what makes sharing the worst real."},{"prompt":"At a family function, a cousin jokes that wives always end up with the worst chores. What do you do?","options":[{"text":"Say the worst jobs should be shared, not left to Meher","then":"Your cousin pauses, and the joke quietly stops landing as a joke.","best":true},{"text":"Laugh and agree that's just how it goes","then":"It makes the old default sound like a law of nature."},{"text":"Say Meher doesn't mind the worst jobs anyway","then":"It speaks for her, and hides how much she dreads them."},{"text":"Say you do whatever she asks you to","then":"It makes the worst jobs hers to hand out, and yours to help with."}],"why":"Saying the worst jobs are shared work turns a joke about defaults into a fair expectation."}],"debrief":"A fair split shares the unpleasant and invisible tasks, not just the pleasant visible ones.","relearn":"Share the unpleasant and invisible tasks fairly too, not just the easy ones."},
  {"id":"ep-068","cat":"two-careers","type":"strike-rewrite","hook":"\"One strong career propped up by the other's unpaid work is as good as two.\"","myth":{"un":"One strong career propped up by the other's unpaid work is as good as two.","re":"Two mutually-supported careers go further than one carried on the other's unpaid labour.","why":"Propping one up wastes the other's potential."},"relearn":"Two mutually-supported careers go further than one carried on the other's unpaid work.","persona":"any","source":"mutual support"},
  {"id":"ep-069","type":"match","hook":"Match the concrete habit to what it makes durable.","pairs":[{"left":"Owned domains","right":"No one left managing"},{"left":"Regular check-ins","right":"Catches drift early"},{"left":"Agreed standards","right":"No hidden re-work"},{"left":"Renegotiating at changes","right":"Keeps pace with life"},{"left":"Noticing and offering","right":"No one quietly burns out"}],"relearn":"Concrete habits, owned domains, check-ins, agreed standards, renegotiation and offering, make equality stick.","persona":"any","source":"make it stick","cat":"keep-it-equal"},
  {"id":"ep-070","cat":"helping-vs-owning","type":"spot","hook":"Spot the two signs you haven't truly shared the load.","scene":[{"id":"a","text":"Your partner never thinks about what you own","trick":false},{"id":"b","text":"Your partner still reminds you to do it","trick":true},{"id":"c","text":"You notice and act without prompting","trick":false},{"id":"d","text":"Your partner keeps a mental list for you","trick":true},{"id":"e","text":"You handle the whole domain end-to-end","trick":false}],"why":"If your partner still reminds you and keeps a mental list for you, the load is still on them, not shared.","relearn":"True owning means your partner never has to remind you or keep a mental list of your domain.","persona":"any","source":"the clear target"},
  {"id":"ep-071","cat":"see-the-load","type":"reflect","hook":"Lensy: naming the invisible load out loud is half the battle, it stops being invisible. Agree?","prompt":"What do you think?","options":["Yes","Name it out loud","Half the battle"],"affirm":"Saying the invisible load out loud is most of the work; once named, it can finally be shared.","relearn":"Naming the invisible load out loud stops it being invisible, that's half the battle.","persona":"Pooja","source":"name it out loud"},
  {"id":"ep-072","cat":"share-it-fairly","type":"spot","hook":"Spot the two moves that create hidden extra load.","scene":[{"id":"a","text":"Agreeing shared standards together","trick":false},{"id":"b","text":"One person silently redoing the other's work","trick":true},{"id":"c","text":"Both accepting 'good enough'","trick":false},{"id":"d","text":"Criticising how the other did a job","trick":true},{"id":"e","text":"Trusting each other's way of doing it","trick":false}],"why":"Silently redoing the other's work and criticising how they did it create hidden re-work; the rest prevent it.","relearn":"Agree shared standards so neither silently redoes nor criticises the other's work and adds hidden load.","persona":"any","source":"shared standards"},
  {"id":"ep-073","type":"sort","persona":"any","source":"belief or bias","hook":"Sort: an equal-careers belief, or a bias?","items":[{"id":"a","text":"Both jobs deserve real support"},{"id":"b","text":"Her job is just 'pocket money'"},{"id":"c","text":"Either career can be the priority"},{"id":"d","text":"His ambitions always come first"},{"id":"e","text":"Both deserve time to up-skill"},{"id":"f","text":"Her work is optional after marriage"}],"bins":[{"id":"equal","label":"Equal-careers","valence":"pos"},{"id":"bias","label":"Bias","valence":"neg"}],"key":{"a":"equal","b":"bias","c":"equal","d":"bias","e":"equal","f":"bias"},"relearn":"Both jobs supported, either-can-be-priority and both up-skilling is equal; 'pocket money', his-always-first and 'optional' is bias.","cat":"two-careers"},
  {"id":"ep-074","cat":"keep-it-equal","type":"reflect","hook":"Lensy: an equal home is something you build together, over years, on purpose. Ready to keep at it?","prompt":"What do you think?","options":["Yes","Build it together","Keep at it"],"affirm":"An equal home is a shared, ongoing project; staying at it together is exactly how it's built.","relearn":"An equal home is built together, over years, on purpose.","persona":"any","source":"build it together"},
  {"id":"ep-075","cat":"tools-and-help","type":"sort","hook":"Sort: this game's stance, or against it?","items":[{"id":"a","text":"Men owning an equal share"},{"id":"b","text":"Shaming a couple's current setup"},{"id":"c","text":"Making the invisible load visible"},{"id":"d","text":"Treating it as a women-only issue"},{"id":"e","text":"An equal home gains everyone"},{"id":"f","text":"\"It's a battle of the sexes\""}],"bins":[{"id":"for","label":"The stance","valence":"pos"},{"id":"against","label":"Against it","valence":"neg"}],"key":{"a":"for","b":"against","c":"for","d":"against","e":"for","f":"against"},"relearn":"Men owning an equal share, making the load visible and everyone gaining is the stance; shaming setups, women-only framing and 'battle of the sexes' isn't.","persona":"any","source":"the stance"},
  {"id":"ep-076","cat":"helping-vs-owning","type":"role-play","persona":"Karthik","source":"taking it off their plate","hook":"Pooja keeps quietly redoing the bookings you already made.","setup":"It's late, and her laptop is open on the airline's site.","steps":[{"prompt":"Pooja says: \"It's easier if I just do it myself, honestly.\"","options":[{"text":"\"Let me actually own this properly, so it's off your plate.\"","then":"Pooja pauses. \"Okay. Show me you mean it, then.\"","best":true},{"text":"\"Okay, if it's easier for you.\"","then":"Pooja sighs. \"Easier tonight. But I don't want to do every trip forever.\""},{"text":"\"I'll try to be more careful next time.\"","then":"Pooja shakes her head. \"It's not about careful. It's about trusting it's handled.\""},{"text":"\"Maybe we should just book everything together.\"","then":"Pooja says, \"Together usually means I still do most of it.\""}],"why":"Asking to properly own it, not just try harder, is what actually takes it off her plate for good."},{"prompt":"Pooja asks: \"What if something goes wrong with a booking?\"","options":[{"text":"\"Then I sort it out. You won't have to step in.\"","then":"Pooja considers this. \"Okay. Let's see how the next one goes.\"","best":true},{"text":"\"Then you can fix it. You're better at it.\"","then":"Pooja sighs. \"So I'm still the backup.\""},{"text":"\"It won't. I'll triple check everything.\"","then":"Pooja says, \"Checking isn't what I'm worried about.\""},{"text":"\"Just tell me what to check for, then.\"","then":"Pooja says, \"That still makes it my checklist, not yours.\""}],"why":"Saying you'll sort any problem yourself is what makes the offer believable."},{"prompt":"Two weeks later, Pooja asks: \"Should I look over the Goa bookings before you pay?\"","options":[{"text":"\"No need. They're mine to get right.\"","then":"Pooja nods slowly. \"Okay. I'll leave them with you.\"","best":true},{"text":"\"Sure, a second pair of eyes can't hurt.\"","then":"Pooja says, \"Okay. So I'm still checking them.\""},{"text":"\"Only the hotel one. That's the tricky one.\"","then":"Pooja says, \"So I'm still checking the hard part.\""},{"text":"\"If you want. You'll probably redo them anyway.\"","then":"Pooja frowns. \"That's not fair. I'm trying to let go.\""}],"why":"Declining the check, and owning the result, is what takes the bookings off her plate for good."}],"relearn":"When 'easier to do it myself' appears, take real ownership so it's genuinely off their plate."},
  {"id":"ep-077","cat":"see-the-load","type":"role-play","persona":"Karthik","source":"narrate the day","hook":"You want to finally see the mental load you've been blind to.","setup":"One evening, you ask Pooja to show you.","steps":[{"prompt":"Pooja asks: \"You really want to hear all of it?\"","options":[{"text":"\"Yes. Walk me through the invisible stuff. I want to really see it.\"","then":"She takes a breath, then starts listing, relieved someone's finally asking.","best":true},{"text":"\"Just the big things. I don't need every detail.\"","then":"She skips the small daily stuff, which turns out to be most of the actual load."},{"text":"\"I think I already have a pretty good idea.\"","then":"Pooja pauses. \"Do you, though?\""},{"text":"\"Sure, but please keep it quick. I have a work call coming up soon.\"","then":"She shortens it, and half of what mattered goes unsaid."}],"why":"Asking for all of it, and meaning it, is what actually lets you see the full load."},{"prompt":"Pooja says: \"Festival planning, the in-laws' visit dates, insurance renewals... it just keeps going.\"","options":[{"text":"\"Keep going. I'm writing each one down.\"","then":"By the end, the written list makes the invisible work impossible to unsee.","best":true},{"text":"\"Okay, I'll try to remember the main points.\"","then":"Pooja pauses. \"You won't remember half of this by tomorrow.\""},{"text":"\"A couple of those don't sound that hard, honestly.\"","then":"Pooja stops mid-sentence, feeling judged instead of heard."},{"text":"\"Can we get to the important ones?\"","then":"Pooja frowns. \"They're all important. That's the point.\""}],"why":"Writing it down as she talks turns a conversation into something you can actually act on."},{"prompt":"Once she's done, Pooja asks: \"So, does that change anything for you?\"","options":[{"text":"\"Yes. Let me take over two of these, starting this week.\"","then":"She looks genuinely relieved, glad it led somewhere real.","best":true},{"text":"\"It really opened my eyes. Thank you for sharing.\"","then":"She appreciates it, but nothing on the list has actually moved yet."},{"text":"\"Honestly, I don't know where to start.\"","then":"Pooja sighs. \"You don't have to start everywhere, just somewhere.\""},{"text":"\"I guess I'll just try to keep it all in mind somehow, okay.\"","then":"Keeping it in mind rarely becomes an actual task taken off her plate."}],"why":"Naming two specific things to take over is what turns seeing the load into sharing it."}],"relearn":"Ask your partner to narrate a day's invisible work to see the mental load."},
  {"id":"ep-078","cat":"share-it-fairly","type":"match","hook":"Match the split principle to what it ensures.","pairs":[{"left":"Own whole domains","right":"No one's left managing"},{"left":"Count all hours","right":"Fair, not just visible"},{"left":"Agree, don't assume","right":"Genuine fairness"},{"left":"Write it down","right":"No weekly re-arguing"},{"left":"Revisit as life shifts","right":"Stays fair over time"}],"relearn":"Owning domains, counting all hours, agreeing, writing it down and revisiting each ensure a genuinely fair split.","persona":"any","source":"split principles"},
  {"id":"ep-079","cat":"keep-it-equal","type":"branch","persona":"any","source":"owning a slip","hook":"You and Arjun agreed a fair split months ago, and life has been busy since.","steps":[{"prompt":"You notice Arjun's gone a little quiet and distant this week. What do you do?","options":[{"text":"Ask directly if the old split has crept back","then":"Arjun exhales. \"Actually, yeah, it kind of has.\"","best":true},{"text":"Assume it's just a busy week and let it pass","then":"The quiet continues, and the real reason stays unnamed."},{"text":"Do something extra nice to smooth things over","then":"He smiles, but the quiet returns by the next day."},{"text":"Wait for him to bring it up if it's real","then":"He doesn't bring it up, and the distance quietly grows."}],"why":"Asking directly, not guessing, is what actually opens the real conversation."},{"prompt":"A few days later, Arjun brings up that he's been carrying more again. What do you do?","options":[{"text":"Own the slip plainly and apologise, no excuses","then":"Arjun softens. \"Thank you for just saying that.\"","best":true},{"text":"Explain how busy you've been lately","then":"The explanation lands as an excuse rather than an apology."},{"text":"Get defensive about how much you already do","then":"Arjun goes quiet again, the opposite of what you wanted."},{"text":"Promise generally to try harder from now on","then":"Arjun nods, but doesn't look convinced anything specific will change."}],"why":"Owning the slip without excuses is what actually lets the resentment start to ease."},{"prompt":"A week later, you catch yourself falling into the old pattern again. What do you do?","options":[{"text":"Stop, name it out loud, and rebalance right there","then":"Arjun notices you catching it yourself, and relaxes.","best":true},{"text":"Let it go this once. You'll fix it properly next week","then":"'Next week' becomes next month, same as before."},{"text":"Wait to see if Arjun notices and says something","then":"He notices, and has to be the one to raise it again."},{"text":"Feel guilty about it without actually changing anything","then":"You feel bad about it, and the task stays exactly where it was."}],"why":"Catching and naming it yourself, right away, is what makes the repair actually stick this time."}],"debrief":"Slips happen; owning them and rebalancing, not defending, keeps the partnership fair and warm.","relearn":"Own a slip back into old patterns, apologise, and rebalance."},
  {"id":"ep-080","cat":"two-careers","type":"role-play","persona":"Karthik","source":"joint decision","hook":"At a family gathering, you and your partner Pooja are asked about your plans.","setup":"An uncle brings up kids as you stand together.","steps":[{"prompt":"The uncle says: \"Once the kids come, she'll stay home, naturally.\"","options":[{"text":"\"That'll be a decision we make together.\"","then":"The uncle blinks. \"Together? That's not how it usually goes.\"","best":true},{"text":"\"We'll see how things go, I guess.\"","then":"The uncle nods, taking that as agreement with his assumption."},{"text":"\"That's really our business, uncle.\"","then":"The uncle looks offended, and the mood turns awkward."},{"text":"\"Probably, yeah. It's easier that way.\"","then":"Pooja's smile stiffens beside you."}],"why":"Naming it as a joint decision, calmly, corrects the assumption without a scene."},{"prompt":"The uncle adds: \"Either way, her career matters less once there's a baby, no?\"","options":[{"text":"\"No, her career matters as much as mine.\"","then":"The uncle pauses, clearly not expecting that answer.","best":true},{"text":"\"It'll matter less for a while, maybe.\"","then":"The uncle nods, satisfied his view was mostly right."},{"text":"\"Depends on the baby, honestly.\"","then":"The answer leaves the assumption basically untouched."},{"text":"\"Let's not get into this here.\"","then":"The uncle shrugs and repeats his view to someone else nearby."}],"why":"Stating her career matters equally is what actually corrects the belief, not just deflects it."},{"prompt":"Later, Pooja says: \"That was a lot today. How are you feeling about it?\"","options":[{"text":"\"Uncomfortable. But it's our decision, and I'll stand by it.\"","then":"She smiles. \"I needed to hear you say it plainly.\"","best":true},{"text":"\"It's fine. Let's not turn this into a big thing tonight.\"","then":"\"So we just don't talk about it?\" she asks, unsure."},{"text":"\"I didn't want to make a scene. That's all it was.\"","then":"\"So next time you'd stay quiet?\" she asks, a little hurt."},{"text":"\"He means well. Please don't take it so seriously.\"","then":"\"It's not about meaning well,\" she says quietly."}],"why":"Naming the discomfort and backing the joint decision tells her you are with her."},{"prompt":"Months later, a cousin says: \"So, will she stay home once you two have kids?\"","options":[{"text":"\"That's a decision we'll make together.\"","then":"The cousin looks surprised, then just nods and moves on.","best":true},{"text":"\"Let's not get into that.\"","then":"Pooja notices the silence, and the old assumption stands unchallenged."},{"text":"\"Are we really doing this again?\"","then":"The gathering turns tense, and the actual point gets lost."},{"text":"\"Pooja, you want to answer that one?\"","then":"Pooja feels like the correcting has quietly become her job."}],"why":"Holding the same steady line whenever it comes up makes the joint decision stick."}],"relearn":"Make clear whether anyone steps back for kids is a joint decision, not assumed."},
  {"id":"ep-081","cat":"tools-and-help","type":"reflect","hook":"Lensy: a truly equal home might be the most loving thing you build together. Believe it?","prompt":"What do you think?","options":["Yes","Most loving","Build it"],"affirm":"Sharing the load fully is a deep act of love and respect; it's one of the best things you can build.","relearn":"A truly equal home is one of the most loving things you can build together.","persona":"any","source":"loving home"},
  {"id":"ep-082","cat":"helping-vs-owning","type":"strike-rewrite","hook":"\"Some people are just naturally better at running a home.\"","myth":{"un":"Some people are just naturally better at running a home.","re":"Running a home is a learnable skill, not an inborn gift; anyone can build the habit of owning it.","why":"'Naturally better' is usually just more practice, often forced."},"relearn":"Running a home is a learnable skill, not an inborn gift; anyone can own it.","persona":"Karthik","source":"it's learnable"},
  {"id":"ep-083","cat":"share-it-fairly","type":"spot","hook":"Spot the two splits that aren't actually fair.","scene":[{"id":"a","text":"Owned domains plus shared mental load","trick":false},{"id":"b","text":"She manages, he does tasks when told","trick":true},{"id":"c","text":"All hours counted and balanced","trick":false},{"id":"d","text":"He picks the easy jobs, she gets the rest","trick":true},{"id":"e","text":"Planning and remembering shared too","trick":false}],"why":"'She manages, he does when told' and 'he picks easy, she gets the rest' aren't fair; the others genuinely are.","relearn":"A fair split owns domains, shares the mental load and counts all hours; one managing or cherry-picking easy jobs isn't.","persona":"any","source":"fair split"},
  {"id":"ep-084","cat":"tools-and-help","type":"reflect","hook":"Lensy: see the load, own your half, value both careers, keep it equal, carry which home?","prompt":"What will you carry?","options":["See the invisible load","Own, don't just help","Value both careers","Keep renegotiating"],"affirm":"Carry that one home, and you build the equal, happier partnership this whole chapter is about.","relearn":"See the load, own your half, value both careers, and keep it equal.","persona":"any","source":"carry forward"},
  {"id":"ep-900","cat":"helping-vs-owning","type":"strike-rewrite","hook":"\"I told her I'd do anything she needs, so I'm a great partner.\"","myth":{"un":"Saying 'tell me anything you need' makes me a great partner.","re":"That still makes her the one who notices and assigns; owning means seeing the need and acting first.","why":"'Tell me' keeps her as the manager of the whole home."},"relearn":"'Tell me what you need' keeps her managing; owning means noticing the need yourself.","persona":"Karthik","source":"tell me anything"},
  {"id":"ep-901","cat":"helping-vs-owning","type":"strike-rewrite","hook":"\"I take out the bins every day, so I clearly do my bit.\"","myth":{"un":"Taking the bins out daily means I do my bit at home.","re":"One repeating chore isn't a domain; owning means running an area's planning and remembering, not just a task.","why":"A single task left her holding everything else."},"relearn":"One repeating chore isn't a domain; owning runs the whole area's planning, not just a task.","persona":"Karthik","source":"one chore isn't a domain"},
  {"id":"ep-902","cat":"helping-vs-owning","type":"strike-rewrite","hook":"\"She's just better at remembering the house stuff than me.\"","myth":{"un":"She's just naturally better at remembering the house stuff.","re":"She remembers because she's been left to carry it; tracking is a habit you can build by owning a domain.","why":"Practice forced on one person isn't a natural gift."},"relearn":"She remembers because she carries it; tracking is a habit you build by owning a domain.","persona":"Karthik","source":"not natural memory"},
  {"id":"ep-903","cat":"helping-vs-owning","type":"strike-rewrite","hook":"\"Once she's trained me on a chore, I've got it handled.\"","myth":{"un":"Once she trains me on a chore, I've fully got it handled.","re":"Needing to be trained each time keeps her as the trainer; owning means learning the whole domain yourself.","why":"Being the trainee leaves the planning on her."},"relearn":"Needing training each time keeps her the trainer; owning means learning the whole domain.","persona":"Karthik","source":"being trained"},
  {"id":"ep-904","cat":"helping-vs-owning","type":"strike-rewrite","hook":"\"I do loads on weekends, so weekdays being all on her is fair.\"","myth":{"un":"Doing loads on weekends makes her carrying weekdays fair.","re":"A weekend burst doesn't own a domain; owning means it runs every day without her managing it.","why":"Bursts leave the daily mental load entirely on her."},"relearn":"A weekend burst isn't owning; owning means a domain runs daily without her managing it.","persona":"Karthik","source":"weekend burst"},
  {"id":"ep-905","cat":"helping-vs-owning","type":"strike-rewrite","hook":"\"My amma ran the house alone, so my wife handling it is normal.\"","myth":{"un":"My mother ran the house alone, so my wife handling it is normal.","re":"That she coped alone was unfair then too; owning your half breaks the pattern, it doesn't honour it.","why":"An old imbalance copied forward is still an imbalance."},"relearn":"Your mother coping alone was unfair too; owning your half breaks the pattern, not honours it.","persona":"Karthik","source":"my mother did it"},
  {"id":"ep-906","cat":"helping-vs-owning","type":"strike-rewrite","hook":"\"I earn more, so doing less at home balances out.\"","myth":{"un":"Earning more at work balances out doing less at home.","re":"Pay doesn't buy you out of the mental load; owning a home domain is part of partnership regardless of income.","why":"Money can't transfer the cognitive work of running a home."},"relearn":"Pay doesn't buy you out of the mental load; owning a domain is partnership regardless of income.","persona":"Karthik","source":"earning more"},
  {"id":"ep-907","cat":"helping-vs-owning","type":"strike-rewrite","hook":"\"I help with the baby whenever she asks, so we share the load.\"","myth":{"un":"Helping with the baby whenever she asks means we share the load.","re":"If she's tracking feeds, naps and doctor dates, the load is still hers; owning means holding that yourself.","why":"Being on-call to be asked isn't carrying the load."},"relearn":"Helping when asked isn't sharing; owning the baby's care means tracking it yourself.","persona":"Karthik","source":"helping with baby"},
  {"id":"ep-908","cat":"helping-vs-owning","type":"strike-rewrite","hook":"\"My job is the demanding one, so the house is naturally her department.\"","myth":{"un":"My job is demanding, so the house is naturally her department.","re":"A demanding job doesn't make home one person's department; both of you own home domains, not just her.","why":"'Her department' is just the old default in new words."},"relearn":"A busy job doesn't make home her department; both of you own home domains.","persona":"Karthik","source":"her department"},
  {"id":"ep-909","cat":"helping-vs-owning","type":"strike-rewrite","hook":"\"I'm hopeless at cooking, so it's better she just owns the kitchen.\"","myth":{"un":"I'm hopeless at cooking, so she should just own the kitchen.","re":"'Hopeless' is unlearned, not unfixable; owning means learning the domain, not handing it back to her.","why":"Staying unskilled keeps the whole kitchen load on her."},"relearn":"'Hopeless' means unlearned; owning means learning the domain, not handing it back.","persona":"Karthik","source":"weaponised incompetence"},
  {"id":"ep-910","cat":"helping-vs-owning","type":"strike-rewrite","hook":"\"I sent her a reminder about the cook's salary, so I'm on top of it.\"","myth":{"un":"Reminding her about the cook's salary means I'm on top of it.","re":"Reminding her just hands the task back; owning means you simply pay it without it touching her mind.","why":"A reminder is still routing the work through her."},"relearn":"Reminding her hands it back; owning means you handle it without it touching her mind.","persona":"Karthik","source":"reminding isn't owning"},
  {"id":"ep-911","cat":"helping-vs-owning","type":"strike-rewrite","hook":"\"I asked her to make me a list and I'll do every item on it.\"","myth":{"un":"If she makes me a list and I do every item, I've shared the load.","re":"Making the list IS the mental load; owning means you build the list, not just tick it off.","why":"The thinking behind the list is the real work."},"relearn":"Making the list is the mental load; owning means you build it, not just tick it off.","persona":"Karthik","source":"the list is the work"},
  {"id":"ep-912","cat":"helping-vs-owning","type":"strike-rewrite","hook":"\"I keep the kids busy while she cooks, so I'm pulling my weight.\"","myth":{"un":"Keeping the kids busy while she cooks means I'm pulling my weight.","re":"Filling time near her isn't owning a domain; owning means a whole area runs on you without her steering.","why":"Being a helpful pair of hands still leaves her steering."},"relearn":"Being helpful hands isn't owning; owning means a whole area runs on you, not her steering.","persona":"Karthik","source":"pulling my weight"},
  {"id":"ep-913","cat":"helping-vs-owning","type":"branch","persona":"Karthik","source":"own the tracking","hook":"You decide to take over the family's medical and appointment tracking.","steps":[{"prompt":"The pharmacy calls about a refill and Pooja picks up first, like always. What do you do?","options":[{"text":"Ask to take future refill calls yourself","then":"The pharmacy puts your number on file for refills.","best":true},{"text":"Let her handle it since she's already on the phone","then":"She notes it down, same as every time before."},{"text":"Ask her to loop you in only for bigger issues","then":"She keeps filtering what counts as 'big enough' to share."},{"text":"Suggest a pharmacy that texts reminders instead","then":"The texts land on her phone, not yours."}],"why":"Taking the calls yourself, not just the big issues, is what makes the tracking actually yours."},{"prompt":"You realise you don't actually know the family doctor's name. What do you do?","options":[{"text":"Ask her for every doctor, date and dosage at once","then":"It takes twenty minutes, and you finally have the whole picture.","best":true},{"text":"Look it up quietly so you don't seem behind","then":"You find half of it and miss what only she knew."},{"text":"Ask her to text you the details whenever relevant","then":"The information keeps arriving in pieces, through her."},{"text":"Decide it's fine. She'll flag anything urgent","then":"She's still the only one holding the full picture."}],"why":"Getting the whole list at once, not in pieces, is what lets you actually own it."},{"prompt":"A checkup is due next week and Pooja hasn't mentioned it. What do you do?","options":[{"text":"Notice the date and book it before she has to","then":"She's surprised to find it's already sorted.","best":true},{"text":"Wait for her to bring it up closer to the date","then":"She brings it up two days before, like always."},{"text":"Ask her to confirm the date is still right","then":"She checks, confirms, and books it herself anyway."},{"text":"Assume it'll get sorted somehow","then":"It nearly gets missed, and she catches it last minute."}],"why":"Noticing the date without being told is the whole point of holding the tracking."},{"prompt":"Your mother phones Pooja to ask when your father's next checkup is. What do you do?","options":[{"text":"Take the call, and ask your mother to come to you","then":"Your mother sounds surprised, but agrees to call you first about health questions.","best":true},{"text":"Let Pooja answer, since she has the dates handy","then":"Pooja answers from memory, and your mother keeps calling her first."},{"text":"Answer, then check with Pooja that you got it right","then":"Pooja confirms it, and stays the one who knows for sure."},{"text":"Suggest your mother just ask in the family group","then":"She posts in the group, and Pooja replies within a minute."}],"why":"Becoming the one family asks, not Pooja, is what moves the tracking off her for good."}],"debrief":"If she holds the master list, you've taken tasks but not the domain; own the tracking itself.","relearn":"Hold the medical tracking yourself; being called when it's due leaves the load on her."},
  {"id":"ep-914","cat":"helping-vs-owning","type":"branch","persona":"Karthik","source":"crisis default","hook":"The maid quits suddenly, and you and Pooja both have work tomorrow.","steps":[{"prompt":"It's 9pm and neither of you has a plan for tomorrow's mess. What do you do?","options":[{"text":"Say you'll take charge of finding a replacement","then":"Pooja looks relieved, and hands you her one lead.","best":true},{"text":"Say you'll help once she starts looking","then":"She starts making calls alone, same as any other crisis."},{"text":"Suggest you both manage a day without help this once","then":"The chores pile up, and one of you quietly absorbs them."},{"text":"Say you're too tired to deal with it tonight","then":"She stays up phoning around by herself, and has nothing by midnight."}],"why":"Taking charge yourself, not waiting to help, is what stops the crisis defaulting to her."},{"prompt":"The next morning, the search is still open and three agency numbers turn out to be dead ends. What do you do?","options":[{"text":"Take the agency calls yourself until one works out","then":"By midday you've lined up two interviews.","best":true},{"text":"Leave the agency calls with Pooja instead","then":"She ends up making the calls, and the search is hers."},{"text":"Post in the building WhatsApp group and wait","then":"Replies trickle in, and someone still has to sort them."},{"text":"Decide agencies aren't worth the effort","then":"The search stalls until she picks it back up."}],"why":"Staying on it yourself through the dead ends is what carrying the gap actually means."},{"prompt":"A candidate wants to meet today, but you're both in back-to-back meetings. What do you do?","options":[{"text":"Step out of your meeting to interview her yourself","then":"You hire her by evening, without Pooja missing a thing.","best":true},{"text":"Ask Pooja to step out instead. Her meetings are shorter","then":"She's the one who ends up slipping away."},{"text":"Ask the candidate to come back another day","then":"The gap stretches on for one more day."},{"text":"Send Pooja the candidate's number to handle","then":"The hiring quietly becomes her task again."}],"why":"Stepping out yourself, not assuming her time is more flexible, keeps the fix genuinely yours."},{"prompt":"A week later, the new maid asks whose number to save for days she can't come. What do you do?","options":[{"text":"Give her your number as the one to call","then":"She saves it, and the next sick-day message comes to you.","best":true},{"text":"Give her Pooja's number, since she's home earlier","then":"She saves it, and every change of plan now lands on Pooja."},{"text":"Give your number, and ask Pooja to brief her on the work","then":"She calls you, then checks every detail with Pooja anyway."},{"text":"Tell her to call whoever happens to be home","then":"Pooja is usually home first, so the calls go to her."}],"why":"Being her contact yourself, routine and all, keeps the fix yours instead of snapping back to Pooja."}],"debrief":"A crisis is where defaults snap back; owning means you carry it without her organising you.","relearn":"In a home crisis, own the fix; 'help if she's stuck' just hands it back to her."},
  {"id":"ep-915","cat":"helping-vs-owning","type":"branch","persona":"Karthik","source":"own groceries","hook":"You realise you've never once started a grocery order at home.","steps":[{"prompt":"The fridge is nearly empty and dinner's in question. What do you do?","options":[{"text":"Open the app and work out what's low","then":"Dinner sorts itself, and Pooja never has to check the fridge.","best":true},{"text":"Ask Pooja what to add to the usual order","then":"She rattles off the list, like she always has."},{"text":"Order a few obvious things and call it done","then":"Half of what's actually needed stays missing."},{"text":"Suggest eating out tonight instead","then":"The fridge stays as empty as before."}],"why":"Working out what's low yourself is the noticing that groceries actually take."},{"prompt":"You run out of a spice you didn't know existed. What do you do?","options":[{"text":"Ask Pooja to walk you through the staples","then":"She lists twelve things you'd never have thought to check.","best":true},{"text":"Skip it and hope nobody notices","then":"The dish tastes off, and she notices right away."},{"text":"Text her a photo asking 'is this the right one'","then":"She answers from work, same as she always has to."},{"text":"Decide staples aren't your job to learn","then":"The gaps in your knowledge stay exactly where they were."}],"why":"Learning the staples once, properly, is what lets you shop without needing her at all."},{"prompt":"A month in, Pooja opens the grocery app out of habit to check the cart. What do you do?","options":[{"text":"Say groceries are yours now, so she can stop checking","then":"She hesitates, then closes the app and leaves the cart to you.","best":true},{"text":"Say you'll keep it up as long as you remember","then":"She keeps the app open, half expecting to pick it back up someday."},{"text":"Ask her to double check the order occasionally","then":"She agrees, and ends up peeking at the cart every week."},{"text":"Let her check, since she knows the staples better","then":"She adds what's missing, and the noticing stays hers."}],"why":"Saying it's fully yours, and she can stop checking, is what makes the ownership stick."}],"debrief":"Noticing what's low is the invisible part; own that, not just the tap of 'order'.","relearn":"Own groceries end-to-end: notice, order, restock; ordering on her word leaves the noticing on her."},
  {"id":"ep-916","cat":"helping-vs-owning","type":"branch","persona":"Karthik","source":"helping with my own baby","hook":"Your mother praises you for 'helping so much' with your own father's recovery.","steps":[{"prompt":"Your father calls out from his room, and Pooja's mid-shower, your mother watching from the sofa. What do you do?","options":[{"text":"Go to him yourself, no announcement needed","then":"Your mother says nothing, and he settles once you're there.","best":true},{"text":"Call out for Pooja. He needs her","then":"She rushes out, and your mother nods like that's normal."},{"text":"Ask your mother to check on him a moment","then":"She does, but she's still the one who steps in, not you."},{"text":"Wait, hoping he settles on his own","then":"He doesn't, and Pooja comes out dripping to handle it."}],"why":"Going to him yourself without being asked is what makes his care actually yours to carry."},{"prompt":"Later, your mother says you're 'helping so much' these days. What do you do?","options":[{"text":"Say gently it's not helping. It's your own father","then":"Your mother pauses, then says, 'Fair enough, beta.'","best":true},{"text":"Say thank you and let the comment pass","then":"The praise quietly settles his care back as Pooja's job."},{"text":"Laugh and say you're just doing your bit","then":"Your mother smiles, and 'helping' stays the word for it."},{"text":"Point out how many meals you've managed today","then":"Your mother counts along, impressed but still watching to see if it lasts."}],"why":"Naming it as your own father, not brushing past the comment, is what actually reframes it."},{"prompt":"That night he needs help twice, and Pooja starts to get up first, as always. What do you do?","options":[{"text":"Get up first, and tell her you'll listen for him","then":"She settles back to sleep, and you're the one listening for him now.","best":true},{"text":"Ask her to wake you when it's your turn","then":"She agrees, and lies awake listening for him anyway."},{"text":"Offer to go if she really needs the rest","then":"She hesitates, unsure if admitting tiredness is allowed."},{"text":"Stay still and hope she doesn't notice you're awake","then":"She gets up anyway, unaware you were even awake."}],"why":"Taking the waking and the listening yourself is what makes his night care yours, not her default."},{"prompt":"At a family function, an aunty asks Pooja how she's 'managing alone' with your father. What do you do?","options":[{"text":"Add that you're caring for him together","then":"The aunty looks between you both and adjusts the question.","best":true},{"text":"Let Pooja answer. It's really her call to make","then":"She answers, and the 'alone' framing quietly stands."},{"text":"Laugh it off as an old-fashioned thing to ask","then":"The joke lands, and the assumption behind it goes unchallenged."},{"text":"Change the subject to something lighter","then":"The moment passes, and the question is never actually corrected."}],"why":"Correcting the assumption openly is what makes the shared care visible to your family."}],"debrief":"Praise for 'helping' with your own family quietly keeps the care her job; name it as equally yours.","relearn":"Caring for your own father isn't something you 'help' with; it's equally yours to carry, not a favour."},
  {"id":"ep-917","cat":"helping-vs-owning","type":"branch","persona":"Karthik","source":"stop texting from the shop","hook":"You keep texting her from the shop: 'which dal? which brand?'","steps":[{"prompt":"You're standing in the dal aisle, phone in hand, about to text again. What do you do?","options":[{"text":"Pick based on what you've seen at home","then":"You get it right, and she never gets the text.","best":true},{"text":"Text her a photo of the shelf instead","then":"She replies from a meeting, same as always."},{"text":"Buy the brand you personally prefer","then":"It's not what the house actually uses, and it goes untouched."},{"text":"Call her instead of texting. It's faster","then":"She answers, a little confused why you didn't just text like usual."}],"why":"Deciding from what you've noticed at home, not asking again, stops the shopping routing through her."},{"prompt":"Later you realise you don't know which cooking oil the house uses either. What do you do?","options":[{"text":"Check the shelf before your next trip","then":"You spot the brand yourself, no question needed.","best":true},{"text":"Keep a mental note to ask her tonight","then":"Tonight comes, and the question routes through her again."},{"text":"Just buy whatever's on offer this time","then":"It's the wrong brand, and dinner tastes slightly off."},{"text":"Ask the store staff what's popular","then":"The staff point to a bestseller, and next trip you're guessing again."}],"why":"Checking the shelf yourself is how you learn the staples without her having to teach you."},{"prompt":"A month later, Pooja offers to keep a list of the brands for you. What do you say?","options":[{"text":"Say no. You'll learn them from the kitchen","then":"She shrugs. \"Okay. One less list for me, then.\"","best":true},{"text":"Say yes, since it would save a lot of texts","then":"She starts a list, and updates it every time something changes."},{"text":"Say yes, but only for the rare items","then":"She keeps a shorter list, and still decides what counts as rare."},{"text":"Say you'll just buy whatever's on offer","then":"She winces, and quietly starts restocking the staples herself."}],"why":"Learning the brands yourself, not from her list, is what takes the shopping off her mind."}],"debrief":"Texting every choice means she's still shopping, just through you; learn the domain instead.","relearn":"Learn the staples and shop without asking; texting each choice makes her shop through your phone."},
  {"id":"ep-918","cat":"helping-vs-owning","type":"branch","persona":"Karthik","source":"claim whole domains","hook":"You both work full-time, but she owns every home domain.","steps":[{"prompt":"You sit down together to actually list out what running the house involves. What do you do?","options":[{"text":"Pick two whole domains and claim them as yours","then":"Pooja crosses them off her list completely, for good.","best":true},{"text":"Offer to be more helpful across the board","then":"'More helpful' doesn't take a single domain off her plate."},{"text":"Ask her which domains she'd like help with","then":"She names a few, and you help within them, still under her."},{"text":"Suggest splitting every single task fifty-fifty","then":"Every task split still means she's tracking every task."}],"why":"Claiming whole domains, not spreading yourself thin, is what actually shortens her list."},{"prompt":"The first week, something slips through the cracks at home. What do you do?","options":[{"text":"Own the miss and fix it yourself","then":"Pooja notices you caught it before she even saw the gap.","best":true},{"text":"Ask her to flag it next time you slip","then":"She nods, but her list stays exactly as long."},{"text":"Explain that it was a busy week","then":"She nods, and quietly fixes it herself that evening."},{"text":"Quietly hope nobody notices the miss","then":"She starts a shared spreadsheet, already dreading updating it."}],"why":"Catching your own slip is what keeps the domain fully yours instead of half-supervised."},{"prompt":"Two months in, Pooja says she still carries a lot of the remembering at home. What do you do?","options":[{"text":"Ask which whole area should come to you next","then":"She names the kitchen stock, and you take all of it on.","best":true},{"text":"Say you'll keep an eye out for things too","then":"She nods, and still notices everything first."},{"text":"Wait for her to bring up anything specific","then":"She doesn't, and keeps carrying the rest quietly."},{"text":"Suggest hiring more help around the house","then":"Help arrives, but she's still the one managing it."}],"why":"Asking what whole area can move next is what keeps the change growing instead of stopping."},{"prompt":"At a dinner, a friend's wife asks Pooja how she 'got him to help so much'. What do you say?","options":[{"text":"Say she shouldn't have to. It's your home too","then":"The friend's wife laughs, and says she'll borrow that line at home.","best":true},{"text":"Let Pooja explain. She knows the story best","then":"She explains, and the framing of 'getting him to' stays unchallenged."},{"text":"Joke that you finally saw the light","then":"Everyone laughs, and the real story stays untold."},{"text":"Say good husbands just notice these things","then":"The friend's wife glances at her own husband, unimpressed by the comparison."}],"why":"Saying it's your home too corrects the idea that she should have to get you to do anything."}],"debrief":"'Be more helpful' adds tasks but not domains; take whole areas off her mental list.","relearn":"Claim whole domains as yours; 'I'll be more helpful' leaves all the managing on her."},
  {"id":"ep-919","cat":"helping-vs-owning","type":"branch","persona":"Karthik","source":"she's away","hook":"She's away for a week and you want the house to run smoothly.","steps":[{"prompt":"Day one, and you realise you don't know the cook's day off. What do you do?","options":[{"text":"Ask the cook directly, and note her days down","then":"The cook texts back her schedule, and it goes in your phone calendar.","best":true},{"text":"Call Pooja to check. It'll take a minute","then":"She answers from the airport, and the pattern starts again."},{"text":"Guess from last week and hope you're right","then":"You guess wrong, and dinner plans fall apart."},{"text":"Ask your mother, who chats with the cook sometimes","then":"Your mother isn't sure either, and suggests you call Pooja."}],"why":"Going straight to the cook, not to Pooja, is what running the house yourself actually looks like."},{"prompt":"By evening, three small things have gone slightly wrong. What do you do?","options":[{"text":"Fix each one yourself and note it for later","then":"By night, the house is steady, without a single call to her.","best":true},{"text":"Call her that evening to ask how she'd handle it","then":"She talks you through it, same as if she'd never left."},{"text":"Let the small things sit until she's back","then":"They pile up quietly, waiting for whenever you get to them."},{"text":"Ask a relative to step in and help sort it","then":"Someone else runs the house, just not you."}],"why":"Fixing things yourself, not calling her for the answer, is what proves the house can run without her."},{"prompt":"Midweek, she texts to ask how it's going. What do you reply?","options":[{"text":"Tell her honestly, and say you'll sort the rest","then":"She sends a thumbs up, and doesn't ask about the house again.","best":true},{"text":"Send a long list of everything you managed","then":"It reads more like a report seeking approval than an update."},{"text":"Ask her a few quick questions just to be sure","then":"The questions quietly pull her back into managing from afar."},{"text":"Say it's all fine so she doesn't worry","then":"She senses something's off, and texts your mother to check."}],"why":"An honest update that keeps the fixing with you is what lets her actually switch off."},{"prompt":"She's back, and mentions another work trip next month. What do you say?","options":[{"text":"Say you'll run the house that week, no calls needed","then":"She smiles, and books the trip without planning meals ahead.","best":true},{"text":"Ask her to leave notes for everything before she goes","then":"She spends her last evening before the trip writing instructions."},{"text":"Suggest your mother stays over while she's away","then":"Your mother agrees, and Pooja spends an hour briefing her."},{"text":"Ask if the trip really needs to happen","then":"She goes quiet, and starts wondering if she should travel less."}],"why":"Offering to run it yourself, without her notes or calls, is what makes the house genuinely yours too."}],"debrief":"If she's still managing the house by phone from another city, it was never shared; own it fully.","relearn":"Run the house yourself when she's away; nightly 'how do you do this' calls keep her managing it."},
  {"id":"ep-920","cat":"helping-vs-owning","type":"branch","persona":"Karthik","source":"family pressure","hook":"Your father-in-law jokes you should 'let her handle the kitchen, na'.","steps":[{"prompt":"The joke lands at the dinner table, and everyone chuckles. What do you do?","options":[{"text":"Smile and say the kitchen is your department","then":"Your father-in-law blinks, then moves on to the next topic.","best":true},{"text":"Laugh along and let the comment pass","then":"The joke stands, unchallenged, as if it were true."},{"text":"Quietly hand Pooja the serving spoon instead","then":"Everyone chuckles again, and Pooja gives you a look."},{"text":"Get visibly annoyed at the comment","then":"The table goes tense, and the actual point gets lost."}],"why":"Naming the kitchen as yours, warmly, holds your ownership without turning dinner into a fight."},{"prompt":"Later, your mother-in-law asks if Pooja 'lets' you cook, or if you insist. What do you say?","options":[{"text":"Say it's simply yours, like any domain","then":"She nods slowly, turning the idea over.","best":true},{"text":"Say Pooja's fine with it, mostly","then":"Your mother-in-law nods slowly, still picturing Pooja's permission behind it."},{"text":"Say you insist because you enjoy it","then":"She smiles, treating it like a nice quirk rather than the norm."},{"text":"Say it's just easier this way","then":"She nods, already wondering when 'easier' will change back."}],"why":"Framing it as simply yours, not something allowed, is what makes the ownership sound normal."},{"prompt":"A cousin later teases that you've 'gone soft' running a kitchen. What do you do?","options":[{"text":"Say running a kitchen has nothing to do with that","then":"The cousin shrugs, and the teasing loses its footing.","best":true},{"text":"Laugh it off without saying anything back","then":"The joke's premise, that it's unmanly, goes unchallenged."},{"text":"Point out you're better at it than most","then":"The cousin laughs, conceding the point without dropping the premise."},{"text":"Avoid the kitchen for a few days to dodge it","then":"Nobody notices you've stopped, except maybe Pooja."}],"why":"Naming that the joke's premise is wrong, plainly, is what actually holds your ground."},{"prompt":"Months later, your father-in-law visits and sees you cooking without a comment. What do you do?","options":[{"text":"Carry on as normal. It's how the house runs now","then":"He watches for a moment, then sits down, unbothered.","best":true},{"text":"Make a point of mentioning how long you've done this","then":"Your father-in-law shifts in his seat, the old topic stirred up again."},{"text":"Ask him if he's finally okay with it","then":"He hesitates, unsure how to answer a question that wasn't really open anymore."},{"text":"Joke that Pooja finally 'let' you take over","then":"The old framing, that she allowed it, quietly returns."}],"why":"Simply carrying on, without reopening the old joke, is what shows the ownership has genuinely settled."}],"debrief":"Family pressure is where ownership quietly slips; you can hold it warmly without a fight.","relearn":"Hold your owned domains warmly with family; handing them back for peace undoes the split."},
  {"id":"ep-921","cat":"helping-vs-owning","type":"branch","persona":"Karthik","source":"stop being delegated to","hook":"You want a fair split but keep slipping into 'just tell me jobs' mode.","steps":[{"prompt":"Pooja hands you the electricity bill to pay, like she has for years. What do you do?","options":[{"text":"Take on all the bills and due dates as yours","then":"She blinks, surprised, then hands over the whole folder.","best":true},{"text":"Pay this one and wait for the next job","then":"The next bill comes the same way, one at a time."},{"text":"Ask her to put the bills on a shared calendar","then":"She sets it up, and she's still the one deciding what goes on it."},{"text":"Suggest an app that splits bills automatically","then":"The app tracks amounts, but she's still the one who checks it."}],"why":"Taking the whole domain at once, not one bill at a time, is what stops the delegating."},{"prompt":"A subscription renewal slips through and gets charged twice. What do you do?","options":[{"text":"Sort the refund, then tell her it's handled","then":"You sort it first and tell Pooja afterwards, so she has nothing to chase.","best":true},{"text":"Tell her, and ask her to keep an eye on it too","then":"She agrees, and the checking stays partly hers."},{"text":"Ask her how she used to catch these","then":"She explains her old method, still halfway managing it with you."},{"text":"Let it go. It's a small amount","then":"Small slips add up, and nobody's actually tracking the pattern."}],"why":"Fixing it yourself, then telling her it's handled, shows the domain runs without her checking."},{"prompt":"The landlord texts Pooja about next month's rent increase, as usual. What do you do?","options":[{"text":"Ask the landlord to message you, with Pooja copied","then":"He saves your number, and the next reminder comes to you, with Pooja copied in.","best":true},{"text":"Wait for Pooja to forward you the details","then":"She forwards it with a note on when to pay, like always."},{"text":"Offer to pay the difference yourself this month","then":"Pooja thanks you, and the next rent message still comes to her."},{"text":"Tell Pooja to push back on the increase","then":"She spends an evening negotiating with him on her own."}],"why":"Moving the messages to you is what stops rent routing through her as a job to hand out."},{"prompt":"It's the first of the month, and Pooja starts working out what's due, out of habit. What do you do?","options":[{"text":"Say the due dates are yours, keeping the accounts open to her","then":"She nods, relieved. The due dates now reach you first, and every account stays open to her.","best":true},{"text":"Let her track this month's dates, just to be safe","then":"'Just this once' becomes a habit that never quite ends."},{"text":"Ask her to send you whatever needs paying each month","then":"She sends three, and stays the one deciding what's due."},{"text":"Say nothing and let her carry on tracking as before","then":"She works out every due date, and pays one bill herself while she's there."}],"why":"Owning the due dates yourself, with the accounts still open to her, is what lets her stop tracking."},{"prompt":"Six months on, a cousin jokes that wives always end up handling the money side. What do you say?","options":[{"text":"Say it's for either of you, not hers by default","then":"Your cousin grins, then admits his wife pays every bill at home.","best":true},{"text":"Laugh and say Pooja does have the head for it","then":"Everyone nods, and in the family's eyes the bills stay hers."},{"text":"Say you help out with the money side a lot","then":"Your cousin nods, and 'helping out' keeps it Pooja's area."},{"text":"Change the subject. Money talk is boring","then":"The joke stands, and nobody wonders who tracks the bills."}],"why":"Saying it's for either of you, not her by default, holds the whole area open to owning."}],"debrief":"Delegated jobs keep her as the manager; take an entire area so its managing isn't hers.","relearn":"Take a whole area like bills so it never reaches her; delegated jobs keep her the delegator."},
  {"id":"ep-922","cat":"helping-vs-owning","type":"branch","persona":"Karthik","source":"invisible half","hook":"She says she's exhausted even though you 'do half the chores'.","steps":[{"prompt":"She says it again, tired, after you point out you vacuumed and did dishes. What do you do?","options":[{"text":"Ask to see the invisible planning","then":"She walks you through it, and it's far more than you expected.","best":true},{"text":"List the chores you did today, again","then":"She listens, patiently, waiting for you to notice what's missing."},{"text":"Suggest she's just having a hard week","then":"She goes quiet, and doesn't bring it up again tonight."},{"text":"Offer to do one extra chore to help","then":"She thanks you, still holding the same mental list."}],"why":"Asking to see the invisible planning, not listing chores, is what finds what's actually exhausting her."},{"prompt":"That evening, you watch how much she's juggling before dinner's even started. What do you do?","options":[{"text":"Take on half of that invisible list today","then":"She looks lighter almost immediately, one less thing to carry alone.","best":true},{"text":"Say you'll help with those when she flags them","then":"She nods, already dreading having to remember to ask."},{"text":"Suggest she write it all down so it's clearer","then":"She starts a list, sighing halfway through it."},{"text":"Say you had no idea it was this much","then":"She nods, and picks the evening back up alone."}],"why":"Taking half the invisible list, not just noting it exists, is what actually shares the load."},{"prompt":"A week later, it's 7pm on Tuesday and nobody has planned dinner. What do you do?","options":[{"text":"Sort dinner yourself, and plan the week's meals","then":"Dinner's on the table by eight, and the week's menu goes on the fridge.","best":true},{"text":"Ask her to plan just this one. You're swamped","then":"One favour like this is how planning quietly slides back."},{"text":"Order in tonight and leave planning for later","then":"Dinner's sorted, and next Tuesday looks exactly the same."},{"text":"Ask her what she had in mind for tonight","then":"She had a plan, and she ends up cooking it too."}],"why":"Sorting tonight and planning ahead yourself is what puts the invisible part in your hands."},{"prompt":"A month later, she mentions she still wakes up running through tomorrow's jobs. What do you do?","options":[{"text":"Ask which of those jobs you could take on fully","then":"She names three, and you take them, reminders and all.","best":true},{"text":"Tell her she worries too much. It all gets done","then":"She laughs it off, and lies awake again that night."},{"text":"Offer to help with anything she writes down","then":"She writes a list for you, and still runs through it at night."},{"text":"Suggest a meditation app to help her switch off","then":"She tries it, and the list in her head stays just as long."}],"why":"Taking whole jobs off her mind, not just easing the worry, is what shares the invisible load."}],"debrief":"Splitting visible chores while she does all the planning isn't equal; own half the invisible work.","relearn":"If she's exhausted despite split chores, take half the invisible planning, not just the tasks."},
  {"id":"ep-923","cat":"helping-vs-owning","type":"role-play","persona":"Karthik","source":"laundry is mine","hook":"You've been doing the laundry for weeks, and today's pile is especially large.","setup":"Your wife folds a towel and smiles at the fresh laundry pile.","steps":[{"prompt":"Your wife says: \"Thanks for helping with the laundry today.\"","options":[{"text":"\"Laundry's mine to run now. No need to thank me.\"","then":"She pauses. \"Oh. Okay, noted.\"","best":true},{"text":"\"No problem, happy to pitch in whenever.\"","then":"She smiles. \"You're sweet for doing that.\""},{"text":"\"It's fine. I don't mind helping sometimes.\"","then":"She says, \"Still, thanks for today.\""},{"text":"\"You really don't need to thank me every time.\"","then":"She looks unsure. \"Sorry, I just meant it kindly.\""}],"why":"Saying it's yours to run, not thanking-worthy help, is what actually reframes the chore."},{"prompt":"She asks: \"Should I still separate the delicates before you wash?\"","options":[{"text":"\"No, I'll sort all of that myself.\"","then":"She pauses. \"Okay, that's one less thing for me to remember.\"","best":true},{"text":"\"Sure, that would help me out.\"","then":"She nods. \"Alright, I'll keep sorting them then.\""},{"text":"\"Only the tricky ones, maybe.\"","then":"She says, \"So I'm still deciding what's tricky.\""},{"text":"\"I'll ask if I ever get confused.\"","then":"She says, \"So I'm still the one with the answers.\""}],"why":"Telling her she doesn't need to sort anything is what removes her from tracking it at all."},{"prompt":"Her mother asks you: \"Shouldn't she be the one doing the washing?\"","options":[{"text":"\"It doesn't have to be her. It's my job now.\"","then":"Her mother blinks. \"Well. Times have changed, I suppose.\"","best":true},{"text":"\"I'm just helping out while she's busy.\"","then":"Her mother nods. \"Good. As long as it's only for now.\""},{"text":"\"I do the washing. She does the folding.\"","then":"Her mother says, \"Good. So she still keeps a hand in.\""},{"text":"\"Ask her. She'd explain it better.\"","then":"Her mother turns to your wife. \"Is he doing it properly?\""}],"why":"Calling it your job, not a favour or a stopgap, is what makes the ownership clear outside the house too."}],"relearn":"Reframe a thanked-for chore as a domain you own, so she stops tracking it at all."},
  {"id":"ep-924","cat":"helping-vs-owning","type":"role-play","persona":"Karthik","source":"never ask again","hook":"Pooja has asked about your sister's school fees every month for a year.","setup":"Pooja glances at her phone, checking the date again.","steps":[{"prompt":"Pooja asks: \"Did you remember the school fees this month?\"","options":[{"text":"\"You never have to ask again. That's fully mine now.\"","then":"Pooja looks relieved. \"Okay. Thank you for saying that.\"","best":true},{"text":"\"Yes, I'll do it today. Thanks for reminding me.\"","then":"Pooja smiles. \"Okay, I'll check again next month then.\""},{"text":"\"I remembered. Don't worry about it.\"","then":"Pooja nods. \"I'll still probably ask, just in case.\""},{"text":"\"It's on my list somewhere.\"","then":"Pooja says, \"Somewhere doesn't sound very certain.\""}],"why":"Telling her she never has to ask again is what actually removes the remembering from her."},{"prompt":"Pooja asks: \"March nearly got missed. What if work gets that busy again?\"","options":[{"text":"\"Then catching it is on me, not your reminders.\"","then":"Pooja nods slowly. \"Okay, that sounds fair.\"","best":true},{"text":"\"You can remind me if it gets that busy.\"","then":"Pooja says, \"So I'm still the backup for this.\""},{"text":"\"It won't happen again. I'll be more careful.\"","then":"Pooja sighs. \"I hope so. I might still keep an eye.\""},{"text":"\"We'll figure it out together if it happens.\"","then":"Pooja says, \"So I'm still part of catching the slip.\""}],"why":"Owning the catch yourself, not her reminder, is what makes the promise actually hold."},{"prompt":"At lunch, Pooja's mother says: \"In our house, the wife keeps track of payments like these.\"","options":[{"text":"\"In ours, the one who pays keeps track. That's me.\"","then":"Her mother raises an eyebrow. \"Hm. Pooja must be relieved.\"","best":true},{"text":"\"Pooja's much better at remembering than me.\"","then":"Her mother smiles. \"See? Women just have the head for it.\""},{"text":"\"She does remind me, and it really helps.\"","then":"Her mother nods. \"Good. Someone has to keep you on track.\""},{"text":"\"We handle it together these days.\"","then":"Her mother says, \"So she still keeps an eye on it, then.\""}],"why":"Saying the one who pays keeps track, not the wife, is what ends the chasing for good."}],"relearn":"Owning means she never has to ask again; take the remembering, not just the doing."},
  {"id":"ep-925","cat":"helping-vs-owning","type":"role-play","persona":"Pooja","source":"handing over a domain","hook":"You want your partner to fully own the bills so you can stop managing them.","setup":"It's the start of the month, bills already piling up on the counter.","steps":[{"prompt":"Karthik says: \"I can handle the bills. Just send me the list.\"","options":[{"text":"\"Take them as yours, start to finish. I'll stop tracking dates.\"","then":"Karthik pauses. \"Okay. I'll set up my own reminders.\"","best":true},{"text":"\"Here's the list, and I'll remind you closer to the dates.\"","then":"Karthik says, \"Sounds good. Just ping me.\""},{"text":"\"Maybe start with just one bill and see how it goes.\"","then":"Karthik says, \"Sure, which one do you want to hand over?\""},{"text":"\"Let's put them all on a shared calendar we both check.\"","then":"Karthik says, \"Sure. So we both keep an eye on it.\""}],"why":"Handing over the whole domain, not the list, is what actually lets you stop tracking it."},{"prompt":"Karthik asks: \"What happens if a due date gets missed early on?\"","options":[{"text":"\"Then you catch it and fix it, not me.\"","then":"Karthik nods. \"Fair. I'll build in my own buffer.\"","best":true},{"text":"\"I'll just remind you if I notice it's close.\"","then":"Karthik says, \"Okay, so you're still half watching it.\""},{"text":"\"Let's check in together the first couple of months.\"","then":"Karthik says, \"Sure, so it's not fully mine yet.\""},{"text":"\"Set a reminder and I'll double check it landed.\"","then":"Karthik says, \"So you're still confirming it. Got it.\""}],"why":"Saying he catches his own slip, not you, is what makes the domain genuinely his."},{"prompt":"A late fee shows up on one bill. Karthik says: \"Sorry, that one slipped.\"","options":[{"text":"\"Okay, that's yours to sort. I won't step in.\"","then":"Karthik says, \"Got it. I'll call and fix it today.\"","best":true},{"text":"\"Don't worry. I'll call and sort the fee.\"","then":"Karthik says, \"Thanks, appreciate it.\""},{"text":"\"It's fine. We'll just be more careful together.\"","then":"Karthik says, \"Yeah, let's both keep an eye.\""},{"text":"\"Maybe I should take that one bill back.\"","then":"Karthik says, \"Okay, if you think that's easier.\""}],"why":"Letting him sort his own slip is what keeps the whole domain his, even when it wobbles."},{"prompt":"A week later, Karthik asks: \"Should I still send you a screenshot each time I pay a bill?\"","options":[{"text":"\"No need. I trust they're yours to handle.\"","then":"Karthik nods. \"Okay. I'll stop sending them.\"","best":true},{"text":"\"Yes, just so I know nothing's slipped.\"","then":"Karthik says, \"Okay, so you're still keeping track.\""},{"text":"\"Only for the big ones, like rent.\"","then":"Karthik says, \"So you still decide which ones matter.\""},{"text":"\"Maybe for a few more months, till it settles.\"","then":"Karthik says, \"Sure. Tell me when I can stop, then.\""}],"why":"Letting go of the updates, not just the paying, is what proves the domain is fully his."}],"relearn":"Hand over a whole domain start to finish; keeping the reminders means you still own it."},
  {"id":"ep-926","cat":"helping-vs-owning","type":"role-play","persona":"Pooja","source":"build your own list","hook":"Karthik wants to do more at home, but waits for you to tell him what.","setup":"Tonight, he finds you writing the week's to-do list.","steps":[{"prompt":"Karthik says: \"I'll help more. Just make me a list each morning.\"","options":[{"text":"\"The list itself is the tiring part.\"","then":"Karthik pauses. \"Oh, I hadn't thought of it that way.\"","best":true},{"text":"\"Okay, I'll leave one on the fridge each night.\"","then":"Karthik says, \"Perfect, that works for me.\""},{"text":"\"I'll text you a list, so you have it at work.\"","then":"Karthik grins. \"Even better. I'll check it at lunch.\""},{"text":"\"Fine, but you owe me for the extra effort.\"","then":"Karthik says, \"Deal. I appreciate it.\""}],"why":"Naming that the list itself is the tiring part is what shifts him toward owning, not just doing."},{"prompt":"Karthik asks: \"What's the one thing you'd most like off your plate?\"","options":[{"text":"\"Take the kitchen, start to finish.\"","then":"Karthik nods. \"Alright, I'll figure out what that even involves.\"","best":true},{"text":"\"Whatever's easiest for you to start with.\"","then":"Karthik shrugs. \"Let's say the bins, then. That's simple.\""},{"text":"\"I'll pick something and let you know.\"","then":"Karthik says, \"Okay, just tell me when you've decided.\""},{"text":"\"Anything, as long as it's off my plate.\"","then":"Karthik looks around. \"Sure, I'll grab something small for now.\""}],"why":"Naming a whole real area, not the easiest task, is what makes it a genuine domain."},{"prompt":"A week in, Karthik asks: \"Are you okay with how I've been doing things?\"","options":[{"text":"\"Your way is fine. It doesn't need to match mine.\"","then":"Karthik relaxes. \"Okay, that actually helps.\"","best":true},{"text":"\"Just do it the way I usually do it.\"","then":"Karthik says, \"Okay, so I'm still following your method.\""},{"text":"\"Close enough. I'll tidy up after if needed.\"","then":"Karthik says, \"So you're still finishing it sometimes.\""},{"text":"\"Let me show you my way. It's quicker.\"","then":"Karthik says, \"Alright, so it's still kind of yours.\""}],"why":"Letting it be his own way, not yours, is what makes the domain actually his to run."}],"relearn":"The list-making is the tiring part; ask your partner to own an area and build their own list."},
  {"id":"ep-927","cat":"helping-vs-owning","type":"role-play","persona":"Pooja","source":"his own way","hook":"Karthik's been putting off taking laundry on as fully his.","setup":"Tonight, he's staring at the washing machine settings.","steps":[{"prompt":"Karthik says: \"What if I get it wrong and mess it up?\"","options":[{"text":"\"Owning it your way is fine. It doesn't have to match mine.\"","then":"Karthik looks relieved. \"Okay, that helps actually.\"","best":true},{"text":"\"Just follow the same steps I always do.\"","then":"Karthik nods. \"Okay, I'll try to copy your way exactly.\""},{"text":"\"You won't. Don't worry about it too much.\"","then":"Karthik says, \"Easy for you to say. You've done it for years.\""},{"text":"\"Check with me before you start, just in case.\"","then":"Karthik says, \"Okay, so I'll ask you first.\""}],"why":"Saying his way is fine, not yours, is what actually lets him take real ownership."},{"prompt":"Karthik asks: \"What if I shrink something by mistake early on?\"","options":[{"text":"\"Then you'll learn from it, same as I did once.\"","then":"Karthik smiles. \"Fair enough. I guess everyone does.\"","best":true},{"text":"\"I'll check the first few loads, just to be safe.\"","then":"Karthik says, \"Okay, so you're still watching for now.\""},{"text":"\"Try to be extra careful with the wool things.\"","then":"Karthik says, \"Got it. I'll be careful with those specifically.\""},{"text":"\"Maybe skip the wool items for now.\"","then":"Karthik says, \"Okay, so that part stays yours.\""}],"why":"Letting him learn from his own mistake is what makes the domain genuinely his to run."},{"prompt":"A month later, Karthik says: \"I've actually changed how I sort it from your old way.\"","options":[{"text":"\"It's your system to build now.\"","then":"Karthik says, \"Thanks, that actually feels like mine.\"","best":true},{"text":"\"As long as it still works, sure.\"","then":"Karthik nods. \"It does, I promise.\""},{"text":"\"Just don't change the detergent brand, please.\"","then":"Karthik shrugs. \"Okay, I'll leave that part as is.\""},{"text":"\"Tell me what you changed. I'm curious.\"","then":"Karthik hesitates. \"Why? Are you going to check it?\""}],"why":"Letting him build his own system is what proves the domain is actually his, not a copy of yours."}],"relearn":"Let your partner own a domain their own way; insisting it match yours keeps you in charge of it."},
  {"id":"ep-928","cat":"helping-vs-owning","type":"role-play","persona":"Karthik","source":"bedtime is mine","hook":"You want to claim cooking dinner every night as fully your domain.","setup":"Pooja drops her bag and stares into the fridge.","steps":[{"prompt":"Pooja says: \"I don't know what to make again tonight.\"","options":[{"text":"\"Dinner's mine now: planning, cooking, the lot.\"","then":"Pooja looks stunned. \"Wait, really, every night?\"","best":true},{"text":"\"I can cook sometimes if you're really tired.\"","then":"Pooja says, \"Sometimes helps, but tonight's still on me.\""},{"text":"\"How about I cook, and you just plan?\"","then":"Pooja says, \"Okay, so I'm still deciding every night.\""},{"text":"\"Order in tonight to make it easier.\"","then":"Pooja says, \"That solves tonight, not the rest of the week.\""}],"why":"Claiming the whole routine, planning and cooking, not a slice of it, is what actually lets her switch off."},{"prompt":"A week later, Pooja says: \"Dinner is still on my mind most of the day.\"","options":[{"text":"\"Dinner's mine end to end. Menus, shopping, cooking.\"","then":"Pooja exhales. \"Okay. I'd love to not think about it.\"","best":true},{"text":"\"Just tell me what you want and I'll make it.\"","then":"Pooja sighs. \"That's still me deciding, just out loud.\""},{"text":"\"Let's get a meal-kit plan so nobody decides.\"","then":"Pooja asks, \"Okay. And who picks the boxes each week?\""},{"text":"\"You're overthinking it. Anything is fine.\"","then":"Pooja frowns. \"Anything still has to be decided by someone.\""}],"why":"Taking the deciding, not just the cooking, is what makes dinner fully yours instead of hers on call."},{"prompt":"Pooja calls out: \"Something smells like it's burning in there!\"","options":[{"text":"\"I've got it. Give me a minute.\"","then":"Pooja calls back, \"Okay. I'm staying out of there.\"","best":true},{"text":"\"Can you grab the backup takeaway menu?\"","then":"Pooja comes in. \"Here. Should I just order for us?\""},{"text":"\"It's fine. Dinner's just going to be late.\"","then":"Pooja calls back, \"How late? Should I start something else?\""},{"text":"\"Maybe you should just take over tonight.\"","then":"Pooja walks in, sighing. \"Fine. Move over.\""}],"why":"Handling the mess yourself, without pulling her in, is what proves the domain can stay fully yours."},{"prompt":"A month later, Pooja asks: \"Should I take dinner back on the nights you work late?\"","options":[{"text":"\"No. I'll plan around those nights myself.\"","then":"Pooja smiles. \"Okay. Then I'll stop keeping a backup plan.\"","best":true},{"text":"\"Yes please. Those nights are really hard.\"","then":"Pooja says, \"Okay. So I'll need to keep track of your schedule.\""},{"text":"\"Maybe just until work calms down.\"","then":"Pooja says, \"So it's still half mine, for now.\""},{"text":"\"Let's just order in on those nights.\"","then":"Pooja asks, \"Okay. Will you remember to order, or should I?\""}],"why":"Planning around your own late nights is what lets her trust dinner has moved to you for good."}],"relearn":"Claim a domain as wholly yours so your partner can switch off; 'sometimes if you're tired' isn't owning."},
  {"id":"ep-929","cat":"helping-vs-owning","type":"role-play","persona":"Pooja","source":"not a favour","hook":"Karthik's been quietly proud of how much he's been doing around the house.","setup":"Tonight, mid-dishes, he says something that gives it away.","steps":[{"prompt":"Karthik says: \"I feel like I'm doing you a favour with all this.\"","options":[{"text":"\"It's not a favour. It's your half of our home.\"","then":"Karthik pauses. \"Huh. I hadn't thought of it that way.\"","best":true},{"text":"\"Well, I do appreciate it either way.\"","then":"Karthik says, \"Good. Glad it's appreciated.\""},{"text":"\"It kind of is, until it becomes a habit.\"","then":"Karthik says, \"So for now it's still a favour. Got it.\""},{"text":"\"Just try not to think of it that way.\"","then":"Karthik says, \"Easier said than done, honestly.\""}],"why":"Naming it as his half, not a favour, is what actually makes the ownership equal."},{"prompt":"Karthik asks: \"So what happens if I just stop one day?\"","options":[{"text":"\"Then it's the same as me stopping my half.\"","then":"Karthik says, \"Fair. That would actually be a problem.\"","best":true},{"text":"\"I'd probably just pick it back up quietly.\"","then":"Karthik says, \"So it's still yours if I drop it.\""},{"text":"\"You wouldn't. You're too kind for that.\"","then":"Karthik says, \"Thanks. But would it matter if I did?\""},{"text":"\"I'd remind you until you started again.\"","then":"Karthik says, \"So you're still managing it, really.\""}],"why":"Treating it as equally essential as your own half is what makes the ownership real, not optional."},{"prompt":"Karthik says: \"My friend joked that I'm 'whipped' for doing all this at home.\"","options":[{"text":"\"Tell him it's not a favour. Just your half.\"","then":"Karthik laughs. \"I'll try that line on him next time.\"","best":true},{"text":"\"It's sweet that you don't mind the joke.\"","then":"Karthik says, \"Yeah, I guess I let it slide.\""},{"text":"\"I'll talk to your friend about it myself.\"","then":"Karthik says, \"Better not. It'll only make it awkward.\""},{"text":"\"Just ignore it. People will always talk.\"","then":"Karthik says, \"True, but it still stings a bit.\""}],"why":"Giving him the words to answer with is what helps the equal framing hold outside your home too."}],"relearn":"Owning a domain isn't a favour to your partner; it's an equal half of a shared home."},
  {"id":"ep-930","cat":"helping-vs-owning","type":"role-play","persona":"Pooja","source":"stop managing","hook":"You're tired of being the household's 'manager' and want to step back.","setup":"Tonight, Karthik notices you tensing up over the chore list again.","steps":[{"prompt":"Karthik asks: \"What can I do to take some pressure off you?\"","options":[{"text":"\"Take the whole groceries domain. I won't chase it.\"","then":"Karthik says, \"Okay. I'll figure out how that even works.\"","best":true},{"text":"\"Just help more when I ask. That'd be nice.\"","then":"Karthik says, \"Sure, just tell me when you need me.\""},{"text":"\"Notice things need doing before I have to say it.\"","then":"Karthik nods. \"I'll try to notice more. I promise.\""},{"text":"\"Honestly, I don't know. Just be more present.\"","then":"Karthik nods. \"Okay, I'll try to be around more.\""}],"why":"Naming a whole domain, and stepping back from chasing it, is what actually lifts the pressure."},{"prompt":"A week later, Karthik says: \"We're out of milk again. I didn't even notice.\"","options":[{"text":"\"Then it's yours to sort. I'll leave it with you.\"","then":"Karthik nods. \"Okay. I'll check the fridge before I shop.\"","best":true},{"text":"\"No worries. I'll pick some up on my way home.\"","then":"Karthik says, \"Thanks. You always catch these.\""},{"text":"\"I noticed yesterday. I thought you'd see it.\"","then":"Karthik frowns. \"Why didn't you just tell me?\""},{"text":"\"I'll text you each time we're running low.\"","then":"Karthik says, \"Perfect. That way I won't miss anything.\""}],"why":"Leaving the miss with him, not catching it yourself, is what lets the noticing move to him."},{"prompt":"Two weeks later, Karthik asks: \"You checked the fridge twice today. Are you keeping track of it?\"","options":[{"text":"\"A bit, out of habit. I'll try to stop.\"","then":"Karthik smiles. \"Okay. I'll try not to give you reasons.\"","best":true},{"text":"\"Only because you missed the milk that time.\"","then":"Karthik says, \"So you're still watching for my misses.\""},{"text":"\"No, I was just looking for a snack.\"","then":"Karthik laughs. \"Must be a very big snack.\""},{"text":"\"Someone has to, or we'd run out.\"","then":"Karthik says, \"So it's still really your job.\""}],"why":"Admitting the habit and stepping back is what lets the noticing become his instead of yours."},{"prompt":"Your mother offers: \"I can remind Karthik when things run out, if you like.\"","options":[{"text":"\"No need, Ma. He'll learn to notice it himself.\"","then":"Your mother shrugs. \"All right. I'll keep out of it.\"","best":true},{"text":"\"That would help. He forgets without reminders.\"","then":"Your mother says, \"Good. Between us, we'll keep him on track.\""},{"text":"\"Just remind me instead, and I'll tell him.\"","then":"Your mother says, \"So you're still the one passing it on.\""},{"text":"\"Maybe for the first month, just in case.\"","then":"Your mother says, \"Fine. Tell me when to stop, then.\""}],"why":"Keeping reminders out of it, even kind ones, is what lets the noticing become truly his."}],"relearn":"To stop being the manager, hand over a whole domain and genuinely stop chasing it."},
  {"id":"ep-931","cat":"helping-vs-owning","type":"role-play","persona":"Karthik","source":"own elder care","hook":"You want to own the in-laws' care logistics, not just drive when told.","setup":"Pooja's been quietly juggling her mother's care for months.","steps":[{"prompt":"Pooja says: \"I need to figure out amma's appointment again this week.\"","options":[{"text":"\"I'll own amma's appointments from now on.\"","then":"Pooja looks surprised. \"You want that whole thing?\"","best":true},{"text":"\"Tell me when it is and I'll drive her.\"","then":"Pooja nods. \"Okay, I'll keep tracking the rest then.\""},{"text":"\"Let me know if you need help this week.\"","then":"Pooja shrugs. \"I'll manage. I just thought I'd mention it.\""},{"text":"\"Ask her to reschedule to a day that suits us.\"","then":"Pooja shakes her head. \"That's not really the part that's hard.\""}],"why":"Owning the appointments, not just the driving, is what actually starts taking the load off her."},{"prompt":"A week later, Pooja says: \"Amma's medicines need refilling soon. Someone has to keep track of those.\"","options":[{"text":"\"I'll own the medicines and refills from now on.\"","then":"Pooja says, \"Okay. That's honestly a huge relief.\"","best":true},{"text":"\"You keep the medicine list. I'll just drive her.\"","then":"Pooja says, \"So the tracking's still on me, then.\""},{"text":"\"We'll figure the medicines out together.\"","then":"Pooja says, \"Together usually means I end up doing it.\""},{"text":"\"I'll help you remember when it's due.\"","then":"Pooja says, \"So I'm still the one who has to remember first.\""}],"why":"Owning the medicines, not just the driving, is what makes her care genuinely yours."},{"prompt":"The pharmacy calls and asks: \"Can you confirm the dosage change for her prescription?\"","options":[{"text":"\"Tell me the change. I'll check it with her doctor.\"","then":"The pharmacist says, \"Sure. It's the evening tablet, now half a dose.\"","best":true},{"text":"\"Let me pass you to my wife. She'd know.\"","then":"The pharmacist says, \"Thanks. I'll save her number for next time.\""},{"text":"\"Can you hold while I check with my wife?\"","then":"The pharmacist sighs. \"Sure. Maybe she should be our contact, then?\""},{"text":"\"Can you call back later? Now's not great.\"","then":"The pharmacist pauses. \"The refill can't go out until someone confirms.\""}],"why":"Checking it yourself, not routing the call to Pooja, is what keeps the domain from sliding back to her."},{"prompt":"That evening, Pooja's father asks: \"Should I still call Pooja about amma's check-ups?\"","options":[{"text":"\"Call me from now on. I'll keep track of them.\"","then":"Her father smiles. \"All right, beta. I'll call you first.\"","best":true},{"text":"\"Call Pooja. She knows amma's history best.\"","then":"Her father nods. \"Yes, she always has it all in her head.\""},{"text":"\"Call either of us, whoever picks up.\"","then":"Her father says, \"Then I'll call Pooja. She always answers.\""},{"text":"\"Call me, and I'll check the details with Pooja.\"","then":"Her father says, \"So Pooja still has the details, then.\""}],"why":"Becoming the one he calls, details and all, is what makes amma's care truly yours to hold."}],"relearn":"Owning elder care means holding the appointments and meds, not just driving when told."},
  {"id":"ep-932","cat":"helping-vs-owning","type":"role-play","persona":"Karthik","source":"no supervision","hook":"You notice your partner still 'supervises' the chores you've taken on.","setup":"It's been a week since you took over the dishes.","steps":[{"prompt":"Pooja says, re-checking a plate: \"Just making sure it's properly clean.\"","options":[{"text":"\"Let this be fully mine, no double checking needed.\"","then":"Pooja pauses. \"Okay. That'll take some trust, but okay.\"","best":true},{"text":"\"Go ahead if it makes you feel better.\"","then":"Pooja picks up another plate. \"It does. But I'd rather not have to.\""},{"text":"\"I'll try to do it properly so you don't have to.\"","then":"Pooja smiles. \"I'll still glance over, just in case.\""},{"text":"\"Tell me if I'm ever doing it wrong.\"","then":"Pooja says, \"So I'm still the one deciding what's wrong.\""}],"why":"Asking for no checking at all, not just better effort, is what removes the supervision."},{"prompt":"Pooja asks: \"What happens if something gets missed?\"","options":[{"text":"\"Then a spot gets missed, and I'll own that too.\"","then":"Pooja says, \"Fair enough. I guess that's allowed to happen.\"","best":true},{"text":"\"I'll be extra careful so that never happens.\"","then":"Pooja says, \"Okay, but I might still glance over sometimes.\""},{"text":"\"You can mention it if you happen to notice.\"","then":"Pooja says, \"So I'm still noticing for you, really.\""},{"text":"\"Set a standard and I'll try to match it.\"","then":"Pooja says, \"So it's still my standard, not yours.\""}],"why":"Letting a missed spot be yours to own, not a shared risk, is what makes the standard fully yours."},{"prompt":"A month later, Pooja says: \"I caught myself about to recheck the pans just now.\"","options":[{"text":"\"Leave them. If one's missed, it's mine to redo.\"","then":"Pooja laughs. \"Okay. I'm walking away from the pans.\"","best":true},{"text":"\"Go on then, just this once.\"","then":"Pooja sighs. \"That's what I said last week too.\""},{"text":"\"Have you found any problems lately?\"","then":"Pooja says, \"None, but I still feel the urge.\""},{"text":"\"Maybe spot check every so often anyway.\"","then":"Pooja says, \"Maybe just now and then, to be safe.\""}],"why":"Asking her to leave it, and owning any miss, is what makes the standard genuinely yours to keep."}],"relearn":"Owning includes the standard; ask to run it without supervision, not just do the task."},
  {"id":"ep-933","cat":"helping-vs-owning","type":"sort","hook":"Sort: owning a domain, or just being a helper?","items":[{"id":"a","text":"You track and pay every bill before it's due"},{"id":"b","text":"You pay a bill the day she flags it"},{"id":"c","text":"You plan the week's meals and shop for them"},{"id":"d","text":"You chop veg once she's decided the menu"},{"id":"e","text":"You book the kids' check-ups yourself"},{"id":"f","text":"You drive to the clinic when she's booked it"}],"bins":[{"id":"owns","label":"Owning","valence":"pos"},{"id":"helps","label":"Just helping","valence":"uhoh"}],"key":{"a":"owns","b":"helps","c":"owns","d":"helps","e":"owns","f":"helps"},"relearn":"Tracking, planning and booking yourself is owning; acting only once she's decided is just helping.","persona":"any","source":"owning vs helping II"},
  {"id":"ep-934","cat":"helping-vs-owning","type":"sort","hook":"Sort: who's still carrying the mental load here?","items":[{"id":"a","text":"You notice the gas cylinder is low and reorder it"},{"id":"b","text":"She reminds you the cylinder's nearly empty"},{"id":"c","text":"You remember the maid's day off and cover it"},{"id":"d","text":"She tells you the maid's off so you adjust"},{"id":"e","text":"You spot school forms are due and fill them"},{"id":"f","text":"She hands you the forms to sign"}],"bins":[{"id":"yours","label":"You carry it","valence":"pos"},{"id":"hers","label":"She still carries it","valence":"uhoh"}],"key":{"a":"yours","b":"hers","c":"yours","d":"hers","e":"yours","f":"hers"},"relearn":"Noticing and acting first means you carry the load; being reminded or handed it means she still does.","persona":"any","source":"who carries the load"},
  {"id":"ep-935","cat":"helping-vs-owning","type":"sort","hook":"Sort: real ownership, or ownership in name only?","items":[{"id":"a","text":"You run laundry on your own schedule, no asking"},{"id":"b","text":"You do laundry but ask her each time how"},{"id":"c","text":"You handle the cook's pay and leave yourself"},{"id":"d","text":"You pay the cook only when she works it out"},{"id":"e","text":"You plan and pack for trips unprompted"},{"id":"f","text":"You pack only the bag she lays out for you"}],"bins":[{"id":"real","label":"Real owning","valence":"pos"},{"id":"name","label":"In name only","valence":"uhoh"}],"key":{"a":"real","b":"name","c":"real","d":"name","e":"real","f":"name"},"relearn":"Running it on your own judgement is real owning; needing her to set it up each time is owning in name only.","persona":"any","source":"real vs name-only"},
  {"id":"ep-936","cat":"helping-vs-owning","type":"sort","hook":"Sort: lifts the planning off her, or leaves it on her?","items":[{"id":"a","text":"You keep the family calendar and add events yourself"},{"id":"b","text":"You attend events once she's put them in the diary"},{"id":"c","text":"You decide and book the weekend plans"},{"id":"d","text":"You go along to whatever she's organised"},{"id":"e","text":"You notice birthdays and arrange gifts"},{"id":"f","text":"You sign the card she's already bought"}],"bins":[{"id":"lifts","label":"Lifts planning","valence":"pos"},{"id":"leaves","label":"Leaves it on her","valence":"uhoh"}],"key":{"a":"lifts","b":"leaves","c":"lifts","d":"leaves","e":"lifts","f":"leaves"},"relearn":"Keeping the calendar and deciding plans lifts the planning; just turning up to what she arranged leaves it.","persona":"any","source":"lift the planning"},
  {"id":"ep-937","cat":"helping-vs-owning","type":"sort","hook":"Sort: an owner's move, or a helper's move?","items":[{"id":"a","text":"\"I've already sorted the electrician for Tuesday\""},{"id":"b","text":"\"Just tell me when the electrician's coming\""},{"id":"c","text":"\"I restocked the medicines, we were low\""},{"id":"d","text":"\"Let me know if we run out of anything\""},{"id":"e","text":"\"I've planned dinners for the whole week\""},{"id":"f","text":"\"What's the plan for dinner tonight?\""}],"bins":[{"id":"owner","label":"Owner's move","valence":"pos"},{"id":"helper","label":"Helper's move","valence":"uhoh"}],"key":{"a":"owner","b":"helper","c":"owner","d":"helper","e":"owner","f":"helper"},"relearn":"'I've already sorted it' is an owner's move; 'just tell me / let me know' is a helper's move.","persona":"any","source":"owner vs helper lines"},
  {"id":"ep-938","cat":"helping-vs-owning","type":"sort","hook":"Sort: this removes the reminding, or this needs reminding?","items":[{"id":"a","text":"You set your own alarm for the cook's salary date"},{"id":"b","text":"You wait for her nudge before paying the cook"},{"id":"c","text":"You renew the gas booking before it lapses"},{"id":"d","text":"You renew it only after she chases you"},{"id":"e","text":"You track the kids' fee dates yourself"},{"id":"f","text":"You pay fees the day she reminds you"}],"bins":[{"id":"removes","label":"Removes reminding","valence":"pos"},{"id":"needs","label":"Still needs reminding","valence":"uhoh"}],"key":{"a":"removes","b":"needs","c":"removes","d":"needs","e":"removes","f":"needs"},"relearn":"Tracking it yourself removes the reminding; waiting for a nudge keeps the reminding on her.","persona":"any","source":"removes reminding"},
  {"id":"ep-939","cat":"helping-vs-owning","type":"sort","hook":"Sort: this is the mental load, or this is the visible task?","items":[{"id":"a","text":"Knowing the fridge is nearly empty"},{"id":"b","text":"Carrying the grocery bags upstairs"},{"id":"c","text":"Remembering the in-laws visit Sunday"},{"id":"d","text":"Setting out the chairs for them"},{"id":"e","text":"Tracking which bills are still unpaid"},{"id":"f","text":"Tapping pay on the bill app"}],"bins":[{"id":"mental","label":"Mental load","valence":"uhoh"},{"id":"visible","label":"Visible task","valence":"neutral"}],"key":{"a":"mental","b":"visible","c":"mental","d":"visible","e":"mental","f":"visible"},"relearn":"Knowing, remembering and tracking are the mental load; carrying, setting out and tapping pay are visible tasks.","persona":"any","source":"mental vs visible"},
  {"id":"ep-940","cat":"helping-vs-owning","type":"reflect","hook":"Lensy: owning means your partner stops keeping a list of what you 'should' do. Sit with that.","prompt":"What's true for you?","options":["That list is heavy","I want it off them","Owning ends the list"],"affirm":"When you truly own a domain, the running-list of what you should do simply leaves their head.","relearn":"Owning a domain ends the mental running-list your partner keeps of what you should do.","persona":"any","source":"end the list"},
  {"id":"ep-941","cat":"helping-vs-owning","type":"reflect","hook":"Lensy: 'helping' quietly says the home is really theirs and you're a guest with chores.","prompt":"Notice how that lands.","options":["It's their home too","I'm not a guest","It's equally mine"],"affirm":"An equal home is as much yours to run as theirs; you're a co-owner, never a guest who helps out.","relearn":"You're a co-owner of your home, not a guest helping out; the home is equally yours to run.","persona":"any","source":"not a guest"},
  {"id":"ep-942","cat":"helping-vs-owning","type":"reflect","hook":"Lensy: the proof you've truly owned something is they never think about it again.","prompt":"What feels true?","options":["That's the real test","I want that for them","Their mind, freed"],"affirm":"The quiet test of owning is simple: your partner's mind is genuinely free of that whole domain.","relearn":"The test of owning is that your partner's mind is fully free of that domain.","persona":"any","source":"the quiet test"},
  {"id":"ep-943","cat":"helping-vs-owning","type":"reflect","hook":"Lensy: it can feel safer to wait to be told than to risk owning it wrong. That fear is normal.","prompt":"What's underneath for you?","options":["Fear of getting it wrong","Easier to be told","I'd rather own it"],"affirm":"Owning a domain your own way, wobbles and all, still lifts more load than waiting to be told ever can.","relearn":"Owning it imperfectly your own way lifts more load than safely waiting to be told.","persona":"any","source":"fear of owning"},
  {"id":"ep-944","cat":"helping-vs-owning","type":"reflect","hook":"Lensy: owning your half isn't losing your free time; it's gaining a partner who isn't burnt out.","prompt":"How does that sit?","options":["A fairer life","We both gain","Worth it for us"],"affirm":"Owning your half is never a loss; an un-exhausted partner and a fairer home are a gain for you both.","relearn":"Owning your half is a gain, not a loss; a fairer, less-exhausted home is better for you both.","persona":"any","source":"both gain"},
  {"id":"ep-945","cat":"helping-vs-owning","type":"reflect","hook":"Lensy: think of one domain you could take so fully your partner forgets it exists.","prompt":"Which one comes to mind?","options":["The kitchen","The bills","The kids' school stuff"],"affirm":"Picking one whole domain to own completely is a real, doable first step out of just helping.","relearn":"A doable first step is to pick one whole domain and own it so completely your partner forgets it.","persona":"any","source":"pick one domain"},
  {"id":"ep-946","cat":"helping-vs-owning","type":"reflect","hook":"Lensy: 'I did the dishes, didn't I?' can hide how much managing they still do.","prompt":"What do you notice?","options":["One task isn't the load","There's more unseen","I'll look closer"],"affirm":"One visible task done doesn't measure the load; the unseen managing is where the real weight sits.","relearn":"A single visible task isn't the load; the unseen managing is where the real weight is.","persona":"any","source":"one task isn't the load"},
  {"id":"ep-947","cat":"helping-vs-owning","type":"spot","hook":"Spot the two lines that are 'helping', not owning.","scene":[{"id":"a","text":"\"I've already booked the plumber for Saturday\"","trick":false},{"id":"b","text":"\"Just tell me what you need from the market\"","trick":true},{"id":"c","text":"\"I track and reorder the medicines myself\"","trick":false},{"id":"d","text":"\"Remind me and I'll pay the maintenance\"","trick":true},{"id":"e","text":"\"The kids' fees are handled, that's my job\"","trick":false}],"why":"'Just tell me' and 'remind me' keep your partner doing the noticing and tracking; that's helping, not owning.","relearn":"'Just tell me' and 'remind me' are helping; owning sounds like 'it's already handled, that's mine'.","persona":"any","source":"spot the helping"},
  {"id":"ep-948","cat":"helping-vs-owning","type":"spot","hook":"Spot the two signs the load is still entirely on her.","scene":[{"id":"a","text":"He pays bills the moment she flags each one","trick":true},{"id":"b","text":"He notices the fridge is empty and shops","trick":false},{"id":"c","text":"He keeps the kids' vaccine schedule himself","trick":false},{"id":"d","text":"She still has to remind him bin day is tomorrow","trick":true},{"id":"e","text":"He books and remembers the car service","trick":false}],"why":"Paying only when she flags, and her reminding him of bin day, mean she's still doing all the tracking.","relearn":"If she's still flagging and reminding, the tracking, the real load, is still entirely hers.","persona":"any","source":"spot the load on her"},
  {"id":"ep-949","cat":"helping-vs-owning","type":"spot","hook":"Spot the two phrases that secretly hand the managing back to her.","scene":[{"id":"a","text":"\"Make me a list and I'll do it all\"","trick":true},{"id":"b","text":"\"I'll plan and cook dinners this week\"","trick":false},{"id":"c","text":"\"I sorted the electrician, it's done\"","trick":false},{"id":"d","text":"\"Let me know if there's anything to do\"","trick":true},{"id":"e","text":"\"School admin's mine, you don't track it\"","trick":false}],"why":"'Make me a list' and 'let me know if there's anything' both leave the noticing and planning on her.","relearn":"'Make me a list' and 'let me know' hand managing back; owning needs no list and no prompting.","persona":"any","source":"spot the handback"},
  {"id":"ep-950","cat":"helping-vs-owning","type":"match","hook":"Match each helper move to its owner upgrade.","pairs":[{"left":"Waits for a list","right":"Builds the list themselves"},{"left":"Pays a bill when reminded","right":"Tracks every due date alone"},{"left":"Cooks once the menu's set","right":"Plans the whole week's meals"},{"left":"Drives to a booked appointment","right":"Books the appointment first"},{"left":"Asks 'what should I do?'","right":"Notices what's needed unasked"}],"relearn":"Every helper move has an owner upgrade: stop waiting and being told, start noticing and planning yourself.","persona":"any","source":"helper to owner upgrades"},
  {"id":"ep-951","cat":"helping-vs-owning","type":"match","hook":"Match each home domain to what fully owning it means.","pairs":[{"left":"Groceries","right":"Notice low stock, order, restock"},{"left":"Bills","right":"Track due dates and pay them all"},{"left":"Kids' school","right":"Hold fees, forms and the calendar"},{"left":"Elder care","right":"Manage appointments and medicines"},{"left":"The cook/maid","right":"Handle pay, leave and cover days"}],"relearn":"Owning a domain means holding its whole planning, not just doing one visible task inside it.","persona":"any","source":"domain ownership map"},
  {"id":"ep-952","cat":"helping-vs-owning","type":"match","hook":"Match the 'helping' phrase to why it leaves the load on her.","pairs":[{"left":"\"Just tell me\"","right":"She keeps doing the noticing"},{"left":"\"Remind me\"","right":"She keeps doing the tracking"},{"left":"\"Make me a list\"","right":"She keeps doing the planning"},{"left":"\"Is there anything to do?\"","right":"She keeps deciding the work"},{"left":"\"I'll help when you're stuck\"","right":"She stays the one in charge"}],"relearn":"Each 'helping' phrase quietly keeps her doing the noticing, tracking, planning or deciding for you.","persona":"any","source":"why helping phrases fail"},
  {"id":"ep-953","cat":"helping-vs-owning","type":"match","hook":"Match the unaware-partner belief to its gentle reframe.","pairs":[{"left":"\"I help loads already\"","right":"Helping isn't owning a domain"},{"left":"\"She's better at home stuff\"","right":"Tracking is a learnable habit"},{"left":"\"I earn more, so it's fair\"","right":"Pay can't transfer the load"},{"left":"\"Reminding me is nagging\"","right":"Owning ends the need to remind"},{"left":"\"It's my day off\"","right":"Home runs every day for both"}],"relearn":"Reframe each unaware belief warmly, never with blame: helping isn't owning, and the load is learnable to carry.","persona":"any","source":"belief to reframe"},
  {"id":"ep-954","cat":"helping-vs-owning","type":"match","hook":"Match each owned domain to the question your partner stops having to ask.","pairs":[{"left":"You own groceries","right":"\"Did we run out of anything?\""},{"left":"You own bills","right":"\"Did that get paid on time?\""},{"left":"You own school admin","right":"\"Are the forms submitted?\""},{"left":"You own the cook","right":"\"Was the salary sorted?\""},{"left":"You own bedtime","right":"\"Are the kids asleep yet?\""}],"relearn":"Truly owning a domain means a whole worry, a question your partner used to carry, simply disappears for them.","persona":"any","source":"questions that disappear"},
  {"id":"ep-990","cat":"keep-it-equal","type":"branch","persona":"any","source":"renegotiate after a move","hook":"You're relocating to Pune for work, and the routine you and Ananya balanced is gone.","steps":[{"prompt":"The moving truck's booked, but nobody's discussed the new routine. What do you do?","options":[{"text":"Sit down and rebuild the split for the new city","then":"You leave with a rough plan for the first month.","best":true},{"text":"Assume the same split will still work","then":"The move happens with no real plan in place."},{"text":"Focus on logistics now. Sort the routine later","then":"'Later' arrives busy, with no time actually set aside."},{"text":"Let Ananya plan it. She's better at this","then":"The planning becomes hers again, by default."}],"why":"Rebuilding the split deliberately is what keeps a big move from resetting old defaults."},{"prompt":"The new commute turns out to be far longer than either of you expected. What do you do?","options":[{"text":"Recalculate who has time for what, honestly","then":"You shift two chores to match the new hours fairly.","best":true},{"text":"Keep the old split. You'll adjust eventually","then":"The old split doesn't fit, and something quietly slips."},{"text":"Take on extra since you feel bad about the move","then":"You take on more, and the guilt quietly becomes the new normal."},{"text":"Ask Ananya to work out a new split for you both","then":"She draws it up alone, and the planning is hers again."}],"why":"Recalculating honestly, based on real time, is what keeps the split fair in the new city."},{"prompt":"Three months in, Ananya's team moves her to late shifts twice a week. What do you do?","options":[{"text":"Sit down and adjust the split for her new shifts","then":"You move two evening jobs to yourself and one morning job to her.","best":true},{"text":"Take the evenings over quietly, without discussing it","then":"You cover the evenings, and start to resent it a little by week three."},{"text":"Tell her the shifts are hers to manage around","then":"She juggles the evenings alone, and stops mentioning work."},{"text":"Wait until the shifts settle before changing anything","then":"The shifts settle, and so does an uneven split nobody chose."}],"why":"Adjusting the split together whenever hours change is what stops old defaults creeping back."}],"debrief":"A move resets the routine, so it's when to renegotiate the split, not assume the old one fits.","relearn":"Rebuild the split deliberately after a move; the old one won't fit a new routine."},
  {"id":"ep-991","cat":"keep-it-equal","type":"branch","persona":"Karthik","source":"renegotiate around study","hook":"Kavya just started an evening MBA; three nights a week she's out till late.","steps":[{"prompt":"Kavya's first late class is tonight, and dinner's suddenly just you. What do you do?","options":[{"text":"Take over those evenings end to end, cooking included","then":"You have dinner sorted before she even gets home.","best":true},{"text":"Order in tonight and figure out a system later","then":"Tonight's fine, and there's still no real plan for the rest."},{"text":"Wait to see how tired she is after class first","then":"Dinner waits too, until you finally just start cooking."},{"text":"Ask your mother to send food over for these nights","then":"The gap gets filled, just not by you."}],"why":"Taking the evenings on end to end, from the first class, is what actually protects her study time."},{"prompt":"A month in, Kavya mentions she's stressed about an assignment due the same night as class. What do you do?","options":[{"text":"Say you'll run all her class nights, dinner to dishes","then":"She visibly relaxes. \"That actually helps so much.\"","best":true},{"text":"Offer to help if she gets stuck with home stuff too","then":"The offer leaves her still holding some of it in her head."},{"text":"Suggest she skip class this week to catch up","then":"It solves the assignment, and costs her the class."},{"text":"Remind her the evenings were her choice to take on","then":"She nods, though the reminder doesn't loosen her shoulders."}],"why":"Taking those nights fully, not offering help, is what actually protects the study she chose to do."},{"prompt":"A cousin asks if it's 'a lot' having Kavya out three nights a week. What do you say?","options":[{"text":"Say it's fair. She'd do the same for your career","then":"Your cousin nods slowly. \"Fair enough. I hadn't seen it that way.\"","best":true},{"text":"Mention it's a lot some weeks, hoping she'll notice","then":"The hint doesn't quite land as anything she should act on."},{"text":"Say you don't mind helping her out till she's done","then":"Your cousin nods, and 'helping her out' makes it sound like a favour."},{"text":"Say Kavya owes you one for this","then":"Your cousin laughs, not realising you're half serious."}],"why":"Seeing it as taking turns backing each other's careers is what keeps it fair, not a favour."}],"debrief":"A partner's new study is a life-change; owning the gap it leaves keeps the split fair.","relearn":"When a partner takes on study, own the home gap it leaves rather than waiting to be asked."},
  {"id":"ep-992","cat":"keep-it-equal","type":"branch","persona":"Pooja","source":"renegotiate when help leaves","hook":"Your domestic help quit suddenly, and there's no replacement for two weeks.","steps":[{"prompt":"It's the first help-free morning, and the chores are piling up fast. What do you do?","options":[{"text":"Sit down and split the extra chores explicitly","then":"You both leave with a clear list for the gap.","best":true},{"text":"Let it land on whoever's 'always done it' this once","then":"The extra work quietly settles onto the same person."},{"text":"Power through it yourself. It's only two weeks","then":"Two weeks of extra load falls entirely on you."},{"text":"Suggest ordering more food to skip some chores","then":"It solves meals, and the rest of the extra work stays unsplit."}],"why":"Splitting the extra load explicitly is what keeps a sudden gap from defaulting to one person."},{"prompt":"By day four, Karthik asks how the extra chores have been going. What do you do?","options":[{"text":"Tell him honestly, and re-split the extra jobs","then":"You shift two jobs his way, and the rest of the week feels even.","best":true},{"text":"Say it's fine. No need to overthink it","then":"You both move on, and the extra work stays where it fell."},{"text":"Say you don't have energy to discuss it now","then":"The question goes unanswered, and nothing gets re-split."},{"text":"List everything you've done since day one","then":"Karthik gets defensive, and the talk turns into a tally."}],"why":"Saying honestly how it's landed, and re-splitting, keeps the gap from settling on one person."},{"prompt":"New help finally starts on Monday. What do you do?","options":[{"text":"Decide together who'll manage the new help","then":"Karthik takes her pay and days off, and you take the kitchen brief.","best":true},{"text":"Brief her yourself, since you know the routine","then":"The routine, and every question she has, now comes to you."},{"text":"Let whoever's home when she arrives brief her","then":"You're home first, so the briefing and every question after it land on you."},{"text":"Go back to how things were before the gap","then":"The old default returns, along with everything the gap showed you."}],"why":"Deciding together who manages the help is what stops the next gap defaulting to one person."}],"debrief":"When help disappears, the freed-up work is re-split on purpose, not absorbed by one person.","relearn":"When help leaves, split the extra work explicitly for the gap instead of letting it default."},
  {"id":"ep-993","cat":"keep-it-equal","type":"branch","persona":"any","source":"eldercare renegotiation","hook":"Rohit's mother Kamala moved in to recover after surgery; her care is a whole new job.","steps":[{"prompt":"Kamala needs help getting to the bathroom on the first night home. What do you do?","options":[{"text":"Help her, and wake Rohit so you share tonight","then":"Rohit takes the second trip, and you agree nights will alternate.","best":true},{"text":"Handle tonight yourself. Sort a schedule tomorrow","then":"Tonight quietly becomes the pattern for the nights after."},{"text":"Wait for Rohit to offer to take a turn","then":"He doesn't offer, unsure if it's expected of him."},{"text":"Book a night nurse so you don't need to discuss it","then":"The nurse helps with the nights, but you two still haven't talked about who does what."}],"why":"Bringing Rohit in from the first night is what keeps her care from defaulting to you."},{"prompt":"A week in, Kamala keeps asking specifically for Rohit, not you. What do you do?","options":[{"text":"Stay put and let Rohit answer her calls himself","then":"He steps up, and Kamala gets used to relying on him too.","best":true},{"text":"Step in anyway since you're usually closer by","then":"You keep answering, and the pattern quietly holds."},{"text":"Feel a bit hurt and say nothing about it","then":"The feeling stays unspoken, and nothing changes."},{"text":"Tell Rohit it's shared, then keep answering so Kamala isn't upset","then":"Rohit agrees it's shared, and you're still the one at her door."}],"why":"Letting him answer her calls himself is what makes the sharing real, not just agreed on paper."},{"prompt":"Kamala's physio appointments need someone to track twice a week. What do you do?","options":[{"text":"Split the appointments and each track your own","then":"You each know your days without checking with the other.","best":true},{"text":"Take the tracking since you're more organised","then":"Being 'more organised' becomes the reason it stays yours."},{"text":"Let Rohit track it, and remind him the day before","then":"Rohit goes to each one, and you still keep every date in your head."},{"text":"Agree to divide it later once things settle","then":"'Later' keeps sliding, and nobody's tracking it properly."}],"why":"Splitting and each tracking your own is what stops the appointments defaulting by habit or guilt."},{"prompt":"A relative praises you for 'taking such good care of her'. What do you say?","options":[{"text":"Say her care is Rohit's job as much as yours","then":"The relative pauses, then turns to ask Rohit how he's finding it.","best":true},{"text":"Say thank you, and let the credit stand","then":"The relative nods, and her care stays pictured as yours alone."},{"text":"Say it's just what family does","then":"The relative nods, still picturing it as mostly you."},{"text":"Deflect and change the subject","then":"The chance to correct the picture passes."}],"why":"Naming her care as Rohit's job too is what keeps it from being seen as yours alone."}],"debrief":"Caring for a parent is real work that arrives with a change; it's renegotiated, not gender-assigned.","relearn":"New eldercare is shared work to split openly, never a daughter-in-law's automatic duty."},
  {"id":"ep-994","cat":"keep-it-equal","type":"branch","persona":"Pooja","source":"catching mental-load drift","hook":"Six months in, you're quietly tracking every bill and appointment again.","steps":[{"prompt":"You catch yourself updating the shared calendar again, out of habit. What do you do?","options":[{"text":"Pause, name the drift to Karthik, and hand half back","then":"Karthik looks surprised. \"I didn't even notice it slid.\"","best":true},{"text":"Keep updating it. It's quicker to just do it yourself","then":"'Quicker' becomes the reason it stays yours again."},{"text":"Feel resentful and say nothing yet","then":"The resentment builds while the tracking stays unnamed."},{"text":"Wait until it's completely overwhelming to mention it","then":"By the time you mention it, it's a much bigger conversation."}],"why":"Naming the drift the moment you notice it is what stops it from settling back in for good."},{"prompt":"Weeks later, Karthik asks how all the tracking ended up with you without either of you deciding it. What do you do?","options":[{"text":"Explain it happened gradually, in small handoffs","then":"He nods. \"That makes sense. Let's watch for that pattern.\"","best":true},{"text":"Say you're not sure. It just sort of happened","then":"Karthik shrugs, and the same handoffs happen again next month."},{"text":"Blame the busy last few months for it","then":"Karthik nods, and the actual pattern goes unexamined."},{"text":"Say it's easier if you just keep doing it","then":"Karthik shrugs, relieved, and the tracking stays yours."}],"why":"Naming how it crept back, in small handoffs, is what helps you both actually catch it next time."},{"prompt":"A month later, Karthik forgets to add his dentist appointment to the shared calendar. What do you do?","options":[{"text":"Leave it to him, and suggest a monthly check","then":"He adds it that evening, and agrees to a first check-in on Sunday.","best":true},{"text":"Add it for him. It takes two seconds","then":"Two seconds at a time, the calendar becomes yours again."},{"text":"Remind him to add it before he forgets","then":"He adds it, and you're back to being his reminder."},{"text":"Say nothing and see if he misses it","then":"He misses it, and you end up rebooking it for him."}],"why":"Leaving his task with him, and setting a regular check, is what stops the drift settling back."}],"debrief":"The mental load drifts back to one person unless you catch it and hand part of it back.","relearn":"When you notice the tracking has crept back onto you, name it and hand half back."},
  {"id":"ep-995","cat":"keep-it-equal","type":"branch","persona":"any","source":"renegotiate around new hours","hook":"Aditya got a promotion with longer hours; your evenings together shrank overnight.","steps":[{"prompt":"The first week of the new hours, dinner's already on you every night. What do you do?","options":[{"text":"Sit down and re-plan chores around his new hours","then":"You redraw the split to fit the week that's actually happening now.","best":true},{"text":"Keep the old split. He's just adjusting for now","then":"The old split doesn't fit, and the gap quietly becomes yours."},{"text":"Pick up the slack quietly so he can settle in","then":"Picking up the slack quietly starts to feel permanent."},{"text":"Wait to see if the hours are actually here to stay","then":"Weeks pass with no plan while the hours stay the same."}],"why":"Re-planning together around the real new hours is what keeps the shift from silently landing on you."},{"prompt":"Aditya says he feels guilty that you're doing more right now. What do you do?","options":[{"text":"Say the plan should shift, not the guilt","then":"He relaxes. \"Okay, let's make sure the plan still fits.\"","best":true},{"text":"Tell him not to worry about it. It's fine","then":"The guilt passes, and the plan stays exactly the same."},{"text":"Agree he should feel a bit guilty about it","then":"He nods, quietly carrying the guilt instead of raising the split."},{"text":"Say you'll manage. You always do","then":"'You always do' quietly becomes the whole plan."}],"why":"Redoing the plan around his real hours, not his guilt, is what actually fixes the imbalance."},{"prompt":"Months later, Aditya's company asks him to travel two days a month. What do you do?","options":[{"text":"Plan together how those days change the split","then":"You swap two of his weekday jobs for weekend ones before the first trip.","best":true},{"text":"Cover those days yourself. It's only two a month","then":"Two days a month quietly adds up to one more thing that's yours."},{"text":"Tell him to turn the travel down for now","then":"He turns it down, and quietly resents it for months."},{"text":"Wait to see how the first trip goes","then":"The first trip comes, and dinner and bills land on you by default."}],"why":"Planning each new change together is what keeps his schedule from quietly becoming your extra shift."}],"debrief":"A promotion shifts the hours, so the split is renegotiated to match, not silently absorbed.","relearn":"When hours change, re-plan the split together rather than absorbing the slack."},
  {"id":"ep-996","cat":"keep-it-equal","type":"branch","persona":"any","source":"the monthly cadence","hook":"It's been months since you and Farhan actually talked about how the home runs.","steps":[{"prompt":"You notice a Sunday with nothing planned and no real conversation in sight. What do you do?","options":[{"text":"Suggest a standing monthly chai chat about the split","then":"Farhan says, \"Actually, that sounds like a good habit.\"","best":true},{"text":"Let the Sunday pass like all the others","then":"Another month goes by without either of you checking in."},{"text":"Wait until something feels unfair to bring it up","then":"Weeks pass, and it finally comes up mid-argument instead."},{"text":"Mention vaguely that you should talk sometime","then":"'Sometime' never quite turns into an actual time."}],"why":"Setting a standing time is what actually gets the check-in to happen, instead of staying a vague idea."},{"prompt":"Eventually, the two of you sit down for a first real chat about the split. It feels a little stiff. What do you do?","options":[{"text":"Keep it light and specific, not a big formal talk","then":"It settles into something easy after a few minutes.","best":true},{"text":"Cancel it. It clearly isn't working like this","then":"One stiff attempt ends the habit before it starts."},{"text":"Push through a long serious conversation anyway","then":"The heaviness makes it something to dread next month."},{"text":"Suggest skipping it if nothing's obviously wrong","then":"'Nothing obviously wrong' becomes the reason to stop checking."}],"why":"Keeping it light and specific is what makes a regular check-in something you'll actually keep doing."},{"prompt":"Three months on, Farhan says the laundry split has started to feel off. What do you do?","options":[{"text":"Talk it through now, and keep a monthly chat going","then":"You fix the laundry split in ten minutes, and book the next chat.","best":true},{"text":"Fix the laundry, and talk again only if needed","then":"The laundry's sorted, and the next drift waits months to surface."},{"text":"Turn it into a full review of everything","then":"An hour in, you're both tired and dreading the next one."},{"text":"Tell him he should've said something sooner","then":"Farhan goes quiet, less likely to raise the next thing."}],"why":"Fixing it now and keeping a regular chat is what catches drift before it grows."}],"debrief":"A simple regular cadence keeps the split honest; waiting means it shows up as built-up resentment.","relearn":"A standing monthly check-in keeps the split fair far better than waiting for something to break."},
  {"id":"ep-997","cat":"keep-it-equal","type":"branch","persona":"any","source":"notice and offer","hook":"Ritu's been low and stretched thin for weeks; the load between you has tilted.","steps":[{"prompt":"You notice Ritu's been going to bed earlier, worn out. What do you do?","options":[{"text":"Offer to take a chunk back while she recovers","then":"She looks relieved. \"That would actually help so much.\"","best":true},{"text":"Wait until she asks for help directly","then":"She doesn't ask, and keeps carrying the extra weight."},{"text":"Tell her to rest more. You'll manage as before","then":"She rests for a night, then quietly picks everything back up."},{"text":"Suggest she take a short holiday to reset","then":"A holiday helps briefly, and the tilted load waits for her return."}],"why":"Offering a specific chunk back, unasked, is what actually shares the dip instead of piling on."},{"prompt":"A few days later, Ritu says she hates feeling like she can't keep up. What do you do?","options":[{"text":"Say it's rebalancing, and take some jobs over","then":"She exhales. \"Okay. That makes it easier to accept.\"","best":true},{"text":"Reassure her she's doing great, and leave it there","then":"The reassurance is kind, and her list stays just as long."},{"text":"Offer to help, but say she owes you one","then":"She accepts, though something in her flinches at 'owes'."},{"text":"Tell her everyone has weeks like this","then":"She nods, and keeps pushing through on her own."}],"why":"Naming it as rebalancing, and acting on it, is what lets her accept the help without guilt."},{"prompt":"A few weeks later, Ritu's back to her usual pace. What do you do?","options":[{"text":"Check in together on how the load's split now","then":"You agree on a split that fits how things are now.","best":true},{"text":"Leave things as they've settled","then":"Whatever tilt the dip left quietly becomes the new normal."},{"text":"Wait for Ritu to raise it if something's off","then":"She doesn't, unsure whether it's hers to bring up."},{"text":"Ask if she's okay, expecting a quick yes","then":"She gives a quick yes before she's sure she means it."}],"why":"Checking in together is what moves the split back to fair, instead of leaving it stuck at the dip."}],"debrief":"When a partner is carrying more, an equal home notices and offers, rather than waiting to be asked.","relearn":"When your partner is stretched thin, offer to take some back instead of waiting to be asked."},
  {"id":"ep-998","cat":"keep-it-equal","type":"branch","persona":"any","source":"festival load-spike","hook":"Diwali's coming, and the cleaning, gifts, sweets and guest planning are all landing on your list.","steps":[{"prompt":"You realise you're already listing every festival job in your head. What do you do?","options":[{"text":"Divide the festival jobs with Manoj before it ramps up","then":"You split cleaning, gifts and sweets clearly, in writing.","best":true},{"text":"Start ticking off the list yourself. It's faster","then":"The whole festival quietly becomes your solo project."},{"text":"Wait for Manoj to notice and offer to help","then":"He doesn't notice, and the list keeps growing on you."},{"text":"Hire extra help for the cleaning part only","then":"Cleaning eases, and the rest of the list stays yours."}],"why":"Dividing the jobs before the season ramps up is what keeps Diwali from becoming a solo overload."},{"prompt":"Manoj asks what 'guest planning' actually involves. He's never really seen it. What do you do?","options":[{"text":"Walk him through every piece, invites to seating","then":"He blinks. \"I had no idea that was this much work.\"","best":true},{"text":"Just say it's 'organising who's coming'","then":"The vague answer leaves most of the real work invisible."},{"text":"Say don't worry. You've got a system for it","then":"The system, and the load, both stay yours."},{"text":"Hand him the guest list and move on","then":"He glances at the list, and doesn't ask what's behind it."}],"why":"Walking through the whole planning, not just the task, is what makes the invisible work visible."},{"prompt":"A relative calls asking about sweets for twenty guests, two days before Diwali. What do you do?","options":[{"text":"Pass the call to Manoj. Let him take this one","then":"He handles the order calmly, without looping you in.","best":true},{"text":"Take the call yourself. It's quicker to just answer","then":"The quick answer quietly pulls sweets back onto your list."},{"text":"Answer, then ask Manoj to confirm the order later","then":"Manoj confirms it after the fact, barely involved in the call."},{"text":"Let the call go to voicemail for now","then":"The order gets delayed, and nobody's clearly on it."}],"why":"Letting him take this one is what starts making a real part of it his."},{"prompt":"The week after Diwali, Manoj asks what you'd change for next year. What do you say?","options":[{"text":"Suggest splitting next year's jobs a month ahead","then":"Manoj puts a reminder for early October in both your calendars.","best":true},{"text":"Say it went fine, so there's nothing to change","then":"Next year, the list quietly starts building in your head again."},{"text":"Say you'll just start your own list earlier","then":"You start earlier, and the whole list is still yours."},{"text":"Suggest skipping the big family gathering next time","then":"Manoj agrees, and the cleaning, gifts and sweets still wait for you."}],"why":"Splitting next year's jobs early, together, is what keeps the festival from becoming a solo overload."}],"debrief":"Festivals are predictable load-spikes; the work and planning are split ahead, not defaulted.","relearn":"Split festival jobs and their planning before the season ramps, instead of defaulting it to one person."},
  {"id":"ep-999","cat":"keep-it-equal","type":"branch","persona":"any","source":"modelling for kids","hook":"Your little nephew Vihaan always reaches for Sana first when he visits, never you.","steps":[{"prompt":"He's staying the weekend, and it's nearly bath and story time. What do you do?","options":[{"text":"Take on bath and story yourself tonight","then":"Vihaan hesitates at bath time, then laughs through it with you.","best":true},{"text":"Leave it to Sana. He's more comfortable with her","then":"Sana does both, and Vihaan's habit gets one more night."},{"text":"Offer to take over whenever Sana needs a break","then":"Sana never quite asks, and you watch from the sofa."},{"text":"Take him out for ice cream first, the fun part","then":"He loves it, and still goes to Sana for bath and story."}],"why":"Taking on real routines yourself is what shows him both of you can care for him."},{"prompt":"A relative jokes that kids 'just have their favourites'. What do you say?","options":[{"text":"Say kids go to whoever does the caring","then":"The relative pauses, then nods slowly.","best":true},{"text":"Laugh along. It's probably true anyway","then":"Everyone chuckles, and the idea quietly sticks."},{"text":"Say nothing. It's not worth the debate","then":"The comment stands unchallenged in front of everyone."},{"text":"Say you're the fun one, and that's fine","then":"Everyone laughs, and the caring stays Sana's job in their eyes."}],"why":"Naming that it's about who does the caring, not preference, is what reframes the pattern."},{"prompt":"On his next visit, Vihaan asks Sana, not you, to help with his shoes. What do you do?","options":[{"text":"Say you'll help, and kneel down to do it","then":"He watches you tie the knot, and holds out the other shoe to you.","best":true},{"text":"Point him back to Sana. He's used to her","then":"Sana ties them, and the habit rolls into another visit."},{"text":"Ask Sana to show you how he likes them tied","then":"Sana shows you, and Vihaan still holds his foot out to her."},{"text":"Tell him big boys tie their own shoes","then":"He struggles, frustrated, until Sana steps in to finish."}],"why":"Stepping in yourself, visit after visit, is what shows him caring isn't one person's job."}],"debrief":"Children learn equality from what they see adults do; living it visibly is how they come to expect it.","relearn":"Children copy what they see, so visibly sharing the home models equality far better than claiming it."},
  {"id":"ep-1000","cat":"keep-it-equal","type":"branch","persona":"any","source":"work-from-home drift","hook":"You moved to work-from-home; somehow you've drifted into doing every daytime chore.","steps":[{"prompt":"A load of laundry needs doing at 2pm, and you're both technically working. What do you do?","options":[{"text":"Name that being home isn't owning it all","then":"Your partner pauses. \"You're right. That's not fair to assume.\"","best":true},{"text":"Just do it quickly between calls, like always","then":"'Quickly between calls' becomes the daily default again."},{"text":"Wait until evening so it doesn't interrupt work","then":"The chore waits for you specifically, every single day."},{"text":"Assume whoever's home just handles daytime things","then":"Weeks pass, and neither of you brings it up out loud."}],"why":"Naming that presence isn't duty is what actually opens the renegotiation."},{"prompt":"A few days later, you bring up how the daytime chores have been landing on you. What do you do?","options":[{"text":"Suggest splitting daytime tasks by schedule","then":"You draft a split based on real gaps in both calendars.","best":true},{"text":"Say you don't mind doing extra for now","then":"Your partner nods, relieved, and 'for now' quietly settles in."},{"text":"List everything you've done to make the point","then":"Your partner listens, a little defensive, and nothing actually changes."},{"text":"Suggest hiring help instead of resplitting","then":"Help arrives, and the daytime default habit stays unexamined."}],"why":"Splitting by actual schedule, not who happens to be home, is what fixes the real imbalance."},{"prompt":"A month later, your partner's office calls them back in three days a week. What do you do?","options":[{"text":"Re-split the daytime jobs around the new office days","then":"You swap laundry and deliveries to match whoever's home each day.","best":true},{"text":"Cover the chores on their office days, since you're home","then":"Being home quietly turns back into doing it all."},{"text":"Leave the current split as it is","then":"The split stops matching anyone's week, and chores pile up."},{"text":"Hire help for the days you're both busy","then":"Help covers those days, and nobody re-splits the rest."}],"why":"Re-splitting whenever schedules change is what keeps being home from meaning doing it all."}],"debrief":"Being home isn't the same as owning all the chores; a remote shift needs the split renegotiated.","relearn":"Working from home shouldn't default all the chores to you; renegotiate so presence isn't duty."},
  {"id":"ep-1001","cat":"keep-it-equal","type":"branch","persona":"any","source":"renegotiate around travel","hook":"Neha's new travel schedule starts Monday: three weeks a month, with the home entirely on you while she's away.","steps":[{"prompt":"It's Friday night, and neither of you has planned how the home will run. What do you do?","options":[{"text":"Re-split so she owns clear remote duties from afar","then":"You agree she'll handle bills and calls, even while travelling.","best":true},{"text":"Just hold everything until she's back each time","then":"Holding everything quietly becomes the new normal."},{"text":"Wait to see how the first trip actually goes","then":"The first trip passes with no plan, and the old default quietly sets in."},{"text":"Hire extra help to cover the gap instead","then":"Help covers tasks, and the two of you still haven't re-split."}],"why":"Giving her clear remote duties, not holding everything, is what keeps distance from meaning default."},{"prompt":"A delivery needs someone physically home to sign for it while she's mid-flight. What do you do?","options":[{"text":"Handle it yourself. It just needs someone home","then":"You sign for it, and don't make it a whole thing.","best":true},{"text":"Wait for her to land and text her right away","then":"The wait creates a small crisis over something small."},{"text":"Feel annoyed she's not reachable for this","then":"The annoyance builds over something a plan would have covered."},{"text":"Decide this travel thing is more trouble than it's worth","then":"One gap becomes a reason to resent the whole arrangement."}],"why":"Handling what needs you there yourself is what makes the arrangement work, remote duties and all."},{"prompt":"She's back for the week between trips, after three weeks of you carrying the home. What do you do?","options":[{"text":"Agree she runs the house this week, to even out the month","then":"She takes over the house, and you get your first real evening off in weeks.","best":true},{"text":"Keep doing everything. She just got back tired","then":"She spends the week resting instead of easing back in."},{"text":"Split this week evenly and ignore the weeks she was away","then":"It feels fair for a week, and the month still leans heavily on you."},{"text":"Ask her to catch up on the errands she missed","then":"She runs the errands, and the rest of the house stays on you."}],"why":"Her running the house this week evens out the month, instead of leaving the travel weeks all on you."},{"prompt":"Two months in, Neha mentions an extra trip next month. What do you do?","options":[{"text":"Talk through the split again before she books","then":"You agree she'll cover two weekends of housework to balance the extra week away.","best":true},{"text":"Say it's fine, and quietly absorb the extra week","then":"One more week lands on you, and nobody says it out loud."},{"text":"Ask her to turn down the extra trip","then":"She turns it down, and wonders if her career always has to give."},{"text":"Tell her she'll owe you for this one","then":"She laughs, unsure how much of it you mean."}],"why":"Re-splitting before each change, not absorbing it, is what keeps her travel from becoming your solo load."}],"debrief":"Heavy travel is a change to renegotiate around, with owned remote duties, not a solo load.","relearn":"When a partner travels a lot, re-split so they still own clear duties rather than defaulting it to you."},
  {"id":"ep-1002","cat":"keep-it-equal","type":"branch","persona":"any","source":"re-even after a crunch","hook":"A brutal work quarter just ended, weeks longer than you expected.","steps":[{"prompt":"With work easing off, you notice Devika's been running everything alone. What do you do?","options":[{"text":"Own the slide, thank her, and take your half back today","then":"She looks relieved. \"Thank you for actually noticing.\"","best":true},{"text":"Ease back in slowly over the next few weeks","then":"'Slowly' stretches out longer than either of you expects."},{"text":"Assume she'll mention it if it's still a problem","then":"She doesn't mention it, quietly waiting for you to notice."},{"text":"Move on now that you're finally less busy","then":"The slide from your crunch quietly becomes her new normal."}],"why":"Owning the slide and acting on it right away is what actually re-evens the load."},{"prompt":"A few days later, Devika opens up about almost saying something sooner. What do you do?","options":[{"text":"Tell her it's always okay to name it, even mid-crunch","then":"She nods. \"That actually helps me know for next time.\"","best":true},{"text":"Say you wish she'd said something earlier","then":"She nods, but something in her posture closes a little."},{"text":"Apologise repeatedly without changing anything yet","then":"The apology's warm, and nothing about the split moves yet."},{"text":"Promise your next busy quarter will be different","then":"She smiles politely, unconvinced anything's different yet."}],"why":"Telling her it's always okay to name it is what makes the next crunch easier to catch early."},{"prompt":"A month later, your manager warns another crunch is coming in spring. What do you do?","options":[{"text":"Agree with Devika to flag slides early this time","then":"You both agree to say it in the first week, not the fifth.","best":true},{"text":"Assume you'll both handle it the same way","then":"Spring comes, and the same quiet slide starts again, unnoticed."},{"text":"Suggest hiring help for spring instead","then":"Help arrives in spring, but nobody's watching for the slide itself."},{"text":"Plan to work late now, to shorten the crunch","then":"You work late for weeks, and Devika runs the home alone again."}],"why":"Agreeing on an early flag before the next crunch is what turns one repair into a lasting habit."}],"debrief":"A temporary cover isn't a new normal; when your crunch ends you own it, thank them and re-balance.","relearn":"When a crunch ends, own the slide it caused and take your share back instead of leaving it."},
  {"id":"ep-1003","cat":"keep-it-equal","type":"branch","persona":"Karthik","source":"warming to the cadence","hook":"Pooja suggests a monthly 'home review'; part of you finds it over-the-top.","steps":[{"prompt":"Pooja proposes the first review this Sunday. What do you do?","options":[{"text":"Agree to try it for a few months honestly","then":"Pooja smiles. \"That's all I'm asking. Just give it a real shot.\"","best":true},{"text":"Say it sounds like treating marriage like an office","then":"Pooja looks hurt, but says she'd still like to try it once."},{"text":"Agree, but plan to skip it if you're busy","then":"You nearly skip it for work, but Pooja moves it to Sunday evening."},{"text":"Suggest talking only when something's actually wrong","then":"Pooja isn't fully convinced, but the first review happens anyway on Sunday."}],"why":"Giving the review a real, honest try is how you find out if a light check-in actually works."},{"prompt":"The first review runs fifteen minutes and covers three small things. What do you do?","options":[{"text":"Admit it wasn't as bad as you expected","then":"Pooja laughs. \"See, not exactly a boardroom meeting.\"","best":true},{"text":"Stay quiet about how it actually went","then":"Your real reaction, good or bad, never gets said out loud."},{"text":"Point out it still felt a little unnecessary","then":"Pooja's face falls a little. \"Oh. Okay, noted.\""},{"text":"Suggest making it longer to cover more ground","then":"Next month's review runs forty minutes, and everyone's checking the clock."}],"why":"Admitting it went better than expected is what lets the habit keep earning your buy-in."},{"prompt":"Three months in, a busy month tempts you both to skip the review. What do you do?","options":[{"text":"Keep it, even if it's just ten minutes","then":"Ten minutes turns up one small drift, and you fix it on the spot.","best":true},{"text":"Skip it. Nothing big has come up lately","then":"Skipping once makes the next one easier to skip too."},{"text":"Leave it to Pooja to decide whether to hold it","then":"Pooja holds it, and the reviews quietly become her project."},{"text":"Push it to next month and do a longer one","then":"Next month's long review feels heavy, and you both put it off."}],"why":"Keeping the review short but steady, even when busy, is what makes the habit actually last."}],"debrief":"A light recurring review isn't cold; it's how couples keep fairness from quietly eroding.","relearn":"A short regular home review keeps fairness honest; it's structure, not coldness."},
  {"id":"ep-1004","cat":"keep-it-equal","type":"branch","persona":"Nisha","source":"plan ahead of a baby","hook":"You're trying for a baby; friends warn the load 'always falls on the mum' eventually.","steps":[{"prompt":"A friend repeats the warning over coffee, half joking. What do you do?","options":[{"text":"Bring it home tonight and start planning with Vikram","then":"You both agree to actually talk it through this week.","best":true},{"text":"Laugh along and figure you'll manage when it happens","then":"The warning gets brushed off instead of planned around."},{"text":"Feel anxious about it without mentioning it to Vikram","then":"The worry stays yours alone, unshared and unplanned."},{"text":"Decide you'll just do more since you carry the baby","then":"Carrying the baby quietly becomes carrying the whole load too."}],"why":"Raising it with Vikram now, before the baby arrives, is what turns a warning into an actual plan."},{"prompt":"A pregnancy checklist you come across mentions splitting care duties. What do you do?","options":[{"text":"Sit with Vikram and map feeds, appointments, chores","then":"You sketch a rough plan together, before anything's urgent.","best":true},{"text":"Skip it. You'll figure out specifics when the time comes","then":"'When the time comes' keeps being put off, and no specifics appear."},{"text":"Read it alone and mention it to him later","then":"'Later' keeps slipping without a real talk."},{"text":"Suggest Vikram read the checklist on his own first","then":"He skims it later, and nothing gets discussed together."}],"why":"Sitting down to map real areas now is what makes the plan concrete, not a vague intention."},{"prompt":"You're now pregnant, and a relative asks who'll take leave from work. What do you say?","options":[{"text":"Say you're hoping you'll both take leave","then":"The relative looks surprised, then interested to hear more.","best":true},{"text":"Say only you'll take leave. You're the mother","then":"The relative nods, the question already answered in everyone's head."},{"text":"Say Vikram's job probably can't flex for this","then":"The relative nods, and Vikram's actual say in it never comes up."},{"text":"Say you haven't really thought about it yet","then":"The relative smiles, already assuming she knows how it'll go."}],"why":"Planning to both take leave keeps the load from defaulting to you before the baby's even here."},{"prompt":"Vikram says he'd like some leave, but his manager hinted new fathers 'don't really need' it. What do you do?","options":[{"text":"Back him firmly in taking the leave","then":"Vikram feels supported, and holds his ground at work.","best":true},{"text":"Suggest he not push it, to avoid trouble at work","then":"Vikram lets the idea go, and the early months default to you."},{"text":"Say it's his call entirely. Stay out of it","then":"Vikram pushes back alone, and mentions it less after that."},{"text":"Feel frustrated but say nothing to him about it","then":"The frustration stays yours, and his leave goes undefended."}],"why":"Backing him to hold his ground is what keeps the baby's care from defaulting to you."},{"prompt":"The baby's due any day, and your mother offers to move in and take over the nights. What do you do?","options":[{"text":"Accept, and still plan the nights with Vikram","then":"Your mother takes meals and some nights, and you and Vikram share the rest.","best":true},{"text":"Accept. Vikram needs his sleep for work","then":"Your mother and you take the nights, and Vikram's part shrinks to weekends."},{"text":"Accept, and let Vikram decide how much to join in","then":"Vikram joins when he wakes up, which turns out to be rarely."},{"text":"Say you'll just take all the nights yourself","then":"You take every night, and sharing them never gets a start."}],"why":"Taking her help while keeping the nights shared with Vikram makes the load designed together, not left to drift."}],"debrief":"The biggest change is when to renegotiate in advance, so the load is shared by design, not drift.","relearn":"Plan how you'll split the baby load before it arrives; 'sort it later' lets it default."},
  {"id":"ep-1005","cat":"keep-it-equal","type":"branch","persona":"any","source":"agreed isn't forever","hook":"You and Imran agreed a split months ago, back when things were calmer.","steps":[{"prompt":"Imran admits the 'settled' split hasn't felt fair for a while. What do you do?","options":[{"text":"Treat it as out of date and re-open it honestly","then":"You both start listing what's actually changed since you agreed it.","best":true},{"text":"Remind him it was already agreed months ago","then":"The reminder shuts down the conversation before it starts."},{"text":"Ask him why he didn't say something sooner","then":"The question puts him on the defensive instead of moving forward."},{"text":"Agree to revisit it, sometime, once things calm down","then":"'Once things calm down' never quite seems to arrive."}],"why":"Treating 'settled' as out of date, not fixed, is what actually lets you fix what's changed."},{"prompt":"A few days later, Imran brings it up again: \"It's mostly the evenings. I never get any real downtime.\" What do you do?","options":[{"text":"Ask what a fair evening split would look like","then":"You sketch a new evening split together, on the spot.","best":true},{"text":"Say evenings have always been split this way","then":"Imran's shoulders drop a little, and the conversation stalls."},{"text":"Offer him one extra free evening a week","then":"Imran nods, though the rest of the week stays exactly the same."},{"text":"Suggest he's just more tired than usual lately","then":"Imran goes quiet, unconvinced that's really it."}],"why":"Asking what fair would actually look like is what turns the complaint into a workable new plan."},{"prompt":"A week later, Imran says there's something else that's been bothering him. What do you do?","options":[{"text":"Ask him to tell you, and listen before answering","then":"He mentions weekend cooking, relieved you asked him to go on.","best":true},{"text":"Say you can't take on another complaint right now","then":"Imran nods, and keeps the rest to himself."},{"text":"Guess what it is and start defending yourself","then":"Imran stops mid-sentence. \"That wasn't even it.\""},{"text":"Suggest saving it all for one big talk next month","then":"A month of small unfairness piles up before the big talk."}],"why":"Hearing him out right away is what stops small unfairness from building up quietly again."},{"prompt":"Months later, a friend asks if your split ever needs changing. What do you say?","options":[{"text":"Say yes. Splits need changing as life does","then":"Your friend looks surprised. \"I thought agreeing once was the goal.\"","best":true},{"text":"Say no. Once you agree, you should stick to it","then":"Your friend nods, and takes 'stick to it' home as advice."},{"text":"Say it changes sometimes, vaguely","then":"Your friend looks unconvinced, and the conversation moves on."},{"text":"Say only if someone complains loudly enough","then":"Your friend laughs, and hears that fairness waits for a fight."}],"why":"Saying splits need changing as life does is what keeps an agreed split open, and so fair."}],"debrief":"'Once agreed' isn't sorted forever; if it stops feeling fair, the honest move is to renegotiate.","relearn":"An agreed split isn't permanent; if it stops feeling fair, re-open it rather than defend it."},
  {"id":"ep-1006","cat":"keep-it-equal","type":"branch","persona":"any","source":"resisting outside pressure","hook":"Your parents keep telling Zeeshan he 'helps too much' at home.","steps":[{"prompt":"Your father makes the comment again at Sunday lunch. What do you do?","options":[{"text":"Back Zeeshan and say you both keep your agreed split","then":"Your father pauses, then shrugs it off.","best":true},{"text":"Let Zeeshan handle the comment himself this time","then":"He deflects it alone, and it comes up again next visit."},{"text":"Quietly agree so lunch doesn't turn tense","then":"Your father nods, satisfied, and brings it up again next month."},{"text":"Change the subject to avoid a scene","then":"The comment goes unanswered, and returns another day."}],"why":"Backing him openly is what holds the fair split against pressure, without starting a fight."},{"prompt":"Zeeshan says he's started pulling back a little to keep the peace. What do you do?","options":[{"text":"Tell him plainly you don't want him pulling back","then":"He looks relieved. \"Honestly, I was hoping you'd say that.\"","best":true},{"text":"Say it's probably easier for everyone if he does","then":"The split quietly slides back toward the old pattern."},{"text":"Suggest he just do it when your parents aren't around","then":"He agrees, and starts quietly hiding half of what he does."},{"text":"Say nothing and let him decide on his own","then":"He goes quiet, and slowly starts pulling back anyway."}],"why":"Telling him clearly you don't want the pullback is what stops outside pressure from working."},{"prompt":"Your mother later asks if Zeeshan 'minds' doing so much. What do you say?","options":[{"text":"Say it's not minding. It's simply his fair share","then":"Your mother considers this, and doesn't push further.","best":true},{"text":"Say he's very understanding about it","then":"Your mother nods, still picturing him as unusually generous."},{"text":"Say you sometimes wonder the same thing","then":"Your mother's eyebrows lift, a new doubt taking root."},{"text":"Laugh it off without really answering","then":"The framing that he's doing extra goes unchallenged."}],"why":"Naming it as his fair share, not generosity, is what actually corrects the framing."},{"prompt":"A year on, your parents have stopped commenting on it. What do you do?","options":[{"text":"Notice it, and check the split still feels fair","then":"Zeeshan admits one job crept back to you, and takes it again.","best":true},{"text":"Relax the split a little now that the pressure's gone","then":"The pressure's gone, and the old pattern starts creeping back anyway."},{"text":"Bring it up with them to make sure they've accepted it","then":"Your parents look startled you'd even bring it up again."},{"text":"Assume it worked itself out on its own","then":"Neither of you checks, and small jobs quietly drift back to you."}],"why":"Checking it's still fair, not just assuming, is what makes the win actually last."}],"debrief":"Outside pressure can drag a fair split back to old patterns; back each other to hold it, kindly.","relearn":"When relatives pressure your split back to old patterns, hold it together rather than quietly sliding back."},
  {"id":"ep-1007","cat":"keep-it-equal","type":"branch","persona":"any","source":"making the fix last","hook":"After a hard patch you and Devansh have rebuilt a fair split; you want it to last this time.","steps":[{"prompt":"The rebuild's a week old, and it's already going smoothly. What do you do?","options":[{"text":"Agree a simple cadence now, while it's fresh","then":"Devansh nods. \"Let's lock that in before we forget.\"","best":true},{"text":"Put the new split on a chart on the fridge","then":"The chart looks great, and nobody plans to look at it again."},{"text":"Assume the rebuild will just hold on its own","then":"A few weeks later, small things start slipping again, unnoticed."},{"text":"Wait until something feels off to revisit it","then":"By the time something feels off, the pattern's already back."}],"why":"Agreeing a cadence while the rebuild's fresh is what actually makes it durable, not a one-off fix."},{"prompt":"A month in, checking in on the split feels a bit awkward to raise. What do you do?","options":[{"text":"Bring it up anyway, lightly","then":"Devansh says, \"Good idea. Let's actually do that.\"","best":true},{"text":"Skip this one. You'll catch the next one","then":"Skipping the first one makes the next one easier to skip too."},{"text":"Wait for Devansh to bring it up instead","then":"Neither of you raises it, and the moment passes."},{"text":"Turn it into a bigger conversation than it needs to be","then":"Making it heavier undoes the point of keeping it light."}],"why":"Following through even when it feels awkward is what turns the idea into an actual habit."},{"prompt":"Six months on, Devansh starts a new job with a longer commute. What do you do?","options":[{"text":"Sit down together and adjust the split for it","then":"You move two morning jobs to yourself, and he takes two weekend ones.","best":true},{"text":"Keep the split as it is for now","then":"His new hours don't fit it, and jobs start slipping by week two."},{"text":"Take on more quietly while he settles in","then":"Settling in stretches on, and the extra stays with you."},{"text":"Wait for Devansh to say if it's too much","then":"He doesn't want to complain, so he says nothing for weeks."}],"why":"Revisiting the split when life changes, not only when it breaks, is what makes the fix last."}],"debrief":"Fairness needs maintenance, not a one-time fix; a regular revisit makes a rebuild actually last.","relearn":"Lock in a rebuilt split with a regular revisit; a one-time fix drifts back without one."},
  {"id":"ep-1008","type":"strike-rewrite","hook":"\"We sorted the split when we married, so it's done.\"","myth":{"un":"We sorted the split when we married, so it's done.","re":"A split is renegotiated as life changes; jobs, moves and kids keep reshaping the workload.","why":"The work itself keeps changing, so a one-time deal stops fitting."},"relearn":"A split is renegotiated as life changes, not settled once for good.","persona":"any","source":"renegotiated, not settled","cat":"keep-it-equal"},
  {"id":"ep-1009","type":"strike-rewrite","hook":"\"If neither of us is complaining, the split must still be fair.\"","myth":{"un":"If neither of us is complaining, the split must still be fair.","re":"Fairness drifts back to old patterns silently; you check on purpose, not wait for complaints.","why":"Drift is quiet, and resentment often builds long before anyone speaks up."},"relearn":"Silence doesn't mean fair; check the split on purpose rather than waiting for complaints.","persona":"any","source":"silence isn't fairness","cat":"keep-it-equal"},
  {"id":"ep-1010","type":"strike-rewrite","hook":"\"Talking about chores every month would just create fights.\"","myth":{"un":"Talking about chores every month would just create fights.","re":"A short, calm monthly check-in prevents fights by catching drift before it turns into resentment.","why":"Small, regular adjustments are far easier than one big blow-up later."},"relearn":"A calm monthly check-in prevents fights; it catches drift before it becomes resentment.","persona":"any","source":"check-ins prevent fights","cat":"keep-it-equal"},
  {"id":"ep-1011","type":"strike-rewrite","hook":"\"An equal home is just more work for me with nothing in it for men.\"","myth":{"un":"An equal home is just more work for me with nothing in it for men.","re":"An equal home is happier and less resentful for both of you; men gain a closer, warmer partnership too.","why":"Shared load lowers resentment, and connection grows for everyone in the home."},"relearn":"An equal home is happier for both partners; men gain a closer partnership, not just more chores.","persona":"Karthik","source":"everyone gains","cat":"keep-it-equal"},
  {"id":"ep-1012","type":"strike-rewrite","hook":"\"Kids are too young to notice who does what at home.\"","myth":{"un":"Kids are too young to notice who does what at home.","re":"Children absorb who runs the home and grow up expecting that pattern; you model their future by living it.","why":"Daily example, not lectures, is what shapes what kids think is normal."},"relearn":"Children absorb who runs the home and expect that pattern later; living equality models their future.","persona":"any","source":"kids model what they see","cat":"keep-it-equal"},
  {"id":"ep-1013","type":"strike-rewrite","hook":"\"Once the baby comes, the load naturally falls to the mother anyway.\"","myth":{"un":"Once the baby comes, the load naturally falls to the mother anyway.","re":"A baby is exactly when to renegotiate deliberately; nothing about baby-care is naturally one parent's job.","why":"Care defaults to whoever plans for it, not to a gender, so you plan it together."},"relearn":"A baby's load is renegotiated deliberately; baby-care isn't naturally the mother's job.","persona":"Nisha","source":"baby isn't the mother's default","cat":"keep-it-equal"},
  {"id":"ep-1014","type":"strike-rewrite","hook":"\"If I keep having to adjust the split, we must have got it wrong.\"","myth":{"un":"If I keep having to adjust the split, we must have got it wrong.","re":"Adjusting the split is the system working; equality is an ongoing conversation, not a one-time setup.","why":"A split that keeps pace with real life has to keep being tuned."},"relearn":"Adjusting the split means it's working; equality is ongoing, not a one-time setup.","persona":"any","source":"adjusting is the system working","cat":"keep-it-equal"},
  {"id":"ep-1015","cat":"keep-it-equal","type":"role-play","persona":"any","source":"naming drift kindly","hook":"You've realised the split has quietly drifted, and Rohan's ended up carrying more of it this year.","setup":"Tonight you decide to bring it up without blame.","steps":[{"prompt":"Rohan asks: \"You've been quiet tonight. What's up?\"","options":[{"text":"\"I think our split has drifted over the year. Can we rebalance it?\"","then":"He nods slowly. \"Yeah, I've felt that too, honestly.\"","best":true},{"text":"\"It's fine. Don't worry about it.\"","then":"He frowns. \"It doesn't feel fine. I've been stretched thin lately.\""},{"text":"\"You always say I do nothing around here, so fine, here's a list.\"","then":"Rohan frowns. \"I never said that. Why so defensive?\""},{"text":"\"I'll just do more around the house from now on. Promise.\"","then":"He smiles, unsure. \"Okay. More of what, though?\""}],"why":"Naming the drift without blame opens a real conversation instead of a fight or silence."},{"prompt":"A few days later, Rohan brings out a notepad and asks: \"Can we list what's gone lopsided this year?\"","options":[{"text":"\"Let's list the invisible stuff too, not just the chores.\"","then":"The invisible list runs long, and you see how much of it he's been holding.","best":true},{"text":"\"Probably just the cooking, since that's the obvious one.\"","then":"You take back the cooking, but the planning stays exactly where it was."},{"text":"\"You know better than me. Just tell me what to do.\"","then":"Rohan sighs. \"So I'm still the one managing it.\""},{"text":"\"Let's not make a list. I'll pick things up as I see them.\"","then":"He puts the notepad down. \"That's what we did last year.\""}],"why":"Naming the invisible planning, not just chores, is what actually rebalances the load."},{"prompt":"A month later, Rohan asks: \"How do you think we're doing with all this?\"","options":[{"text":"\"Let's sit down and check honestly, and do it every month.\"","then":"He agrees, and you both add a monthly reminder to the calendar.","best":true},{"text":"\"Good for now. I really don't think we need to check again so soon.\"","then":"He shrugs. Two months later, it's quietly drifted back onto him."},{"text":"\"You tell me. You'd notice before I would.\"","then":"Rohan's face falls. \"So I'm still the one keeping track?\""},{"text":"\"Much better. I've been doing loads more, haven't I?\"","then":"Rohan gives a small laugh. \"Some. Not loads.\""}],"why":"Checking honestly, on a regular rhythm, keeps the split from drifting back onto one of you."}],"relearn":"Name the drift without blame and ask to rebalance it together."},
  {"id":"ep-1016","cat":"keep-it-equal","type":"role-play","persona":"any","source":"proposing the cadence","hook":"You want to start checking in regularly on how you're sharing things, but you're worried it'll sound like a complaint.","setup":"You bring it up on a calm evening.","steps":[{"prompt":"Naina asks: \"You've been thinking about something. What is it?\"","options":[{"text":"\"Could we do a quick monthly check on how we're sharing things?\"","then":"She relaxes. \"Oh, that sounds useful, not scary.\"","best":true},{"text":"\"I feel like we should talk more in general.\"","then":"She nods, but isn't sure what you actually want to change."},{"text":"\"We never talk anymore. You never help. Something has to change.\"","then":"Naina looks hurt. \"That's not fair.\""},{"text":"\"Never mind. Forget I said anything.\"","then":"Naina tilts her head. \"You clearly had something on your mind.\""}],"why":"A specific, low-key monthly check sounds like upkeep, not an accusation."},{"prompt":"Later that week, Naina asks: \"Be honest. Is this about me not doing enough?\"","options":[{"text":"\"No. It's for both of us, to catch whatever's drifted.\"","then":"She relaxes. \"Okay. That actually sounds fair.\"","best":true},{"text":"\"Not really. It's just a few things I've been noticing.\"","then":"She looks unsure. \"What sort of things? Mine?\""},{"text":"\"Well, you do forget your share sometimes, honestly.\"","then":"Naina crosses her arms. \"So it is a complaint.\""},{"text":"\"Don't worry about it. Let's just drop it.\"","then":"Naina hesitates. \"I don't want to drop it. I want to know.\""}],"why":"Framing it as upkeep for both of you keeps it from sounding like a complaint about her."},{"prompt":"A month later, Naina says: \"We keep meaning to talk about the house, and we never do.\"","options":[{"text":"\"Let's put a short monthly check-in on the calendar.\"","then":"She adds a recurring reminder. \"First Sunday of every month, then.\"","best":true},{"text":"\"Let's just talk whenever something comes up.\"","then":"She nods. Weeks pass, and nothing comes up until it boils over."},{"text":"\"Only if you bring up your side of things too.\"","then":"Naina frowns. \"That sounds like keeping score.\""},{"text":"\"I think we're fine. Let's not make it a formal thing.\"","then":"Naina isn't convinced. \"Fine is how it drifted last time.\""}],"why":"A fixed date on the calendar turns a good intention into a habit you both keep."}],"relearn":"Propose the check-in as shared upkeep, not a complaint about your partner."},
  {"id":"ep-1017","cat":"keep-it-equal","type":"role-play","persona":"Karthik","source":"specific notice-and-offer","hook":"Pooja's swamped at work this month, and you can see the home load tilting onto her.","setup":"You notice it over a quiet dinner.","steps":[{"prompt":"Pooja says: \"Sorry dinner's late again. It's been a mad week.\"","options":[{"text":"\"You've had a brutal month. Let me take cooking till it eases.\"","then":"She exhales. \"That would actually help so much.\"","best":true},{"text":"\"Tell me if you ever feel like you need a hand with anything, okay?\"","then":"She nods, but nothing specific changes."},{"text":"\"It's okay. I really don't mind waiting a bit for dinner.\"","then":"Pooja looks a little more tired, still holding it all."},{"text":"\"Maybe you should try leaving the office a little earlier.\"","then":"She bristles. \"It's not that simple.\""}],"why":"Naming exactly what you'll take over, not a vague offer, actually lifts the load."},{"prompt":"A few days later, Pooja says: \"The electricity bill's due, and I haven't even opened it.\"","options":[{"text":"\"Send me the login. I'll track and pay it from now on.\"","then":"She forwards it right away, relieved.","best":true},{"text":"\"I'll pay it. Just remind me before it's due.\"","then":"She sighs. \"That's still me remembering for you.\""},{"text":"\"You're better with numbers. Can you do just this one?\"","then":"Pooja looks stung. \"It's not about numbers. It's about time.\""},{"text":"\"It's just one bill. Don't stress.\"","then":"She sighs, and quietly adds it back to her own list."}],"why":"Owning the bill including the tracking, not just paying it, is what actually takes it off her."},{"prompt":"By the end of the month, Pooja asks: \"How do you think this month went, with everything?\"","options":[{"text":"\"Let's sit down once work eases and set a split that fits us both.\"","then":"She smiles. \"I was hoping you'd say that. Let's pick a day.\"","best":true},{"text":"\"Let's keep this exact split from now on, whatever changes.\"","then":"Pooja hesitates. \"Even if your work gets busy next?\""},{"text":"\"See, I told you I could handle it.\"","then":"The moment feels more about you than the relief she's feeling."},{"text":"\"We'll just see how it goes for now.\"","then":"Neither of you commits, and old habits creep back next month."}],"why":"Revisiting the split together as work changes keeps it fair, instead of fixing it or dropping it."}],"relearn":"When your partner's swamped, name specific things you'll take back, not a vague offer."},
  {"id":"ep-1018","cat":"keep-it-equal","type":"role-play","persona":"Nisha","source":"planning the baby split","hook":"Your baby with Aman is due in four months, and nobody's worked out who does what.","setup":"One evening, Aman opens a blank page in his notebook.","steps":[{"prompt":"Aman asks: \"Where do we even start with the baby stuff?\"","options":[{"text":"\"Let's map every baby task first, then split them on purpose.\"","then":"He nods. \"Good idea, before we're too tired to plan.\"","best":true},{"text":"\"I'm sure your mother will come and help me manage all of it.\"","then":"Aman hesitates. \"She can visit, but she won't be up with us at night.\""},{"text":"\"I'll handle the baby side. Your job's bigger right now.\"","then":"Aman frowns. \"Why should my job decide that?\""},{"text":"\"Let's not overthink it before the baby's even here.\"","then":"Aman shakes his head. \"I'd rather plan now than argue at 3am.\""}],"why":"Mapping the real tasks now, on purpose, beats leaving them to a job title, a relative or chance."},{"prompt":"Aman asks: \"So who's actually up at night when the baby wakes?\"","options":[{"text":"\"Let's alternate nights, and whoever slept through takes the morning.\"","then":"He agrees, glad it's a clear, fair rule.","best":true},{"text":"\"I'll just do nights, since I'm probably better at waking up anyway.\"","then":"Aman looks relieved. \"If you're sure.\" The pattern sets itself for good."},{"text":"\"Let's split nights 50/50 and sort the mornings out as we go.\"","then":"Aman nods. \"Sure. But who's up at dawn after a bad night?\""},{"text":"\"We'll wing it depending on who's more tired.\"","then":"Aman shrugs. \"We're both going to be tired, though.\""}],"why":"A clear rule for nights and the morning after keeps night duty from becoming one person's job."},{"prompt":"Later, Aman asks: \"Should any of this change once we're both back at work?\"","options":[{"text":"\"Yes, let's revisit it properly once we're both working again.\"","then":"He agrees to put a date on the calendar to redo it.","best":true},{"text":"\"Only if it stops working.\"","then":"Nothing's booked, so the revisit quietly never happens."},{"text":"\"It'll probably just sort itself out naturally by the time it comes.\"","then":"Three months later, the same plan hasn't fit reality for weeks."},{"text":"\"Let's not jinx it by planning too far ahead.\"","then":"Aman shrugs it off, and the plan stays untouched."}],"why":"Booking the revisit now is what makes sure the split gets renegotiated, not just assumed."}],"relearn":"Map the baby load in advance and split it on purpose, rather than defaulting it."},
  {"id":"ep-1019","cat":"keep-it-equal","type":"role-play","persona":"any","source":"renegotiate ahead of a job","hook":"Your new job starts next month, and you both know it'll reshape the evenings.","setup":"You bring it up while planning the week ahead.","steps":[{"prompt":"Nikhil asks: \"Should we wait and see how the new hours actually feel first?\"","options":[{"text":"\"Let's redo the evening split now, before it starts.\"","then":"He agrees. \"Better than scrambling later.\"","best":true},{"text":"\"Let's just do whatever we did last time my hours changed.\"","then":"Nikhil shrugs. \"Did that even work, though?\""},{"text":"\"You'll probably need to take over most of the evenings then.\"","then":"He looks surprised. \"Why me by default?\""},{"text":"\"Let's not worry about it until it's a problem.\"","then":"Nothing's planned, and old habits are already loading up."}],"why":"Renegotiating ahead of a known change keeps it fair before habits set wrong."},{"prompt":"A few days later, Nikhil asks: \"So what's actually going to be different about your evenings?\"","options":[{"text":"\"I'll be home an hour later. Let's shift cooking and groceries.\"","then":"He works out the new split with you, task by task.","best":true},{"text":"\"Just a bit later. It's probably not a big deal.\"","then":"You skip past specifics, and the actual hour gets lost."},{"text":"\"You'll just have to cover a bit more till I settle in properly.\"","then":"Nikhil frowns. \"For how long, though?\""},{"text":"\"Let's cross that bridge closer to the date.\"","then":"Nikhil sighs. \"It's only a few weeks away, though.\""}],"why":"Naming exactly what changes lets you redesign the split around the real hour lost, not a guess."},{"prompt":"A week before the job starts, Nikhil asks: \"What if the evenings still don't work once you've started?\"","options":[{"text":"\"Then we redo it. Let's pick a date in my second week to check.\"","then":"He nods. \"Okay. I'll put it in the calendar.\"","best":true},{"text":"\"It'll work out. We won't need to check again.\"","then":"He shrugs. Within weeks, the evenings stop matching any plan."},{"text":"\"That's your call. I've done my part already.\"","then":"Nikhil frowns. \"So now I'm the one who has to police it?\""},{"text":"\"Let's just see how the first week goes, and not stress.\"","then":"\"Fine,\" he says, but nobody books a time to actually talk."}],"why":"Booking a check-in once the change is real keeps the split fair in practice, not just on paper."}],"relearn":"Renegotiate the split ahead of a known change instead of leaving it to sort itself."},
  {"id":"ep-1020","cat":"keep-it-equal","type":"role-play","persona":"any","source":"owning the slip aloud","hook":"You've drifted back into old habits at home, and Ishita's gone quiet about it.","setup":"After dinner, she switches off the TV and turns to you.","steps":[{"prompt":"Ishita says: \"I've done the dishes and the groceries alone for three weeks.\"","options":[{"text":"\"You're right. That's on me. Let's reset it so it's even.\"","then":"She softens, relieved you didn't get defensive.","best":true},{"text":"\"Sorry, I've just been really busy lately.\"","then":"She nods, but nothing about the split actually changes."},{"text":"\"You could just remind me next time. You know how busy I get.\"","then":"Ishita's face falls. \"That's exactly the problem.\""},{"text":"\"I didn't think it was that noticeable.\"","then":"She looks tired. \"It was. For weeks.\""}],"why":"Owning the slip and resetting the split beats just apologising or asking to be reminded."},{"prompt":"Ishita asks: \"So what actually changes from tonight?\"","options":[{"text":"\"I'll take the dishes and the grocery runs back, starting now.\"","then":"She relaxes, glad it's concrete and starting immediately.","best":true},{"text":"\"I'll try to do better generally.\"","then":"It sounds sincere, but nothing specific is decided."},{"text":"\"Whatever you personally think needs the most fixing, honestly.\"","then":"Ishita sighs. \"I shouldn't have to assign it.\""},{"text":"\"Let's not make a whole big thing out of it tonight.\"","then":"The reset quietly doesn't happen."}],"why":"Naming exact tasks starting now is what turns owning it into actually fixing it."},{"prompt":"A few weeks later, Ishita asks: \"Have you noticed how the evenings have been going?\"","options":[{"text":"\"Let's look at them honestly, and check in monthly from now on.\"","then":"She nods. \"Yes. A monthly check would help us both.\"","best":true},{"text":"\"Much better. I don't think we need to check in again.\"","then":"Ishita hesitates. Two months later, the same slide starts again."},{"text":"\"See, I told you I'd fix it.\"","then":"Ishita gives a thin smile. \"It's not about scoring a point.\""},{"text":"\"Let's just keep going the way we are for now.\"","then":"She shrugs. \"The way we are is how it slipped last time.\""}],"why":"Checking honestly, on a regular rhythm, is what keeps a reset split from slipping again."}],"relearn":"Own a slip back into old habits and reset the split, instead of putting reminding on your partner."},
  {"id":"ep-1021","cat":"keep-it-equal","type":"role-play","persona":"Karthik","source":"owning, not helping, aloud","hook":"Relatives keep praising you for helping so much at home, and you want Pooja to know you see it differently.","setup":"That evening, the topic comes up over dinner.","steps":[{"prompt":"Pooja says: \"Everyone kept telling you how lucky I am today.\"","options":[{"text":"\"They call it helping, but this home's half mine to run.\"","then":"She looks at you, surprised and quietly relieved.","best":true},{"text":"\"See, even they think I do plenty around here, don't they?\"","then":"Pooja's smile fades. \"That's not really the point.\""},{"text":"\"I know. It's a bit much sometimes, isn't it?\"","then":"The comment just sits there, unaddressed."},{"text":"\"People say all kinds of things. Just ignore them.\"","then":"She feels like her own frustration's being brushed off."}],"why":"Naming it as owning, not helping, tells her you see past the compliment to the real load."},{"prompt":"Later, Pooja asks: \"If I stopped reminding you about things, what would actually get done?\"","options":[{"text":"\"I'll run the groceries fully, no reminders needed.\"","then":"She lights up. \"That alone would save me so much thinking.\"","best":true},{"text":"\"I'd notice more, I promise. I just need a little time.\"","then":"Pooja smiles faintly. \"Notice what, though?\""},{"text":"\"Just tell me what you want me to take, and I will.\"","then":"Pooja sighs. \"That's still me managing it.\""},{"text":"\"Most of it would still get done. I do a lot already.\"","then":"Pooja goes quiet. \"Most of it gets done because I remember it.\""}],"why":"Naming a whole domain to run, not just noticing more, is what owning actually looks like."},{"prompt":"A month later, your mother asks: \"Does Pooja still do everything at home?\"","options":[{"text":"\"It shouldn't be hers alone. It's half my home to run.\"","then":"Your mother looks surprised, then nods slowly.","best":true},{"text":"\"I help out quite a lot more these days.\"","then":"Your mother smiles. \"Such a good helper you are.\""},{"text":"\"She still does most of it, same as always.\"","then":"Pooja overhears, and her face falls a little."},{"text":"\"Depends on the week. It's hard to say, really.\"","then":"Your mother nods. \"So she does, then.\""}],"why":"Calling it your half to run, not help, changes the story people tell about her."}],"relearn":"Reframe 'helping' as owning your half, so your partner isn't left managing you."},
  {"id":"ep-1022","cat":"keep-it-equal","type":"role-play","persona":"any","source":"adjust, don't defend","hook":"At your monthly check-in, Karan admits one area's quietly become unfair.","setup":"You take a breath before responding.","steps":[{"prompt":"Karan says: \"Honestly, the laundry's ended up all on me lately.\"","options":[{"text":"\"Thanks for saying it. Let's swap that one over so it's even from now.\"","then":"He relaxes. \"That's all I wanted, thank you.\"","best":true},{"text":"\"I didn't realise. I'll try to help with it sometimes.\"","then":"Karan nods, but sometimes isn't quite what he needed."},{"text":"\"I do so much else already. Can't you let this one go?\"","then":"His face falls. \"It's not a competition.\""},{"text":"\"You could've said something about it a lot sooner, honestly, no?\"","then":"Karan looks stung. \"I'm saying it now.\""}],"why":"Adjusting the split, not defending your overall effort, is what a fair check-in actually needs."},{"prompt":"Karan asks: \"Should we look at anything else while we're at it?\"","options":[{"text":"\"Yes, let's go through the whole list, not just laundry.\"","then":"You find two more small things that had quietly drifted too.","best":true},{"text":"\"Laundry's probably the only one. I think we're fine.\"","then":"You close the check-in early, and one more drifted task stays hidden."},{"text":"\"Let's not open up too much at once.\"","then":"Karan looks like he wanted to say more, but doesn't."},{"text":"\"You'd know better than me. You keep track.\"","then":"The tracking, again, stays on him."}],"why":"Going through the whole list catches other drift, not just the one thing that got mentioned."},{"prompt":"At next month's check-in, Karan asks: \"How's the split feeling to you now?\"","options":[{"text":"\"Let's start with laundry. Is it still landing on you?\"","then":"Karan looks relieved. \"Honestly, some weeks it still is.\"","best":true},{"text":"\"Good, I think. We could probably skip next month.\"","then":"Karan hesitates. \"Skipping is how it drifted last time.\""},{"text":"\"See, it really wasn't that big a deal in the end, was it?\"","then":"Karan's face tightens. \"It was a big deal to me.\""},{"text":"\"You tell me. You're the one who noticed last time.\"","then":"Karan sighs. \"So I'm still the one keeping track?\""}],"why":"Checking the thing that drifted, and asking him straight, keeps the check-in honest."}],"relearn":"When a check-in surfaces unfairness, adjust it rather than defending your overall contribution."},
  {"id":"ep-1023","cat":"keep-it-equal","type":"role-play","persona":"any","source":"modelling in the moment","hook":"Rakesh's little niece is staying with you both this week.","setup":"Tonight she perches on the kitchen counter while you cook.","steps":[{"prompt":"She asks: \"Why is it always you cooking, aunty?\"","options":[{"text":"\"Good question. That's not fair. Uncle and I will share it.\"","then":"She grins. \"Uncle's going to cook? Cool.\"","best":true},{"text":"\"Because I've always enjoyed it. That's all there is to it.\"","then":"She nods. \"So cooking's your thing, aunty.\""},{"text":"\"Because cooking is an aunty's job, beta.\"","then":"She nods, already learning it as normal."},{"text":"\"Ask Uncle, not me. He should really answer that one himself.\"","then":"She frowns. \"But I'm asking you.\""}],"why":"Saying it should be shared, and meaning it, teaches her equality better than any reason."},{"prompt":"Later, Rakesh says: \"She asked me why I never cook. I didn't know what to say.\"","options":[{"text":"\"Say you will. Let's split cooking nights, starting this week.\"","then":"He nods slowly. \"Okay. I'll take Tuesdays and Thursdays.\"","best":true},{"text":"\"Say you help me out whenever you can. That's true enough.\"","then":"Rakesh shrugs. \"Helping. Sure.\" And helping is all he does."},{"text":"\"Tell her I just like cooking. Kids forget these things quickly.\"","then":"He looks relieved, and her question never gets a real answer."},{"text":"\"You should know that yourself, honestly.\"","then":"Rakesh bristles. \"I'm asking because I don't.\""}],"why":"Turning your answer into real cooking nights is what makes it true for her to see."},{"prompt":"A few weeks later, the niece visits again and says: \"My friend says boys don't cook.\"","options":[{"text":"\"Anyone can cook. Let's call Uncle in to make the rotis.\"","then":"Rakesh rolls up his sleeves, and she watches, delighted.","best":true},{"text":"\"Some boys do. Your uncle helps me sometimes.\"","then":"She nods. \"So it's still your job, aunty.\""},{"text":"\"That's how most homes are, beta.\"","then":"She shrugs. \"Okay. So Uncle just eats.\""},{"text":"\"Don't listen to your friend. Friends say silly things.\"","then":"She looks confused. \"But who does cook, then?\""}],"why":"Showing her Uncle cooking, right then, teaches her more than any explanation could."}],"relearn":"Answer a child's question in a way that models the home as shared, not gendered."},
  {"id":"ep-1024","type":"reflect","hook":"Lensy: most splits drift over a year, even good ones. Worth a regular check?","prompt":"What do you think?","options":["Yes","Catch it early","Worth a check"],"affirm":"Even good splits drift over time; a regular check is how couples catch it before resentment sets in.","relearn":"Even good splits drift; a regular check catches it before resentment sets in.","persona":"any","source":"drift happens to everyone","cat":"keep-it-equal"},
  {"id":"ep-1025","type":"reflect","hook":"Lensy: 'we agreed once' can quietly become 'this stopped working.' Worth re-opening when it does?","prompt":"What do you think?","options":["Yes","Re-open it","It changes"],"affirm":"An agreed split isn't sorted forever; re-opening it when it stops working is how it stays fair.","relearn":"An agreed split isn't forever; re-opening it when it stops working keeps it fair.","persona":"any","source":"agreed can expire","cat":"keep-it-equal"},
  {"id":"ep-1026","type":"reflect","hook":"Lensy: a baby, a move, a new job, each reshapes the load. Worth renegotiating at each?","prompt":"What do you think?","options":["Yes","At every change","Renegotiate it"],"affirm":"Big changes reshape the workload; renegotiating at each is how the split keeps pace with your life.","relearn":"Big life changes reshape the load; renegotiate the split at each one.","persona":"any","source":"renegotiate at each change","cat":"keep-it-equal"},
  {"id":"ep-1027","type":"reflect","hook":"Lensy: noticing your partner's carrying more, and offering, says a lot. Worth doing unasked?","prompt":"What do you think?","options":["Yes","Offer first","Without asking"],"affirm":"Noticing your partner is carrying more and offering, unprompted, is what keeps an equal home warm.","relearn":"Notice when your partner carries more and offer unprompted; it keeps the home warm.","persona":"any","source":"unprompted offering","cat":"keep-it-equal"},
  {"id":"ep-1028","type":"reflect","hook":"Lensy: kids grow up copying the home they see, not the one we describe. Worth living it out loud?","prompt":"What do you think?","options":["Yes","They copy us","Live it out loud"],"affirm":"Children grow up expecting the home they see; living equality visibly is how you pass it on.","relearn":"Children expect the home they see; living equality visibly passes it on.","persona":"any","source":"living it for kids","cat":"keep-it-equal"},
  {"id":"ep-1029","type":"reflect","hook":"Lensy: an equal home is a project you keep building, not a box you tick once. Sit with that?","prompt":"What do you think?","options":["Yes","Keep building","Never just done"],"affirm":"An equal home is an ongoing project, not a one-time tick; staying at it is exactly how it's built.","relearn":"An equal home is an ongoing project, never a one-time tick.","persona":"any","source":"ongoing project","cat":"keep-it-equal"},
  {"id":"ep-1030","type":"reflect","hook":"Lensy: owning a slip and resetting is braver than defending it. Worth doing when you slide?","prompt":"What do you think?","options":["Yes","Own the slip","Reset it"],"affirm":"Owning a slip and resetting, instead of defending it, is what repairs and protects the partnership.","relearn":"Owning a slip and resetting protects the partnership better than defending it.","persona":"any","source":"owning over defending","cat":"keep-it-equal"},
  {"id":"ep-1031","type":"reflect","hook":"Lensy: a fair split protects the relationship as much as it shares the work. Feel true?","prompt":"What do you think?","options":["Yes","Protects us","Shares the work"],"affirm":"A fair split shares the work and guards the relationship; unfair load quietly breeds the resentment that erodes it.","relearn":"A fair split shares the work and guards the relationship from resentment.","persona":"any","source":"fairness protects the bond","cat":"keep-it-equal"},
  {"id":"ep-1032","type":"reflect","hook":"Lensy: outside voices will nudge your split back to old patterns. Worth holding it together?","prompt":"What do you think?","options":["Yes","Hold it","Back each other"],"affirm":"Outside pressure nudges splits back to old patterns; backing each other is how you hold the fairness you built.","relearn":"Outside pressure nudges splits back; backing each other holds the fairness you built.","persona":"any","source":"holding against pressure","cat":"keep-it-equal"},
  {"id":"ep-1033","type":"reflect","hook":"Lensy: a check-in isn't a complaint, it's shared upkeep, like servicing a bike. Land for you?","prompt":"What do you think?","options":["Yes","Shared upkeep","Not a complaint"],"affirm":"A check-in is shared upkeep, not a complaint; regular small tuning is what keeps fairness running.","relearn":"A check-in is shared upkeep, not a complaint; regular tuning keeps fairness running.","persona":"any","source":"check-in as upkeep","cat":"keep-it-equal"},
  {"id":"ep-1034","type":"reflect","hook":"Lensy: the partner who's freer this month can quietly take more. Worth offering when that's you?","prompt":"What do you think?","options":["Yes","When I'm freer","Take more"],"affirm":"Whoever has more room this month can offer to take more; that give-and-take is what keeps it even over time.","relearn":"Whoever has more room can offer to take more; give-and-take keeps it even over time.","persona":"any","source":"flex with capacity","cat":"keep-it-equal"},
  {"id":"ep-1035","type":"reflect","hook":"Lensy: the goal isn't a perfect split forever, it's catching drift kindly each time. Sit right?","prompt":"What do you think?","options":["Yes","Catch it kindly","Not perfect"],"affirm":"The goal isn't a perfect permanent split; it's catching drift kindly and re-evening, again and again.","relearn":"The goal is catching drift kindly and re-evening, not a perfect permanent split.","persona":"any","source":"kindly catching drift","cat":"keep-it-equal"},
  {"id":"ep-1036","type":"reflect","hook":"Lensy: less resentment, more closeness, that's what couples report from keeping it equal. Worth it?","prompt":"What do you think?","options":["Yes","Less resentment","More closeness"],"affirm":"Couples who keep it equal report less resentment and more closeness; the ongoing effort genuinely pays both back.","relearn":"Keeping it equal brings less resentment and more closeness; the effort pays both partners back.","persona":"any","source":"the payoff of equal","cat":"keep-it-equal"},
  {"id":"ep-1037","type":"reflect","hook":"Lensy: 'we've drifted' is information, not an accusation. Worth hearing it that way?","prompt":"What do you think?","options":["Yes","It's information","Not an attack"],"affirm":"Hearing 'we've drifted' as information rather than attack lets you both adjust calmly instead of defending.","relearn":"Hearing 'we've drifted' as information, not attack, lets you adjust calmly.","persona":"any","source":"drift as information","cat":"keep-it-equal"},
  {"id":"ep-1038","type":"sort","hook":"Sort: keeps a split fair over time, or lets it quietly drift?","items":[{"id":"a","text":"A standing monthly check-in"},{"id":"b","text":"Assuming the old deal still fits"},{"id":"c","text":"Re-splitting around a new job"},{"id":"d","text":"Ignoring that you do more now"},{"id":"e","text":"Offering to take more when she's swamped"},{"id":"f","text":"Waiting for resentment to boil over"}],"bins":[{"id":"keeps","label":"Keeps it fair","valence":"pos"},{"id":"drifts","label":"Lets it drift","valence":"neg"}],"key":{"a":"keeps","b":"drifts","c":"keeps","d":"drifts","e":"keeps","f":"drifts"},"relearn":"Check-ins, re-splitting at changes and offering keep it fair; assuming, ignoring and waiting let it drift.","persona":"any","source":"fair vs drift habits","cat":"keep-it-equal"},
  {"id":"ep-1039","type":"sort","hook":"Sort: a moment to renegotiate the split, or business as usual?","items":[{"id":"a","text":"A new baby on the way"},{"id":"b","text":"A quiet, unchanged week"},{"id":"c","text":"Moving to a new city"},{"id":"d","text":"An ordinary Tuesday"},{"id":"e","text":"A partner starting evening study"},{"id":"f","text":"Nothing's changed at all"}],"bins":[{"id":"renegotiate","label":"Renegotiate now","valence":"tell"},{"id":"asis","label":"Business as usual","valence":"neutral"}],"key":{"a":"renegotiate","b":"asis","c":"renegotiate","d":"asis","e":"renegotiate","f":"asis"},"relearn":"A baby, a move or new study are moments to renegotiate the split; ordinary unchanged days run as usual.","persona":"any","source":"when to renegotiate","cat":"keep-it-equal"},
  {"id":"ep-1040","type":"sort","hook":"Sort: keeps a rebuilt split durable, or lets it slide back?","items":[{"id":"a","text":"Revisiting it on a set cadence"},{"id":"b","text":"Trusting it'll just hold"},{"id":"c","text":"Backing each other against outside pressure"},{"id":"d","text":"Quietly pulling back to please relatives"},{"id":"e","text":"Owning a slip and resetting"},{"id":"f","text":"Getting defensive when it's raised"}],"bins":[{"id":"durable","label":"Keeps it durable","valence":"pos"},{"id":"slides","label":"Lets it slide back","valence":"neg"}],"key":{"a":"durable","b":"slides","c":"durable","d":"slides","e":"durable","f":"slides"},"relearn":"Revisiting, backing each other and owning slips keep a rebuild durable; trusting it, pulling back and defending let it slide.","persona":"any","source":"durable vs sliding back","cat":"keep-it-equal"},
  {"id":"ep-1041","type":"sort","hook":"Sort: a warm way to raise the split, or one that puts your partner on the back foot?","items":[{"id":"a","text":"\"I think it's drifted, can we rebalance?\""},{"id":"b","text":"\"You never do anything here.\""},{"id":"c","text":"\"You've carried more, let me take some.\""},{"id":"d","text":"\"Why do I do everything?\""},{"id":"e","text":"\"Let's do a quick monthly check.\""},{"id":"f","text":"\"Forget it, I'll just do it.\""}],"bins":[{"id":"warm","label":"Opens it warmly","valence":"pos"},{"id":"blames","label":"On the back foot","valence":"uhoh"}],"key":{"a":"warm","b":"blames","c":"warm","d":"blames","e":"warm","f":"blames"},"relearn":"Naming drift, offering and proposing a check-in open it warmly; blame and martyrdom put your partner on the back foot.","persona":"any","source":"warm vs blaming openers","cat":"keep-it-equal"},
  {"id":"ep-1042","type":"sort","hook":"Sort: what an equal home gives both partners, or what it costs?","items":[{"id":"a","text":"Less resentment between you"},{"id":"b","text":"A loss for men"},{"id":"c","text":"A closer, warmer partnership"},{"id":"d","text":"A battle of the sexes"},{"id":"e","text":"Kids who expect equality"},{"id":"f","text":"More chores and nothing back"}],"bins":[{"id":"gains","label":"What both gain","valence":"pos"},{"id":"myths","label":"Myths about the cost","valence":"neg"}],"key":{"a":"gains","b":"myths","c":"gains","d":"myths","e":"gains","f":"myths"},"relearn":"An equal home brings less resentment, closeness and kids who expect equality; 'a loss for men' or 'a battle' are myths.","persona":"any","source":"gains vs cost-myths","cat":"keep-it-equal"},
  {"id":"ep-1043","type":"sort","hook":"Sort: a check-in habit that works, or one that quietly fails?","items":[{"id":"a","text":"Short, regular and calm"},{"id":"b","text":"Only when resentment boils over"},{"id":"c","text":"Both can raise a concern"},{"id":"d","text":"One person delivers a verdict"},{"id":"e","text":"Ends in a concrete swap"},{"id":"f","text":"Ends with vague promises"}],"bins":[{"id":"works","label":"A check-in that works","valence":"pos"},{"id":"fails","label":"One that quietly fails","valence":"neg"}],"key":{"a":"works","b":"fails","c":"works","d":"fails","e":"works","f":"fails"},"relearn":"A check-in that's short, two-sided and ends in a concrete swap works; boil-over timing, verdicts and vague promises fail.","persona":"any","source":"good vs failing check-in","cat":"keep-it-equal"},
  {"id":"ep-1044","type":"sort","hook":"Sort: a fair response when a partner's stretched thin, or a way that piles on?","items":[{"id":"a","text":"Offering to take a chunk back"},{"id":"b","text":"Waiting until she finally asks"},{"id":"c","text":"Naming exactly what you'll cover"},{"id":"d","text":"Saying 'tell me if you need anything'"},{"id":"e","text":"Taking it back without keeping score"},{"id":"f","text":"Reminding her how much you usually do"}],"bins":[{"id":"shares","label":"Shares the dip","valence":"pos"},{"id":"pileson","label":"Piles on","valence":"uhoh"}],"key":{"a":"shares","b":"pileson","c":"shares","d":"pileson","e":"shares","f":"pileson"},"relearn":"Offering, naming what you'll cover and not scorekeeping share the dip; waiting, vague offers and scorekeeping pile on.","persona":"any","source":"sharing the dip vs piling on","cat":"keep-it-equal"},
  {"id":"ep-1045","type":"match","hook":"Match each life-change to the part of the split it forces you to rethink.","pairs":[{"left":"A new baby","right":"Who owns night feeds and care"},{"left":"A move to a new city","right":"The whole routine, rebuilt"},{"left":"A partner's promotion","right":"Evenings around new hours"},{"left":"Help quitting","right":"The freed-up chores, re-split"},{"left":"A parent needing care","right":"Eldercare, shared not assigned"}],"relearn":"Each life-change forces a specific part of the split to be rethought, deliberately and together.","persona":"any","source":"change to what it reshapes","cat":"keep-it-equal"},
  {"id":"ep-1046","type":"match","hook":"Match the keeping-it-equal habit to what it protects against.","pairs":[{"left":"Monthly check-in","right":"Silent drift"},{"left":"Renegotiating at changes","right":"Defaulting to old roles"},{"left":"Offering when she's swamped","right":"One partner burning out"},{"left":"Owning a slip","right":"Festering resentment"},{"left":"Backing each other","right":"Outside pressure"}],"relearn":"Each ongoing habit guards against a specific way fairness erodes over time.","persona":"any","source":"habit to what it guards","cat":"keep-it-equal"},
  {"id":"ep-1047","type":"match","hook":"Match the unfair pattern to the warm move that resets it.","pairs":[{"left":"The split's quietly drifted","right":"Name it and rebalance together"},{"left":"You slid back into old habits","right":"Own the slip and reset"},{"left":"She's carrying more this month","right":"Offer to take a chunk back"},{"left":"You never review it","right":"Set a standing check-in"},{"left":"Relatives push it backwards","right":"Hold your agreed split together"}],"relearn":"Every drift has a warm, concrete reset; the move is to name it and re-even, not to blame.","persona":"any","source":"pattern to its reset","cat":"keep-it-equal"},
  {"id":"ep-1048","type":"match","hook":"Match what an equal home gives to who gains from it.","pairs":[{"left":"Less resentment","right":"Both partners"},{"left":"A closer partnership","right":"Men especially"},{"left":"Equality treated as normal","right":"The children"},{"left":"A model to copy","right":"The next generation"},{"left":"Shared mental load","right":"Whoever carried it alone"}],"relearn":"An equal home pays off for everyone in it; it's never a loss for men.","persona":"any","source":"gain to who benefits","cat":"keep-it-equal"},
  {"id":"ep-1049","type":"match","hook":"Match the myth about keeping it equal to the truth that replaces it.","pairs":[{"left":"\"Once agreed, it's sorted\"","right":"It's renegotiated as life changes"},{"left":"\"No complaints means fair\"","right":"Drift is silent, so check on purpose"},{"left":"\"Check-ins cause fights\"","right":"They prevent fights by catching drift"},{"left":"\"Nothing in it for men\"","right":"A warmer, closer partnership"},{"left":"\"Kids don't notice\"","right":"They copy the home they see"}],"relearn":"Each keeping-it-equal myth has a plain truth: equality is ongoing, checked on purpose, and gains everyone.","persona":"any","source":"myth to truth","cat":"keep-it-equal"},
  {"id":"ep-1050","type":"match","hook":"Match each check-in question to what it surfaces.","pairs":[{"left":"\"What's drifted this month?\"","right":"Quiet shifts in the load"},{"left":"\"Who's carrying more right now?\"","right":"An imbalance to re-even"},{"left":"\"What changed in our lives?\"","right":"A reason to renegotiate"},{"left":"\"What should we swap?\"","right":"A concrete adjustment"},{"left":"\"Are we both okay with this?\"","right":"Hidden resentment, early"}],"relearn":"Good check-in questions surface drift, imbalance, change and hidden resentment before they harden.","persona":"any","source":"question to what it surfaces","cat":"keep-it-equal"},
  {"id":"ep-1051","type":"match","hook":"Match the change in capacity to the fair way to flex the split.","pairs":[{"left":"You have a lighter month","right":"Offer to take more of the load"},{"left":"Your partner's deep in deadlines","right":"Take a chunk back till it eases"},{"left":"Both of you are stretched","right":"Drop or share the non-essentials"},{"left":"Things have settled down","right":"Reset back to the even split"},{"left":"One had a long heavy stretch","right":"Re-even and don't keep score"}],"relearn":"A fair split flexes with real capacity each month, then resets to even, without scorekeeping.","persona":"any","source":"capacity to the flex","cat":"keep-it-equal"},
  {"id":"ep-1052","type":"spot","hook":"Spot the two red flags: which lines let a fair split quietly drift back?","scene":[{"id":"a","text":"\"We agreed this once, so it's settled.\"","trick":true},{"id":"b","text":"\"Let's check next month if it's drifted.\"","trick":false},{"id":"c","text":"\"No one's complained, so it must be fine.\"","trick":true},{"id":"d","text":"\"You've had more on lately, let me take some.\"","trick":false},{"id":"e","text":"\"Our split should flex as life changes.\"","trick":false}],"why":"'It's settled' and 'no one's complained' are the red flags; both let drift go unchecked while it quietly slides onto one person.","relearn":"'It's settled' and 'no one's complained' let a split drift onto one person.","persona":"any","source":"spot the drift-enablers","cat":"keep-it-equal"},
  {"id":"ep-1053","type":"spot","hook":"Spot the two red flags: which reactions to 'we've drifted' shut the conversation down?","scene":[{"id":"a","text":"\"Thanks for saying it, let's rebalance.\"","trick":false},{"id":"b","text":"\"But I do so much already.\"","trick":true},{"id":"c","text":"\"Which bits feel uneven to you?\"","trick":false},{"id":"d","text":"\"You're never satisfied, are you.\"","trick":true},{"id":"e","text":"\"Let's swap that one so it's even.\"","trick":false}],"why":"'I do so much already' and 'you're never satisfied' are the red flags; both defend and deflect instead of adjusting the split.","relearn":"Defending and deflecting shut a check-in down; adjusting the split is the fair response.","persona":"any","source":"spot the defensive shut-downs","cat":"keep-it-equal"},
  {"id":"ep-1054","type":"spot","hook":"Spot the two red flags: which responses to a baby coming let the load default to the mum?","scene":[{"id":"a","text":"\"Let's plan the night feeds and split them.\"","trick":false},{"id":"b","text":"\"You'll naturally handle the baby stuff.\"","trick":true},{"id":"c","text":"\"I'll own the appointments and supplies.\"","trick":false},{"id":"d","text":"\"Your mother can help you manage it.\"","trick":true},{"id":"e","text":"\"Let's map the care work in advance.\"","trick":false}],"why":"'You'll naturally handle it' and 'your mother can help' are the red flags; both default baby-care to the mother instead of splitting it.","relearn":"Baby-care defaults to the mother unless you plan and split it in advance.","persona":"Nisha","source":"spot the baby-defaults","cat":"keep-it-equal"},
  {"id":"ep-1055","type":"spot","hook":"Spot the two red flags: which lines turn a check-in into a complaint session?","scene":[{"id":"a","text":"\"What's drifted that we should swap?\"","trick":false},{"id":"b","text":"\"You never do a single thing here.\"","trick":true},{"id":"c","text":"\"You've carried more, let me take some back.\"","trick":false},{"id":"d","text":"\"Why is it always me doing everything?\"","trick":true},{"id":"e","text":"\"Let's keep this quick and fix one thing.\"","trick":false}],"why":"'You never do a thing' and 'why is it always me' are the red flags; both blame instead of opening a calm, fixable check-in.","relearn":"Blaming lines turn a check-in into a fight; keep it calm and fix one concrete thing.","persona":"any","source":"spot the blaming lines","cat":"keep-it-equal"},
  {"id":"ep-1056","type":"spot","hook":"Spot the two red flags: which beliefs make an equal home sound like a loss?","scene":[{"id":"a","text":"An equal home is happier for both of you.","trick":false},{"id":"b","text":"It's a battle of the sexes to win.","trick":true},{"id":"c","text":"Men gain a closer partnership too.","trick":false},{"id":"d","text":"It's just more chores, nothing back.","trick":true},{"id":"e","text":"Kids grow up expecting equality.","trick":false}],"why":"'A battle of the sexes' and 'just more chores, nothing back' are the red flags; both miss that an equal home gains everyone, men included.","relearn":"An equal home gains everyone, men included; 'a battle' or 'nothing back' are the myths.","persona":"Karthik","source":"spot the loss-myths","cat":"keep-it-equal"},
  {"id":"ep-1057","type":"spot","hook":"Spot the two red flags: which moves slide a rebuilt split back to old patterns?","scene":[{"id":"a","text":"Revisiting it on a set cadence.","trick":false},{"id":"b","text":"Pulling back to please relatives.","trick":true},{"id":"c","text":"Backing each other on the agreed split.","trick":false},{"id":"d","text":"Assuming the fix just holds itself.","trick":true},{"id":"e","text":"Owning a slip and resetting fast.","trick":false}],"why":"'Pulling back to please relatives' and 'assuming the fix holds' are the red flags; both let a rebuilt split quietly slide back.","relearn":"Pleasing relatives and assuming the fix holds slide a rebuilt split back; revisit and back each other.","persona":"any","source":"spot the slide-backs","cat":"keep-it-equal"},
  {"id":"ep-1058","type":"spot","hook":"Spot the two red flags: which responses to a swamped partner pile on instead of sharing?","scene":[{"id":"a","text":"\"Let me take the cooking and bills back.\"","trick":false},{"id":"b","text":"\"Tell me if you ever need anything.\"","trick":true},{"id":"c","text":"\"I'll cover bedtime all week.\"","trick":false},{"id":"d","text":"\"Remember how much I usually do, though.\"","trick":true},{"id":"e","text":"\"You rest, I've got the house tonight.\"","trick":false}],"why":"'Tell me if you need anything' and 'remember how much I do' are the red flags; a vague offer and a scorecard both leave the load on her.","relearn":"A vague offer and a scorecard leave the load on her; name what you'll take.","persona":"any","source":"spot the piling-on lines","cat":"keep-it-equal"},
  {"id":"ep-1059","type":"spot","hook":"Spot the two red flags: which signs say a 'settled' split has stopped being fair?","scene":[{"id":"a","text":"One of you quietly does the extra now.","trick":true},{"id":"b","text":"You still review it together each month.","trick":false},{"id":"c","text":"Resentment shows up over small things.","trick":true},{"id":"d","text":"Both can raise a concern freely.","trick":false},{"id":"e","text":"You re-even it whenever life shifts.","trick":false}],"why":"One person quietly doing the extra, and resentment leaking over small things, are the red flags that a 'settled' split has drifted unfair.","relearn":"Quiet extra work and resentment over small things signal a 'settled' split has drifted unfair.","persona":"any","source":"spot the drift signs","cat":"keep-it-equal"},
  {"id":"ep-1080","cat":"see-the-load","type":"strike-rewrite","hook":"\"I do my tasks, so I carry half the load.\"","myth":{"un":"I do my tasks, so I carry half the load.","re":"Doing tasks isn't the whole load; the planning, tracking and remembering behind them is half the work too.","why":"One person can do chores while the other still carries all the managing."},"relearn":"Doing tasks isn't half the load; the invisible planning and remembering is real work too.","persona":"Karthik","source":"tasks aren't the whole load"},
  {"id":"ep-1081","cat":"see-the-load","type":"strike-rewrite","hook":"\"If it mattered, she'd just tell me what to do.\"","myth":{"un":"If it mattered, she'd just tell me what to do.","re":"Having to tell you is itself the work; the noticing and deciding is the load you're not seeing.","why":"Being the one who must instruct is exhausting, invisible labour."},"relearn":"Needing to tell you is itself the invisible load; the noticing and deciding is real work.","persona":"Karthik","source":"the telling is the work"},
  {"id":"ep-1082","cat":"see-the-load","type":"strike-rewrite","hook":"\"Mental load is just being a worrier.\"","myth":{"un":"The mental load is just being a worrier by nature.","re":"It's the constant tracking of what the home needs, not a personality flaw; anyone holding it would feel it.","why":"Calling real cognitive labour 'worrying' makes invisible work disappear."},"relearn":"The mental load is real tracking work, not a worrying personality; anyone carrying it feels the weight.","persona":"Pooja","source":"not just worrying"},
  {"id":"ep-1083","cat":"see-the-load","type":"strike-rewrite","hook":"\"She's home earlier, so the house is naturally her domain.\"","myth":{"un":"She gets home earlier, so the house is naturally her domain.","re":"Being home first doesn't make the whole invisible load one person's job; the managing is still shared.","why":"Who arrives first is a schedule, not a reason to carry all the planning."},"relearn":"Getting home first doesn't make the mental load one person's domain; the managing stays shared.","persona":"any","source":"early home isn't ownership"},
  {"id":"ep-1084","cat":"see-the-load","type":"strike-rewrite","hook":"\"My mother ran the home alone, so it's normal.\"","myth":{"un":"My mother ran the whole home alone, so that's just normal.","re":"That she carried it unseen for years doesn't mean it was fair or that it has to repeat.","why":"A pattern being old doesn't make the invisible load any lighter to carry."},"relearn":"An old family pattern of one person carrying the home doesn't make that load fair or inevitable.","persona":"any","source":"old pattern isn't fair"},
  {"id":"ep-1085","cat":"see-the-load","type":"strike-rewrite","hook":"\"I take the bins and bills, so I've got the load covered.\"","myth":{"un":"I handle the bins and the bills, so I've got the load covered.","re":"A couple of owned tasks isn't the load; dozens of small daily noticings and decisions sit with one person.","why":"The load is the long invisible list, not two visible jobs."},"relearn":"Two visible jobs aren't the load; it's the dozens of daily noticings sitting with one person.","persona":"Karthik","source":"two jobs isn't the load"},
  {"id":"ep-1086","cat":"see-the-load","type":"strike-rewrite","hook":"\"She never looks tired, so the load can't be heavy.\"","myth":{"un":"She never looks tired, so the load can't be that heavy.","re":"Mental load is invisible and often hidden behind a calm face; not looking tired isn't proof it's light.","why":"You can't read a cognitive load off someone's expression."},"relearn":"A calm face isn't proof the mental load is light; invisible work hides behind it.","persona":"any","source":"calm isn't light"},
  {"id":"ep-1087","cat":"see-the-load","type":"strike-rewrite","hook":"\"Planning the festival is just the fun part, not work.\"","myth":{"un":"Planning Diwali and the guests is the fun part, not real work.","re":"Remembering gifts, sweets, cleaning and who visits when is heavy invisible labour, even when it's also joyful.","why":"Something can be meaningful and still be exhausting work to hold alone."},"relearn":"Planning a festival, the gifts, food and guests, is heavy invisible work even when it's joyful.","persona":"Pooja","source":"festival load counts"},
  {"id":"ep-1088","cat":"see-the-load","type":"strike-rewrite","hook":"\"Once the maid comes, there's no load left to share.\"","myth":{"un":"We have a maid, so there's no real load left to share.","re":"Hired help does some chores, but planning, instructing, checking and the rest of the managing still sits with someone.","why":"Outsourcing tasks doesn't outsource the mental load behind them."},"relearn":"Hiring help removes some chores, not the planning, instructing and managing that one person still carries.","persona":"any","source":"help isn't the whole load"},
  {"id":"ep-1089","cat":"see-the-load","type":"strike-rewrite","hook":"\"Keeping the kids' routine going isn't really a job.\"","myth":{"un":"Keeping the kids' routine, meals and naps going isn't really a job.","re":"Holding a child's whole day in your head, meals, sleep, mood, what's next, is constant cognitive work.","why":"The routine only looks effortless because someone is silently running it."},"relearn":"Holding a child's meals, sleep and what's-next in your head is constant, invisible cognitive work.","persona":"any","source":"routine is work"},
  {"id":"ep-1090","cat":"see-the-load","type":"strike-rewrite","hook":"\"She enjoys managing the home, so it isn't a burden.\"","myth":{"un":"She enjoys managing the home, so it isn't a burden on her.","re":"Being good at something, or even liking parts of it, doesn't make carrying it all alone fair or light.","why":"Enjoyment and overload can sit in the same person at the same time."},"relearn":"Enjoying parts of running a home doesn't make carrying the whole invisible load alone fair.","persona":"Pooja","source":"enjoy isn't fair"},
  {"id":"ep-1091","cat":"see-the-load","type":"strike-rewrite","hook":"\"I earn more, so the home stuff is fairly hers.\"","myth":{"un":"I earn more, so the home and its load are fairly hers.","re":"A bigger pay packet doesn't transfer the mental load; the invisible work is still shared work.","why":"Income buys some help, never a partner's whole second shift."},"relearn":"Earning more doesn't transfer the mental load; the invisible work stays shared regardless of pay.","persona":"any","source":"pay isn't an exemption"},
  {"id":"ep-1092","cat":"see-the-load","type":"strike-rewrite","hook":"\"Men just can't see the small home stuff.\"","myth":{"un":"Men just can't see the small home stuff; it's how they're wired.","re":"Noticing what a home needs is a learnable skill, not a gendered ability; anyone can train the eye.","why":"Treating it as 'wiring' lets the load stay stuck on one person."},"relearn":"Seeing what a home needs is a learnable skill, not a gendered trait; anyone can build it.","persona":"any","source":"seeing is learnable"},
  {"id":"ep-1093","cat":"see-the-load","type":"strike-rewrite","hook":"\"We never fight about chores, so the load's fine.\"","myth":{"un":"We never argue about chores, so the load must be fine.","re":"A quiet home can mean one person silently absorbs everything to keep the peace, not that it's fair.","why":"No conflict can be one partner's exhaustion, not balance."},"relearn":"No arguments about chores can mean one person silently absorbs it all, not that the load is fair.","persona":"Pooja","source":"quiet isn't fair"},
  {"id":"ep-1094","cat":"see-the-load","type":"strike-rewrite","hook":"\"Tracking what the in-laws expect isn't on my plate.\"","myth":{"un":"Tracking what the in-laws expect of us isn't really on my plate.","re":"Anticipating relatives' needs and smoothing things over is heavy emotional labour that should be shared.","why":"Managing family expectations is work, even when no chore is visible."},"relearn":"Anticipating in-laws' needs and smoothing things over is shared emotional labour, not one person's job.","persona":"any","source":"family load counts"},
  {"id":"ep-1095","cat":"see-the-load","type":"sort","hook":"Sort: would removing this from one person's head lighten their load?","items":[{"id":"a","text":"Tracking which medicines are running out"},{"id":"b","text":"Wiping the dining table after a meal"},{"id":"c","text":"Remembering a parent's check-up date"},{"id":"d","text":"Folding the dried clothes"},{"id":"e","text":"Knowing whose turn it is to call relatives"},{"id":"f","text":"Watering the plants in the evening"}],"bins":[{"id":"head","label":"Lifts a mental-load weight","valence":"pos"},{"id":"hands","label":"Just a hands task","valence":"neutral"}],"key":{"a":"head","b":"hands","c":"head","d":"hands","e":"head","f":"hands"},"relearn":"Tracking medicines, dates and whose turn it is lives in one head; wiping, folding and watering are hands tasks.","persona":"any","source":"head vs hands"},
  {"id":"ep-1096","cat":"see-the-load","type":"sort","hook":"Sort: a one-off task, or ongoing background tracking?","items":[{"id":"a","text":"Always knowing how much gas is left in the cylinder"},{"id":"b","text":"Hanging a new photo on the wall"},{"id":"c","text":"Keeping a running list of what the house is low on"},{"id":"d","text":"Mopping the floor once this week"},{"id":"e","text":"Holding everyone's medicine schedule in mind"},{"id":"f","text":"Fixing a loose door handle today"}],"bins":[{"id":"ongoing","label":"Ongoing tracking","valence":"uhoh"},{"id":"oneoff","label":"One-off task","valence":"neutral"}],"key":{"a":"ongoing","b":"oneoff","c":"ongoing","d":"oneoff","e":"ongoing","f":"oneoff"},"relearn":"Always-knowing the gas, the low list and medicine schedules is ongoing tracking; hanging a photo or a mop is one-off.","persona":"any","source":"ongoing vs one-off"},
  {"id":"ep-1097","cat":"see-the-load","type":"sort","hook":"Sort: who is really carrying this part of the load?","items":[{"id":"a","text":"\"Just tell me what to buy and I'll get it\""},{"id":"b","text":"\"I've made the list and I'll go this evening\""},{"id":"c","text":"\"Remind me when the bill is due\""},{"id":"d","text":"\"I've set the bill to pay itself, it's handled\""},{"id":"e","text":"\"Let me know if you need help with dinner\""},{"id":"f","text":"\"I've planned dinner for the week, here it is\""}],"bins":[{"id":"oneperson","label":"Load still on one","valence":"uhoh"},{"id":"owned","label":"Fully owned","valence":"pos"}],"key":{"a":"oneperson","b":"owned","c":"oneperson","d":"owned","e":"oneperson","f":"owned"},"relearn":"\"Tell me / remind me / let me know\" keeps the load on one person; \"I've made / set / planned it\" owns it.","persona":"Karthik","source":"tell me vs i've got it"},
  {"id":"ep-1098","cat":"see-the-load","type":"sort","hook":"Sort: visible work everyone sees, or invisible work no one notices?","items":[{"id":"a","text":"Scrubbing the bathroom"},{"id":"b","text":"Remembering it's the kids' vaccine week"},{"id":"c","text":"Carrying water bottles to the car"},{"id":"d","text":"Knowing which relative's birthday is next"},{"id":"e","text":"Drying and stacking the utensils"},{"id":"f","text":"Quietly planning the whole week's meals"}],"bins":[{"id":"seen","label":"Visible, everyone sees it","valence":"neutral"},{"id":"unseen","label":"Invisible, no one notices","valence":"uhoh"}],"key":{"a":"seen","b":"unseen","c":"seen","d":"unseen","e":"seen","f":"unseen"},"relearn":"Scrubbing, carrying and stacking are seen; remembering vaccine week, birthdays and planning meals goes unnoticed.","persona":"any","source":"seen vs unnoticed"},
  {"id":"ep-1099","cat":"see-the-load","type":"sort","hook":"Sort: this gives the manager rest, or just moves the chore?","items":[{"id":"a","text":"\"I'll fully own the kids' school stuff, you don't track it\""},{"id":"b","text":"\"I washed the dishes you pointed out\""},{"id":"c","text":"\"I'll keep the whole grocery system, start to finish\""},{"id":"d","text":"\"I did the one errand you asked\""},{"id":"e","text":"\"I'll plan and book every doctor visit from now\""},{"id":"f","text":"\"Tell me each thing and I'll do it\""}],"bins":[{"id":"rest","label":"Gives the manager rest","valence":"pos"},{"id":"moves","label":"Just moves one chore","valence":"uhoh"}],"key":{"a":"rest","b":"moves","c":"rest","d":"moves","e":"rest","f":"moves"},"relearn":"Owning a whole domain end-to-end gives the manager rest; doing single pointed-out tasks just moves a chore.","persona":"Karthik","source":"rest vs a moved chore"},
  {"id":"ep-1100","cat":"see-the-load","type":"sort","hook":"Sort: this lightens the invisible load, or adds to it?","items":[{"id":"a","text":"\"I'll handle the whole festival guest list\""},{"id":"b","text":"\"What should I cook? You decide and I'll make it\""},{"id":"c","text":"\"I track the bills now, you can forget them\""},{"id":"d","text":"\"Which uniform is washed? You'd know\""},{"id":"e","text":"\"I've got the school-fee deadlines covered\""},{"id":"f","text":"\"Where do we keep the spare keys again?\""}],"bins":[{"id":"lighter","label":"Lightens the load","valence":"pos"},{"id":"heavier","label":"Adds to the load","valence":"uhoh"}],"key":{"a":"lighter","b":"heavier","c":"lighter","d":"heavier","e":"lighter","f":"heavier"},"relearn":"Taking a domain off her head lightens the load; asking her to decide or recall each thing adds to it.","persona":"Karthik","source":"lighter vs heavier"},
  {"id":"ep-1101","cat":"see-the-load","type":"spot","hook":"Spot the two lines that quietly leave all the managing on one person.","scene":[{"id":"a","text":"\"Just make a list and I'll do whatever's on it\"","trick":true},{"id":"b","text":"\"I'll own the groceries end-to-end from now\"","trick":false},{"id":"c","text":"\"Remind me and I'll never forget the bills\"","trick":true},{"id":"d","text":"\"I've put the bills on auto-pay, they're handled\"","trick":false},{"id":"e","text":"\"I'll plan and book the kids' check-ups myself\"","trick":false}],"why":"\"Make a list\" and \"remind me\" keep the noticing and remembering on her; the others take the whole job off her head.","relearn":"Lines that need a list or a reminder leave the mental load on one person.","persona":"Karthik","source":"who keeps the managing"},
  {"id":"ep-1102","cat":"see-the-load","type":"spot","hook":"Spot the two tasks that are pure invisible mental load.","scene":[{"id":"a","text":"Tracking when each bill falls due","trick":true},{"id":"b","text":"Sweeping the front step","trick":false},{"id":"c","text":"Holding the whole family's week in your head","trick":true},{"id":"d","text":"Ironing a shirt for tomorrow","trick":false},{"id":"e","text":"Refilling the water jug","trick":false}],"why":"Tracking due dates and holding the week in your head is invisible mental load; sweeping, ironing and refilling are visible.","relearn":"Tracking deadlines and holding the family's week in mind is pure, invisible mental load.","persona":"any","source":"pure mental load"},
  {"id":"ep-1103","cat":"see-the-load","type":"spot","hook":"Spot the two phrases that prove the load is sitting on one person.","scene":[{"id":"a","text":"\"Did you remember to...\" said to the same partner daily","trick":true},{"id":"b","text":"\"I noticed we were low, so I restocked\"","trick":false},{"id":"c","text":"\"You're the one who keeps track of all this\"","trick":true},{"id":"d","text":"\"We both keep an eye on what's running out\"","trick":false},{"id":"e","text":"\"Either of us books the appointments\"","trick":false}],"why":"A daily \"did you remember\" and \"you keep track of all this\" show one person carries it; the rest show shared noticing.","relearn":"If one partner is always the keeper-of-track and the reminder, the load isn't shared.","persona":"any","source":"phrases that reveal it"},
  {"id":"ep-1104","cat":"see-the-load","type":"spot","hook":"Spot the two beliefs that keep the mental load invisible.","scene":[{"id":"a","text":"\"It's not work if no one's lifting anything\"","trick":true},{"id":"b","text":"\"Planning the week is real, tiring work\"","trick":false},{"id":"c","text":"\"She's just naturally better at remembering\"","trick":true},{"id":"d","text":"\"Remembering can be shared if we both try\"","trick":false},{"id":"e","text":"\"The invisible stuff counts as much as chores\"","trick":false}],"why":"\"Not work unless you're lifting\" and \"she's naturally better\" keep the load hidden on one person; the rest name it.","relearn":"Beliefs that planning isn't 'work' or is one person's 'nature' keep the load invisible.","persona":"any","source":"myths that hide it"},
  {"id":"ep-1105","cat":"see-the-load","type":"spot","hook":"Spot the two lines that hand the mental load back, not share it.","scene":[{"id":"a","text":"\"Which doctor do we use? You'd remember\"","trick":true},{"id":"b","text":"\"I've saved the doctor's number, I'll book it\"","trick":false},{"id":"c","text":"\"What did we decide about the trip? You tell me\"","trick":true},{"id":"d","text":"\"I checked our notes and sorted the trip\"","trick":false},{"id":"e","text":"\"I'll keep the travel plans in my head this time\"","trick":false}],"why":"Asking her to recall the doctor and trip hands the load back; the others keep it off her head.","relearn":"Asking your partner to recall every detail hands the load back instead of sharing it.","persona":"Karthik","source":"handing it back"},
  {"id":"ep-1106","cat":"see-the-load","type":"spot","hook":"Spot the two signs that 'helping' is hiding an unequal load.","scene":[{"id":"a","text":"One partner always waits to be told what to do","trick":true},{"id":"b","text":"Both spot a job and start it without a word","trick":false},{"id":"c","text":"Only one keeps the master to-do list in mind","trick":true},{"id":"d","text":"Either one can run a whole errand alone","trick":false},{"id":"e","text":"Both know what's due this week","trick":false}],"why":"Waiting to be told and being the lone list-keeper show the load sits on one; the rest show both carry it.","relearn":"Waiting to be told and being the only list-keeper are signs the mental load is unequal.","persona":"any","source":"helping hides imbalance"},
  {"id":"ep-1107","cat":"see-the-load","type":"branch","persona":"Karthik","source":"behind even chores","hook":"Pooja's started falling asleep on the sofa by nine most nights.","steps":[{"prompt":"The chores look evenly split, yet she's so tired. What do you do?","options":[{"text":"Ask her to list everything she holds in her head daily","then":"The list of things she's tracking is far longer than the chore chart.","best":true},{"text":"Suggest she nap more on weekends","then":"She could use the rest, but nothing about what's exhausting her actually changes."},{"text":"Point out the chores are already split exactly 50/50","then":"Pooja looks even more tired hearing that used as an argument."},{"text":"Ask if she's coming down with something","then":"She says she's fine, physically, just quietly exhausted."}],"why":"Asking what she tracks daily reveals the load a chore chart can't show."},{"prompt":"At the weekend, Pooja mentions birthday reminders and insurance renewals you'd never thought about. What do you do?","options":[{"text":"Take over two of those, reminders and all","then":"Pooja visibly relaxes, two fewer things sitting in her head.","best":true},{"text":"Say you'll help remember them together","then":"You both try to remember, but the actual responsibility stays with her."},{"text":"Say most of those honestly seem pretty minor","then":"She points out it's exactly that mindset that made them invisible."},{"text":"Suggest she write reminders in her phone","then":"The tool changes, but who's responsible for checking it doesn't."}],"why":"Fully taking over specific tracked items, not just sharing the remembering, actually lightens the load."},{"prompt":"Weeks later, a cousin comments the house 'runs itself' these days. What do you do?","options":[{"text":"Say it runs because someone tracks it, and who","then":"Your cousin looks surprised, then a little thoughtful.","best":true},{"text":"Say Pooja's just really organised","then":"It praises her, and hides the work behind the organising."},{"text":"Agree it does run itself now","then":"It erases the tracking that keeps the house going."},{"text":"Joke that you've finally stepped up properly","then":"It frames the home as hers, with you helping out."}],"why":"Naming the tracking honestly stops invisible work being written off as a house that runs itself."}],"debrief":"A chore chart can look even and still hide an uneven mental load; ask to see the tracking, not the tally.","relearn":"When chores look even but a partner is drained, ask to see the invisible load they track."},
  {"id":"ep-1108","cat":"see-the-load","type":"branch","persona":"Pooja","source":"he helps reframe","hook":"Your aunt's visiting for the weekend, full of opinions about your household.","steps":[{"prompt":"Your aunt says you're so lucky Karthik helps at home. What do you do?","options":[{"text":"Gently say you're both learning to share the load","then":"Your aunt pauses, then says that's a nicer way to put it.","best":true},{"text":"Say he's actually gotten a lot better lately","then":"It sounds positive, but it still frames the home as yours by default."},{"text":"Just smile and let 'he helps' stand","then":"Your aunt nods, and the comment settles as the family's understanding."},{"text":"Joke that you trained him well","then":"It gets a laugh, but it still puts you in charge and him as a helper."}],"why":"Naming it as sharing, not helping, gently corrects the frame without an argument."},{"prompt":"Later, your aunt asks what exactly Karthik does at home. What do you do?","options":[{"text":"List the specific things he actually owns","then":"Your aunt looks a little surprised at how much it actually is.","best":true},{"text":"Say he does quite a bit around the house generally","then":"It sounds fine, but quite a bit doesn't say much at all."},{"text":"Say he does the heavy stuff, mostly","then":"It quietly reinforces that the everyday running is still yours."},{"text":"Say you're not really keeping count","then":"It makes the shared load sound vague and unconfirmed."}],"why":"Naming his specific owned tasks shows the sharing is real, not just a kind phrase."},{"prompt":"That evening, Karthik asks how the conversation with your aunt went. What do you do?","options":[{"text":"Tell him honestly, and ask him to back you up on it next time","then":"He agrees, glad to be seen as an owner, not a helper.","best":true},{"text":"Say it was fine and just leave it there for now","then":"The reframe stays yours alone to keep repeating each time."},{"text":"Say it doesn't really matter what relatives think anyway","then":"It's true, but it also drops the chance to make the reframe stick."},{"text":"Say you're tired of having to explain it every time","then":"It turns into a complaint instead of a plan for next time."}],"why":"Asking him to back the reframe up together makes it a shared story, not just yours to repeat."}],"debrief":"'He helps' keeps the load hers by default; naming shared ownership gently shifts the frame.","relearn":"When others praise a partner for 'helping', reframe it as both sharing the whole load."},
  {"id":"ep-1109","cat":"see-the-load","type":"branch","persona":"Karthik","source":"her thing relabelled","hook":"Lately you've noticed a habit in how you talk about the house.","steps":[{"prompt":"You catch yourself calling the home 'her thing' again. What do you do?","options":[{"text":"Ask Pooja to walk you through a full day's invisible work","then":"By the third item, you realise how much you'd quietly labelled away.","best":true},{"text":"Decide it's fine since she's never actually said otherwise","then":"Her silence was never the same as things being fine."},{"text":"Tell yourself she's just better at it than you","then":"It sounds like a compliment, but it also excuses you from learning it."},{"text":"Wait for her to bring it up if it bothers her","then":"She's been carrying it quietly for months, waiting for you to notice first."}],"why":"Asking her to walk you through a real day is how you actually unlearn 'her thing'."},{"prompt":"That weekend, Pooja says she's been juggling the maid's leave, the gas booking and your mother's check-up. What do you do?","options":[{"text":"Ask which parts she'd most want handed over first","then":"She names two things immediately, relieved to finally be asked.","best":true},{"text":"Say you feel bad and promise to notice more","then":"Noticing more is a start, but nothing specific has actually moved yet."},{"text":"Say you didn't realise because she never complained","then":"It quietly puts the responsibility back on her for staying silent."},{"text":"Tell her you'll take over 'some stuff' soon","then":"Without specifics, some stuff never quite arrives."}],"why":"Asking what to take over first turns a hard realisation into an actual handover."},{"prompt":"A month later, your sister-in-law calls the house 'her domain' as a compliment. What do you do?","options":[{"text":"Say gently that it should be both of yours to run","then":"Your sister-in-law looks surprised, then a bit curious.","best":true},{"text":"Let the compliment stand, since it's clearly meant kindly","then":"The label sticks, and 'her thing' settles back into place."},{"text":"Agree, since she really is better at it","then":"It quietly hands the label right back, in one easy sentence."},{"text":"Joke that you'd be lost without her running it","then":"Everyone laughs, and the label gets a little stronger."}],"why":"Correcting the label out loud, even gently, is what keeps 'her thing' from creeping back."}],"debrief":"Labelling the load 'her thing' makes it invisible; see a real day before deciding it's fair.","relearn":"If you call the home 'her thing', ask her to walk you through a real day's invisible work."},
  {"id":"ep-1110","cat":"see-the-load","type":"branch","persona":"any","source":"see it before it grows","hook":"Kabir mentioned last week that parenthood is closer than it feels.","steps":[{"prompt":"With the baby due in a few months, you want to understand the load before it grows. What do you do?","options":[{"text":"Map every visible and invisible task together, now","then":"The list surprises you both, and it's far calmer to build now than later.","best":true},{"text":"Agree to wait and sort it out once the baby comes","then":"Waiting sounds easier, but the newborn weeks are the worst time to start mapping anything."},{"text":"Ask your mother how she managed it, and copy that","then":"Her era's split doesn't match what you and Kabir actually need."},{"text":"Buy every gadget that promises to make it easier","then":"The gadgets help a little, but nobody's actually planned who does what."}],"why":"Mapping the full load now, while it's calmer, beats discovering it mid-chaos later."},{"prompt":"A week later, Kabir asks who'll be up at night once the baby comes. What do you do?","options":[{"text":"Sit down and plan the night-time load together now","then":"You both leave with a clear, agreed plan for the hardest hours.","best":true},{"text":"Say you'll split it naturally once you see how the baby sleeps","then":"It sounds flexible, but naturally usually means whoever's already awake."},{"text":"Say you'll take nights since you sleep lighter","then":"It's decided in one sentence, without really discussing it."},{"text":"Say it feels too far off to plan yet","then":"The hardest hours stay unplanned, exactly where it matters most."}],"why":"Assigning the night load in advance, not waiting to see, keeps it from defaulting unfairly."},{"prompt":"A relative asks if you've 'sorted the baby stuff' yet. What do you do?","options":[{"text":"Say honestly what you've planned together and what's still open","then":"Your relative looks surprised you're planning it as a pair.","best":true},{"text":"Say you're sure it'll work itself out","then":"It sounds relaxed, and quietly signals nobody needs to plan."},{"text":"Say Kabir's got it handled","then":"It hands the planning, in everyone's eyes, to one of you."},{"text":"Say you'll deal with it once the baby's here","then":"The relative nods, and waiting starts to sound like a plan."}],"why":"Being honest about what you've planned as a pair keeps the planning shared, even in others' eyes."}],"debrief":"Seeing the whole load before a big change is far easier than untangling it mid-crisis.","relearn":"Map the full visible and invisible load together before a big life change, not during it."},
  {"id":"ep-1111","cat":"see-the-load","type":"branch","persona":"Karthik","source":"never switching off","hook":"Pooja's been running on fumes all week, her mind never quite switching off.","steps":[{"prompt":"Pooja's half asleep, still murmuring tomorrow's tasks. What do you do?","options":[{"text":"Say you'll hold tomorrow's list tonight, so she can rest","then":"She murmurs a thank you and, for once, actually drifts off.","best":true},{"text":"Gently tell her to just stop thinking and relax","then":"It's meant kindly, but her mind keeps running exactly the same list."},{"text":"Let her drift off, and finish the list yourself quietly","then":"You finish it, but she still wakes up thinking it's all on her."},{"text":"Ask her gently if she's okay","then":"She says she's fine, and the running list keeps running anyway."}],"why":"Taking the actual tracking off her, not just telling her to relax, is what lets her mind switch off."},{"prompt":"The next morning, Pooja is quietly going over the day's tasks again. What do you do?","options":[{"text":"Take two things off her list, and confirm them now","then":"She looks genuinely surprised, and visibly lighter.","best":true},{"text":"Say you got the gist and it's handled","then":"It sounds reassuring, but she's still not sure what's actually covered."},{"text":"Ask her to remind you what was on it","then":"The tracking quietly lands right back on her, again."},{"text":"Say you were honestly too tired to really take it all in","then":"She sighs and starts rebuilding the list in her head."}],"why":"Confirming exactly what's handled, specifically, is what actually lets her stop tracking it."},{"prompt":"A week later, you notice Pooja's stopped narrating her lists out loud. What do you do?","options":[{"text":"Ask what else you could take off her mind","then":"She names two more things, relieved someone's actually asking.","best":true},{"text":"Take it as a sign everything's fine now","then":"The quiet isn't relief. It's her going back to holding it alone."},{"text":"Ask her once if she's okay, then let it drop","then":"She says she's fine, and the subject doesn't come up again."},{"text":"Assume she's just gotten used to it","then":"She shrugs and goes on holding every list herself, tired and quiet."}],"why":"Actively asking what else to take off, rather than assuming calm means fine, keeps the load shared."}],"debrief":"The load is partly never putting it down. Offer to hold it. Don't say 'just relax'.","relearn":"The mental load is a mind that won't switch off. Hold the tracking. Don't say 'relax'."},
  {"id":"ep-1112","cat":"see-the-load","type":"branch","persona":"any","source":"a week of decisions","hook":"Ananya's phone buzzes all evening with questions from the maid, the society office and your mother.","steps":[{"prompt":"You suspect you've never really seen how much Ananya tracks. What do you do?","options":[{"text":"For a week, write down every home decision and who made it","then":"By Wednesday, the page already tells a different story than you expected.","best":true},{"text":"Trust your gut that it's roughly even","then":"Your gut feels confident, but it's never actually been tested against anything."},{"text":"Ask Ananya directly if she feels it's unfair","then":"She hesitates to answer honestly, not wanting to start a fight over a feeling."},{"text":"Compare how many chores each of you physically does around the house","then":"The chore count says nothing about who's deciding and remembering them."}],"why":"A week of writing down who decides what makes the invisible load visible on paper, not guesswork."},{"prompt":"A few days later, Ananya says she's tired of deciding every small thing, from dinner to the plumber. What do you do?","options":[{"text":"Go through those calls with her, and pick some to own","then":"Each 'small' call turns out to hide a chain of checking, and you take on three.","best":true},{"text":"Say you'll just decide more things yourself from now on","then":"You start deciding things, but not the ones she's actually been holding."},{"text":"Say everyone gets tired of deciding things sometimes","then":"Ananya goes quiet. It sounds like her tiredness doesn't count."},{"text":"Suggest you both just alternate every decision from now on","then":"Alternating sounds fair, but some calls need someone who's been tracking all along."}],"why":"Learning what each call involves, then owning some, shares the weight, not just the deciding."},{"prompt":"A friend says her husband insists their home is 'roughly even'. What do you do?","options":[{"text":"Suggest they write down every home decision for a week","then":"Your friend decides to try it, curious what the page will show.","best":true},{"text":"Say it's probably fine if neither of them is complaining","then":"Your friend looks unconvinced. She's clearly the one who's tired."},{"text":"Tell her to keep arguing it with him until he sees it","then":"More arguing hardens his 'roughly even' instead of testing it."},{"text":"Say it evens out over time in most homes","then":"It sounds reassuring, and leaves 'roughly even' untested."}],"why":"A week of noting who decides what tests 'roughly even' against something real."}],"debrief":"A week of noting who decides what makes the invisible load visible on paper.","relearn":"Note who makes each home decision for a week to see who's really carrying the managing."},
  {"id":"ep-1113","cat":"see-the-load","type":"branch","persona":"Karthik","source":"running it all","hook":"Pooja's been unusually quiet after finishing yet another long list in her head.","steps":[{"prompt":"Pooja says she's tired from running it all, not the chores. What do you do?","options":[{"text":"Believe her, and ask what 'running it all' means daily","then":"She describes a constant background hum of decisions you'd never noticed.","best":true},{"text":"Say chores aren't heavy so she shouldn't be tired","then":"Pooja goes quiet, feeling unheard rather than understood."},{"text":"Suggest she's just stressed about work","then":"It moves the conversation away from the actual thing she named."},{"text":"Offer to do a couple of extra chores this week","then":"It's kind, but it answers a question she didn't actually ask."}],"why":"Asking what 'running it all' means, and believing her, is how you actually learn the real load."},{"prompt":"Later that week, Pooja says most of what tires her happens in her head, not on any list. What do you do?","options":[{"text":"Ask her to teach you to run one whole piece of it yourself","then":"She walks you through the building's maintenance WhatsApp group, relieved to hand off one real thing.","best":true},{"text":"Say you'll try to think about those things too","then":"You both end up thinking about the same things, doubling the effort instead of sharing it."},{"text":"Suggest she write it all down so it's less to remember","then":"Writing it down is still her job, and now there's a list to maintain too."},{"text":"Say it sounds exhausting and leave it there","then":"Sympathy alone doesn't move a single thing off her plate."}],"why":"Taking over one whole piece of the running, not just thinking alongside her, actually shares the load."},{"prompt":"A week later, Pooja sighs that she's the only one who knows when anything is due. What do you do?","options":[{"text":"Offer to own the due dates yourself, starting this month","then":"She talks you through what's due, and for once doesn't have to hold it afterwards.","best":true},{"text":"Tell her she can always ask you to check things","then":"It keeps her as the one who knows, and you as the one who's asked."},{"text":"Remind her how much you've already been doing","then":"Pooja goes quiet. Her tiredness now has to wait its turn."},{"text":"Suggest a shared calendar so she can put it all in","then":"It's a neat tool, but she's still the one filling it in."}],"why":"Owning the due dates yourself, not offering to be asked, is what takes the knowing off her."}],"debrief":"The exhausting part is often the running, not the chores; ask what that running involves.","relearn":"When a partner is tired from 'running it all', the load is the managing, not the chores."},
  {"id":"ep-1114","cat":"see-the-load","type":"branch","persona":"Karthik","source":"the daily question","hook":"The nightly dinner question has become a running joke, except it isn't really funny anymore.","steps":[{"prompt":"You're about to ask what's for dinner for the hundredth time. What do you do?","options":[{"text":"Take over dinner-planning fully this week instead","then":"Pooja looks up, surprised. \"You mean deciding, not just eating?\"","best":true},{"text":"Ask anyway, since it's only a simple question","then":"It's simple for you to ask, and one more small decision landed on her."},{"text":"Suggest ordering in so nobody has to decide","then":"It skips the question tonight, but tomorrow it's right back."},{"text":"Ask Pooja to just tell you the week's meals in advance","then":"She now has to plan the week and still answer questions daily."}],"why":"Owning the planning yourself, not asking her to decide, actually removes the daily handoff."},{"prompt":"The next evening, you open the fridge and can't tell what's already there. What do you do?","options":[{"text":"Check what's there yourself and plan around it","then":"You catch yourself doing the quiet tracking she used to do alone.","best":true},{"text":"Ask Pooja quickly what's already in the fridge","then":"It's fast, but the tracking of what's in stock stays with her."},{"text":"Just buy everything fresh regardless of what's there","then":"Half the fridge goes to waste, and nobody planned around it."},{"text":"Skip checking and hope nothing overlaps","then":"You end up with three kinds of dal and no vegetables."}],"why":"Tracking what's actually in stock yourself is part of owning dinner, not just deciding the menu."},{"prompt":"At the weekend, Pooja jokes that 'what's for dinner' is her least favourite question. What do you do?","options":[{"text":"Say you'll plan dinner from now on, fridge included","then":"She looks at you, half hopeful. \"Planning it, not just cooking it?\"","best":true},{"text":"Say you'll take it over once things are less busy","then":"It quietly tells her the question stays hers for now."},{"text":"Promise to stop asking her what's for dinner","then":"The question stops, but the deciding still happens in her head."},{"text":"Ask her to keep a list of meal ideas for you","then":"It saves you thinking, and adds one more list to her head."}],"why":"Owning dinner planning, stock included, is what finally takes the question off her mind."}],"debrief":"Small daily 'what's for...' questions are tiny load-handoffs; owning the domain ends them.","relearn":"Each 'what's for dinner?' hands the load back; owning the planning removes the question."},
  {"id":"ep-1115","cat":"see-the-load","type":"branch","persona":"any","source":"blame to mapping","hook":"Rhea snapped at you over the unwashed pressure cooker tonight, and you snapped back.","steps":[{"prompt":"You're both exhausted, and it's turning into blame. What do you do?","options":[{"text":"Stop, and suggest listing the full load together instead","then":"The tone shifts from arguing to actually mapping what's real.","best":true},{"text":"Keep score of who did less this week","then":"The scoreboard just gives you both new numbers to fight about."},{"text":"Point out you've had a harder week than her","then":"Rhea's face hardens. It's turned into a competition."},{"text":"Suggest you both just calm down and stop talking about it","then":"The exhaustion stays, unnamed and unaddressed, under the surface."}],"why":"Mapping the full load together turns a fight into a shared problem you can actually solve."},{"prompt":"The next evening, calmer, Rhea starts listing everything the house needs, and it runs long. What do you do?","options":[{"text":"Keep going with her, even the uncomfortable items","then":"The finished list explains, finally, why you've both been so tired.","best":true},{"text":"Say that's enough, since the point's already made","then":"You stop before the list is complete, and half the load stays unnamed."},{"text":"Suggest skipping the parts that might start another fight","then":"The load stays partly hidden, exactly where blame used to live."},{"text":"Leave her to finish it since she's better with details","then":"It quietly hands the mapping itself back onto her."}],"why":"Finishing the list honestly, not stopping early, is what makes the imbalance fully visible."},{"prompt":"Over the weekend, Rhea asks what you should do with what you've written. What do you do?","options":[{"text":"Suggest picking owned areas from it together","then":"You end with a real plan instead of leftover resentment.","best":true},{"text":"Say it just helps to have it all out","then":"Feeling heard is real, but nothing about the actual load has moved."},{"text":"Say you'll each just do more from now on","then":"Nobody knows who's doing more of what, so nothing really changes."},{"text":"Suggest taking a break from the topic for now","then":"The list sits there, seen but untouched."}],"why":"Turning the list into owned areas, not just relief, is what actually rebalances things."}],"debrief":"Blame hides the load; mapping it together turns a fight into a shared problem.","relearn":"Swap blame for mapping the full load together to see what's really unshared."},
  {"id":"ep-1116","cat":"see-the-load","type":"match","hook":"Match each invisible-load job to the visible chore people see instead.","pairs":[{"left":"Planning the week's meals","right":"Cooking the dinner"},{"left":"Tracking what's running out","right":"Buying the groceries"},{"left":"Remembering the bill dates","right":"Paying the bill"},{"left":"Holding the kids' schedule","right":"Dropping them to class"},{"left":"Knowing what guests need","right":"Serving the tea"}],"relearn":"Behind each visible chore sits an invisible planning job people rarely see or count.","persona":"any","source":"invisible behind visible"},
  {"id":"ep-1117","cat":"see-the-load","type":"match","hook":"Match each load word to what it actually means at home.","pairs":[{"left":"Mental load","right":"Holding everything that's needed in mind"},{"left":"Emotional labour","right":"Keeping everyone okay and at peace"},{"left":"Anticipating","right":"Seeing a need before it becomes a problem"},{"left":"Delegating","right":"Deciding who does what, and tracking it"},{"left":"Default parent","right":"The one everyone turns to first"}],"relearn":"Mental load, emotional labour, anticipating and being the default are the invisible parts of running a home.","persona":"any","source":"naming the parts"},
  {"id":"ep-1118","cat":"see-the-load","type":"match","hook":"Match the comment to the hidden load it's pointing at.","pairs":[{"left":"\"How do you always know where things are?\"","right":"You carry the home's whole memory"},{"left":"\"Did the school send anything?\"","right":"You track every notice and form"},{"left":"\"We're out of atta again?\"","right":"You monitor every supply"},{"left":"\"When's your mother's medicine due?\"","right":"You hold the family's health calendar"},{"left":"\"What do we gift them?\"","right":"You manage all the social obligations"}],"relearn":"Everyday questions land on one person because they carry the home's memory, supplies, calendar and social load.","persona":"Pooja","source":"questions reveal the load"},
  {"id":"ep-1119","cat":"see-the-load","type":"match","hook":"Match each 'I help' line to the load it leaves untouched.","pairs":[{"left":"\"I cook when you ask\"","right":"You still plan every meal"},{"left":"\"I shop with the list you make\"","right":"You still track what we need"},{"left":"\"I pay the bills you flag\"","right":"You still remember the dates"},{"left":"\"I drop the kids when you remind me\"","right":"You still hold the schedule"},{"left":"\"I tidy when you point it out\"","right":"You still notice the mess first"}],"relearn":"'Helping when asked' leaves all the planning, tracking and noticing, the real load, on one person.","persona":"Karthik","source":"help leaves the load"},
  {"id":"ep-1120","cat":"see-the-load","type":"match","hook":"Match each home role to the invisible work it really involves.","pairs":[{"left":"The cook","right":"Deciding what feeds everyone all week"},{"left":"The shopper","right":"Knowing the whole house's needs"},{"left":"The 'reminder'","right":"Carrying everyone's deadlines"},{"left":"The peacemaker","right":"Managing every family mood"},{"left":"The planner","right":"Mapping the days before they happen"}],"relearn":"Each everyday home role carries invisible deciding, knowing, remembering and planning underneath the visible task.","persona":"any","source":"roles carry load"},
  {"id":"ep-1121","cat":"see-the-load","type":"match","hook":"Match each India-home moment to the invisible load behind it.","pairs":[{"left":"Cylinder swapped before it runs out","right":"Someone tracks the gas daily"},{"left":"Right sweets ready for every guest","right":"Someone recalls each taste"},{"left":"Uniforms always washed by Monday","right":"Someone runs the laundry calendar"},{"left":"In-laws' rituals never forgotten","right":"Someone holds the festival schedule"},{"left":"Maid briefed well each morning","right":"Someone plans the help"}],"relearn":"Smooth Indian homes hide one person tracking gas, guests, laundry, rituals and the help.","persona":"any","source":"india home load"},
  {"id":"ep-1122","cat":"see-the-load","type":"match","hook":"Match each tired phrase to the load it's quietly describing.","pairs":[{"left":"\"I can never switch off\"","right":"The mind always tracking what's next"},{"left":"\"Nothing happens unless I drive it\"","right":"Being the home's only engine"},{"left":"\"I'm the family Google calendar\"","right":"Holding everyone's dates alone"},{"left":"\"If I forget, it just doesn't get done\"","right":"No backup for the remembering"},{"left":"\"I'm tired before the day starts\"","right":"Waking already loaded with the list"}],"relearn":"Phrases like 'I can never switch off' name a mental load one person carries with no backup.","persona":"Pooja","source":"tired phrases"},
  {"id":"ep-1123","cat":"see-the-load","type":"reflect","hook":"Lensy: the mental load is the part no one claps for, planning, tracking, remembering. Seen it in your home?","prompt":"What do you notice?","options":["Yes, all the time","Now that you say it","I want to look closer"],"affirm":"Just noticing the invisible work is the start; once you see it, you can finally begin to share it.","relearn":"The first move toward fairness is simply noticing the invisible planning and tracking at home.","persona":"any","source":"noticing the unclapped work"},
  {"id":"ep-1124","cat":"see-the-load","type":"reflect","hook":"Lensy: think of one job at home that runs so smoothly you forget someone's running it.","prompt":"Which one comes to mind?","options":["Meals","The kids' routine","Bills and supplies"],"affirm":"Whatever you pictured, someone is quietly carrying it; smooth-running things are the most invisible load of all.","relearn":"The home jobs that run smoothly are often the heaviest invisible load, carried unseen.","persona":"any","source":"the smooth-running job"},
  {"id":"ep-1125","cat":"see-the-load","type":"reflect","hook":"Lensy: if your partner vanished for a week, what would you suddenly have to remember?","prompt":"What pops up first?","options":["So many small things","I'd be lost on dates","More than I'd like to admit"],"affirm":"Everything that flooded in is the invisible load they carry daily; that list is the work no one usually sees.","relearn":"Imagining a partner's absence reveals the invisible mental load they carry every single day.","persona":"Karthik","source":"the absence test"},
  {"id":"ep-1126","cat":"see-the-load","type":"reflect","hook":"Lensy: 'who keeps the home in their head?' is a bigger question than 'who does the chores'. Sit with it.","prompt":"What comes up?","options":["It's mostly one of us","More even than I thought","I need to ask my partner"],"affirm":"There's no wrong answer here; asking who holds the home in their head is how the invisible load gets seen.","relearn":"Asking who keeps the home in their head surfaces a load that counting chores never shows.","persona":"any","source":"who holds it in mind"},
  {"id":"ep-1127","cat":"see-the-load","type":"reflect","hook":"Lensy: notice a time you said 'just tell me what to do' at home. What was it really asking?","prompt":"What do you see now?","options":["I left the thinking to them","It seemed helpful at the time","I'd phrase it differently now"],"affirm":"However you saw it, 'just tell me' quietly leaves the planning with one person; noticing that is real progress.","relearn":"'Just tell me what to do' leaves the planning load on one partner, even when it feels helpful.","persona":"Karthik","source":"just tell me"},
  {"id":"ep-1128","cat":"see-the-load","type":"reflect","hook":"Lensy: picture your home's invisible work written on one page. Whose handwriting fills it?","prompt":"What do you imagine?","options":["Mostly one of us","A real mix","I honestly don't know yet"],"affirm":"Whatever you pictured, imagining that page is how the unseen load becomes something you can finally share.","relearn":"Picturing the home's invisible work as one page helps you see who's really filling it.","persona":"any","source":"whose handwriting"},
  {"id":"ep-1129","cat":"see-the-load","type":"role-play","persona":"Pooja","source":"show you the load","hook":"You want Karthik to grasp the load without it sounding like an attack.","setup":"One evening he looks up and notices your face.","steps":[{"prompt":"Karthik asks: \"Is something wrong? You seem tense lately.\"","options":[{"text":"\"Can I show you everything I keep track of?\"","then":"He nods, curious rather than defensive. \"Yeah, show me.\"","best":true},{"text":"\"You have no idea how much I actually do around here.\"","then":"Karthik stiffens and defends himself. Then, quieter: \"Okay. What am I missing?\""},{"text":"\"It's nothing. I'm just tired.\"","then":"He accepts that, then pauses. \"You've seemed tense for weeks. What's really going on?\""},{"text":"\"You could pay a lot more attention if you actually cared.\"","then":"Karthik looks hurt rather than curious. After a moment: \"Then tell me what I'm not seeing.\""}],"why":"Framing it as showing him something invisible, not accusing him, keeps him listening."},{"prompt":"Karthik says: \"I mean it. I'd rather understand than guess. Where do we even start?\"","options":[{"text":"\"Start with today, everything I've tracked since morning.\"","then":"By lunch alone, the list already surprises him.","best":true},{"text":"\"Just believe me that it's a lot.\"","then":"He wants to believe it, but without specifics it's hard for him to really see."},{"text":"\"Compare it to how little you actually do around here these days.\"","then":"It turns into a scoreboard instead of a shared view."},{"text":"\"It's too much to even explain properly.\"","then":"Karthik shrugs, unsure what he's even meant to understand."}],"why":"Walking through one real day, specifically, makes the invisible load land, not just feel true."},{"prompt":"Karthik says: \"I want to get this right. What would actually help you?\"","options":[{"text":"\"Pick two things I track, and take them over from today.\"","then":"He agrees right away, glad to finally have something concrete to do.","best":true},{"text":"\"Just keep trying to understand. That's enough for now.\"","then":"Wanting to understand is real, but nothing you carry has actually moved."},{"text":"\"I've been asking for this for ages.\"","then":"Karthik goes defensive. \"I didn't know it was that long.\" The talk turns to the past, and no task gets picked."},{"text":"\"It's honestly fine. I'm used to it by now anyway.\"","then":"It quietly lets the load settle right back onto you."}],"why":"Naming what to take over now, not just feeling understood, is what shares the load."}],"relearn":"Invite your partner to see the invisible load with you, rather than accusing them of not seeing it."},
  {"id":"ep-1130","cat":"see-the-load","type":"role-play","persona":"Pooja","source":"runs itself","hook":"You've been quietly running everything behind the scenes, and today it finally gets on your nerves.","setup":"You decide to name it, right then.","steps":[{"prompt":"Karthik says: \"Honestly, this place just runs itself these days.\"","options":[{"text":"\"It runs because I'm tracking it all day.\"","then":"He pauses, surprised. \"I didn't realise that's what was happening.\"","best":true},{"text":"\"Fine, let it just run itself then. See how that goes.\"","then":"He looks confused as things quietly start slipping the next morning."},{"text":"\"You'd definitely notice if I ever stopped.\"","then":"It lands as a threat rather than an invitation to see the work."},{"text":"\"It's fine. Don't worry about it.\"","then":"Karthik pauses. \"You don't sound fine. What's going on?\""}],"why":"Naming the tracking, and inviting him to see it, corrects the frame without a fight."},{"prompt":"Later, Karthik asks: \"Seriously, what goes into keeping this place running?\"","options":[{"text":"\"Let me walk you through today, everything I remembered.\"","then":"By evening, he's genuinely startled by how long the list is.","best":true},{"text":"\"It's really hard to explain. You'd have to feel it yourself.\"","then":"He nods, but without specifics, it's hard for him to actually grasp."},{"text":"\"It means I do everything, basically.\"","then":"It sounds like a complaint rather than something he can act on."},{"text":"\"Never mind. It's not worth going into.\"","then":"He frowns. \"It clearly is worth it. I'll ask again.\""}],"why":"Walking through a real day's tracking makes the invisible engine visible, not just claimed."},{"prompt":"A few days later, Karthik says: \"I've been thinking about what you said. I want to actually take some of this on.\"","options":[{"text":"\"Take this one whole piece, starting tomorrow.\"","then":"He writes it down carefully, taking it seriously.","best":true},{"text":"\"Just help whenever you notice something.\"","then":"Whenever he notices means the noticing is still your job too."},{"text":"\"It's fine. I've got a system already.\"","then":"The offer quietly gets declined, and nothing changes."},{"text":"\"I'll give you something small first to see if you follow through.\"","then":"It starts the handover with suspicion instead of trust."}],"why":"Handing over one whole tracked piece, clearly, is what turns the offer into an actual shift."}],"relearn":"Name the invisible tracking that makes a home 'run itself', and invite your partner to see it."},
  {"id":"ep-1131","cat":"see-the-load","type":"role-play","persona":"Karthik","source":"walk me through a day","hook":"You realise you've never actually asked what Pooja holds in her head all day.","setup":"That evening, you ask, and mean it.","steps":[{"prompt":"Pooja looks a little surprised and asks: \"Why the sudden interest?\"","options":[{"text":"\"Walk me through a normal day, every little thing you're remembering.\"","then":"She starts slowly. Then the list picks up speed as it comes back to her.","best":true},{"text":"\"It can't be that much, surely.\"","then":"Pooja's face falls, hearing it dismissed. She takes a breath. \"Let me show you, then.\""},{"text":"\"I just want to check that nothing's really wrong between us.\"","then":"Pooja softens. \"Nothing's wrong between us. It's the load I'm carrying.\""},{"text":"\"No reason, just curious today.\"","then":"It sounds casual, and she gives a short answer. \"Honestly? It's a lot.\""}],"why":"Asking to really get it, specifically, invites the honest, full answer instead of a quick one."},{"prompt":"Pooja says: \"This week alone, three renewals are due, and I'm the one tracking them.\"","options":[{"text":"\"Which three? Tell me what each one needs.\"","then":"She lists them, and admits holding it all in her head is exhausting.","best":true},{"text":"\"Just send me the amounts. I'll pay whatever you tell me.\"","then":"She hesitates. \"Paying's easy. It's the remembering.\""},{"text":"\"Maybe you should start writing everything down somewhere.\"","then":"She sighs. \"Then I'm remembering it on paper instead.\""},{"text":"\"Are any of them really that urgent?\"","then":"Pooja stiffens. \"Everything's urgent when it's only on me.\""}],"why":"Asking what each one needs, not just paying it, shows you the remembering behind it."},{"prompt":"Pooja finishes and says: \"That's basically an average week.\"","options":[{"text":"\"I'm taking all the renewals off you from now on.\"","then":"She looks lighter already, hearing it named as done, not just felt.","best":true},{"text":"\"That sounds really tiring, honestly.\"","then":"Sympathy lands well, but her week ahead looks exactly the same."},{"text":"\"I don't know how you'd ever remember all that.\"","then":"She gives a tired smile. \"That's why it has always been me.\""},{"text":"\"Maybe we should get a shared calendar app.\"","then":"Pooja nods slowly. \"Maybe. But who would set it up and keep it filled in?\""}],"why":"Naming exactly what you're taking over is what turns a hard conversation into real relief."}],"relearn":"Ask your partner to narrate a day's invisible remembering so you can finally see the load."},
  {"id":"ep-1132","cat":"see-the-load","type":"role-play","persona":"Pooja","source":"reframe lucky","hook":"Sunita aunty's visiting, and she has strong opinions about modern husbands.","setup":"You decide to gently reframe it.","steps":[{"prompt":"Sunita aunty says: \"You're so lucky. He helps so much around the house.\"","options":[{"text":"\"We're learning to share it, not him helping me.\"","then":"Sunita aunty tilts her head, thinking that one over.","best":true},{"text":"\"Yes, I'm very lucky he helps.\"","then":"Sunita aunty nods, and 'lucky' quietly stays the story."},{"text":"\"Honestly, it's still mostly me, but it's fine.\"","then":"It undoes the reframe before it's even started."},{"text":"\"I wouldn't say lucky, more like tired.\"","then":"It sounds like a complaint, and Sunita aunty just laughs it off."}],"why":"Naming it as shared, not helped, corrects the frame without it turning into a complaint."},{"prompt":"Sunita aunty asks: \"In my day, men never touched the planning. Does he?\"","options":[{"text":"\"Some, and more each month. It's ours to plan.\"","then":"Sunita aunty raises her eyebrows. \"Ours? Times have changed.\"","best":true},{"text":"\"He does quite a fair bit these days, honestly.\"","then":"Sunita aunty smiles. \"Helping, you mean. Lucky girl.\""},{"text":"\"No, but he does the important stuff, mostly.\"","then":"Aunty nods. \"Men handle the big things. As it should be.\""},{"text":"\"Planning's more a woman's strength anyway.\"","then":"Sunita aunty beams. \"Exactly what I've always said.\""}],"why":"Naming the planning as shared, honestly, keeps it from being seen as yours by default."},{"prompt":"Karthik asks: \"So, how did it go with your aunty?\"","options":[{"text":"\"She thinks you 'help'. Can we both say it's shared?\"","then":"He nods. \"Yes. It's our home. I'll say so too.\"","best":true},{"text":"\"Fine. I didn't really get into it with her.\"","then":"He shrugs. \"Okay.\" You're left alone keeping the story straight."},{"text":"\"Relatives will think whatever they want anyway.\"","then":"He laughs. \"True.\" And 'he helps' stays the family story."},{"text":"\"Honestly, I'm getting tired of correcting everyone.\"","then":"He hesitates. \"Okay.\" It stays your fight, not a shared one."}],"why":"Asking him to tell the same story means the reframe isn't work you carry alone."}],"relearn":"Reframe 'he helps' as 'we share the load', so the planning isn't quietly left as yours."},
  {"id":"ep-1133","cat":"see-the-load","type":"role-play","persona":"Karthik","source":"i hadn't seen it","hook":"You want to admit, honestly, that you hadn't seen how much Pooja carries.","setup":"You bring it up yourself, without being asked.","steps":[{"prompt":"Pooja looks up, a little wary, and asks: \"What's this about?\"","options":[{"text":"\"I've only been seeing the chores, not the planning.\"","then":"Her face softens, surprised you noticed on your own.","best":true},{"text":"\"I guess I could do a bit more sometimes.\"","then":"It's vague enough that nothing actually shifts afterward."},{"text":"\"I've realised you do a lot. That's all.\"","then":"It names the load without offering to actually take any of it."},{"text":"\"I think we should probably talk about the chores more often.\"","then":"It stays focused on chores, missing the planning entirely."}],"why":"Naming the planning specifically, not just admitting it, is what makes the moment mean something."},{"prompt":"Pooja asks: \"And what do you want to do about it?\"","options":[{"text":"\"I'll own the insurance renewals and the festival planning fully.\"","then":"She writes it down, relieved to see it stated so clearly.","best":true},{"text":"\"I'll check in with you a lot more about what needs doing.\"","then":"Checking in still leaves the deciding and remembering with her."},{"text":"\"Whatever feels fair to you, honestly.\"","then":"Pooja sighs. \"I shouldn't have to design my own relief.\""},{"text":"\"Let's just see how it goes and adjust things later.\"","then":"Without anything named now, later rarely actually arrives."}],"why":"Naming specific owned areas, not vague support, is what turns the offer into a real split."},{"prompt":"A month later, Pooja asks: \"Do you think anything's really changed?\"","options":[{"text":"\"Let's check what's moved off you, and what hasn't.\"","then":"She nods. \"Yes. Let's actually go through it.\"","best":true},{"text":"\"Definitely. I've been handling loads more, haven't I?\"","then":"Pooja hesitates. \"Some. Can we look before we decide?\""},{"text":"\"Why don't you keep an eye on it and tell me?\"","then":"She sighs. \"Then I'm tracking it all again.\""},{"text":"\"I think so. You seem less stressed.\"","then":"Pooja shrugs. \"Seeming isn't the same as it being fair.\""}],"why":"Going through what's moved and what hasn't, together, keeps the offer honest."}],"relearn":"Admit you'd only seen the chores, and offer to carry half the invisible planning too."},
  {"id":"ep-1134","cat":"see-the-load","type":"role-play","persona":"Pooja","source":"say it without guilt","hook":"You're worn out from holding everything, and you want to say so without apologising for it.","setup":"It's late, and the kitchen's finally quiet.","steps":[{"prompt":"Karthik notices and asks: \"You've barely touched your food. Everything okay?\"","options":[{"text":"\"I'm carrying all the remembering here. It's a lot.\"","then":"He puts his fork down. \"Tell me. What are you carrying?\"","best":true},{"text":"\"Sorry, I'm just tired. Ignore me.\"","then":"He lets it go, and the actual load stays unnamed."},{"text":"\"You wouldn't understand. Don't worry about it.\"","then":"Karthik looks hurt. \"Try me. I'd like to understand.\""},{"text":"\"I'm fine, just a long day.\"","then":"It sounds ordinary, and nothing about the real weight comes through."}],"why":"Naming the remembering plainly, without an apology, is what makes it heard as real, not fine."},{"prompt":"Later, Karthik says: \"I want to understand what's wearing you out. Where do we start?\"","options":[{"text":"\"Let's write down everything I'm keeping track of, together.\"","then":"You both sit with the list until it's genuinely complete.","best":true},{"text":"\"Just trust me that it's a lot. I don't want to make a list.\"","then":"He wants to believe you, but without specifics it stays abstract to him."},{"text":"\"You'd see it if you looked. I shouldn't have to explain.\"","then":"Karthik looks lost. \"I'm trying. Help me see it.\""},{"text":"\"Forget it. It sounds like too much effort right now.\"","then":"He hesitates. \"Okay. But I'm asking again tomorrow.\""}],"why":"Writing it down together, specifically, turns 'a lot' into something he can actually see and share."},{"prompt":"A few days later, Karthik asks: \"What can I actually take off you?\"","options":[{"text":"\"Pick two things you'll own fully, from tonight.\"","then":"He picks two, seriously, and you feel the difference within a week.","best":true},{"text":"\"Just help out whenever you see me busy.\"","then":"He agrees, and the noticing stays with you."},{"text":"\"I'll make you a list of what to do each day.\"","then":"He nods, and managing him becomes one more job for you."},{"text":"\"It's okay. I'm managing fine.\"","then":"He looks unsure, and the load stays exactly where it was."}],"why":"Asking him to own specific things, fully, is what turns being seen into real sharing."}],"relearn":"Name that you carry all the remembering, without apology, and ask to make it visible and shared."},
  {"id":"ep-1135","cat":"see-the-load","type":"role-play","persona":"Pooja","source":"point at the managing","hook":"You've been quietly hoping Karthik would ask the right question instead of the usual one.","setup":"You decide how to answer him.","steps":[{"prompt":"Karthik says: \"I want to help more around here. Just tell me what to do.\"","options":[{"text":"\"More than chores, I'd love you to own the remembering.\"","then":"He pauses. \"Own it, meaning not asking you first?\"","best":true},{"text":"\"Sure, you can do the dishes more often.\"","then":"Dishes get done, but the remembering stays exactly where it was."},{"text":"\"Just do whatever you think needs doing.\"","then":"He does a couple of visible things and calls it help."},{"text":"\"Honestly, I'm just too tired to explain all this right now.\"","then":"He nods. \"Okay. Tomorrow, then. I mean it.\""}],"why":"Pointing at owning the remembering, not another chore, aims the offer at what actually exhausts you."},{"prompt":"The next day, Karthik asks: \"What would help most, honestly? I'm listening.\"","options":[{"text":"\"Pick one whole area, like bills, and run it without asking me.\"","then":"He nods slowly. \"Okay. Bills, starting this month, fully mine.\"","best":true},{"text":"\"Just try to think about these things more often.\"","then":"He tries, but without a specific area, the thinking stays scattered."},{"text":"\"Watch me for a week and copy what I do exactly.\"","then":"He watches closely, but you're still the one doing all of it."},{"text":"\"I'll make you a list of reminders to follow.\"","then":"You've just created another thing for yourself to track and maintain."}],"why":"Naming one whole area to run alone, without asking, is what turns the offer into real ownership."},{"prompt":"A month later, Karthik asks: \"I think I'm doing better at home. Am I?\"","options":[{"text":"\"Let's check. What are you tracking without my reminders?\"","then":"He counts on his fingers, and you both see what's still on you.","best":true},{"text":"\"Yes. Thank you for helping so much.\"","then":"He smiles, and 'helping' quietly settles back in."},{"text":"\"It took long enough, didn't it?\"","then":"His face falls. \"I was trying.\""},{"text":"\"Mostly. I still double-check everything you do, though.\"","then":"He frowns. \"Then you're still tracking it all.\""}],"why":"Checking what he runs without reminders shows whether he owns it or still helps."}],"relearn":"When a partner offers to help more, point them at owning the remembering, not just doing extra chores."},
  {"id":"ep-1136","cat":"see-the-load","type":"sort","hook":"Sort: counts as managing the load, or just doing as told?","items":[{"id":"a","text":"Deciding the whole week's school drop-off plan"},{"id":"b","text":"Driving the route someone else mapped"},{"id":"c","text":"Working out the monthly home budget"},{"id":"d","text":"Paying for the items on a given list"},{"id":"e","text":"Noticing a child's shoes are too small"},{"id":"f","text":"Buying the exact shoes you were sent for"}],"bins":[{"id":"managing","label":"Managing the load","valence":"uhoh"},{"id":"doing","label":"Doing as told","valence":"neutral"}],"key":{"a":"managing","b":"doing","c":"managing","d":"doing","e":"managing","f":"doing"},"relearn":"Deciding plans, budgets and noticing needs is managing the load; driving, paying and buying to order is doing as told.","persona":"any","source":"managing vs doing"},
  {"id":"ep-1137","cat":"see-the-load","type":"sort","hook":"Sort: this load shows up at night, or only during chores?","items":[{"id":"a","text":"Lying awake running tomorrow's to-do list"},{"id":"b","text":"Sweeping the courtyard in the morning"},{"id":"c","text":"Worrying if you booked the train tickets"},{"id":"d","text":"Washing the lunch dishes at noon"},{"id":"e","text":"Remembering at midnight that fees are due"},{"id":"f","text":"Hanging clothes out after the wash"}],"bins":[{"id":"night","label":"Follows you to bed","valence":"uhoh"},{"id":"task","label":"Stays with the chore","valence":"neutral"}],"key":{"a":"night","b":"task","c":"night","d":"task","e":"night","f":"task"},"relearn":"Lists, worries and sudden 'fees are due' follow you to bed; sweeping, dishes and washing stay with the chore.","persona":"Pooja","source":"load that follows to bed"},
  {"id":"ep-1138","cat":"see-the-load","type":"sort","hook":"Sort: this would still need doing even if a maid came tomorrow?","items":[{"id":"a","text":"Deciding what the family eats all week"},{"id":"b","text":"Scrubbing the bathroom tiles"},{"id":"c","text":"Tracking everyone's medical appointments"},{"id":"d","text":"Mopping all the floors"},{"id":"e","text":"Knowing which bills fall due when"},{"id":"f","text":"Washing and drying the clothes"}],"bins":[{"id":"stays","label":"Stays on a person","valence":"uhoh"},{"id":"hireable","label":"A maid could do it","valence":"neutral"}],"key":{"a":"stays","b":"hireable","c":"stays","d":"hireable","e":"stays","f":"hireable"},"relearn":"Deciding meals, tracking appointments and bill dates stay on a person; scrubbing, mopping and washing are hireable.","persona":"any","source":"what a maid can't take"},
  {"id":"ep-1170","cat":"share-it-fairly","type":"branch","persona":"any","source":"agree early","hook":"You and Rohit have been married three weeks, and the dishes already seem to be yours.","steps":[{"prompt":"You want to agree a home split with Rohit before defaults set in. What do you do?","options":[{"text":"Sit down now and agree who owns what, openly","then":"Rohit's glad you raised it before either of you fell into a default.","best":true},{"text":"See how it shakes out naturally over the first few months","then":"A pattern starts setting itself, and nobody chooses it on purpose."},{"text":"Copy roughly how your parents split things","then":"Their era's split doesn't really match what either of you actually needs."},{"text":"Put it off until after the wedding rush settles down","then":"The rush drags on, and the conversation keeps getting pushed back."}],"why":"Agreeing openly now, before defaults harden, is what actually starts you off fair."},{"prompt":"A few weeks later, Rohit suggests writing down who does what, and asks how detailed to go. What do you do?","options":[{"text":"Include the planning and remembering, not just chores","then":"The list ends up covering far more than either of you first expected.","best":true},{"text":"Keep it broad, just the big categories","then":"The broad categories leave a lot of small, exhausting things unclaimed."},{"text":"Just the visible daily tasks for now","then":"The invisible planning quietly has no owner from day one."},{"text":"Whatever feels easiest to write down","then":"Ease decides the list, not what actually needs covering."}],"why":"Including the invisible planning from the start is what makes an early agreement genuinely complete."},{"prompt":"Two months in, Rohit notices one area's already started slipping. What do you do?","options":[{"text":"Name it honestly, and fix it before it becomes routine","then":"You catch it early enough that it never quite becomes a habit.","best":true},{"text":"Tell Rohit he's probably misreading it","then":"He isn't. That area really has started slipping."},{"text":"Let it go since you only just agreed things","then":"Letting the first slip go makes the second one easier."},{"text":"Blame the schedule instead of adjusting the split","then":"The schedule's not really the problem. The ownership is."}],"why":"Fixing a slip early, honestly, is what keeps a new agreement from quietly eroding already."},{"prompt":"Six months in, a friend asks how you and Rohit keep the housework fair. What do you do?","options":[{"text":"Say fairness needs who-owns-what said out loud, not assumed","then":"Your friend admits they've never actually said it out loud, and wants to try.","best":true},{"text":"Say it just naturally stays even between you","then":"It credits luck for something that only works when it's agreed."},{"text":"Say you haven't really thought about it lately","then":"Saying it out loud, you realise you're not sure it's fair anymore."},{"text":"Say Rohit's just easy to live with","then":"It makes fairness sound like his nature, not something you agree on."}],"why":"Naming an open, spoken agreement, not luck, is what explains how a split stays fair."}],"debrief":"Fairness comes from an explicit, agreed split, not from waiting to see where work drifts.","relearn":"Agree who owns what openly and early, rather than letting the split fall by default."},
  {"id":"ep-1171","cat":"share-it-fairly","type":"branch","persona":"Pooja","source":"list the invisible too","hook":"You and Karthik finally sat down together to write out the home's full list.","steps":[{"prompt":"Making the list with Karthik, you notice he's written only chores, nothing about planning. What do you do?","options":[{"text":"Point out the gap and add the planning items together","then":"Karthik looks surprised at how much longer the list gets.","best":true},{"text":"Quietly add the planning items yourself later","then":"The planning ends up documented, but still entirely your job to track."},{"text":"Split only the visible tasks on the list","then":"The finished list looks fair, and quietly misses most of what exhausts you."},{"text":"Assume Karthik will notice on his own eventually","then":"He doesn't, and the gap on the list stays exactly as it was."}],"why":"Naming the missing planning items is what makes the list actually cover the real load."},{"prompt":"Later, Karthik asks what exactly still makes you so tired. What do you do?","options":[{"text":"Walk him through one planning job, start to finish","then":"By the end, he understands why it's its own item, not part of a chore.","best":true},{"text":"Say it's basically the remembering and planning","then":"It's accurate but thin, and doesn't quite land as something to own."},{"text":"Say he should be able to guess","then":"Karthik looks stuck, unsure what he's actually being asked to take on."},{"text":"Move on and explain it another time","then":"Planning stays a vague word, and nobody's really claimed any of it."}],"why":"Explaining one job fully turns an abstract load into something he can actually take ownership of."},{"prompt":"That weekend, you sit down with Karthik to assign the planning jobs. What do you do?","options":[{"text":"Split the planning items between you, clearly named","then":"Each planning item now has one clear owner, same as the chores.","best":true},{"text":"Keep the planning items for yourself since you know them best","then":"Karthik never learns them, and every one stays in your head."},{"text":"Leave the planning items unassigned for now","then":"Unassigned quietly means they default back to you."},{"text":"Assign them all to Karthik to make up for lost time","then":"He's overwhelmed, and half of them quietly slide back to you within a week."}],"why":"Splitting the planning items clearly, not lumping or dumping them, makes the split genuinely fair."},{"prompt":"A relative later says planning 'comes naturally' to women like you. What do you do?","options":[{"text":"Say planning is learned work, and Karthik can own it too","then":"Your relative looks a little surprised, then nods slowly.","best":true},{"text":"Say you're just more organised than him","then":"It quietly agrees that the planning belongs with you."},{"text":"Laugh and say someone has to do it","then":"The myth stands, and so does the load."},{"text":"Say Karthik's hopeless at remembering things","then":"It gets a laugh, and lets him off owning any of it."}],"why":"Calling planning learned work, not a woman's nature, keeps it open to be shared."}],"debrief":"A fair split must include the planning and remembering, not just the visible tasks.","relearn":"Put the planning and remembering into the split, not just the visible chores."},
  {"id":"ep-1172","cat":"share-it-fairly","type":"branch","persona":"any","source":"flex with capacity","hook":"Farah's just started a rotation in the hospital's emergency department.","steps":[{"prompt":"Her shifts now run long and change every week. You want a split that fits. What do you do?","options":[{"text":"Agree a split that flexes with each person's real hours","then":"Farah looks relieved, like someone's finally planning around her actual week.","best":true},{"text":"Insist on an identical 50/50 regardless of shifts","then":"On her worst weeks, the identical split leaves her more exhausted than before."},{"text":"Take on everything during her shifts without discussing it","then":"It's generous, but it's also unspoken, and it never really gets revisited."},{"text":"Ask her to swap fewer shifts instead","then":"It asks her career to flex first, instead of the home split."}],"why":"A split that flexes with real hours fits your actual lives, not just a number on paper."},{"prompt":"Farah's new roster comes out, and next week looks nothing like this one. What do you do?","options":[{"text":"Look at her roster together each week and adjust the split","then":"You both glance at the roster each Sunday and shift tasks from there.","best":true},{"text":"Watch how tired she looks and guess from that","then":"Guessing from her exhaustion means you're always reacting late."},{"text":"Tell her to say when it's too much","then":"It puts the asking back on the tired person."},{"text":"Keep the same fixed split and hope it mostly works","then":"It works on her easy weeks and fails badly on her hard ones."}],"why":"Checking her actual roster each week is what makes a flexible split reliable, not vague."},{"prompt":"A brutal week hits, and Farah's barely home before midnight most nights. What do you do?","options":[{"text":"Take on nearly everything at home this week","then":"Farah comes home to a functioning house and finally exhales.","best":true},{"text":"Do a bit more than usual, but keep your normal routine too","then":"The gap between a bit more and what's actually needed leaves things half-covered."},{"text":"Ask your mother to come and cook for the week","then":"It helps, but the rest of the house still falls between the cracks."},{"text":"Say you're tired too and split it as usual","then":"It ignores how uneven the actual week has been for each of you."}],"why":"Fully stepping up in her brutal week is what fair, not identical, looks like."},{"prompt":"The next month, your own project deadline runs long. What do you do?","options":[{"text":"Tell Farah honestly, and ask to shift the split your way for now","then":"She agrees, and moves two of your tasks onto her lighter weeks.","best":true},{"text":"Try to manage it all yourself so you don't have to ask","then":"You end up exhausted, and the give only ever goes one way."},{"text":"Assume she'll offer without you needing to ask","then":"She's mid-shift and doesn't notice you're struggling until much later."},{"text":"Skip your share for a few weeks and explain later","then":"Farah comes off a night shift to find the kitchen piled up."}],"why":"Flexing works both ways, so asking openly when it's your turn keeps the split fair for both."}],"debrief":"Fair doesn't always mean identical; it flexes with each person's real capacity and is revisited.","relearn":"Let the split flex with each person's real capacity; fair isn't always identical."},
  {"id":"ep-1173","cat":"share-it-fairly","type":"branch","persona":"Pooja","source":"name the drift","hook":"Lately you've been doing the math on your evenings, and it doesn't add up the way it used to.","steps":[{"prompt":"You realise the split with Karthik has drifted, and you're carrying more than agreed. What do you do?","options":[{"text":"Name the drift calmly and ask to rebalance it","then":"Karthik looks a little surprised, then nods. \"You're right. Let's fix it.\"","best":true},{"text":"Carry the extra silently and hope he notices","then":"Weeks pass, and he genuinely hasn't noticed anything's changed."},{"text":"Drop hints and wait for him to catch on","then":"The hints go past him, and the extra load just keeps piling up."},{"text":"Bring it up mid-argument about something else","then":"It gets lost in the heat of an unrelated fight."}],"why":"Naming the drift calmly, directly, is what actually gets it noticed and fixed."},{"prompt":"A few days later, Karthik notices you're up late finishing the evening jobs and asks what's changed. What do you do?","options":[{"text":"Name the two specific things that shifted onto you","then":"He nods, able to picture something specific to fix.","best":true},{"text":"Say it's honestly hard to pin down exactly","then":"Without specifics, the talk stalls, though he still wants to fix it."},{"text":"Say it's basically everything at this point","then":"Karthik feels overwhelmed and unsure where to even start."},{"text":"Say he should already know if he thinks about it","then":"He genuinely doesn't, and the moment turns defensive."}],"why":"Naming the two specific things that drifted is what turns a feeling into a fixable problem."},{"prompt":"A week later, Karthik says he's taken back a couple of evening jobs. What do you do?","options":[{"text":"Go through the evenings with him, and check what's actually moved","then":"One job has moved for good, and one is quietly still yours.","best":true},{"text":"Assume it's sorted now that he's said so","then":"One job has quietly slid back already, unnoticed."},{"text":"Say nothing, since checking might seem like nagging","then":"The habit of not checking is exactly what let it drift the first time."},{"text":"Take the jobs back yourself to avoid an awkward talk","then":"The rebalance undoes itself before it even settles."}],"why":"Checking together what's actually moved is what keeps a rebalance from drifting straight back."},{"prompt":"A month later, Karthik asks how you both stop this drifting again. What do you do?","options":[{"text":"Suggest a short monthly check on how you're sharing things","then":"Karthik agrees, glad to catch it early next time instead of after months.","best":true},{"text":"Say you'll both just try harder from now on","then":"Trying harder has no date or shape, so the drift creeps back."},{"text":"Say you'll just watch for it yourself from now on","then":"Watching alone puts the noticing, once again, only on you."},{"text":"Say he should flag it if he ever sees it drifting","then":"It hands the noticing to him alone, and it's easy to miss."}],"why":"A regular check, not just trying harder, is what stops the same drift from repeating."}],"debrief":"Raise rebalancing without blame: a drifted split is fixed by naming it, not by suffering it.","relearn":"Name a drifted split without blame and ask to rebalance it, rather than carrying the extra silently."},
  {"id":"ep-1174","cat":"share-it-fairly","type":"branch","persona":"any","source":"build it together","hook":"You and Yusuf have never actually sat down and mapped out who does what.","steps":[{"prompt":"You want to start the split conversation with Yusuf so it feels shared. What do you do?","options":[{"text":"Say, let's map it all out together and split it fairly","then":"Yusuf sits down right away, glad to be building it with you, not handed one.","best":true},{"text":"Hand him a finished rota you made alone","then":"He looks at it politely, but it never quite feels like his plan too."},{"text":"Wait for him to bring it up first","then":"Weeks pass, and the conversation just never quite starts."},{"text":"Post about fair splits and hope he sees it","then":"Yusuf doesn't see it, and nothing about your actual home changes."}],"why":"Opening the conversation together, as an invitation, is what makes the split feel built, not imposed."},{"prompt":"One Sunday, Yusuf says the house feels chaotic and asks where you'd even begin sorting it. What do you do?","options":[{"text":"Walk through one ordinary day together, hour by hour","then":"One ordinary day, talked through together, surfaces more than either of you expected.","best":true},{"text":"Offer to write the list yourself, since you know the house better","then":"The list comes out complete, but it's yours again, not built together."},{"text":"Say you'll start once things calm down at work","then":"Work doesn't calm down, and the chaos stays unsorted."},{"text":"Say it's easier to just wing it as you talk","then":"Without a starting point, the conversation wanders without landing anywhere."}],"why":"Starting from one shared, ordinary day is what makes building the list together actually work."},{"prompt":"Later, you and Yusuf disagree on who should own the grocery planning. What do you do?","options":[{"text":"Talk through both your real schedules honestly","then":"It becomes clear pretty quickly who actually has the bandwidth for it.","best":true},{"text":"Let Yusuf decide since he probably has stronger opinions on it","then":"One person deciding alone is the exact default you were trying to move away from."},{"text":"Drop it and move to an easier item","then":"The unresolved item quietly stays unassigned."},{"text":"Insist on your original idea to keep things moving","then":"Yusuf goes along with it, but it doesn't feel like it was actually built together."}],"why":"Talking through it honestly together, even the disagreement, keeps the split genuinely shared."},{"prompt":"That weekend, Yusuf asks whether you should write down what you've agreed so far. What do you do?","options":[{"text":"Write it up together and both sign off on it","then":"You both keep a copy, proud it's something you actually built side by side.","best":true},{"text":"Let Yusuf write the final version since he's neater","then":"It's a small thing, but the final document ends up feeling like his, not both of yours."},{"text":"Type it up yourself so it looks organised","then":"The organising quietly becomes your job too, on top of everything else."},{"text":"Skip writing it down since you both remember it","then":"A verbal agreement is easy to forget and easier to quietly drift from."}],"why":"Writing it up and signing off together is what keeps the split feeling built, not handed over."}],"debrief":"An agreed split is built together, not imposed; either partner can open the conversation.","relearn":"Open the split talk together and build it as a team, rather than imposing a finished rota."},
  {"id":"ep-1175","cat":"share-it-fairly","type":"branch","persona":"any","source":"split in joint family","hook":"Zoya's been part of the family for six months now, long enough for the old patterns to settle in.","steps":[{"prompt":"In your joint family, cooking's assumed to fall to Zoya. What do you do?","options":[{"text":"Agree your own fair kitchen split as a couple first","then":"Zoya looks relieved you're deciding this together, not leaving her to fight it alone.","best":true},{"text":"Quietly help Zoya in the kitchen without saying anything","then":"You help, but the family's assumption that it's hers stays exactly the same."},{"text":"Let it default to what relatives expect for now","then":"The kitchen settles back into being her job, unquestioned."},{"text":"Tell Zoya to raise it with the family herself","then":"It leaves her alone to challenge an expectation that's really about you both."}],"why":"Agreeing your own split first, as a couple, is what lets you actually hold it against the default."},{"prompt":"One evening, your mother tells Zoya a good bahu has dinner ready before the men get home. What do you do?","options":[{"text":"Say calmly that cooking in your home is shared by you both","then":"Your mother looks surprised, but doesn't push further.","best":true},{"text":"Say you'll help Zoya out tonight","then":"It confirms the kitchen is Zoya's, with you as the exception."},{"text":"Say nothing now, and talk to Zoya about it later","then":"Your mother's words go unanswered, and Zoya hears them alone."},{"text":"Ask your mother not to make a big deal of it","then":"It manages her comfort instead of answering her."}],"why":"Naming it plainly as shared is what actually shifts the family's assumption, not just your actions."},{"prompt":"Zoya mentions the relatives keep making comments to her about the cooking. What do you do?","options":[{"text":"Back her up directly the next time it comes up","then":"The next comment gets a clear answer from both of you, and it stops repeating.","best":true},{"text":"Tell her to just brush the comments off","then":"She's left absorbing the comments alone, every single time."},{"text":"Say the relatives will get used to it eventually","then":"Eventually means Zoya keeps fielding it alone in the meantime."},{"text":"Ask her what she said to make them comment","then":"It sounds curious, but it hints the comments are her doing."}],"why":"Backing her up directly, together, is what actually stops the comments from landing only on her."},{"prompt":"Months later, a new daughter-in-law joins and looks nervous about the kitchen. What do you do?","options":[{"text":"Tell her plainly that the kitchen isn't only the women's job","then":"She looks visibly relieved, and Zoya gives you a small smile.","best":true},{"text":"Let her figure out the household norms on her own","then":"She quietly assumes the old expectation, since nobody's told her otherwise."},{"text":"Say every household's different, best to just see","then":"It's technically true, and it leaves her guessing at exactly the moment she needs clarity."},{"text":"Mention it lightly, so it's at least been said once","then":"Said once in passing, it's easy for her to miss or doubt."}],"why":"Saying plainly that cooking isn't the women's job alone protects the next person from the default."}],"debrief":"Couples can hold a fair arrangement together even amid joint-family expectations.","relearn":"Agree your own fair split as a couple, rather than defaulting to what relatives assume."},
  {"id":"ep-1176","cat":"share-it-fairly","type":"branch","persona":"any","source":"count unpaid hours","hook":"By every measure you'd used before, your household looked perfectly balanced.","steps":[{"prompt":"You both work full-time, but Lavanya also runs the whole house. What do you do?","options":[{"text":"Actually count her unpaid home hours alongside the paid ones","then":"Adding it up, the total hours tell a very different story than you'd assumed.","best":true},{"text":"Judge fairness on paid work alone, since that's easiest to compare","then":"It looks fair on paper, and completely ignores the second, unpaid job she's also doing."},{"text":"Assume it's fine since neither of you has complained","then":"Neither of you says anything, and the hours behind that quiet stay uncounted."},{"text":"Say the house basically runs itself these days","then":"You say it, and Lavanya gives a small smile, then goes to start dinner."}],"why":"Counting the unpaid home hours too is what shows whether the split is actually fair, not just paid work."},{"prompt":"One Sunday, Lavanya adds up her week out loud: office hours, then hours of cooking, bills and errands. What do you do?","options":[{"text":"Take on a real share of the home hours to close the gap","then":"The next week's actual total is finally close to even.","best":true},{"text":"Feel bad about it, and tell her you'll do better","then":"The guilt is genuine, but the actual hours haven't shifted yet."},{"text":"Suggest she cut back on some home tasks instead","then":"It asks her standards to flex rather than your hours."},{"text":"Say your job is more demanding, so it balances out","then":"It quietly decides your paid hours count for more than her unpaid ones."}],"why":"Actually taking on home hours, not just feeling bad, is what closes the gap her week just showed."},{"prompt":"A month later, you wonder whether the hours at home have really shifted. What do you do?","options":[{"text":"Add up both your hours again, honestly, and adjust","then":"The count shows where it's slipped, and you agree which job moves over.","best":true},{"text":"Assume things have evened out by now","then":"They haven't, quietly, and nobody's checked to notice."},{"text":"Skip counting, since it might start a fight","then":"The hours stay uncounted, and so does the gap."},{"text":"Ask Lavanya to tell you if it feels off","then":"It puts the ongoing tracking, again, entirely on her."}],"why":"Recounting the real hours honestly is what keeps a fair split from quietly slipping."},{"prompt":"A colleague says his wife 'doesn't really work' since she's not employed. What do you do?","options":[{"text":"Say running a home is real work, hours and all","then":"Your colleague goes quiet, clearly not having thought of it that way.","best":true},{"text":"Say nothing. It's not really your place to comment","then":"The comment stands unchallenged, and your colleague carries on with his lunch."},{"text":"Laugh along to keep things easy","then":"It quietly agrees that unpaid work isn't really work."},{"text":"Say at least she has more free time than him","then":"He nods, glad of the company, and the talk moves on."}],"why":"Calling home hours real work, out loud, makes the invisible hours count in other rooms too."}],"debrief":"The invisible and unpaid hours should count in the split; they're often ignored.","relearn":"Count unpaid home hours, not just paid work, when deciding whether the split is fair."},
  {"id":"ep-1177","cat":"share-it-fairly","type":"branch","persona":"any","source":"share the dull jobs","hook":"You and Simran pinned your chore list on the fridge a month ago.","steps":[{"prompt":"Looking at it now, you realise you've kept every chore you enjoy. What do you do?","options":[{"text":"Point it out, and offer to re-split the dull jobs together","then":"Simran looks surprised you noticed before she had to say anything.","best":true},{"text":"Quietly pick up a dull job or two, without saying anything","then":"You do a bit more, but the list still says the dull jobs are hers."},{"text":"Keep the nice jobs. She's never actually complained","then":"Her silence was never the same as her being fine with it."},{"text":"Suggest you both just do whichever tasks you feel like","then":"In practice, you both keep reaching for the same enjoyable ones."}],"why":"Naming it and re-splitting the dull jobs together is what makes a split genuinely fair."},{"prompt":"That evening, Simran suggests going through every job, fun and dull, and trading some. What do you do?","options":[{"text":"Trade so you each end up with a fair mix of fun and dull","then":"You hand over the weekend cooking, and take the ironing and the drains.","best":true},{"text":"Swap completely, so she gets the fun jobs and you the dull","then":"It sounds generous, but it just flips the imbalance, and it won't last."},{"text":"Take only the dull jobs you mind least","then":"The worst ones, like scrubbing the drains, stay firmly with Simran."},{"text":"Say you'll swap later, once you've got used to the list","then":"Later keeps moving, and the list stays exactly as it is."}],"why":"A fair mix of fun and dull for both, not a flipped pile, is what makes the split even."},{"prompt":"A month later, Simran asks whether the list still feels fair to you both. What do you do?","options":[{"text":"Go through it together and swap anything that's tipped","then":"One dull job had quietly slid back to her, and you swap it over.","best":true},{"text":"Say it's fine, since you've done more dull jobs lately","then":"Simran nods, and the job that slid back to her goes unmentioned."},{"text":"Say fair is fair, but you'd rather keep your favourites","then":"Simran shrugs, and the fun jobs stay yours by default."},{"text":"Say she'd know better, since she does the dull ones","then":"It hands the checking of fairness back to her, again."}],"why":"Checking the list together keeps the dull jobs from quietly drifting back to her."},{"prompt":"A friend says the fairest split is each person doing what they're good at. What do you do?","options":[{"text":"Say 'good at it' often means 'enjoys it', and dull jobs still need sharing","then":"Your friend laughs, then admits that's exactly how their own split works.","best":true},{"text":"Agree, since it's the most efficient way","then":"It sounds sensible, and quietly keeps the fun jobs with whoever picked first."},{"text":"Say it works as long as nobody complains","then":"Silence becomes the test, and the dull jobs stay with the quiet one."},{"text":"Say it depends on the couple","then":"It sounds fair-minded, and says nothing about who gets the dull jobs."}],"why":"Noticing that 'good at it' can hide 'likes it' keeps the dull jobs from settling on one person."}],"debrief":"A fair split shares the unpleasant tasks, not just the pleasant visible ones.","relearn":"Share the dull and unpleasant jobs fairly too, not just keep the ones you enjoy."},
  {"id":"ep-1178","cat":"share-it-fairly","type":"branch","persona":"any","source":"write it down","hook":"You and Vikram sorted out the housework over chai last month, and it seemed simple then.","steps":[{"prompt":"Now you've both forgotten half of who owns what. What do you do?","options":[{"text":"Write the owned domains down somewhere you both see","then":"Vikram pins it up by the fridge. \"Now neither of us has an excuse.\"","best":true},{"text":"Try to remember it better next time","then":"By next week, the same details are already fuzzy again."},{"text":"Keep it all in your heads and re-argue each week","then":"The same argument about who owns what happens, again, over dinner."},{"text":"Ask Vikram to write it down for both of you","then":"It quietly makes the writing itself, and the remembering, his job alone."}],"why":"Writing the split down where you both can see it is what stops it from being re-litigated weekly."},{"prompt":"A week later, the gas cylinder runs low. It never made it onto any list, and you each recall a different plan. What do you do?","options":[{"text":"Settle it together, and put it on a list you both see","then":"You settle it in a minute, and it's on paper for next time.","best":true},{"text":"Assume your own version is what was agreed","then":"You each remember it slightly differently, and the confusion continues."},{"text":"Decide it's not worth arguing over one job","then":"The cylinder runs out a day later, and the job is still nobody's."},{"text":"Let Vikram decide, since he usually books it","then":"It settles tonight, and the job quietly becomes his by default."}],"why":"Settling it together, in writing, stops the same job being re-argued next week."},{"prompt":"A month later, Vikram's shifts change, and some of who-does-what no longer fits. What do you do?","options":[{"text":"Sit down together and rewrite the split to match","then":"The new version fits your actual weeks, not just the old ones.","best":true},{"text":"Keep the old split, since it was agreed already","then":"What was agreed stops matching what's actually happening."},{"text":"Just adjust things in your heads as you go","then":"Now there are two versions floating around, and neither's reliable."},{"text":"Let Vikram rework it, since it's his shifts that changed","then":"It becomes his plan to fix, not a split you both own."}],"why":"Rewriting the split together keeps it matching your actual lives, not just the first month."},{"prompt":"A visiting friend asks how you two stop arguing over chores. What do you do?","options":[{"text":"Say it works best written down, and kept up to date","then":"Your friend decides to try it, and asks what goes on the list.","best":true},{"text":"Say you just have a good memory for these things","then":"It credits memory for something memory keeps failing at."},{"text":"Say you just argue it out whenever it comes up","then":"Your friend laughs. That's exactly the fight they keep having."},{"text":"Say a written list feels too rigid for a couple","then":"Your friend agrees that lists feel stiff, and keeps arguing it out from memory."}],"why":"Naming a written, updated split is what explains how a couple stops re-arguing it."}],"debrief":"A clear, written split of owned domains lasts; a vague verbal one quietly fails.","relearn":"Write the owned domains down where you both can see, rather than keeping a vague verbal split."},
  {"id":"ep-1179","cat":"share-it-fairly","type":"branch","persona":"any","source":"share guest load","hook":"Anika's been quietly stressed about something for days, and you finally ask why.","steps":[{"prompt":"Anika's parents arrive next week, and the extra work isn't part of your usual split. What do you do?","options":[{"text":"Agree how you'll share the guest load before they arrive","then":"Anika's relieved it's planned in advance, not left to sort out mid-visit.","best":true},{"text":"Assume you'll pitch in naturally once they're here","then":"Nothing gets planned, and Anika quietly starts a list of her own."},{"text":"Assume she'll handle her own parents' visit","then":"Anika quietly adds the whole visit to her already full week."},{"text":"Suggest eating out more so there's less to manage","then":"It avoids a bit of cooking, but the rest of the extra care work is still unassigned."}],"why":"Agreeing the guest load in advance means nobody silently absorbs it once the visit's underway."},{"prompt":"Two days before they arrive, Anika mentions the airport pickup and extra meals still need sorting. What do you do?","options":[{"text":"Split them clearly now, one each","then":"Anika relaxes, seeing the plan cover the details, not just the idea.","best":true},{"text":"Say you'll both just help with whatever comes up","then":"Whatever comes up tends to land on whoever's already used to noticing it."},{"text":"Leave it loose since her parents won't mind either way","then":"Her parents' comfort was never really the question. The workload was."},{"text":"Take the fun outings and leave the logistics to her","then":"The pickup and meal planning quietly stay hers, same as always."}],"why":"Clearly splitting specific tasks, not just the general idea of helping, is what makes the plan real."},{"prompt":"Midway through the visit, her father needs daily rides to physiotherapy. What do you do?","options":[{"text":"Sort out with Anika who drives which day, tonight","then":"You split the days, and neither of you is stuck doing all of them.","best":true},{"text":"Say you'll drive whenever work allows, and see how it goes","then":"Most days work doesn't allow, and Anika quietly fills the gaps."},{"text":"Assume Anika will take him, since it's her father","then":"Anika ends up rushing between rides, meals and her own work."},{"text":"Ask her father to take autos instead","then":"It shifts the awkwardness onto a guest instead of adjusting the plan."}],"why":"Sorting it out together, day by day, keeps the extra care from landing on one person."},{"prompt":"After her parents leave, Anika asks how you think the visit went. What do you do?","options":[{"text":"Talk through what worked and what landed on her, for next time","then":"Anika names two things, and you agree to plan those earlier next visit.","best":true},{"text":"Say you're relieved it's over","then":"It treats the visit as something survived, not something to plan better."},{"text":"Say her parents are easy guests, so it went fine","then":"It skips over whatever quietly landed on Anika."},{"text":"Say you're glad you helped out so much","then":"'Helped out' undersells what owning half the guest load means."}],"why":"Looking back at who carried what, together, makes the next visit fairer from the start."}],"debrief":"An explicit, agreed split covers extra seasons of work too, not only the everyday tasks.","relearn":"Agree how to share guest and extra-care load in advance, rather than assuming it falls to her."},
  {"id":"ep-1180","cat":"share-it-fairly","type":"branch","persona":"any","source":"pay isn't a buy-out","hook":"You've started earning a lot more than Diya at work.","steps":[{"prompt":"You've quietly assumed your bigger salary buys you out of home work. What do you do?","options":[{"text":"Take an equal home share regardless of who earns more","then":"Diya looks surprised you brought it up yourself, before she had to.","best":true},{"text":"Offer to pay for more services instead of doing more yourself","then":"Hired help covers some tasks, but the everyday load and its tracking stay with her."},{"text":"Treat your bigger salary as paying you out of chores","then":"Diya's doing a full job and most of the home, while your money buys your exit."},{"text":"Say your longer hours already justify doing less","then":"Longer hours at work don't make her hours at home count for less."}],"why":"Taking an equal share regardless of pay is what keeps income from deciding the load."},{"prompt":"A few days later, Diya asks what you think a fair split would look like. What do you do?","options":[{"text":"Take over two whole home areas, starting this week","then":"She names two she'd love off her plate, and you take them on fully.","best":true},{"text":"Say you'll pitch in more generally","then":"It sounds like a shift, but nothing specific has actually moved."},{"text":"Say you'll increase the household budget instead","then":"More money for services doesn't answer who's actually doing and tracking the rest."},{"text":"Ask her what she thinks is fair","then":"It quietly hands the redesign of your own share back to her again."}],"why":"Naming specific areas to take on is what turns the principle into an actual, felt change."},{"prompt":"A relative jokes that with your salary, Diya's 'set for life'. What do you do?","options":[{"text":"Say your salary doesn't buy you out of the home work","then":"Your relative looks a bit thrown, clearly expecting a different answer.","best":true},{"text":"Laugh along, since it's meant as a genuine compliment","then":"The joke quietly reinforces that your money is what really matters here."},{"text":"Agree. She's lucky not to have to worry","then":"It treats Diya's own work, paid and unpaid, as if it doesn't count."},{"text":"Say nothing and let the comment pass","then":"It leaves the idea that money buys out home work sitting unanswered."}],"why":"Saying pay doesn't buy anyone out of home work protects an equal share, even in a joke."},{"prompt":"A year later, your salary gap has grown even further. What do you do?","options":[{"text":"Check honestly with Diya whether the home split is fair","then":"You find two jobs that had quietly slid back to Diya, and take them.","best":true},{"text":"Assume it's fine since you haven't noticed anything","then":"Not noticing was never proof nothing had changed."},{"text":"Feel like your bigger income should count for even more now","then":"It's the same buy-out idea, only bigger now."},{"text":"Let Diya bring it up if something's changed","then":"It puts the noticing, once again, entirely on her."}],"why":"Checking in honestly, even as the pay gap grows, is what keeps income from ever buying an exit."}],"debrief":"Earning more doesn't exempt anyone; the split is fair regardless of who earns what.","relearn":"Take an equal home share regardless of pay, rather than treating a bigger salary as a buy-out."},
  {"id":"ep-1181","cat":"share-it-fairly","type":"branch","persona":"Karthik","source":"no chasing","hook":"Every Tuesday and Thursday, the same text from Pooja arrives like clockwork.","steps":[{"prompt":"You split chores by day months ago, but Pooja still chases you on your days. What do you do?","options":[{"text":"Own your days fully, so no chasing is needed","then":"Pooja looks cautiously hopeful. \"That would genuinely change things.\"","best":true},{"text":"Promise to try harder to remember","then":"The promise is sincere, and the same reminder text arrives again next Tuesday."},{"text":"Say she could remind you more gently","then":"It puts the burden of managing your memory back onto her."},{"text":"Say your days are just naturally harder to remember","then":"It excuses the pattern instead of actually fixing it."}],"why":"Owning your days without needing reminders is what removes the chasing from her plate."},{"prompt":"Pooja asks what would actually help you remember on your own. What do you do?","options":[{"text":"Set your own reminders, not ones from her","then":"You add them to your own calendar, so the reminding can leave her hands.","best":true},{"text":"Ask her to text you only when it's really urgent","then":"She still has to watch your days to know when it's urgent."},{"text":"Say you'll just try to keep it in mind","then":"Keeping it in mind hasn't worked so far, and it doesn't start working now."},{"text":"Ask her to set the same reminders she used to give you","then":"It's her doing the same job, just typed into your phone instead of said out loud."}],"why":"Setting your own reminders, not asking for hers, is what actually removes the chasing for good."},{"prompt":"Next Tuesday, Pooja starts typing her usual reminder text. What do you do?","options":[{"text":"Tell her you've got it, and do it before she has to check","then":"She puts the phone down, and the task's done before dinner.","best":true},{"text":"Wait for her text, then do the task straight away","then":"It gets done on time, and she's still the one who remembered."},{"text":"Tell her, a bit irritated, that she doesn't need to text","then":"She stops typing, but keeps checking later whether it's done."},{"text":"Ask her to text a little earlier, so you have more time","then":"The reminder job stays hers, just on a new schedule."}],"why":"Doing it before she has to remind you, and saying so, is what takes the watching off her."},{"prompt":"A month later, one busy week nearly gets away from you. What do you do?","options":[{"text":"Catch it yourself and adjust before Pooja has to say anything","then":"She never even notices the near-miss, because you caught it first.","best":true},{"text":"Let her flag it if she notices anything slipping","then":"It quietly reopens the door to her being the one who notices for you."},{"text":"Ask her to check in on you that week specifically","then":"It's a small ask, and it's still her doing the checking, not you."},{"text":"Skip the task that week since it's just one week","then":"One skipped week is usually how the old chasing pattern starts again."}],"why":"Catching your own near-miss, without her flagging it, is what makes owning your days actually stick."}],"debrief":"A real split removes the chasing; if she still has to remind you, the managing is still hers.","relearn":"Own your share of the split fully so no chasing is needed, rather than relying on her reminders."},
  {"id":"ep-1182","cat":"share-it-fairly","type":"branch","persona":"any","source":"split tracking too","hook":"Ritika mentioned, almost as a joke, that she could recite every bill's due date from memory.","steps":[{"prompt":"You've split who pays which bills, and it seems sorted. What do you do?","options":[{"text":"Agree each of you owns whole bills, tracking included","then":"Ritika looks relieved. \"That's the part that actually exhausts me.\"","best":true},{"text":"Offer to double-check the due dates with her","then":"Double-checking still means she's the one keeping the master list."},{"text":"Split paying but leave all the tracking to her","then":"You pay on time when reminded, and she's still the one doing the remembering."},{"text":"Suggest an app that sends both of you reminders","then":"The app helps, but someone still has to enter and maintain every bill in it."}],"why":"Owning whole bills, tracking included, is what actually shares the mental load, not just the paying."},{"prompt":"At the month's end, Ritika mentions the annual car insurance and house tax are due soon. What do you do?","options":[{"text":"Take the annual ones yourself, tracking and all","then":"Ritika's glad the ones she always worried about are now clearly yours.","best":true},{"text":"Split annual ones evenly by number too","then":"Some annual bills need far more tracking than others, and the split misses that."},{"text":"Leave the annual ones for whoever remembers first","then":"In practice, that's always been Ritika, and nothing's actually changed."},{"text":"Set a single shared reminder for all of them","then":"One shared reminder for many different dates is easy for both of you to miss."}],"why":"Deliberately taking the easy-to-forget bills yourself is what makes the split actually fair."},{"prompt":"A month later, you nearly miss paying the internet bill, one of yours. What do you do?","options":[{"text":"Catch it yourself and pay it before it's late","then":"Ritika never even finds out it was close, because you handled it.","best":true},{"text":"Ask Ritika when it's due","then":"It quietly hands the tracking straight back to her."},{"text":"Let it go a few days late this once","then":"A late fee shows up, a small but real cost of nobody tracking it."},{"text":"Blame the bank's app for not reminding you","then":"Ritika raises an eyebrow. The bank's app has no reminder set, and neither do you."}],"why":"Catching your own near-miss, without asking her, is what taking over the tracking looks like."},{"prompt":"Three months on, Ritika asks if she still needs to keep an eye on your bills. What do you do?","options":[{"text":"Say no, and set up your own way to track your bills","then":"She laughs, relieved. \"One less list in my head.\"","best":true},{"text":"Say a quick monthly summary from her would still help","then":"A summary is small, but it's still a sliver of tracking on her plate."},{"text":"Say yes, just in case, since she's better at it","then":"The master list, and the worry, stay firmly with her."},{"text":"Say you'll both keep an eye on them together","then":"Ritika nods. Two weeks on, each of you thinks the other has the electricity bill."}],"why":"Tracking your own bills yourself is what lets her actually stop watching them."},{"prompt":"A friend asks how you split bills, since theirs always causes fights. What do you do?","options":[{"text":"Say each person should own whole bills, due dates included","then":"Your friend takes the idea home, hoping it ends their recurring fight.","best":true},{"text":"Say you just split the amounts evenly","then":"It sounds fair, and misses who's doing the remembering."},{"text":"Say Ritika's just naturally better at bills","then":"It makes tracking sound like her talent, not shared work."},{"text":"Say an app with reminders sorts it all out","then":"It sounds modern, and skips who keeps the app up to date."}],"why":"Owning whole bills, due dates included, is the part that actually ends the fights."}],"debrief":"A fair split shares the tracking and remembering, not just the paying.","relearn":"Each own whole bills including the tracking, rather than splitting only the paying."},
  {"id":"ep-1183","cat":"share-it-fairly","type":"branch","persona":"any","source":"fair free time","hook":"Sana's been coming home and immediately starting a second round of work, every night.","steps":[{"prompt":"You want a split that respects both your jobs and the home, not just chores. What do you do?","options":[{"text":"Count paid hours, home hours and rest fairly for both","then":"Laid out together, the numbers show whose rest has actually been shrinking.","best":true},{"text":"Just make sure the visible chores are even","then":"The chores look balanced, and it says nothing about who's actually getting to rest."},{"text":"Take the evenings off, and do more on weekends","then":"Weekends fill up with plans, and Sana's weeknights stay full of work."},{"text":"Assume whoever's home first has more free time","then":"Sana still walks in and starts the second round of work, and nothing shifts."}],"why":"Counting all three, paid, unpaid and rest, is what shows whether the split is actually fair."},{"prompt":"Later that week, Sana says she can't remember her last free evening. What do you do?","options":[{"text":"Give up some of your own downtime so she gets hers","then":"Your evenings shrink a little, and hers finally start to grow back.","best":true},{"text":"Suggest she try to relax more efficiently","then":"It asks her to be better at resting rather than actually giving her more time to rest."},{"text":"Say your job is more mentally demanding, so it balances out","then":"It quietly decides your tiredness counts for more than hers."},{"text":"Offer to plan a nice weekend to make up for it","then":"One weekend doesn't touch a gap that repeats every single week."}],"why":"Giving up some of your own downtime, not advice, is what actually gives her rest back."},{"prompt":"A week later, you wonder whether Sana's evenings have really changed. What do you do?","options":[{"text":"Count both your free hours, honestly, and adjust","then":"The count shows exactly where she's still short, and you agree what to shift.","best":true},{"text":"Assume things have evened out by now","then":"They haven't, quite, and nobody checks to notice."},{"text":"Skip counting, since it could start an argument","then":"The gap stays uncounted, and so does her tiredness."},{"text":"Ask Sana to tell you if she's still short on rest","then":"It puts the ongoing tracking of her own exhaustion back on her."}],"why":"Counting honestly, not assuming things have changed, is what closes a stubborn rest gap."},{"prompt":"A friend says rest isn't really something a couple needs to split. What do you do?","options":[{"text":"Say free time is part of the split, just like chores","then":"Your friend looks thoughtful, clearly not having considered it that way.","best":true},{"text":"Say it mostly depends on whose job is harder","then":"It makes rest a prize for the harder job, not something both need."},{"text":"Agree. It does sound a bit much to track","then":"Your friend nods, and the talk moves on, though Sana's rest is still unsettled."},{"text":"Say counting hours means you don't trust each other","then":"Your friend nods, wary of keeping score, and drops the idea."}],"why":"Counting rest as part of the split is what keeps free time from quietly landing on one person."},{"prompt":"Months later, Sana's promotion means longer hours for her. What do you do?","options":[{"text":"Sit down and redo the split before her new hours start","then":"You move two evening jobs over before her new hours even begin.","best":true},{"text":"Say you'll see how it goes once she starts","then":"The first month, her free evenings quietly vanish again."},{"text":"Suggest hiring more help so nothing else needs to change","then":"Help covers some chores, but who plans and tracks them stays unclear."},{"text":"Say you're happy for her, and leave it there","then":"The congratulations are warm, and the split stays exactly as it was."}],"why":"Revisiting the split when life changes keeps rest fair before the gap reopens."}],"debrief":"Fairness counts all hours, paid and unpaid, so rest and free time land evenly too.","relearn":"Count paid and unpaid hours so both get fair rest, rather than taking your downtime from her load."},
  {"id":"ep-1184","cat":"share-it-fairly","type":"branch","persona":"any","source":"agree standards","hook":"Neither of you has said anything, but something odd's been happening with the laundry.","steps":[{"prompt":"You've noticed you and Omkar keep quietly redoing each other's chores. What do you do?","options":[{"text":"Suggest agreeing a shared 'good enough' standard for each job","then":"Omkar laughs, relieved. \"I thought I was the only one redoing things.\"","best":true},{"text":"Just accept that his way is probably right anyway","then":"It stops the redoing on your side, but nothing's actually been agreed between you."},{"text":"Silently redo whatever he does 'wrong'","then":"Omkar's already redoing your work too, and neither of you says a word about it."},{"text":"Point out all the different ways he keeps getting it wrong","then":"Omkar gets defensive, and it turns into a standards contest instead of an agreement."}],"why":"Agreeing a shared standard together is what stops the hidden, doubled-up re-work for good."},{"prompt":"That weekend, Omkar re-washes the dishes you just did, and you both notice. What do you do?","options":[{"text":"Talk through what 'clean enough' actually means for both of you","then":"You land on a standard neither of you would've guessed the other actually wanted.","best":true},{"text":"Just pick your own standard since you usually notice first","then":"It settles the dishes, but only by defaulting to one person's preference again."},{"text":"Say his standard is just fussy","then":"It turns a practical conversation into a judgment about him."},{"text":"Say standards don't really matter that much","then":"It skips the actual conversation that would stop the silent redoing."}],"why":"Actually talking through what each standard means is what makes an agreement real, not assumed."},{"prompt":"A week later, you catch yourself about to quietly redo Omkar's laundry fold. What do you do?","options":[{"text":"Stop, and check it against what you'd actually call good enough","then":"It does, technically, and you let it go, genuinely, for the first time.","best":true},{"text":"Redo it quickly since it only takes a minute","then":"A minute here and there is exactly the hidden re-work you were trying to stop."},{"text":"Decide his fold is fine, but privately lower your opinion of his effort","then":"You don't redo it, but the quiet judgment does its own damage."},{"text":"Tell him his fold still really isn't quite right yet","then":"Omkar sighs and refolds it, and now you're both redoing things again."}],"why":"Checking it against 'good enough', not habit, is what stops the hidden re-work."},{"prompt":"Your mother visits and quietly refolds the towels Omkar put away. What do you do?","options":[{"text":"Tell her gently that his way is good enough for your home","then":"Your mother pauses, then leaves the next pile as it is.","best":true},{"text":"Let her refold them, since it keeps the peace","then":"The towels look neater, and Omkar quietly stops doing that job."},{"text":"Refold the rest yourself before she finds them","then":"It's more hidden re-work, now done to please someone else."},{"text":"Tell Omkar to fold them her way from now on","then":"Omkar's face falls. The standard's been decided without him."}],"why":"Backing the standard you share at home, even with family, stops hidden re-work coming back."},{"prompt":"Months later, Omkar asks if the redoing thing still bothers you. What do you do?","options":[{"text":"Say honestly where it still happens, and agree to revisit","then":"He nods. \"Let's check it every few months, then.\"","best":true},{"text":"Say it's all fine now, no need to talk about it","then":"The one job still being redone stays unmentioned."},{"text":"Say you've just stopped caring how things are done","then":"It sounds relaxed, and hides the resentment of lowering your bar alone."},{"text":"Say he's the one who still redoes things, not you","then":"Omkar goes quiet, and it turns into a tally instead of a talk."}],"why":"Being honest about where it still happens, and revisiting, keeps a shared standard from slipping."}],"debrief":"Agree shared standards so neither partner silently redoes the other's work and adds hidden load.","relearn":"Agree a shared 'good enough' standard for each job, rather than silently redoing the other's work."},
  {"id":"ep-1185","cat":"share-it-fairly","type":"branch","persona":"any","source":"share prep work","hook":"A baby's on the way, and a long list of research and setup is piling up.","steps":[{"prompt":"Your partner says there's a lot to figure out before the due date. What do you do?","options":[{"text":"Say let's split the research and setup now","then":"She looks relieved, and you both pick items off the list together.","best":true},{"text":"Say you'll help however she needs","then":"She says thanks and starts making the list herself."},{"text":"Say there's time, no rush yet","then":"The list stays untouched as the weeks pass."},{"text":"Suggest hiring someone to sort it all","then":"You look into services together, but no one owns the actual coordinating."}],"why":"Dividing the list now, not waiting to be asked, stops one person becoming the manager."},{"prompt":"A relative asks who's handling everything for the baby. What do you say?","options":[{"text":"Say you're each taking pieces of it, and name what's yours","then":"The relative pauses, then asks what each of you is doing.","best":true},{"text":"Say she's naturally on top of these things","then":"The relative nods like that's expected, and the assumption holds."},{"text":"Change the subject","then":"The relative shrugs and assumes she's running it."},{"text":"Promise you'll help out a lot when things get busy","then":"The relative smiles, still sure it's her show either way."}],"why":"Naming what you own out loud resets the assumption before it hardens."},{"prompt":"The nursery, the bag and the paperwork all need doing before the due date. What do you do?","options":[{"text":"Claim two of them fully, start to finish","then":"She notices you've already started, and the load feels lighter for both.","best":true},{"text":"Ask her to make you a checklist first","then":"She spends an evening writing it out. You follow it, but she planned it."},{"text":"Wait for her to assign you tasks","then":"You do solid work, but she's still deciding all of it."},{"text":"Leave the paperwork to her. It's detailed work","then":"She adds it to her plate and doesn't mention it again."}],"why":"Owning tasks fully, not waiting for a checklist, shares the planning too."}],"debrief":"Split the planning and admin of a big change too, so one person doesn't become the default manager.","relearn":"Divide the setup, research and admin of a big change now, rather than leaving it to her."},
  {"id":"ep-1186","cat":"share-it-fairly","type":"branch","persona":"any","source":"managing the help","hook":"You've hired a cook, but your partner is the only one instructing and tracking them.","steps":[{"prompt":"The cook asks about the week's menu and timing. What do you do?","options":[{"text":"Step in and plan the menu with her this time","then":"You and she work it out together, and the cook has one clear answer.","best":true},{"text":"Tell your partner to just handle it. She's better at it","then":"She sighs and takes the menu call alone, again."},{"text":"Stay out of it since it's not your job","then":"She fields the question herself, like every week."},{"text":"Suggest switching cooks instead","then":"A new cook arrives, but she's still the only one managing them."}],"why":"Stepping into the planning, not just paying for help, shares the managing."},{"prompt":"The cook calls in sick and someone needs to sort the day's meals. What do you do?","options":[{"text":"Call the backup and sort it yourself this time","then":"You handle it. Your partner notices she wasn't the one who had to scramble.","best":true},{"text":"Text your partner to ask what she wants done","then":"She answers from her desk, still the one deciding."},{"text":"Assume she'll handle it like always","then":"She quietly sorts it, and the day goes on unnoticed."},{"text":"Order food today so nothing has to be sorted","then":"It solves today, but next time the sick-day call is hers again by default."}],"why":"Taking the scramble yourself shows the managing can genuinely move."},{"prompt":"The cook has started texting only her every time something comes up. What do you do?","options":[{"text":"Agree you'll alternate weeks instructing the help","then":"You set a simple rota, and the cook gets used to hearing from both of you.","best":true},{"text":"Ask her to keep you posted on what's needed","then":"She keeps briefing you, still the one holding the thread."},{"text":"Leave it to work itself out naturally","then":"Within a month, she's back to managing it alone."},{"text":"Tell her to just ask if she ever needs a hand","then":"The offer sits there. She rarely asks, so nothing changes."}],"why":"A standing rota, not an open offer, is what actually keeps it shared."}],"debrief":"Even with paid help, the managing is real work. Share it. Don't leave it on one person.","relearn":"Share managing any hired help, rather than leaving the instructing and tracking to her."},
  {"id":"ep-1187","cat":"share-it-fairly","type":"sort","hook":"Sort: a fair way to divide, or an unfair default?","items":[{"id":"a","text":"Agreeing owned domains together"},{"id":"b","text":"Whatever she 'naturally' ends up with"},{"id":"c","text":"Counting paid and unpaid hours"},{"id":"d","text":"Leaving the lower earner all the chores"},{"id":"e","text":"Splitting the planning too"},{"id":"f","text":"Whoever's home 'should just do it'"}],"bins":[{"id":"fair","label":"Fair","valence":"pos"},{"id":"default","label":"Unfair default","valence":"neg"}],"key":{"a":"fair","b":"default","c":"fair","d":"default","e":"fair","f":"default"},"relearn":"Agreed domains, counted hours and split planning are fair; 'naturally hers' or the lower-earner doing it all is default.","persona":"any","source":"fair vs default"},
  {"id":"ep-1188","cat":"share-it-fairly","type":"sort","hook":"Sort: belongs in a fair split, or gets left out?","items":[{"id":"a","text":"Paid working hours"},{"id":"b","text":"The mental load carried"},{"id":"c","text":"Unpaid home hours"},{"id":"d","text":"Only the chores you can see"},{"id":"e","text":"Emotional labour for in-laws"},{"id":"f","text":"Just whatever gets noticed"}],"bins":[{"id":"in","label":"Counts in the split","valence":"pos"},{"id":"out","label":"Often left out","valence":"neg"}],"key":{"a":"in","b":"in","c":"in","d":"out","e":"in","f":"out"},"relearn":"Paid hours, unpaid hours, mental load and emotional labour all count; counting only visible chores leaves most out.","persona":"any","source":"what counts in"},
  {"id":"ep-1189","cat":"share-it-fairly","type":"sort","hook":"Sort: visible task, or the invisible managing behind it?","items":[{"id":"a","text":"Cooking the dinner"},{"id":"b","text":"Planning the week's meals"},{"id":"c","text":"Paying the electricity bill"},{"id":"d","text":"Remembering when it's due"},{"id":"e","text":"Dropping the child to class"},{"id":"f","text":"Tracking the whole class timetable"}],"bins":[{"id":"task","label":"Visible task","valence":"neutral"},{"id":"managing","label":"Invisible managing","valence":"uhoh"}],"key":{"a":"task","b":"managing","c":"task","d":"managing","e":"task","f":"managing"},"relearn":"Cooking, paying and dropping off are visible tasks; planning, remembering and tracking are the invisible managing.","persona":"any","source":"task vs managing"},
  {"id":"ep-1190","cat":"share-it-fairly","type":"sort","hook":"Sort: opens a fair split well, or shuts it down?","items":[{"id":"a","text":"'Let's map it all out together'"},{"id":"b","text":"'You're just better at this'"},{"id":"c","text":"'Let's count everyone's hours'"},{"id":"d","text":"'It's always worked like this'"},{"id":"e","text":"'I think it's drifted, can we rebalance?'"},{"id":"f","text":"'Stop complaining, it's fine'"}],"bins":[{"id":"opens","label":"Opens it","valence":"tell"},{"id":"shuts","label":"Shuts it down","valence":"neg"}],"key":{"a":"opens","b":"shuts","c":"opens","d":"shuts","e":"opens","f":"shuts"},"relearn":"Mapping it out, counting hours and naming drift open a fair split; 'you're better at it' and 'it's fine' shut it down.","persona":"any","source":"opens or shuts"},
  {"id":"ep-1191","cat":"share-it-fairly","type":"sort","hook":"Sort: keeps the split fair, or loads one person?","items":[{"id":"a","text":"Both own whole domains"},{"id":"b","text":"One person stays the manager"},{"id":"c","text":"Sharing the remembering"},{"id":"d","text":"One does all the chasing"},{"id":"e","text":"Revisiting the split together"},{"id":"f","text":"Reminders flow one way only"}],"bins":[{"id":"fair","label":"Keeps it fair","valence":"pos"},{"id":"loads","label":"Loads one person","valence":"neg"}],"key":{"a":"fair","b":"loads","c":"fair","d":"loads","e":"fair","f":"loads"},"relearn":"Owning domains, sharing the remembering and revisiting keep it fair; one manager, one chaser and one-way reminders load her.","persona":"any","source":"fair or loaded"},
  {"id":"ep-1192","cat":"share-it-fairly","type":"sort","hook":"Sort: a fair way to handle a busy season, or unfair?","items":[{"id":"a","text":"Whoever's freer takes more this month"},{"id":"b","text":"Her load stays full whatever happens"},{"id":"c","text":"Trading off when work peaks"},{"id":"d","text":"His crunch always wins automatically"},{"id":"e","text":"Revisiting once the season passes"},{"id":"f","text":"Never adjusting once set"}],"bins":[{"id":"fair","label":"Fair flex","valence":"pos"},{"id":"unfair","label":"Unfair","valence":"neg"}],"key":{"a":"fair","b":"unfair","c":"fair","d":"unfair","e":"fair","f":"unfair"},"relearn":"Letting the freer person take more, trading off and revisiting is fair flex; her load never easing or his crunch always winning isn't.","persona":"any","source":"busy season"},
  {"id":"ep-1193","cat":"share-it-fairly","type":"sort","hook":"Sort: counts the invisible work, or ignores it?","items":[{"id":"a","text":"Budgeting the household together"},{"id":"b","text":"Only logging who scrubbed what"},{"id":"c","text":"Tracking the kids' health needs"},{"id":"d","text":"Calling chores the whole load"},{"id":"e","text":"Holding the family calendar"},{"id":"f","text":"Ignoring all the planning"}],"bins":[{"id":"counts","label":"Counts it","valence":"pos"},{"id":"ignores","label":"Ignores it","valence":"neg"}],"key":{"a":"counts","b":"ignores","c":"counts","d":"ignores","e":"counts","f":"ignores"},"relearn":"Budgeting, tracking health needs and holding the calendar count the invisible work; logging only scrubbing ignores it.","persona":"any","source":"counts invisible"},
  {"id":"ep-1194","cat":"share-it-fairly","type":"sort","hook":"Sort: shared decision, or one person deciding alone?","items":[{"id":"a","text":"Agreeing the split face to face"},{"id":"b","text":"One handing the other a rota"},{"id":"c","text":"Both naming what they can take"},{"id":"d","text":"One assigning the other's jobs"},{"id":"e","text":"Deciding the standards together"},{"id":"f","text":"One setting the rules for both"}],"bins":[{"id":"shared","label":"Decided together","valence":"pos"},{"id":"alone","label":"Decided by one","valence":"neg"}],"key":{"a":"shared","b":"alone","c":"shared","d":"alone","e":"shared","f":"alone"},"relearn":"Agreeing face to face, both naming capacity and deciding standards together is shared; handing over rotas or rules is one deciding.","persona":"any","source":"together not imposed"},
  {"id":"ep-1195","cat":"share-it-fairly","type":"sort","hook":"Sort: a fair split principle, or a myth about fairness?","items":[{"id":"a","text":"Fair can flex with capacity"},{"id":"b","text":"Fair means exactly identical always"},{"id":"c","text":"The invisible work must count"},{"id":"d","text":"Only visible chores matter"},{"id":"e","text":"Either partner can open the talk"},{"id":"f","text":"Only she can raise the split"}],"bins":[{"id":"principle","label":"Fair principle","valence":"pos"},{"id":"myth","label":"Fairness myth","valence":"neg"}],"key":{"a":"principle","b":"myth","c":"principle","d":"myth","e":"principle","f":"myth"},"relearn":"Fair flexes, counts the invisible work and either partner can open it; 'always identical', 'only visible' and 'only she raises it' are myths.","persona":"any","source":"principle or myth"},
  {"id":"ep-1196","cat":"share-it-fairly","type":"sort","hook":"Sort: a fair split move, or a quiet unfairness?","items":[{"id":"a","text":"Splitting the school admin"},{"id":"b","text":"Her chasing every form alone"},{"id":"c","text":"Both owning a care domain"},{"id":"d","text":"One owning all the 'soft' stuff"},{"id":"e","text":"Trading domains when one tires"},{"id":"f","text":"Never rotating the dull jobs"}],"bins":[{"id":"fair","label":"Fair move","valence":"pos"},{"id":"unfair","label":"Quiet unfairness","valence":"neg"}],"key":{"a":"fair","b":"unfair","c":"fair","d":"unfair","e":"fair","f":"unfair"},"relearn":"Splitting admin, both owning care and trading when tired is fair; her chasing alone, one owning all 'soft' work and never rotating isn't.","persona":"any","source":"move or unfairness"},
  {"id":"ep-1197","cat":"share-it-fairly","type":"role-play","persona":"any","source":"open as a team","hook":"You've been carrying most of the mental load at home, and it's starting to wear on you.","setup":"Tonight, over dinner, you decide to bring it up.","steps":[{"prompt":"Farhan asks: \"You've been quiet. Something on your mind?\"","options":[{"text":"\"Let's map out everything our home needs and split it fairly.\"","then":"Farhan sits up. \"Okay, let's actually do that this weekend.\"","best":true},{"text":"\"Nothing really, just a long week at work and everything else.\"","then":"He nods sympathetically and the moment passes."},{"text":"\"You always dump everything on me, honestly.\"","then":"Farhan looks hurt. \"That's not true. I do things too.\""},{"text":"\"It's fine. I'll figure it out like always.\"","then":"He relaxes, relieved nothing more is coming."}],"why":"Framing it as a shared map, not a complaint, invites him in instead of putting him on the defensive."},{"prompt":"That weekend, you both realise groceries never got sorted, again. Farhan says: \"Let's actually figure out what I'm missing here.\"","options":[{"text":"\"The planning, reminding and worrying, not just the tasks.\"","then":"\"Huh. I never thought about the reminding part,\" he says.","best":true},{"text":"\"I'll just ask you whenever I need a hand with something.\"","then":"\"Sure,\" he says, still waiting to be asked."},{"text":"\"If you paid attention, you'd already know.\"","then":"\"That's not fair,\" he says, sounding stung."},{"text":"\"It's hard to explain. Let's not get into it.\"","then":"He shrugs, and the topic quietly closes again."}],"why":"Naming the mental load itself, not just tasks, is what actually shifts his picture."},{"prompt":"The next day, Farhan brings it up again: \"So, how do we actually split this fairly?\"","options":[{"text":"\"Let's write it all down together and split it as a team.\"","then":"\"Let's do it tonight,\" he says, pulling out a notebook.","best":true},{"text":"\"I'll keep the list, and just tell you what to do.\"","then":"\"Okay,\" he says, and the list stays yours to keep."},{"text":"\"Just do half of whatever I've been doing.\"","then":"He frowns. \"Half of what, exactly?\""},{"text":"\"I'm not sure. Let's figure it out eventually.\"","then":"The plan stays vague, and nothing changes yet."}],"why":"Writing it down together turns the intention into an actual shared plan."}],"relearn":"Open the split as a shared mapping of everything, including the invisible work, not as an accusation."},
  {"id":"ep-1198","cat":"share-it-fairly","type":"role-play","persona":"Pooja","source":"reopen the split","hook":"The cooking and cleaning split you and Karthik agreed has quietly slid back to you.","setup":"Tonight you decide to bring it up.","steps":[{"prompt":"Karthik asks: \"You've been quiet all evening. What's wrong?\"","options":[{"text":"\"I think our split has drifted. Can we rebalance it?\"","then":"He sets down his fork. \"Drifted how? Tell me what changed.\"","best":true},{"text":"\"Nothing. I'm just tired from cooking again tonight.\"","then":"\"Okay,\" he says, and doesn't ask further."},{"text":"\"You've basically stopped doing your half lately.\"","then":"Karthik frowns. \"I do plenty. That's not fair.\""},{"text":"\"Forget it. I'll just keep doing it all myself.\"","then":"He relaxes, relieved the topic has passed."}],"why":"Naming the drift plainly, without blame, opens the talk without a fight."},{"prompt":"The next morning, dishes are piled up again. Karthik asks: \"What's actually on your plate that I'm missing?\"","options":[{"text":"\"Cooking most nights, plus remembering what we're low on.\"","then":"\"I didn't realise the remembering part was yours too,\" he says.","best":true},{"text":"\"Just help more in the kitchen whenever you happen to be free.\"","then":"\"Sure,\" he says, still waiting to be asked."},{"text":"\"You'd know if you actually paid attention.\"","then":"\"That's harsh,\" he says, sounding a little stung."},{"text":"\"It's a long list. Let's not get into it now.\"","then":"He nods, and the conversation quietly stalls."}],"why":"Naming the remembering, not just the cooking, is what he actually needs to hear."},{"prompt":"A few days later, the same pattern repeats. Karthik asks: \"Okay, so how do we make sure this actually changes?\"","options":[{"text":"\"Let's redo the split now, and check in every month.\"","then":"\"Deal,\" he says, and writes a reminder on his phone.","best":true},{"text":"\"Just try hard to remember your half of it from now on.\"","then":"He nods, but nothing about the routine changes."},{"text":"\"I'll remind you whenever it slips again.\"","then":"\"Sure,\" he says, leaving you the one keeping watch."},{"text":"\"It's fine as long as you actually mean it.\"","then":"He agrees, but nothing gets written down anywhere."}],"why":"A redo plus a standing check-in catches drift, instead of relying on memory alone."}],"relearn":"Name a drifted split without blame and ask to rebalance it, rather than silently absorbing it."},
  {"id":"ep-1199","cat":"share-it-fairly","type":"role-play","persona":"Karthik","source":"domains not lists","hook":"Naveen keeps saying 'just tell me what to do' instead of noticing things himself.","setup":"Tonight you decide to change how the split works.","steps":[{"prompt":"Naveen asks: \"So what do you want me to do this week?\"","options":[{"text":"\"Instead of assigning tasks, let's each own whole areas.\"","then":"Naveen pauses. \"Own an area? Like what, exactly?\"","best":true},{"text":"\"Okay, I'll make you a fresh list first thing every single morning.\"","then":"\"Sure,\" he says, and waits for tomorrow's list."},{"text":"\"Figure it out yourself for once.\"","then":"He looks lost. \"I don't even know where to start.\""},{"text":"\"Just do the dishes and take out the trash.\"","then":"He does exactly that, and nothing else all week."}],"why":"Owning whole areas ends the daily assigning; a list just keeps you the manager."},{"prompt":"A week later, Naveen asks: \"What if I just took over one whole part of the house?\"","options":[{"text":"\"You take the kitchen and groceries, start to finish.\"","then":"\"Got it,\" he says, and starts a grocery note of his own.","best":true},{"text":"\"Whatever's easiest for you. You can just choose it.\"","then":"He picks something small and light, and stalls there."},{"text":"\"Same as before, just do what I tell you.\"","then":"He shrugs. \"So nothing's actually changed then.\""},{"text":"\"Pick something small so you don't mess it up.\"","then":"Naveen looks stung. \"I can handle more than that.\""}],"why":"Naming a specific whole domain, not 'whatever's easy', makes ownership real."},{"prompt":"A month later, Naveen says: \"I keep forgetting things on my side. What should I do?\"","options":[{"text":"\"Own the remembering too. Build your own system for it.\"","then":"\"Fair,\" he says, and sets a weekly reminder himself.","best":true},{"text":"\"It's fine. I'll just keep track of it for both of us.\"","then":"You quietly pick the tracking back up, unnoticed."},{"text":"\"See, this is why I should just handle it.\"","then":"Naveen looks deflated, and steps back entirely."},{"text":"\"Just check with me whenever you're not sure about it.\"","then":"He does, and you are back to being the one he checks with."}],"why":"Building his own system for remembering is what makes ownership hold."}],"relearn":"Shift the split from 'I assign, you do' to each owning whole domains, so no one stays the manager."},
  {"id":"ep-1200","cat":"share-it-fairly","type":"role-play","persona":"any","source":"count the hours","hook":"You and Kabir both work full days, but only his hours at the office seem to count.","setup":"Tonight you sit down to actually agree the split.","steps":[{"prompt":"Kabir says: \"I think I do more. My job runs longer hours.\"","options":[{"text":"\"Let's count home hours too, not just office ones.\"","then":"Kabir blinks. \"Home hours? I hadn't actually counted those.\"","best":true},{"text":"\"Fair. I guess your job is heavier than mine.\"","then":"He nods, satisfied, and the split stays as it is."},{"text":"\"I guess I'm home more, so the house is basically mine.\"","then":"Kabir looks relieved the house stays mostly yours."},{"text":"\"Let's not turn this into a competition.\"","then":"He shrugs. \"Fine, but someone still has to decide.\""}],"why":"Naming unpaid home hours brings the real workload onto the table."},{"prompt":"A few days later, you're both exhausted after a long weekend. Kabir says: \"Maybe we should actually count what a week at home looks like.\"","options":[{"text":"\"We track a week honestly, then split from what we see.\"","then":"\"Okay,\" Kabir says, and starts a note on his phone that night.","best":true},{"text":"\"Just guess roughly. It doesn't need to be exact.\"","then":"The rough guess mostly favours whoever spoke first."},{"text":"\"Count it, but only the chores. Planning is hard to measure.\"","then":"Kabir agrees, and the planning hours never make it onto the note."},{"text":"\"Let's not bother. It'll take too long to track.\"","then":"He agrees, and the whole idea quietly drops."}],"why":"A real week's tally, not a guess, is what makes the split honest."},{"prompt":"A week later, Kabir asks: \"So how do we actually decide who does what at home?\"","options":[{"text":"\"List every task with its hours, planning too. Then split it fairly.\"","then":"You both write it out. Kabir is surprised how long the planning part is.","best":true},{"text":"\"Let's keep it loose and fix things as they come up.\"","then":"Nothing is written down, and old habits return within a week."},{"text":"\"Let's keep things as they were. It works well enough.\"","then":"Kabir shrugs. \"Then why are we even talking about it?\""},{"text":"\"Whoever has more free time can pick up the rest.\"","then":"It sounds fair, but 'free time' is never actually agreed."}],"why":"Listing every task with its hours, planning included, makes the split honest."}],"relearn":"Ask to count unpaid home hours alongside paid hours before splitting, not just the office ones."},
  {"id":"ep-1201","cat":"share-it-fairly","type":"role-play","persona":"Karthik","source":"claim a domain","hook":"Bills and bank work have quietly stayed on Pooja's plate for years.","setup":"Tonight, you decide to change how bills get handled.","steps":[{"prompt":"Pooja says: \"I forgot to pay a bill again this month.\"","options":[{"text":"\"I'll own bills and banking start to finish from now on.\"","then":"She looks up, surprised. \"You mean all of it? Really?\"","best":true},{"text":"\"Remind me and I'll help out with the bills sometimes.\"","then":"\"Sure,\" she says, and keeps the reminders coming."},{"text":"\"You should set up auto pay so you don't forget.\"","then":"She sighs. \"That's still me managing it, just automated.\""},{"text":"\"It's just one bill. Don't stress about it.\"","then":"She nods, but the worry about the next one stays."}],"why":"Owning it start to finish, not offering to help, actually takes it off her plate."},{"prompt":"A week later, Pooja says: \"There's a bank email neither of us has answered.\"","options":[{"text":"\"I've got it. I'll reply and handle whatever it needs.\"","then":"You reply that evening. Pooja doesn't even see the email.","best":true},{"text":"\"Forward it to me and I'll take a look tonight.\"","then":"She forwards it, then checks back the next day to make sure."},{"text":"\"Let's both look at it together this weekend.\"","then":"The weekend passes, and the email sits unanswered."},{"text":"\"You're better with the bank stuff. You handle it.\"","then":"Pooja sighs and replies, like she always has."}],"why":"Handling it without being asked, and without her checking back, is what owning means."},{"prompt":"Pooja says: \"There's a late fee. A payment slipped through the cracks.\"","options":[{"text":"\"I'll take this now and set a better system.\"","then":"You call the bank, pay it, and set reminders on your own phone.","best":true},{"text":"\"Sorry, can you sort it since you know the accounts?\"","then":"She sorts it, and the bills stay with her."},{"text":"\"These things happen. Let's not make a big deal of it.\"","then":"The fee gets paid, but no one fixes what caused it."},{"text":"\"You usually catch these. What happened this time?\"","then":"Pooja bristles. \"Since when is this only my job to catch?\""}],"why":"Fixing it and building a system so she needn't chase it is what owning looks like."}],"relearn":"Claim a domain end to end so your partner stops thinking about it, rather than offering to help sometimes."},
  {"id":"ep-1202","cat":"share-it-fairly","type":"role-play","persona":"any","source":"hold the split","hook":"At a family function, the old assumptions about who cooks come up again.","setup":"You and Meera exchange a look, and you decide to speak first.","steps":[{"prompt":"An aunt says: \"In our house, the bahu always ran the kitchen.\"","options":[{"text":"\"We've agreed to share the kitchen. It works well for us.\"","then":"The aunt raises an eyebrow, but doesn't argue further.","best":true},{"text":"\"Meera's actually a wonderful cook and she doesn't mind it at all.\"","then":"The aunt nods, satisfied, and the assumption holds."},{"text":"\"Times have changed, aunty. Please don't start.\"","then":"The aunt looks offended, and the tension rises at the table."},{"text":"\"You're right. She'll handle all the cooking.\"","then":"Meera's smile stiffens, but she says nothing."}],"why":"Naming the actual, agreed split holds the line without dismissing her outright."},{"prompt":"A bit later, an uncle says: \"Our boys never had to learn cooking. That is how it has always been.\"","options":[{"text":"\"A home where both of us cook looks fair to us, and it works.\"","then":"The uncle chuckles, unconvinced, but drops it.","best":true},{"text":"\"I just help out when she's busy. That's all.\"","then":"The uncle nods, relieved it's still mostly hers."},{"text":"\"That's an old way of thinking. Let's just eat, please.\"","then":"The table goes quiet, and the moment feels tense."},{"text":"\"Maybe so. It's just easier this way for now.\"","then":"Meera glances over, unsure what 'for now' means."}],"why":"Owning it as normal, not as a favour, holds the split without backing down."},{"prompt":"That night, Meera brings it up: \"So, how did that feel to you, back there?\"","options":[{"text":"\"Uncomfortable. But it's our split, and I'll stand by it.\"","then":"She smiles and leans into you. \"I needed to hear that.\"","best":true},{"text":"\"It's fine, but let's not make a habit of arguing.\"","then":"\"Arguing?\" she asks, surprised. \"I only asked how you felt.\""},{"text":"\"I didn't want to cause a scene, honestly.\"","then":"\"So next time you'll stay quiet?\" she asks, a little hurt."},{"text":"\"They mean well. Don't take it personally.\"","then":"She looks away. \"It's not about meaning well.\""}],"why":"Owning the discomfort and backing the split going forward reassures her it will hold."},{"prompt":"The same aunt brings it up again at the next function: \"So, has anything changed in your kitchen?\"","options":[{"text":"\"We share it, and it's working well for us.\"","then":"The aunt shrugs this time and moves on to other topics.","best":true},{"text":"\"Let's just get through today without making a fuss about it.\"","then":"The question hangs in the air, and Meera ends up answering it alone."},{"text":"\"Can we please not do this every single time?\"","then":"The comment lands anyway, and the room feels awkward."},{"text":"\"She's gotten better at it, actually.\"","then":"The aunt nods, and cooking stays framed as Meera's job."}],"why":"Holding the same steady line each time is what makes the split hold over years."}],"relearn":"State the fair split you've agreed as a couple, rather than accepting that cooking is 'naturally' hers."},
  {"id":"ep-1203","cat":"share-it-fairly","type":"role-play","persona":"any","source":"flex this month","hook":"Ananya's work has gone into a brutal crunch, while your own schedule has eased up.","setup":"Tonight you notice she's barely eaten dinner.","steps":[{"prompt":"Ananya says: \"Sorry, I just can't get to the dishes tonight.\"","options":[{"text":"\"I've got more room this month. Let me take extra.\"","then":"She exhales. \"Really? That would help so much.\"","best":true},{"text":"\"It's okay. I'll do them just this once.\"","then":"She thanks you, unsure if it's a one-time thing or not."},{"text":"\"A deal's a deal. Your half is still your half.\"","then":"Ananya nods, tired, and gets up to do them anyway."},{"text":"\"Leave them. We'll deal with it tomorrow.\"","then":"The dishes pile up, and neither of you feels good about it."}],"why":"Naming the offer as a real flex, not a one-off favour, actually eases her load."},{"prompt":"A few days later, the crunch is still going. Ananya says: \"I don't know how much longer I can keep up like this.\"","options":[{"text":"\"Let me take on more until this eases, then we'll rebalance.\"","then":"\"Deal,\" she says, visibly relieved it's not open-ended.","best":true},{"text":"\"It's totally fine. Please don't worry about it at all.\"","then":"She nods, but keeps wondering if she owes you one."},{"text":"\"I know. Hang in there. It won't be forever.\"","then":"Ananya looks touched, but nothing about the split actually changes."},{"text":"\"Let's just see how it goes.\"","then":"Neither of you is sure what the plan actually is."}],"why":"Naming that it's temporary, with a clear rebalance point, keeps the flex fair."},{"prompt":"Ananya says: \"Things finally feel normal again. What should we do about the split?\"","options":[{"text":"\"Let's sit down and set an even split, so it's agreed again.\"","then":"You both redo the split that weekend, evenly this time.","best":true},{"text":"\"There's no rush. We'll sort the split out sometime soon.\"","then":"Ananya feels grateful, but the split stays unclear a while longer."},{"text":"\"Things feel fine as they are. Let's not bother.\"","then":"Whatever the crunch shifted stays where it landed, unspoken."},{"text":"\"You should take on extra now, to make up for the crunch.\"","then":"Ananya feels she owes you for the crunch."}],"why":"Rebalancing as soon as the crunch ends is what keeps flexing fair both ways."}],"relearn":"Offer to flex the split toward whoever has capacity now, and rebalance later, rather than holding a rigid half."},
  {"id":"ep-1204","cat":"share-it-fairly","type":"match","hook":"Match the fair-split move to what it ensures.","pairs":[{"left":"Own whole domains","right":"No one's left managing"},{"left":"Count all the hours","right":"Fair, not just visible"},{"left":"Agree, don't assume","right":"A genuine, chosen split"},{"left":"Write it down","right":"No weekly re-arguing"},{"left":"Revisit regularly","right":"Stays fair as life shifts"}],"relearn":"Owning domains, counting hours, agreeing, writing it down and revisiting each make the split genuinely fair.","persona":"any","source":"split moves"},
  {"id":"ep-1205","cat":"share-it-fairly","type":"match","hook":"Match the unfair default to the fairer alternative.","pairs":[{"left":"It lands on whoever's home","right":"Agree owned domains together"},{"left":"Only chores get counted","right":"Count the invisible work too"},{"left":"She keeps the dreary jobs","right":"Share the dull tasks fairly"},{"left":"One stays the manager","right":"Both own and remember"},{"left":"Set once and forgotten","right":"Revisit as life changes"}],"relearn":"Each unfair default has a fairer alternative: agreed domains, counted invisible work, shared dull jobs, shared managing, revisiting.","persona":"any","source":"default to fair"},
  {"id":"ep-1206","cat":"share-it-fairly","type":"match","hook":"Match the home job to the kind of work it really is.","pairs":[{"left":"Scrubbing the pans","right":"Visible chore"},{"left":"Planning the week's meals","right":"Mental load"},{"left":"Soothing an upset child","right":"Emotional labour"},{"left":"Tracking the bills' due dates","right":"Invisible managing"},{"left":"Carrying the shopping in","right":"Physical task"}],"relearn":"A home runs on visible chores, mental load, emotional labour, invisible managing and physical tasks, all real work to split.","persona":"any","source":"kinds of work"},
  {"id":"ep-1207","cat":"share-it-fairly","type":"match","hook":"Match the split phrase to whether it's fair or a default.","pairs":[{"left":"'Let's split it, invisible work too'","right":"Opens a fair split"},{"left":"'You're just better at home'","right":"Excuses a default"},{"left":"'Let's count both our hours'","right":"Makes it fair"},{"left":"'It's always been her job'","right":"Locks in a default"},{"left":"'Can we rebalance this?'","right":"Keeps it fair"}],"relearn":"Phrases like 'split it, invisible too' and 'let's rebalance' open fairness; 'you're better at it' and 'always her job' lock in defaults.","persona":"any","source":"phrase to label"},
  {"id":"ep-1208","cat":"share-it-fairly","type":"match","hook":"Match the part of the split to who should hold it.","pairs":[{"left":"A domain you own","right":"Yours to run unprompted"},{"left":"The standard for a job","right":"Agreed by both of you"},{"left":"The hours that count","right":"Paid and unpaid alike"},{"left":"A drifted arrangement","right":"Either of you can reopen it"},{"left":"The planning behind a chore","right":"Split, not pooled on one"}],"relearn":"You run your own domains, agree standards together, count all hours, either reopens a drift, and split the planning too.","persona":"any","source":"who holds what"},
  {"id":"ep-1209","cat":"share-it-fairly","type":"match","hook":"Match the situation to the fair next step.","pairs":[{"left":"You're just married","right":"Agree the split openly now"},{"left":"One of you is swamped","right":"Flex it for this season"},{"left":"It's quietly drifted","right":"Name it and rebalance"},{"left":"A baby is coming","right":"Re-split before it arrives"},{"left":"You keep redoing each other's jobs","right":"Agree shared standards"}],"relearn":"Each split situation has a fair next step: agree openly, flex, rebalance, re-split at change, or agree standards.","persona":"any","source":"situation to step"},
  {"id":"ep-1210","cat":"share-it-fairly","type":"match","hook":"Match the home domain to what owning it fully means.","pairs":[{"left":"Kitchen and groceries","right":"Plan, buy and cook without being asked"},{"left":"Bills and money admin","right":"Track and pay them all yourself"},{"left":"Kids' school life","right":"Hold the whole timetable and forms"},{"left":"Home upkeep","right":"Notice and fix without reminders"},{"left":"In-law relations","right":"Manage your own family's needs"}],"relearn":"Owning a domain means running it end to end, planning and remembering, not just doing tasks when reminded.","persona":"any","source":"own a domain fully"},
  {"id":"ep-1211","cat":"share-it-fairly","type":"reflect","hook":"Lensy: a fair split written down beats a fair split you both keep forgetting. Worth doing?","prompt":"What do you think?","options":["Yes","Write it down","Beats forgetting"],"affirm":"Putting the split in writing settles it, so the home runs on a shared agreement, not on memory and chasing.","relearn":"A written, agreed split keeps the home fair without re-arguing it every week.","persona":"any","source":"write it down"},
  {"id":"ep-1212","cat":"share-it-fairly","type":"reflect","hook":"Lensy: a fair split counts the hours nobody sees, not just the chores you can. Makes sense?","prompt":"What do you think?","options":["Yes","Count the unseen","Makes sense"],"affirm":"Counting the invisible hours is what makes a split actually fair, not just fair-looking on the surface.","relearn":"A genuinely fair split counts the invisible hours, not only the visible chores.","persona":"any","source":"count the unseen"},
  {"id":"ep-1213","cat":"share-it-fairly","type":"reflect","hook":"Lensy: either of you can open the split talk, it's nobody's job alone. Agree?","prompt":"What do you think?","options":["Yes","Either of us","Not her job alone"],"affirm":"An agreed split is built together; either partner can open the conversation, so it's never one person's burden to raise.","relearn":"Either partner can open the split conversation; it's not hers alone to raise.","persona":"any","source":"either opens it"},
  {"id":"ep-1214","cat":"share-it-fairly","type":"reflect","hook":"Lensy: fair doesn't have to mean identical, it means it fits both your real lives. Sit right?","prompt":"What do you think?","options":["Yes","Fits our lives","Not identical"],"affirm":"Fair flexes with each person's real capacity; the test isn't an identical 50/50, it's that it genuinely fits both of you.","relearn":"Fair means a split that fits both your real lives, not a rigid identical half each.","persona":"any","source":"fits both lives"},
  {"id":"ep-1215","cat":"share-it-fairly","type":"reflect","hook":"Lensy: splitting the planning, not just the chores, is what finally lifts the load. Feel that?","prompt":"What do you think?","options":["Yes","Split the planning","Lifts the load"],"affirm":"When the planning and remembering are split too, the invisible load stops sitting on one person; that's a real split.","relearn":"Splitting the planning and remembering, not just the chores, is what makes a split truly fair.","persona":"Pooja","source":"split the planning"},
  {"id":"ep-1216","cat":"share-it-fairly","type":"reflect","hook":"Lensy: a split you agree out loud beats one that just 'happens' to land on her. Right?","prompt":"What do you think?","options":["Yes","Say it out loud","Beats defaults"],"affirm":"An explicit, agreed split replaces silent defaults, so fairness is chosen on purpose rather than left to chance.","relearn":"An explicit, agreed split is fairer than letting the load silently default to one person.","persona":"any","source":"agreed not default"},
  {"id":"ep-1217","cat":"share-it-fairly","type":"reflect","hook":"Lensy: sharing the dull jobs fairly, not just the nice ones, is the real test of a split. Agree?","prompt":"What do you think?","options":["Yes","Share the dull too","Real test"],"affirm":"A split is only fair if the dreary, unpleasant jobs are shared too, not just the pleasant visible ones.","relearn":"A fair split shares the dull, unpleasant jobs too, not just the nicer ones.","persona":"any","source":"share the dull jobs"},
  {"id":"ep-1218","cat":"share-it-fairly","type":"spot","hook":"Spot the two unfair defaults hiding in this 'split'.","scene":[{"id":"a","text":"Owned domains agreed together","trick":false},{"id":"b","text":"Whatever's left lands on her","trick":true},{"id":"c","text":"Paid and unpaid hours counted","trick":false},{"id":"d","text":"Only the visible chores counted","trick":true},{"id":"e","text":"The planning shared too","trick":false}],"why":"'Whatever's left lands on her' and 'only visible chores counted' are the unfair defaults; the rest are genuinely fair.","relearn":"Unfair defaults: leftover work landing on her and counting only visible chores; a fair split counts all the work.","persona":"any","source":"two defaults"},
  {"id":"ep-1219","cat":"share-it-fairly","type":"spot","hook":"Spot the two lines that quietly keep the load on one person.","scene":[{"id":"a","text":"\"Let's split the invisible work too\"","trick":false},{"id":"b","text":"\"You're just naturally better at this\"","trick":true},{"id":"c","text":"\"Either of us can reopen the split\"","trick":false},{"id":"d","text":"\"It's always been the woman's job\"","trick":true},{"id":"e","text":"\"Let's count everyone's hours\"","trick":false}],"why":"'You're naturally better' and 'always the woman's job' keep the load on her; the others open a fair split.","relearn":"Lines like 'you're naturally better' and 'always the woman's job' lock the load on her; spot and drop them.","persona":"any","source":"two loaded lines"},
  {"id":"ep-1220","cat":"share-it-fairly","type":"spot","hook":"Spot the two signs this split is unfair, not shared.","scene":[{"id":"a","text":"Both own whole domains","trick":false},{"id":"b","text":"She still chases him for everything","trick":true},{"id":"c","text":"The standards were agreed together","trick":false},{"id":"d","text":"Only she remembers what's due","trick":true},{"id":"e","text":"They revisit it together monthly","trick":false}],"why":"Her chasing him and being the only one who remembers are the unfair signs; the rest show a genuinely shared split.","relearn":"If she still chases and remembers everything, the managing is still hers, that's not a fair split.","persona":"any","source":"two unfair signs"},
  {"id":"ep-1221","cat":"share-it-fairly","type":"spot","hook":"Spot the two moves that make a split secretly unequal.","scene":[{"id":"a","text":"Splitting paying and tracking bills","trick":false},{"id":"b","text":"He pays, she tracks every due date","trick":true},{"id":"c","text":"Sharing the school admin","trick":false},{"id":"d","text":"She keeps all the 'soft' care work","trick":true},{"id":"e","text":"Trading domains when one is busy","trick":false}],"why":"Leaving her all the tracking and all the 'soft' care work makes a split secretly unequal; the others share it fairly.","relearn":"Pooling the tracking or the 'soft' care work on her makes a split secretly unequal; share those too.","persona":"any","source":"two secret loads"},
  {"id":"ep-1222","cat":"share-it-fairly","type":"spot","hook":"Spot the two reasons this 'fair' split won't last.","scene":[{"id":"a","text":"It's written down where both can see","trick":false},{"id":"b","text":"It's vague 'we'll both pitch in'","trick":true},{"id":"c","text":"They check in and adjust it","trick":false},{"id":"d","text":"They assume it'll sort itself out","trick":true},{"id":"e","text":"Each owns clear domains","trick":false}],"why":"Vague 'we'll pitch in' and assuming it'll sort itself out are why a split fails; the rest make it last.","relearn":"Vagueness and assuming it'll sort itself out make a split fail; written domains and check-ins make it last.","persona":"any","source":"two reasons it fails"},
  {"id":"ep-1223","cat":"share-it-fairly","type":"spot","hook":"Spot the two things that should count but get left out of splits.","scene":[{"id":"a","text":"The hours of paid work","trick":false},{"id":"b","text":"The mental load of remembering","trick":true},{"id":"c","text":"The visible chores done","trick":false},{"id":"d","text":"The planning nobody sees","trick":true},{"id":"e","text":"The errands run that day","trick":false}],"why":"The mental load and the unseen planning are what get left out of splits, even though they're real work to share.","relearn":"The mental load and unseen planning should count in a split but usually get left out; put them in.","persona":"any","source":"two left out"},
  {"id":"ep-1224","cat":"share-it-fairly","type":"spot","hook":"Spot the two replies that shut down a fair-split talk.","scene":[{"id":"a","text":"\"Let's map it all out together\"","trick":false},{"id":"b","text":"\"Stop complaining, it's fine\"","trick":true},{"id":"c","text":"\"I think it's drifted, let's rebalance\"","trick":false},{"id":"d","text":"\"This is just how marriage is\"","trick":true},{"id":"e","text":"\"Let's count both our hours\"","trick":false}],"why":"'Stop complaining, it's fine' and 'this is just how marriage is' shut down the talk; the others open it fairly.","relearn":"Replies like 'stop complaining' and 'that's just marriage' shut down a fair-split talk; the open ones invite it.","persona":"any","source":"two shut-downs"},
  {"id":"ep-1225","cat":"share-it-fairly","type":"strike-rewrite","hook":"\"However the work happens to land between us is fair enough.\"","myth":{"un":"However the work lands between us is fair enough.","re":"Fairness comes from an explicit, agreed split, not from where work happens to land.","why":"Left to chance, the load defaults onto one person."},"relearn":"Fairness is an explicit, agreed split, not wherever the work happens to land.","persona":"any","source":"agreed not landed"},
  {"id":"ep-1226","cat":"share-it-fairly","type":"strike-rewrite","hook":"\"We split the chores down the middle, so our split is fair.\"","myth":{"un":"We split the chores down the middle, so it's fair.","re":"A fair split must include the planning and remembering, not just the visible chores.","why":"Splitting only chores leaves all the managing on one person."},"relearn":"A fair split includes the planning and remembering, not just an even cut of the visible chores.","persona":"any","source":"chores aren't the whole split"},
  {"id":"ep-1227","cat":"share-it-fairly","type":"strike-rewrite","hook":"\"A fair split has to be exactly identical, 50/50, always.\"","myth":{"un":"A fair split must be exactly identical, always.","re":"Fair doesn't always mean identical; it flexes with each person's real capacity and is revisited.","why":"Real lives have busy seasons; a rigid half can stop being fair."},"relearn":"Fair flexes with real capacity and is revisited; it isn't always an identical half each.","persona":"any","source":"fair isn't identical"},
  {"id":"ep-1228","cat":"share-it-fairly","type":"strike-rewrite","hook":"\"The unpaid home hours don't really need to count in the split.\"","myth":{"un":"The unpaid home hours don't need to count.","re":"The invisible and unpaid hours should count in the split; they're often ignored.","why":"Unpaid work is real work, even though no one bills for it."},"relearn":"The invisible and unpaid hours should count in the split, not be ignored.","persona":"any","source":"unpaid hours count"},
  {"id":"ep-1229","cat":"share-it-fairly","type":"strike-rewrite","hook":"\"Raising the split again means you're picking a fight.\"","myth":{"un":"Raising the split again means picking a fight.","re":"You can raise rebalancing without blame: 'I think our split has drifted, can we rebalance it?'","why":"Naming a drift early prevents the resentment a fight comes from."},"relearn":"Raise rebalancing without blame by naming the drift; it prevents fights, it isn't one.","persona":"Pooja","source":"rebalance isn't a fight"},
  {"id":"ep-1230","cat":"share-it-fairly","type":"strike-rewrite","hook":"\"One of us should just quietly design the split and hand it over.\"","myth":{"un":"One of us should design the split and hand it over.","re":"An agreed split is built together, not imposed; either partner can open the conversation.","why":"A split owned by both is one both will actually keep."},"relearn":"An agreed split is built together, not designed by one and imposed; either partner can open it.","persona":"any","source":"built together"},
  {"id":"ep-1231","cat":"share-it-fairly","type":"strike-rewrite","hook":"\"Whoever earns less should just take on the bigger share of home work.\"","myth":{"un":"Whoever earns less should take the bigger home share.","re":"A fair split divides owned domains and counts all hours; it isn't set by who earns less.","why":"Earning less doesn't make someone's time worth less."},"relearn":"A fair split divides owned domains and counts all hours; it isn't dumped on the lower earner.","persona":"any","source":"not by who earns less"},
  {"id":"ep-1232","cat":"share-it-fairly","type":"strike-rewrite","hook":"\"Once we've agreed who does what, the split is sorted for good.\"","myth":{"un":"Once we agree who does what, it's sorted for good.","re":"A fair split is revisited as life changes; agreeing it once isn't the end of the conversation.","why":"New jobs, moves and a baby all shift the real load."},"relearn":"A fair split is revisited as life changes; agreeing it once doesn't sort it forever.","persona":"any","source":"revisit the split"},
  {"id":"ep-1260","cat":"tools-and-help","type":"match","hook":"Match each fairness tool to the exact job it does.","pairs":[{"left":"A full load inventory","right":"Makes the invisible work visible"},{"left":"An owned-domains split","right":"Shares the mental load"},{"left":"A monthly check-in","right":"Keeps it fair over time"},{"left":"A 'who-decides' list","right":"Stops one person deciding all"},{"left":"A one-week task log","right":"Shows where hours really go"}],"relearn":"Each tool maps to a job: inventory sees the work, owned split shares the load, check-in keeps it fair.","persona":"any","source":"tools to jobs"},
  {"id":"ep-1261","cat":"tools-and-help","type":"match","hook":"Match the home complaint to the tool that actually fixes it.","pairs":[{"left":"\"I do tasks, she still manages\"","right":"Owned-domains split"},{"left":"\"It was fair, now it's slipped\"","right":"Monthly check-in"},{"left":"\"He can't see what I do\"","right":"Full load inventory"},{"left":"\"We just argue, never decide\"","right":"A couples counsellor"},{"left":"\"He controls the money\"","right":"Respect at Home & help"}],"relearn":"Pick the tool by the problem: managing-gap needs an owned split, drift needs a check-in, control needs help.","persona":"any","source":"complaint to tool"},
  {"id":"ep-1262","cat":"tools-and-help","type":"match","hook":"Match the need to where it should route.","pairs":[{"left":"A drifted, unfair split","right":"A fair-split renegotiation"},{"left":"Control over money or movement","right":"Respect at Home & help"},{"left":"Constant fighting, no contempt","right":"A couples counsellor"},{"left":"\"He just can't see the load\"","right":"A shared load inventory"},{"left":"One career always sidelined","right":"A two-careers rebalance"}],"relearn":"Route by need: drift to renegotiation, control to help, fights to counselling, blindness to an inventory.","persona":"Saxena","source":"route by need"},
  {"id":"ep-1263","cat":"tools-and-help","type":"match","hook":"Match what an equal home gives each person.","pairs":[{"left":"The over-loaded partner","right":"Load shared, not just helped"},{"left":"The unaware partner","right":"Deeper connection, less guilt"},{"left":"Both of them","right":"Less resentment, more warmth"},{"left":"Their future kids","right":"Equality modelled as normal"},{"left":"The relationship","right":"More partnership, less scorekeeping"}],"relearn":"An equal home gains everyone: shared load, deeper connection, less resentment, a model for the kids.","persona":"any","source":"everyone gains"},
  {"id":"ep-1264","cat":"tools-and-help","type":"match","hook":"Match each warm line of support to what it gives a friend.","pairs":[{"left":"\"That's the mental load, it's real\"","right":"Names the invisible work"},{"left":"\"You deserve owning, not helping\"","right":"Raises the standard"},{"left":"\"This isn't ingratitude, it's fairness\"","right":"Validates the resentment"},{"left":"\"Want to map it together?\"","right":"Offers a concrete next step"},{"left":"\"If it's control, there's help\"","right":"Opens the safety door"}],"relearn":"Good support names the load, raises the bar, validates the feeling, offers a step and opens the safety door.","persona":"any","source":"language that helps"},
  {"id":"ep-1265","cat":"tools-and-help","type":"match","hook":"Match the tool to the equal-partners lesson it serves.","pairs":[{"left":"Load inventory","right":"See the whole load"},{"left":"Owned-domains split","right":"Own it, don't just help"},{"left":"All-hours count","right":"Share it fairly"},{"left":"Turn-taking on flex","right":"Both careers count"},{"left":"Monthly check-in","right":"Keep it equal over time"}],"relearn":"Each tool carries one lesson: see, own, share fairly, value both careers, keep renegotiating.","persona":"any","source":"tool to lesson"},
  {"id":"ep-1266","cat":"tools-and-help","type":"match","hook":"Match the unfair pattern to the everyday tool that names it.","pairs":[{"left":"\"Just tell me what to do\"","right":"You're still the manager"},{"left":"Redoing the school forms quietly","right":"Hidden, uncounted hours"},{"left":"\"Her job can flex\"","right":"A career-default to check"},{"left":"\"We sorted this last year\"","right":"A check-in that's overdue"},{"left":"Tracking it all in her head","right":"The mental load, unshared"}],"relearn":"Naming the pattern is the tool: who manages, hidden hours, career defaults, overdue check-ins, the unshared load.","persona":"any","source":"name the pattern"},
  {"id":"ep-1267","cat":"tools-and-help","type":"match","hook":"Match the question to the check-in it belongs to.","pairs":[{"left":"\"What did I track this week?\"","right":"The load check"},{"left":"\"Has our split drifted?\"","right":"The fairness check"},{"left":"\"Whose career flexed last?\"","right":"The careers check"},{"left":"\"What changed in our life?\"","right":"The renegotiation check"},{"left":"\"Is anyone being controlled?\"","right":"The safety check"}],"relearn":"A good check-in asks five things: load tracked, fairness drift, careers, life changes, and safety.","persona":"any","source":"the check-in questions"},
  {"id":"ep-1268","cat":"tools-and-help","type":"match","hook":"Match each myth to the truth that retires it.","pairs":[{"left":"\"Equal homes are a women's demand\"","right":"They're a better life for both"},{"left":"\"He loses if she gains\"","right":"Men gain connection too"},{"left":"\"Helping is sharing\"","right":"Owning beats helping"},{"left":"\"Once agreed, it's sorted\"","right":"It's renegotiated as life changes"},{"left":"\"No complaint means it's fair\"","right":"Silence can be exhaustion"}],"relearn":"Each load myth has a truth: better for both, men gain, owning beats helping, renegotiate, silence isn't fairness.","persona":"any","source":"myth to truth"},
  {"id":"ep-1269","cat":"tools-and-help","type":"match","hook":"Match each starting line to the conversation it opens.","pairs":[{"left":"\"Walk me through your invisible day\"","right":"Seeing the load"},{"left":"\"Let me own this end-to-end\"","right":"Owning a domain"},{"left":"\"Let's map it all and split fairly\"","right":"Agreeing the split"},{"left":"\"This time my job can flex\"","right":"Sharing the career-flex"},{"left":"\"Can we check in monthly?\"","right":"Keeping it equal"}],"relearn":"One opening line starts each conversation: see, own, split, take a turn flexing, and keep checking in.","persona":"Karthik","source":"opening lines"},
  {"id":"ep-1270","cat":"tools-and-help","type":"match","hook":"Match what a partner can offer to the person who needs it.","pairs":[{"left":"Language for the load","right":"A friend who feels alone in it"},{"left":"A path forward, not blame","right":"A partner who's defensive"},{"left":"An offer to take some back","right":"A partner carrying more lately"},{"left":"A discreet route to help","right":"Someone facing control"},{"left":"A shared check-in habit","right":"A couple who keep drifting"}],"relearn":"Offer the right thing: language, a path, a hand back, a safe route, or a habit, to the person who needs it.","persona":"any","source":"offer to person"},
  {"id":"ep-1271","cat":"tools-and-help","type":"match","hook":"Match each fair-split rule to what it protects against.","pairs":[{"left":"Count the invisible hours too","right":"An unfair 'visible-only' split"},{"left":"Own whole domains","right":"Leaving one person managing"},{"left":"Agree it, don't assume","right":"Silent, drifting defaults"},{"left":"Revisit when life changes","right":"A split that's gone stale"},{"left":"Share the unpleasant tasks","right":"Dumping the worst on one"}],"relearn":"Each split rule guards a trap: count invisible hours, own domains, agree it, revisit, and share the worst.","persona":"any","source":"rules and traps"},
  {"id":"ep-1272","cat":"tools-and-help","type":"match","hook":"Match the situation to the right first move.","pairs":[{"left":"\"I don't even know all I carry\"","right":"Write a load inventory"},{"left":"\"He helps but I still manage\"","right":"Hand him a domain to own"},{"left":"\"We agreed but it slipped\"","right":"Book a monthly check-in"},{"left":"\"He decides where I can go\"","right":"Reach out for help"},{"left":"\"We can't talk without fighting\"","right":"See a couples counsellor"}],"relearn":"Match the first move: inventory the load, hand over a domain, book a check-in, get help, or get counselling.","persona":"any","source":"first move"},
  {"id":"ep-1273","cat":"tools-and-help","type":"match","hook":"Match each sign to what it tells you about the home.","pairs":[{"left":"No one's left managing","right":"The load is truly shared"},{"left":"Neither career is the 'backup'","right":"Both jobs count"},{"left":"You rebalance without blame","right":"It stays fair over time"},{"left":"One controls the money","right":"Time to reach for help"},{"left":"Reminders have disappeared","right":"He's actually owning it"}],"relearn":"Read the signs: no manager means shared, no backup-career means both count, no reminders means truly owned.","persona":"any","source":"reading the signs"},
  {"id":"ep-1274","cat":"tools-and-help","type":"sort","hook":"Sort: a fairness tool, or a thing that keeps the load stuck?","items":[{"id":"a","text":"A shared load inventory"},{"id":"b","text":"\"You're just better at it\""},{"id":"c","text":"An owned-domains split"},{"id":"d","text":"Waiting to be asked"},{"id":"e","text":"A monthly check-in"},{"id":"f","text":"Keeping it all in one head"}],"bins":[{"id":"tool","label":"A fairness tool","valence":"pos"},{"id":"stuck","label":"Keeps it stuck","valence":"neg"}],"key":{"a":"tool","b":"stuck","c":"tool","d":"stuck","e":"tool","f":"stuck"},"relearn":"Inventories, owned splits and check-ins are tools; 'you're better at it', waiting to be asked and one-head-tracking keep it stuck.","persona":"any","source":"tool or stuck"},
  {"id":"ep-1275","cat":"tools-and-help","type":"sort","hook":"Sort each issue to where it really should go.","items":[{"id":"a","text":"Our split has quietly drifted"},{"id":"b","text":"He controls who I can see"},{"id":"c","text":"We fight but still respect each other"},{"id":"d","text":"He limits my access to money"},{"id":"e","text":"One career always gives way"},{"id":"f","text":"We keep arguing in circles"}],"bins":[{"id":"split","label":"Renegotiate the split","valence":"pos"},{"id":"help","label":"Help · Respect at Home","valence":"uhoh"},{"id":"counsel","label":"A counsellor","valence":"tell"}],"key":{"a":"split","b":"help","c":"counsel","d":"help","e":"split","f":"counsel"},"relearn":"Drift and career-default go to renegotiation; control over money or movement goes to help; circular fights go to a counsellor.","persona":"Saxena","source":"where it goes"},
  {"id":"ep-1276","cat":"tools-and-help","type":"sort","hook":"Sort: does this make the home better for everyone, or only feel like a fight?","items":[{"id":"a","text":"He gains deeper connection too"},{"id":"b","text":"\"It's her winning, me losing\""},{"id":"c","text":"Less resentment for both"},{"id":"d","text":"\"A battle of the sexes\""},{"id":"e","text":"Kids learn equality is normal"},{"id":"f","text":"\"Keeping score of chores\""}],"bins":[{"id":"better","label":"Better for everyone","valence":"pos"},{"id":"fight","label":"Just a fight","valence":"neg"}],"key":{"a":"better","b":"fight","c":"better","d":"fight","e":"better","f":"fight"},"relearn":"An equal home is better for everyone: connection, less resentment, kids learning it, not a battle of the sexes or scorekeeping.","persona":"Karthik","source":"better not battle"},
  {"id":"ep-1277","cat":"tools-and-help","type":"sort","hook":"Sort the support line: helps a struggling friend, or shuts her down?","items":[{"id":"a","text":"\"That's the mental load, it's real\""},{"id":"b","text":"\"That's just how marriage is\""},{"id":"c","text":"\"You deserve owning, not helping\""},{"id":"d","text":"\"At least he helps a bit\""},{"id":"e","text":"\"Want to map it out together?\""},{"id":"f","text":"\"Don't be ungrateful\""}],"bins":[{"id":"helps","label":"Helps her","valence":"pos"},{"id":"shuts","label":"Shuts her down","valence":"neg"}],"key":{"a":"helps","b":"shuts","c":"helps","d":"shuts","e":"helps","f":"shuts"},"relearn":"Name the load, raise the bar and offer to help; 'that's just marriage', 'at least he helps' and 'don't be ungrateful' shut her down.","persona":"any","source":"support or shutdown"},
  {"id":"ep-1278","cat":"tools-and-help","type":"sort","hook":"Sort: is this unfairness to renegotiate, or control that needs help?","items":[{"id":"a","text":"He does chores only when asked"},{"id":"b","text":"He blocks her from seeing family"},{"id":"c","text":"Her career always flexes by default"},{"id":"d","text":"He takes her phone and money"},{"id":"e","text":"The mental load sits on her"},{"id":"f","text":"He tracks her every movement"}],"bins":[{"id":"reneg","label":"Renegotiate it","valence":"pos"},{"id":"help","label":"That's abuse · get help","valence":"uhoh"}],"key":{"a":"reneg","b":"help","c":"reneg","d":"help","e":"reneg","f":"help"},"relearn":"Unequal chores, default-flex and an unshared load are renegotiated; controlling movement, money or contacts is abuse, get help.","persona":"any","source":"unfair vs control"},
  {"id":"ep-1279","cat":"tools-and-help","type":"sort","hook":"Sort: a real fairness tool, or a fake fix that dumps it back on her?","items":[{"id":"a","text":"Owned domains, end-to-end"},{"id":"b","text":"\"Just communicate better\""},{"id":"c","text":"Counting all the hours"},{"id":"d","text":"\"Do some self-care\""},{"id":"e","text":"A no-blame monthly check-in"},{"id":"f","text":"\"Make him a chore list\""}],"bins":[{"id":"real","label":"A real tool","valence":"pos"},{"id":"fake","label":"Dumps it on her","valence":"neg"}],"key":{"a":"real","b":"fake","c":"real","d":"fake","e":"real","f":"fake"},"relearn":"Owned domains, counted hours and check-ins are real tools; 'communicate better', 'self-care' and 'make him a list' put it back on her.","persona":"Pooja","source":"real vs fake fix"},
  {"id":"ep-1280","cat":"tools-and-help","type":"sort","hook":"Sort each line by which equal-partners tool it belongs to.","items":[{"id":"a","text":"\"Walk me through your invisible day\""},{"id":"b","text":"\"I'll own the bills end-to-end\""},{"id":"c","text":"\"This time my job flexes\""},{"id":"d","text":"\"Has our split drifted lately?\""},{"id":"e","text":"\"Show me what you track\""},{"id":"f","text":"\"You shouldn't have to remind me\""}],"bins":[{"id":"see","label":"Seeing the load","valence":"neutral"},{"id":"own","label":"Owning a domain","valence":"neutral"},{"id":"keep","label":"Keeping it equal","valence":"neutral"}],"key":{"a":"see","b":"own","c":"keep","d":"keep","e":"see","f":"own"},"relearn":"Lines sort by tool: 'walk me through' and 'show me' see the load; 'I'll own it' owns; 'has it drifted' keeps it equal.","persona":"any","source":"line to tool"},
  {"id":"ep-1281","cat":"tools-and-help","type":"sort","hook":"Sort: builds the partnership, or quietly erodes it?","items":[{"id":"a","text":"Owning the remembering, not just doing"},{"id":"b","text":"Defending how much you do"},{"id":"c","text":"Offering to take some back"},{"id":"d","text":"Keeping score to win"},{"id":"e","text":"Naming drift without blame"},{"id":"f","text":"Waiting for resentment to boil over"}],"bins":[{"id":"builds","label":"Builds it","valence":"pos"},{"id":"erodes","label":"Erodes it","valence":"neg"}],"key":{"a":"builds","b":"erodes","c":"builds","d":"erodes","e":"builds","f":"erodes"},"relearn":"Owning the remembering, offering to take some back and naming drift build it; defending, scoring and bottling up erode it.","persona":"any","source":"build or erode"},
  {"id":"ep-1282","cat":"tools-and-help","type":"sort","hook":"Sort: a sign the tools are working, or a sign they're not yet?","items":[{"id":"a","text":"Reminders have faded away"},{"id":"b","text":"\"Just tell me what to do\""},{"id":"c","text":"Both careers get backed in turn"},{"id":"d","text":"She still holds the whole calendar"},{"id":"e","text":"The check-in catches drift early"},{"id":"f","text":"Resentment keeps creeping back"}],"bins":[{"id":"working","label":"Working","valence":"pos"},{"id":"notyet","label":"Not yet","valence":"uhoh"}],"key":{"a":"working","b":"notyet","c":"working","d":"notyet","e":"working","f":"notyet"},"relearn":"Faded reminders, turn-taking and early-caught drift mean it's working; 'just tell me', a one-person calendar and creeping resentment mean not yet.","persona":"any","source":"working or not"},
  {"id":"ep-1283","cat":"tools-and-help","type":"reflect","hook":"Lensy: the simplest first tool is just writing down everything you both carry. Worth trying?","prompt":"What do you think?","options":["Yes","Write it down","See it first"],"affirm":"A full load inventory makes the invisible work visible, that's always the honest first step.","relearn":"The first tool is a load inventory: write down everything you both carry to see it.","persona":"any","source":"the inventory"},
  {"id":"ep-1284","cat":"tools-and-help","type":"reflect","hook":"Lensy: an equal home isn't her win and his loss, it's a fairer life you both live in. Agree?","prompt":"What do you think?","options":["Yes","For both","Not a loss"],"affirm":"An equal home is never a loss for men; it's a better, warmer life for everyone in it.","relearn":"An equal home is not a battle of the sexes; it's a fairer life for both partners.","persona":"Karthik","source":"not a loss"},
  {"id":"ep-1285","cat":"tools-and-help","type":"reflect","hook":"Lensy: men gain too, deeper connection and a fairer life, when home is truly equal. Believe it?","prompt":"What do you think?","options":["Yes","He gains too","Deeper connection"],"affirm":"An equal home is happier for everyone; men gain real connection and a fairer life, not just more chores.","relearn":"Men gain too from an equal home: deeper connection and a fairer life, never a loss.","persona":"Karthik","source":"men gain too"},
  {"id":"ep-1286","cat":"tools-and-help","type":"reflect","hook":"Lensy: the right tool depends on the problem, drift, blindness, or control aren't the same. Makes sense?","prompt":"What do you think?","options":["Yes","Match the problem","Different routes"],"affirm":"Drift needs a renegotiation, blindness needs an inventory, control needs help, you route by what's actually wrong.","relearn":"Route by need: drift to renegotiation, blindness to an inventory, control to help.","persona":"any","source":"route by need"},
  {"id":"ep-1287","cat":"tools-and-help","type":"reflect","hook":"Lensy: when inequality becomes control over money, movement or who you see, that's abuse. Clear?","prompt":"What do you think?","options":["Yes","That's abuse","Not my fault"],"affirm":"Inequality that tips into control or coercion is abuse, never your fault, and help is there (see Respect at Home).","relearn":"When home inequality becomes control over money, movement or contacts, that's abuse, and help exists.","persona":"any","source":"control is abuse"},
  {"id":"ep-1288","cat":"tools-and-help","type":"reflect","hook":"Lensy: you can give a struggling friend language she's never had for the load. Worth doing?","prompt":"What do you think?","options":["Yes","Give her words","Name it"],"affirm":"Naming the mental load for a friend, and saying she deserves a partner who owns half, is real support.","relearn":"You can give a friend language for the load and remind her she deserves owning, not just helping.","persona":"any","source":"language for a friend"},
  {"id":"ep-1289","cat":"tools-and-help","type":"reflect","hook":"Lensy: the best tool is the one you'll actually keep using, not the most elaborate. Agree?","prompt":"What do you think?","options":["Yes","Keep it simple","One we'll use"],"affirm":"A simple monthly check-in you actually keep beats a perfect system you abandon, fairness needs a habit.","relearn":"The best fairness tool is the simple one you'll keep using, like a monthly check-in.","persona":"any","source":"the one you'll use"},
  {"id":"ep-1290","cat":"tools-and-help","type":"reflect","hook":"Lensy: kids who grow up in an equal home expect equality, the tools outlive you. Worth it?","prompt":"What do you think?","options":["Yes","For the kids","Model it"],"affirm":"Children who see equal parents grow up expecting equality; the fairness you build becomes their normal.","relearn":"An equal home models equality for kids; the tools you use outlive you.","persona":"any","source":"outlives you"},
  {"id":"ep-1291","cat":"tools-and-help","type":"reflect","hook":"Lensy: asking for help with home inequality isn't weakness, it's how couples get fairer. Agree?","prompt":"What do you think?","options":["Yes","It's strength","Get help"],"affirm":"Reaching for a counsellor, a tool or a helpline is how fairness gets built, not a sign of failure.","relearn":"Asking for help with home inequality is how couples get fairer, not weakness.","persona":"Saxena","source":"help isn't weakness"},
  {"id":"ep-1292","cat":"tools-and-help","type":"reflect","hook":"Lensy: you don't need a perfect home, just one you keep making fairer together. True for you?","prompt":"What do you think?","options":["Yes","Keep making it fairer","Together"],"affirm":"No home is perfectly equal forever; the win is two people who keep choosing to make it fairer.","relearn":"You don't need a perfect home, just one you keep making fairer together.","persona":"any","source":"not perfect, fairer"},
  {"id":"ep-1293","cat":"tools-and-help","type":"reflect","hook":"Lensy: 'log kya kahenge' will judge an equal home, your fairness is still worth it. Agree?","prompt":"What do you think?","options":["Yes","Worth it anyway","Our home, our rules"],"affirm":"Relatives may raise eyebrows at a husband who owns half; a fairer, warmer home is worth more than their approval.","relearn":"Others may judge an equal home; the fairness it gives you both is still worth it.","persona":"any","source":"log kya kahenge"},
  {"id":"ep-1294","cat":"tools-and-help","type":"reflect","hook":"Lensy: routing coercion to help is not betraying your partner, it's protecting a person. Clear?","prompt":"What do you think?","options":["Yes","Protect the person","Help is right"],"affirm":"Where unfairness becomes control, reaching for help protects someone; it's care, not betrayal.","relearn":"Routing real coercion to help protects a person; that's care, not betrayal.","persona":"any","source":"help is care"},
  {"id":"ep-1295","cat":"tools-and-help","type":"reflect","hook":"Lensy: the load is real work even when no one ever named it as work. Does that land?","prompt":"What do you think?","options":["Yes","It's real work","Name it work"],"affirm":"Planning, tracking and remembering is real, tiring work; a tool just lets you finally count it.","relearn":"The mental load is real work; a tool lets you name and count it at last.","persona":"Pooja","source":"it's real work"},
  {"id":"ep-1296","cat":"tools-and-help","type":"reflect","hook":"Lensy: one good tool used by both of you beats ten 'tips' aimed only at her. Agree?","prompt":"What do you think?","options":["Yes","Both of us","Not just her"],"affirm":"Shared tools both partners use beat self-help tips that quietly put the whole burden back on one person.","relearn":"A shared tool both partners use beats tips aimed only at the over-loaded partner.","persona":"any","source":"shared, not just her"},
  {"id":"ep-1297","cat":"tools-and-help","type":"reflect","hook":"Lensy: seeing the load, owning your half, keeping it fair, which do you want to carry first?","prompt":"What will you pick up first?","options":["See the invisible load","Own a whole domain","Book a check-in","Value both careers"],"affirm":"Pick up one and start; the equal home this chapter is about is built one honest tool at a time.","relearn":"Start with one tool: see the load, own a domain, book a check-in or value both careers.","persona":"any","source":"pick one up"},
  {"id":"ep-1298","cat":"tools-and-help","type":"reflect","hook":"Lensy: 'I'll own it so you don't manage it' might be the kindest thing you say all week. Agree?","prompt":"What do you think?","options":["Yes","Say it","Kindest line"],"affirm":"Taking a domain fully off your partner's plate, planning and all, is a quiet, powerful act of love.","relearn":"'I'll own it so you don't have to manage it' is a kind, powerful thing to say.","persona":"Karthik","source":"the kindest line"},
  {"id":"ep-1299","cat":"tools-and-help","type":"reflect","hook":"Lensy: a check-in works best as a gentle date, not a complaint session. Sound right?","prompt":"What do you think?","options":["Yes","Make it warm","Not a complaint"],"affirm":"A check-in over chai, curious not accusing, keeps fairness a shared project instead of a fight.","relearn":"A check-in works best warm and curious, a gentle date, not a complaint session.","persona":"any","source":"warm check-in"},
  {"id":"ep-1300","cat":"tools-and-help","type":"reflect","hook":"Lensy: noticing your partner is carrying more, before they ask, is itself a tool. Agree?","prompt":"What do you think?","options":["Yes","Notice first","Offer it"],"affirm":"Catching that your partner's been carrying more, and offering to take some back, is owning at its best.","relearn":"Noticing your partner is carrying more, before they ask, is itself a fairness tool.","persona":"any","source":"noticing is a tool"},
  {"id":"ep-1301","cat":"tools-and-help","type":"strike-rewrite","hook":"\"There's no real tool for this, you just have to nag him more.\"","myth":{"un":"There's no real tool for this, you just have to nag him more.","re":"A load inventory and owned-domains split end the nagging by making him the owner, not the helper.","why":"Owning removes the need to remind; nagging is the symptom of an unshared load."},"relearn":"The fix isn't more nagging; it's an inventory and owned split that make him the owner.","persona":"Pooja","source":"not more nagging"},
  {"id":"ep-1302","cat":"tools-and-help","type":"strike-rewrite","hook":"\"An equal home means men just lose their freedom and gain only chores.\"","myth":{"un":"An equal home means men just lose their freedom and gain only chores.","re":"Men gain deeper connection, less guilt and a fairer life; an equal home is never a net loss for them.","why":"Sharing the load builds partnership both people actually want to be in."},"relearn":"An equal home isn't loss for men; they gain connection, less guilt and a fairer life.","persona":"Karthik","source":"men gain, not lose"},
  {"id":"ep-1303","cat":"tools-and-help","type":"strike-rewrite","hook":"\"If it's just unfair, you should never bring outside help into a marriage.\"","myth":{"un":"If it's just unfair, you should never bring outside help into a marriage.","re":"A counsellor or a clear tool can help a stuck couple get fairer; and real coercion needs outside help fast.","why":"Some loads are too set to shift alone, and control is never a private matter."},"relearn":"Outside help is fine for a stuck split, and necessary the moment unfairness becomes control.","persona":"Saxena","source":"help has a place"},
  {"id":"ep-1304","cat":"tools-and-help","type":"strike-rewrite","hook":"\"Controlling the money is just him being the responsible head of the house.\"","myth":{"un":"Controlling the money is just him being the responsible head of the house.","re":"Cutting off your access to money is control, not responsibility; that's abuse, and help exists.","why":"Responsibility is shared and transparent; control isolates and is never your fault."},"relearn":"Controlling your access to money isn't 'being the head'; it's abuse, and help is there.","persona":"any","source":"control isn't responsibility"},
  {"id":"ep-1305","cat":"tools-and-help","type":"strike-rewrite","hook":"\"Tools and check-ins are overkill, a good couple just figures it out naturally.\"","myth":{"un":"Tools and check-ins are overkill, a good couple just figures it out naturally.","re":"Even loving couples drift to old defaults; a simple check-in is what catches it before resentment sets.","why":"Fairness fades without a deliberate habit, however much you love each other."},"relearn":"Even good couples drift; a simple check-in catches it, love alone doesn't keep it fair.","persona":"any","source":"love isn't a tool"},
  {"id":"ep-1306","cat":"tools-and-help","type":"strike-rewrite","hook":"\"Helping a friend means agreeing her husband is a villain.\"","myth":{"un":"Helping a friend means agreeing her husband is a villain.","re":"Real support names the load and raises her standard, without making him the enemy; this isn't about blame.","why":"You can validate her exhaustion and still believe the home can change."},"relearn":"Supporting a friend means naming the load, not casting her husband as a villain.","persona":"any","source":"support without blame"},
  {"id":"ep-1307","cat":"tools-and-help","type":"strike-rewrite","hook":"\"An equal home is a fashionable idea that doesn't survive a real Indian joint family.\"","myth":{"un":"An equal home is a fashionable idea that doesn't survive a real Indian joint family.","re":"Couples build fairer homes inside joint families every day, with clear owned domains and quiet check-ins.","why":"Equality adapts to in-laws and 'log kya kahenge'; it doesn't need a Western nuclear setup."},"relearn":"An equal home survives a joint family through clear owned domains and quiet check-ins.","persona":"any","source":"works in a joint family"},
  {"id":"ep-1308","cat":"tools-and-help","type":"role-play","persona":"any","source":"validate, don't shame","hook":"Alka's exhausted, but her husband 'helps out,' so she doesn't think she has the right to say anything.","setup":"She confides in you over the phone.","steps":[{"prompt":"Alka says: \"I feel bad even bringing this up.\"","options":[{"text":"\"That's the mental load. Wanting it shared is fairness.\"","then":"\"Fairness,\" Alka repeats. \"I hadn't thought of it that way.\"","best":true},{"text":"\"You should honestly just be grateful he helps at all.\"","then":"Alka goes quiet, and the guilt settles in a little deeper."},{"text":"\"Everyone feels tired sometimes. It's normal.\"","then":"She nods, but the specific unfairness stays unnamed."},{"text":"\"Maybe you're just more sensitive to it.\"","then":"Alka starts wondering if the problem is actually her."}],"why":"Naming it as fairness, not ingratitude, is what lifts the guilt."},{"prompt":"Alka asks: \"Am I being unfair to him for wanting more than what he already does?\"","options":[{"text":"\"No, wanting it shared equally isn't unfair to him.\"","then":"\"Okay,\" she says, sitting a little straighter. \"That helps.\"","best":true},{"text":"\"A little, maybe, since he tries hard.\"","then":"Alka's shoulders drop again, back to doubting herself."},{"text":"\"Compare it to your friends' husbands first, maybe.\"","then":"She starts measuring her marriage against others instead of naming her own load."},{"text":"\"Just appreciate what he does do.\"","then":"Alka nods, but the exhaustion is still there, unnamed."}],"why":"Reassuring her that wanting equality isn't unfair frees her from the guilt."},{"prompt":"Alka asks: \"So how do I even say this without sounding ungrateful?\"","options":[{"text":"\"Name what you carry, calmly, not as a complaint.\"","then":"\"I can try that,\" Alka says, sounding steadier already.","best":true},{"text":"\"Just say thank you first, then bring it up.\"","then":"Alka softens the ask so much it barely lands."},{"text":"\"Wait for the right moment to mention it.\"","then":"The right moment keeps not arriving."},{"text":"\"Maybe just let it go for now.\"","then":"Alka sighs, and the exhaustion stays exactly where it was."}],"why":"A calm, specific naming, not gratitude first, is what actually gets heard."}],"relearn":"Name the mental load for a friend and frame wanting it shared as fairness, not ingratitude."},
  {"id":"ep-1309","cat":"tools-and-help","type":"role-play","persona":"Razia","source":"open the safety door","hook":"Neha mentions, almost in passing, that her husband tracks her phone and controls the money.","setup":"You sense there's more she isn't saying.","steps":[{"prompt":"Neha says: \"I guess every marriage has its adjustments.\"","options":[{"text":"\"That sounds like control. That's abuse, not just an adjustment.\"","then":"Neha goes still. \"I've never heard anyone call it that.\"","best":true},{"text":"\"True, every marriage does need some give.\"","then":"Neha nods, and the moment closes back over."},{"text":"\"That sounds really bad. Honestly, you need to leave.\"","then":"Neha pulls back. \"It's not that simple. Please don't push.\""},{"text":"\"Have you tried talking to him about it?\"","then":"Neha shrugs. \"He says I'm imagining things.\""}],"why":"Naming it as control, without an ultimatum, opens the door without pushing her."},{"prompt":"A little later, Neha asks: \"Do you think this is actually my fault somehow?\"","options":[{"text":"\"No. None of this is your fault.\"","then":"Neha's eyes fill up. \"I needed to hear that.\"","best":true},{"text":"\"Maybe if you'd handled money differently.\"","then":"Neha shrinks a little, taking on more blame."},{"text":"\"It takes two to make a marriage work, right?\"","then":"Neha nods slowly, unsure who that leaves responsible."},{"text":"\"Faults aside, what matters is fixing it.\"","then":"Neha looks unsure what 'fixing it' would even mean here."}],"why":"Saying plainly it's not her fault is what a friend in this position needs to hear first."},{"prompt":"Neha asks: \"What would I even do, if I wanted help?\"","options":[{"text":"\"There's help if you ever want it, at your pace.\"","then":"\"At my pace,\" she repeats. You add: \"Women Helpline 181, women-in-distress 1091, emergency 112.\"","best":true},{"text":"\"You should call someone about it today.\"","then":"Neha freezes, not ready to move that fast."},{"text":"\"I'll handle it. Just tell me what's going on.\"","then":"Neha looks alarmed. \"Please don't do anything yet.\""},{"text":"\"Maybe it'll get better on its own.\"","then":"Neha nods, but nothing about the pattern actually changes."}],"why":"Naming help exists, without forcing her pace, keeps the door open safely."},{"prompt":"A month later, Neha brings it up herself: \"I keep thinking about what you said.\"","options":[{"text":"\"I'm here whenever you're ready, no pressure.\"","then":"Neha exhales. \"That actually means a lot.\"","best":true},{"text":"\"You really should do something soon.\"","then":"Neha tenses. \"I know. I just... not yet.\""},{"text":"\"Have you thought more about leaving?\"","then":"Neha looks overwhelmed by the question."},{"text":"\"Let's not talk about it if it's stressful.\"","then":"Neha nods, and the door quietly starts to close."}],"why":"Staying steady and unpressured is what keeps the door open at her pace."}],"relearn":"When a friend describes control over money or movement, name it as abuse, say it's not her fault, and open the door to help."},
  {"id":"ep-1310","cat":"tools-and-help","type":"role-play","persona":"Karthik","source":"what he gains","hook":"Your brother Vishal is quiet after the chores topic came up at lunch.","setup":"You're driving him home after a family lunch.","steps":[{"prompt":"Vishal says: \"So basically I just end up doing more work, no?\"","options":[{"text":"\"No, you gain a real partner and a calmer home.\"","then":"Vishal glances over. \"A calmer home? Go on.\"","best":true},{"text":"\"Yeah, kind of, but it's the right thing to do.\"","then":"Vishal sighs. \"Great, so it's just a sacrifice then.\""},{"text":"\"It evens out eventually. Don't worry.\"","then":"Vishal shrugs, unconvinced it's worth the effort now."},{"text":"\"Depends how you look at it, I guess.\"","then":"Vishal looks even less sure than before."}],"why":"Naming the real gain, not just fairness, actually speaks to his doubt."},{"prompt":"Vishal asks: \"What do I actually get out of it though?\"","options":[{"text":"\"A partner who trusts you, not one who resents you.\"","then":"Vishal goes quiet, thinking that one over.","best":true},{"text":"\"You get to feel pretty good about doing your part.\"","then":"\"Sure,\" he says, unmoved."},{"text":"\"Society expects it now, honestly.\"","then":"Vishal rolls his eyes. \"That's not exactly inspiring.\""},{"text":"\"You avoid getting in trouble at home.\"","then":"Vishal laughs. \"So it's just about avoiding a fight?\""}],"why":"Naming trust instead of resentment shows him a gain worth wanting."},{"prompt":"Vishal asks: \"Has it actually worked out that way for you?\"","options":[{"text":"\"Yes, honestly, my home feels lighter now.\"","then":"Vishal looks surprised. \"Lighter? I didn't expect that word.\"","best":true},{"text":"\"It's still a work in progress, mostly.\"","then":"Vishal nods, sounding less convinced it's worth trying."},{"text":"\"I just do what I'm told, mostly.\"","then":"Vishal frowns. \"That doesn't sound like gaining anything.\""},{"text":"\"I don't really think about it that way.\"","then":"Vishal looks unconvinced there's a real answer here."}],"why":"A real, honest example is more convincing to him than any argument."}],"relearn":"Reframe an equal home for a doubting man as a gain: a real partner and deeper connection, not a loss."},
  {"id":"ep-1311","cat":"tools-and-help","type":"role-play","persona":"any","source":"warm proposal","hook":"You've been meaning to talk to Yusuf about how you're sharing things at home.","setup":"You bring it up over chai one evening.","steps":[{"prompt":"Yusuf asks: \"What's this about? Is something wrong?\"","options":[{"text":"\"Can we check in monthly on how we're sharing things, both ways?\"","then":"Yusuf relaxes. \"Both ways, I like that. Sure.\"","best":true},{"text":"\"We need to sit down and talk about everything you're not doing.\"","then":"Yusuf stiffens. \"That feels like an ambush.\""},{"text":"\"Nothing, forget I said anything.\"","then":"Yusuf doesn't let it go. \"No, tell me. What's on your mind?\""},{"text":"\"Just generally checking we're doing okay.\"","then":"Yusuf nods vaguely, unsure what's actually being proposed."}],"why":"Framing it as mutual and regular, not a list of complaints, invites him in."},{"prompt":"A few days later, Yusuf asks: \"How would we even talk about how we share things? What should it look like?\"","options":[{"text":"\"Monthly, on what felt fair and what felt like too much.\"","then":"\"Okay,\" he says. \"That sounds like something I could do.\"","best":true},{"text":"\"Mostly just whatever's bothering me that particular month.\"","then":"Yusuf braces for a monthly list of complaints."},{"text":"\"We'll figure it out when we get there.\"","then":"The plan stays vague, but you land on trying it that weekend anyway."},{"text":"\"Whatever you think needs discussing.\"","then":"Yusuf looks unsure it's actually meant to include him."}],"why":"Naming that it covers both sides is what keeps the check-in mutual, not one-sided."},{"prompt":"At the check-in, Yusuf asks: \"So, how do you want to start?\"","options":[{"text":"\"Something that felt unfair, and something I appreciated.\"","then":"Yusuf nods. \"That feels fair. My turn next.\"","best":true},{"text":"\"Mostly things you could be doing better.\"","then":"Yusuf's face falls, already dreading next month."},{"text":"\"I'm not totally sure. Let's just see how it goes tonight.\"","then":"The chat drifts without landing on anything real."},{"text":"\"I saved up a whole list, actually.\"","then":"Yusuf looks overwhelmed by how much there is."}],"why":"Naming something appreciated too, not just complaints, keeps the check-in balanced."}],"relearn":"Propose a check-in as a warm, mutual habit, not a list of the other person's failings."},
  {"id":"ep-1312","cat":"tools-and-help","type":"role-play","persona":"Karthik","source":"build it together","hook":"Pooja looks close to burnout, and you want to actually help her carry it.","setup":"You sit down with her one quiet evening.","steps":[{"prompt":"Pooja says: \"I just can't keep everything straight in my head anymore.\"","options":[{"text":"\"Let's write down everything you carry, visible and invisible.\"","then":"Pooja looks relieved. \"Someone finally wants to see it all.\"","best":true},{"text":"\"You should honestly just try to be more organised about it.\"","then":"Pooja's face falls. \"I am organised. That's not the problem.\""},{"text":"\"Maybe use an app to track everything.\"","then":"She nods, but downloading an app doesn't share the actual load."},{"text":"\"It'll calm down once things settle.\"","then":"Pooja sighs, unsure when 'settled' will ever arrive."}],"why":"Offering to build the list together is a real tool, not advice aimed at her alone."},{"prompt":"A few days later, you sit down to write it all out together. Pooja says, surprised: \"I didn't realise it was this long.\"","options":[{"text":"\"Keep going. I want to see all of it.\"","then":"The list fills two pages, most of it invisible work.","best":true},{"text":"\"That's probably most of it by now, right?\"","then":"She stops early, unsure if the rest even counts."},{"text":"\"Wow, that's a lot. Are you sure?\"","then":"Pooja second-guesses herself and starts trimming the list."},{"text":"\"Let's finish this another day.\"","then":"The list stays half-done, and so does the picture of her load."}],"why":"Letting the list run its full length is what makes the invisible work visible."},{"prompt":"Pooja asks: \"So what happens with this list now?\"","options":[{"text":"\"I'll take real ownership of half of it, starting today.\"","then":"\"Today,\" she repeats, like she needs to hear it again.","best":true},{"text":"\"I'll help out with whatever's on there.\"","then":"\"Help,\" she echoes quietly, disappointed."},{"text":"\"We'll figure that out over time.\"","then":"The list sits on the fridge, admired but untouched."},{"text":"\"You keep the list, and just tell me whatever's needed.\"","then":"The list becomes one more thing for her to manage."}],"why":"Claiming real ownership, not just help, is what turns the list into an actual share."}],"relearn":"Offer to build a shared load inventory together rather than handing your partner self-improvement advice."},
  {"id":"ep-1313","cat":"tools-and-help","type":"role-play","persona":"any","source":"holding the line","hook":"Your aunt Nirmala teases that you and your partner overthink the whole fairness thing.","setup":"She brings it up again at a family dinner.","steps":[{"prompt":"Nirmala says: \"All this sharing talk, it's a bit much, no?\"","options":[{"text":"\"It's working for us. Our home's a lot warmer now.\"","then":"Nirmala pauses. \"Warmer how? Tell me more.\"","best":true},{"text":"\"You're right. We're probably overthinking it.\"","then":"Nirmala nods, satisfied, and the topic quietly closes."},{"text":"\"It's really none of your business, honestly.\"","then":"Nirmala looks offended, and dinner turns tense."},{"text":"\"Maybe, but we're happy, so let's move on.\"","then":"Nirmala shrugs, unconvinced but done arguing."}],"why":"Naming the actual result, warmth, holds the line without dismissing her."},{"prompt":"A little later, over dessert, Nirmala circles back: \"But isn't all this talking and splitting exhausting?\"","options":[{"text":"\"Less exhausting than resentment building quietly.\"","then":"\"Hm,\" Nirmala says, chewing on that thought.","best":true},{"text":"\"A little, yes, but it's worth it I guess.\"","then":"Nirmala nods like that confirms her doubts."},{"text":"\"You wouldn't understand. It's a modern thing.\"","then":"Nirmala bristles at being dismissed."},{"text":"\"We're figuring it out as we go, mostly.\"","then":"Nirmala looks unconvinced there's a real plan."}],"why":"Naming what the old way actually costs makes the new way sound worth it."},{"prompt":"Later, Nirmala says: \"Your uncle and I never needed any of this.\"","options":[{"text":"\"Whatever worked for you, this works for us.\"","then":"Nirmala softens slightly. \"Fair enough, I suppose.\"","best":true},{"text":"\"Times were different back then. That's all.\"","then":"Nirmala looks a little stung by the comparison."},{"text":"\"Maybe you needed it more than you think.\"","then":"Nirmala stiffens, feeling judged about her own marriage."},{"text":"\"Sure, whatever you say, aunty.\"","then":"Nirmala isn't sure if you actually mean that."}],"why":"Respecting her marriage while holding your own keeps the peace without backing down."},{"prompt":"At the next family event, Nirmala says to the table: \"They're still at it with all that sharing business.\"","options":[{"text":"\"Still at it, and still working well for us.\"","then":"The others nod along, and Nirmala's teasing softens a little.","best":true},{"text":"\"Please, not in front of everyone, aunty.\"","then":"Nirmala looks a bit hurt, and repeats it anyway later."},{"text":"\"Can we not do this every single time?\"","then":"The comment lands anyway, and the table feels awkward."},{"text":"\"Whatever you say, aunty.\"","then":"The comment stands unchallenged, and nothing shifts."}],"why":"The same steady, warm line each time is what makes the fairness work actually hold."}],"relearn":"Hold the line kindly when relatives dismiss your fairness work. Name that it's making your home better."},
  {"id":"ep-1314","cat":"tools-and-help","type":"role-play","persona":"any","source":"reset with a tool","hook":"You've noticed Divya's gone quiet and short with you the last few days.","setup":"Tonight you finally ask what's wrong.","steps":[{"prompt":"Divya says: \"Honestly, I'm just tired of carrying everything again.\"","options":[{"text":"\"I let it slide back onto you. I'm sorry.\"","then":"Divya's shoulders drop. \"Thank you for saying that.\"","best":true},{"text":"\"But I do loads around here already.\"","then":"Divya's jaw tightens. \"That's not what I said, though.\""},{"text":"\"I didn't even notice, honestly.\"","then":"Divya looks more tired hearing that than before."},{"text":"\"I'll try to do better. I promise.\"","then":"Divya nods, but the promise feels vague and familiar."}],"why":"Owning it plainly, without defending yourself, is what actually lands as an apology."},{"prompt":"Divya asks: \"So what actually changes this time?\"","options":[{"text":"\"Let's redo our split this week, and check in monthly.\"","then":"\"Okay,\" she says, sounding cautiously hopeful.","best":true},{"text":"\"I'll just try much harder to remember this time, promise.\"","then":"Divya's heard that promise before, and it shows on her face."},{"text":"\"Whatever you think is fair, honestly.\"","then":"Divya sighs. \"I don't want to be the one deciding again.\""},{"text":"\"Let's not overthink it. We'll be fine.\"","then":"Divya looks unconvinced anything will actually change."}],"why":"A concrete redo plus a standing check-in is a plan, not just a promise."},{"prompt":"A month later, Divya brings it up again: \"How do you think this month's gone?\"","options":[{"text":"\"Let's look at it honestly, starting with my part.\"","then":"\"Thanks for starting with yourself,\" she says, softening.","best":true},{"text":"\"Pretty good, honestly. Don't you think?\"","then":"Divya raises an eyebrow. \"Not exactly, no.\""},{"text":"\"About the same as usual, I'd say.\"","then":"Divya sighs. \"That's kind of the problem.\""},{"text":"\"Let's talk about it another time.\"","then":"The conversation slips again, and the pattern repeats."}],"why":"Starting with your own part, honestly, is what keeps the check-in working."}],"relearn":"After a slip, own it and propose redoing the split plus a check-in, rather than defending your contribution."},
  {"id":"ep-1315","cat":"tools-and-help","type":"spot","hook":"Spot the two lines that quietly dump the load back on her (the red flags).","scene":[{"id":"a","text":"\"Let's inventory everything we both carry\"","trick":false},{"id":"b","text":"\"You just need to communicate better\"","trick":true},{"id":"c","text":"\"I'll own the bills end-to-end\"","trick":false},{"id":"d","text":"\"Make me a list and I'll do it\"","trick":true},{"id":"e","text":"\"You shouldn't have to remind me\"","trick":false}],"why":"'Communicate better' and 'make me a list' leave her managing; an inventory, owning a domain and removing reminders share it.","relearn":"'Communicate better' and 'make me a list' dump the load back on her; real tools share it.","persona":"any","source":"who's left managing"},
  {"id":"ep-1316","cat":"tools-and-help","type":"spot","hook":"Spot the two lines that frame an equal home as a fight (the red flags).","scene":[{"id":"a","text":"\"This makes our home better for both of us\"","trick":false},{"id":"b","text":"\"It's just you winning and me losing\"","trick":true},{"id":"c","text":"\"You gain a real partner out of this\"","trick":false},{"id":"d","text":"\"This whole thing is a battle of the sexes\"","trick":true},{"id":"e","text":"\"Less resentment is good for us both\"","trick":false}],"why":"'You winning, me losing' and 'battle of the sexes' frame fairness as a fight; an equal home is a gain for both.","relearn":"'You winning, me losing' and 'battle of the sexes' are red flags; an equal home gains everyone.","persona":"Karthik","source":"gain, not a fight"},
  {"id":"ep-1317","cat":"tools-and-help","type":"spot","hook":"Spot the two lines that shut a struggling friend down (the red flags).","scene":[{"id":"a","text":"\"That's the mental load, and it's real\"","trick":false},{"id":"b","text":"\"At least he helps, be grateful\"","trick":true},{"id":"c","text":"\"You deserve owning, not just helping\"","trick":false},{"id":"d","text":"\"That's just how marriage is, adjust\"","trick":true},{"id":"e","text":"\"Want to map it out together?\"","trick":false}],"why":"'Be grateful' and 'that's just marriage' silence her; naming the load and offering to help open it up.","relearn":"'Be grateful' and 'that's just marriage' shut a friend down; name the load and offer to help instead.","persona":"any","source":"don't silence her"},
  {"id":"ep-1318","cat":"tools-and-help","type":"spot","hook":"Spot the two signs this has tipped from unfairness into control (the red flags).","scene":[{"id":"a","text":"He does chores only when asked","trick":false},{"id":"b","text":"He blocks her from seeing her family","trick":true},{"id":"c","text":"Her career flexes by default","trick":false},{"id":"d","text":"He controls all access to money","trick":true},{"id":"e","text":"The mental load sits all on her","trick":false}],"why":"Blocking her family and controlling all money is coercive control, that's abuse and needs help; the rest is unfairness to renegotiate.","relearn":"Blocking contact and controlling money are control, not just unfairness, that's abuse, get help.","persona":"any","source":"unfair vs control"},
  {"id":"ep-1319","cat":"tools-and-help","type":"spot","hook":"Spot the two 'tools' that are really fake fixes aimed only at her (the red flags).","scene":[{"id":"a","text":"A shared load inventory","trick":false},{"id":"b","text":"\"Just do some self-care, you'll cope\"","trick":true},{"id":"c","text":"An owned-domains split","trick":false},{"id":"d","text":"\"A better planner app for her\"","trick":true},{"id":"e","text":"A no-blame monthly check-in","trick":false}],"why":"'Self-care' and 'a planner for her' leave the whole load on one person; real tools, inventory, owned split, check-in, share it.","relearn":"'Self-care' and 'a planner for her' are fake fixes that keep the load on her; real tools share it.","persona":"Pooja","source":"fake fixes"},
  {"id":"ep-1320","cat":"tools-and-help","type":"spot","hook":"Spot the two lines that are still 'helping', not owning (the red flags).","scene":[{"id":"a","text":"\"I'll run the whole school admin\"","trick":false},{"id":"b","text":"\"Just tell me what you need doing\"","trick":true},{"id":"c","text":"\"You won't have to remind me again\"","trick":false},{"id":"d","text":"\"I helped a lot this weekend, right?\"","trick":true},{"id":"e","text":"\"I'll track the bills so you don't\"","trick":false}],"why":"'Tell me what to do' and 'I helped, right?' keep her managing; running a domain and removing reminders is owning.","relearn":"'Just tell me' and 'I helped, right?' are still helping; running a domain unprompted is owning.","persona":"Karthik","source":"helping vs owning"},
  {"id":"ep-1321","cat":"tools-and-help","type":"spot","hook":"Spot the two routing mistakes that send a problem to the wrong place (the red flags).","scene":[{"id":"a","text":"Drifted split → renegotiate it","trick":false},{"id":"b","text":"He controls her money → just talk it out","trick":true},{"id":"c","text":"Circular fights → a counsellor","trick":false},{"id":"d","text":"He tracks her every move → a chore chart","trick":true},{"id":"e","text":"He can't see the load → a shared inventory","trick":false}],"why":"Controlling money or tracking movement is abuse, it needs help, not a chat or a chore chart; the others are routed right.","relearn":"Control over money or movement must route to help, never to 'just talk' or a chore chart.","persona":"Saxena","source":"routing mistakes"},
  {"id":"ep-1322","cat":"tools-and-help","type":"branch","persona":"Karthik","source":"start with seeing","hook":"Pooja seems exhausted most evenings, and you're not sure where the load is actually coming from.","steps":[{"prompt":"One more evening, she drops onto the sofa, drained. What do you do?","options":[{"text":"Sit with her and list everything she carries","then":"You're startled by how long the list gets, most of it invisible.","best":true},{"text":"Jump straight to splitting the visible chores 50/50","then":"The chore list balances, but she still seems just as tired."},{"text":"Ask her to just tell you when she needs a break","then":"She rarely asks, and the exhaustion quietly continues."},{"text":"Assume it's just a busy season that will pass","then":"The busy season never really ends."}],"why":"Seeing the whole load first, including what's invisible, is where a real split has to start."},{"prompt":"Pooja mentions she keeps forgetting to book the car's service and re-order supplies. What do you do?","options":[{"text":"Take real ownership of both of those invisible items","then":"You start tracking both yourself, so she can stop keeping them in her head.","best":true},{"text":"Offer to help with them whenever she happens to flag one","then":"She still has to notice and ask each time."},{"text":"Suggest she just let some things slide","then":"She tries, but the appointments still need remembering by someone."},{"text":"Point out you already do the heavier chores","then":"Pooja looks deflated. \"This isn't about which is heavier.\""}],"why":"Owning invisible items outright, not waiting to be asked, is what actually lightens the load."},{"prompt":"A few weeks later, Pooja mentions yet another thing she was tracking alone. What do you do?","options":[{"text":"Go through the invisible load together and take on what's still hers","then":"You find two items still sitting with her and take them on.","best":true},{"text":"Tell her to just remind you if something slips","then":"The reminding itself becomes new invisible work for her."},{"text":"Assume it's working well enough as it is","then":"The slipped items quietly stay hers from then on."},{"text":"Wait for her to bring it up if it's a problem","then":"She doesn't bring it up, and the drift goes unnoticed."}],"why":"Checking the load together catches what is still hers before it settles into the old pattern."},{"prompt":"A relative asks how you two manage the housework and everything behind it. What do you say?","options":[{"text":"Say the invisible work has to be seen and shared too","then":"The relative looks intrigued and asks how that actually works.","best":true},{"text":"Say Pooja's just naturally more organised than you are","then":"Pooja glances over, and the credit for the system quietly stays with her."},{"text":"Say you both just try harder these days","then":"The relative nods, with no real sense of what actually changed."},{"text":"Say you leave most of it to her judgement","then":"The relative assumes she's still running everything alone."}],"why":"Saying the invisible work must be seen and shared explains what a fair home looks like."}],"debrief":"See the whole load with an inventory first; you can't split fairly what's invisible.","relearn":"Start with a shared load inventory; you can't fairly split what you haven't made visible."},
  {"id":"ep-1323","cat":"tools-and-help","type":"branch","persona":"Razia","source":"route coercion to help","hook":"Shalini tells you her husband controls where she goes and the household money.","steps":[{"prompt":"She tells you this quietly, looking anxious. What do you do?","options":[{"text":"Say this is abuse. It's never her fault","then":"Shalini's eyes well up. \"I didn't know what to call it.\"","best":true},{"text":"Tell her she needs to leave him immediately","then":"Shalini pulls back. \"It's not that simple,\" she says quietly."},{"text":"Say every marriage has its ups and downs","then":"Shalini nods slowly, and the moment closes over."},{"text":"Ask her exactly how bad it's gotten","then":"She tenses up, unsure how much detail is safe to share."}],"why":"Naming it as control, gently, is what a friend actually needs to hear first."},{"prompt":"Later that evening, Shalini asks: \"Do you think I'm overreacting?\"","options":[{"text":"Say no. This is real, and it's not her fault","then":"She exhales. \"I keep telling myself it's normal.\"","best":true},{"text":"Say maybe things will improve with time","then":"Shalini nods, but her shoulders stay tense."},{"text":"Say she should have seen this coming","then":"Shalini flinches, and pulls further into herself."},{"text":"Say you'd have left by now","then":"She goes quiet, feeling judged instead of heard."}],"why":"Believing her plainly, without judgment, is what actually helps."},{"prompt":"Shalini says she doesn't know what to do next. What do you do?","options":[{"text":"Say help exists, and offer to look into it together","then":"You share Women Helpline 181, women-in-distress 1091 and emergency 112. \"Together?\" she asks. \"I'd like that.\"","best":true},{"text":"Tell her clearly and firmly what she should do next","then":"Shalini nods along, but doesn't say what she actually wants."},{"text":"Say it's not your business to get involved","then":"She looks even more alone with the question."},{"text":"Offer to talk to her husband yourself","then":"Shalini goes pale. \"Please don't. He could make things harder for me.\""}],"why":"Offering to look into help together respects her pace, without taking over."},{"prompt":"A week later, Shalini hasn't brought it up again. What do you do?","options":[{"text":"Check in gently, and remind her help is still there","then":"She softens. \"I've been thinking about it, actually.\"","best":true},{"text":"Leave it alone, since she hasn't raised it herself again","then":"Weeks pass, and the silence starts to feel like distance."},{"text":"Push her to make a decision soon","then":"Shalini pulls back, feeling cornered instead of supported."},{"text":"Tell her family what's happening","then":"Shalini looks alarmed. \"Please don't. That could make it worse.\""}],"why":"A gentle check-in, at her pace, keeps the door open without pushing her."}],"debrief":"Control over money or movement is abuse, not just unfairness. Name it, say it's not her fault, point to help.","relearn":"Name control over money or movement as abuse, say it's not her fault, and point her to help, not an ultimatum."},
  {"id":"ep-1323b","cat":"tools-and-help","type":"branch","persona":"any","source":"the check-in habit","hook":"You and Suresh have agreed a fair split twice now, and it keeps quietly drifting back.","steps":[{"prompt":"You notice you're back to doing most of the evening routine again. What do you do?","options":[{"text":"Suggest a standing monthly check-in to catch drift early","then":"Suresh agrees, and you pick the first Sunday of each month.","best":true},{"text":"Just try much harder to remember the split between yourselves","then":"You both mean well, but the same pattern creeps back within weeks."},{"text":"Say nothing and hope it balances out again","then":"It doesn't balance out. The evenings stay mostly yours."},{"text":"Redo the whole split from scratch again","then":"The new split looks fairer on paper, but nothing catches the next drift."}],"why":"A standing check-in catches drift as it happens, instead of relying on memory."},{"prompt":"A month later, the same pattern is still there. What do you do?","options":[{"text":"Go through each area together and flag what's slipped","then":"You catch two chores that had quietly become yours again, and agree to make this regular.","best":true},{"text":"Have a general chat about how things feel","then":"It feels good, but nothing specific actually gets fixed."},{"text":"Decide it's not worth making a fuss about","then":"The pattern quietly repeats again next month."},{"text":"Only bring it up if something's really bothering you","then":"Small drifts go unnoticed until they build into a bigger one."}],"why":"Going through it area by area catches small drift before it becomes a pattern."},{"prompt":"Three months on, you and Suresh take stock of how things have actually gone. What do you do?","options":[{"text":"Make a monthly check-in a permanent habit","then":"It becomes a normal, unremarkable part of your month.","best":true},{"text":"Skip formal check-ins now that things feel steady lately","then":"Within weeks, the old drift starts creeping back in."},{"text":"Only check in when one of you remembers to raise it","then":"Some months it happens. Some months it quietly doesn't."},{"text":"Check in once a year instead","then":"A year is long enough for the split to drift completely."}],"why":"A standing monthly check-in, not an occasional one, is what actually holds the split."}],"debrief":"Fairness drifts to old defaults unless a regular check-in catches it; the habit is the tool.","relearn":"Catch drift with a standing monthly check-in; the habit is the tool, not trying harder alone."},
  {"id":"ep-1324","cat":"tools-and-help","type":"branch","persona":"Pooja","source":"let them own it","hook":"You handed Karthik the laundry to own, but you keep quietly redoing parts of it.","steps":[{"prompt":"You notice the towels are folded differently than you'd do it. What do you do?","options":[{"text":"Leave it. His way is still a valid way","then":"The towels stay as he folded them, and you let it go.","best":true},{"text":"Refold them quickly while he's not looking","then":"The towels look how you like, but the load has quietly moved back to you."},{"text":"Point out the better way to fold them","then":"Karthik shrugs and does it your way from then on, a little less his."},{"text":"Take over this load yourself. It's easier","then":"You do this load yourself. Karthik does the next one, but hesitates over it."}],"why":"Letting his method stand is what actually makes the domain his, not yours to correct."},{"prompt":"A colour runs in the wash, and one of your shirts is ruined. What do you do?","options":[{"text":"Let it go, and let him learn the domain his way","then":"Karthik apologises, and starts sorting colours on his own after that.","best":true},{"text":"Write him a note on how to sort colours","then":"He follows the note exactly, but keeps checking with you each time."},{"text":"Take over the sorting from now on","then":"From then on you sort every batch, and Karthik has less of it to own."},{"text":"Bring it up at dinner in front of everyone","then":"Karthik feels embarrassed instead of trusted to keep learning."}],"why":"Letting a mistake be his to learn from is part of actually owning the domain."},{"prompt":"A month later, the laundry runs smoothly, though not exactly your old system. What do you do?","options":[{"text":"Notice it's working and say nothing more","then":"The laundry stays his, running quietly in the background.","best":true},{"text":"Tweak a few things back to your old way","then":"The system slides slowly back toward how you used to run it."},{"text":"Ask him to switch to your original system","then":"Karthik feels like his version was never good enough."},{"text":"Check in on it every few days just in case","then":"The checking itself becomes a new kind of managing."}],"why":"Leaving a working system alone, even if different, is what keeps it truly his."}],"debrief":"Owning means your partner runs the domain their way; quietly redoing it pulls the load back.","relearn":"Let your partner own a domain their way; redoing it silently pulls the load back onto you."},
  {"id":"ep-1325","cat":"tools-and-help","type":"branch","persona":"Saxena","source":"when to see a counsellor","hook":"Every time you and Sameer try to talk about housework, it circles into the same fight.","steps":[{"prompt":"The conversation starts again, and you can already feel where it's headed. What do you do?","options":[{"text":"Suggest bringing in a couples counsellor to help","then":"Sameer looks relieved. \"Yes. We clearly can't do this alone.\"","best":true},{"text":"Decide to just stop bringing it up at all","then":"The fight stops, but the resentment quietly stays underneath."},{"text":"Push through the same argument one more time","then":"It ends exactly like the last five times, nowhere."},{"text":"Write him a long message explaining your side","then":"Sameer reads it defensively, and the spiral starts again by text."}],"why":"A counsellor breaks a spiral neither of you can break alone, without blaming either of you."},{"prompt":"A friend recommends Dr. Saxena, a couples counsellor with an opening this week. What do you do?","options":[{"text":"Book the session and both agree to actually go","then":"You sit across from Dr. Saxena together, a little nervous but hopeful.","best":true},{"text":"Go alone first, just to see if it's even worth it","then":"Sameer feels a little left out of a decision that affects you both, but joins you for the next one."},{"text":"Wait until things feel calmer to book it","then":"The calm never quite arrives, but Sameer ends up booking it himself a few weeks later."},{"text":"Ask her to just email some tips instead","then":"The tips don't help, so you end up booking a real session after all."}],"why":"Going together lets you both shape the work from the start."},{"prompt":"In the session, Dr. Saxena asks each of you to name what the fight is really about. What do you do?","options":[{"text":"Answer honestly, even the uncomfortable part","then":"Sameer looks surprised. \"Oh. I didn't know that's what it was.\"","best":true},{"text":"Give the safe, polite version of the answer","then":"The session stays surface level, and nothing much shifts."},{"text":"Let Sameer answer first and just agree","then":"Dr. Saxena gently asks what you actually think, separately."},{"text":"Say you're not sure. It's hard to explain","then":"The session moves on without really landing anywhere."}],"why":"Naming the real thing honestly is what a counsellor actually needs to work with."},{"prompt":"A few sessions in, you start using her language, like owning instead of helping, at home. What do you do?","options":[{"text":"Keep using it consistently, even outside sessions","then":"The new words start replacing the old fight, one evening at a time.","best":true},{"text":"Use it only when things start to tense up","then":"The words feel like a tool for fights, not for everyday life."},{"text":"Let it fade once the sessions end","then":"Within months, the same circular fight starts up again."},{"text":"Expect Sameer to bring it up first from now on","then":"The new habit quietly becomes one more thing left unsaid."}],"why":"Carrying the shared language home is what makes the counselling actually stick."}],"debrief":"A couple who respect each other but keep spiralling can route to a counsellor.","relearn":"A respectful couple stuck in circular fights can route to a counsellor to break the spiral."},
  {"id":"ep-1326","cat":"tools-and-help","type":"branch","persona":"Karthik","source":"helping into owning","hook":"Karthik has taken on more chores lately, vacuuming and doing the dishes today.","steps":[{"prompt":"Karthik grins and asks how much he helped today. What do you do?","options":[{"text":"Warmly invite him to own a whole domain instead","then":"Karthik pauses, intrigued. \"Own it, like all of it?\"","best":true},{"text":"Thank him warmly and keep managing everything yourself","then":"He beams, pleased, and waits for the next thing you'll ask him."},{"text":"Point out helping isn't the same as sharing","then":"Karthik's smile fades. \"I thought I was doing something good.\""},{"text":"Say nothing and just keep going with your evening","then":"He looks a little deflated, unsure if it landed well."}],"why":"A warm invite to own a domain builds on his effort instead of shaming it."},{"prompt":"A few days later, Karthik asks what taking on more at home would really look like. What do you say?","options":[{"text":"Explain it means running it end to end, unasked","then":"\"So I notice things myself, not wait to be told,\" he says slowly.","best":true},{"text":"Say it means doing more chores each week","then":"He nods, thinking it's just about volume, not about noticing."},{"text":"Say you'll explain later when there's time","then":"The conversation trails off, and the idea stays vague."},{"text":"Hand him a written list of extra tasks","then":"He follows the list closely, still waiting to be told what's next."}],"why":"Naming the noticing and planning, not just more tasks, is what owning means."},{"prompt":"A few weeks later, Karthik is looking after the kitchen. What do you do?","options":[{"text":"Step back fully and let him run it his way","then":"Within weeks, he's restocking groceries before you even notice they're low.","best":true},{"text":"Keep an eye on it just to be safe","then":"Karthik feels watched, and never quite settles into it."},{"text":"Give him a checklist to follow each week","then":"He follows it exactly, and never has to notice anything himself."},{"text":"Praise every small thing he does in the kitchen","then":"The praise feels nice, but the noticing still isn't fully his."}],"why":"Stepping back completely is what turns a domain into something he genuinely owns."}],"debrief":"'See how much I helped?' is a chance to warmly reframe helping into owning a domain.","relearn":"Turn 'see how I helped?' into a warm invite to own a domain; no shame, real sharing."},
  {"id":"ep-1327","cat":"tools-and-help","type":"branch","persona":"any","source":"take turns flexing","hook":"You notice it's always your schedule that bends whenever Irfan's work gets busy.","steps":[{"prompt":"Irfan asks if you can handle the weekend errands again this week since he has a deadline. What do you do?","options":[{"text":"Agree, but raise that you want to take turns flexing","then":"Irfan pauses. \"You're right. It's always been you, hasn't it?\"","best":true},{"text":"Agree quietly, since it's simply easier this week","then":"You handle it, and the pattern continues unnoticed."},{"text":"Say no flatly and leave him to sort it out","then":"Irfan looks stressed and snaps, and the errands go undone."},{"text":"Agree, but ask him to owe you one","then":"Irfan agrees loosely, but 'owing one' is never actually cashed in."}],"why":"Naming the pattern while still helping opens the door to actually rebalancing it."},{"prompt":"A few weeks later, you have a big deadline of your own. What do you do?","options":[{"text":"Ask Irfan to flex for you this time","then":"\"Fair's fair,\" he says, and clears his evening for you.","best":true},{"text":"Try to manage both without asking for help","then":"You stay up late finishing everything alone."},{"text":"Quietly push your deadline instead","then":"You slip the deadline, and the old pattern holds a little longer."},{"text":"Hint that you're busy and hope he notices","then":"Irfan doesn't pick up on the hint, and nothing changes."}],"why":"Actually asking directly, instead of hoping he notices, is what makes taking turns real."},{"prompt":"A year in, you look back at whose work has flexed more often. What do you do?","options":[{"text":"Check the balance together and adjust if it's tilted","then":"You go through it honestly, and agree on what needs to shift.","best":true},{"text":"Assume it's probably balanced by now","then":"It turns out one of you flexed far more than the other."},{"text":"Let whoever asks first keep getting the flex each time","then":"The louder asker keeps winning, without either of you noticing."},{"text":"Stop tracking it. It feels unnecessary now","then":"The old default quietly starts creeping back in."}],"why":"Actually checking the balance, not assuming it, is what keeps taking turns fair over time."}],"debrief":"Whose career flexes shouldn't default to one person; take turns backing each other's work.","relearn":"Don't let one career always flex; agree to take turns backing each other's work."},
  {"id":"ep-1328","cat":"tools-and-help","type":"branch","persona":"any","source":"equip a friend","hook":"Tanvi looks exhausted and says she just can't keep up with everything at home.","steps":[{"prompt":"She starts listing everything she's juggling, overwhelmed. What do you do?","options":[{"text":"Name it as the mental load, real and exhausting","then":"Tanvi's shoulders drop. \"So it's not just me being bad at this.\"","best":true},{"text":"Let her vent and tell her she'll feel better","then":"She feels heard in the moment, but nothing about her days changes."},{"text":"Tell her she should just ask her husband for help","then":"Tanvi sighs. \"I do ask. He 'helps' when I remind him.\""},{"text":"Say every marriage feels like this sometimes","then":"Tanvi nods, but the exhaustion doesn't actually lift."}],"why":"Naming it as real, exhausting work is the first thing that actually lands."},{"prompt":"Tanvi asks what she's even supposed to do about it. What do you do?","options":[{"text":"Walk her through building a load inventory together","then":"You sit with her and list it all out, page after page.","best":true},{"text":"Suggest she try to organise her time better","then":"Tanvi feels like the problem is being handed back to her."},{"text":"Tell her to just push through this phase","then":"She nods, unconvinced it will ever actually end."},{"text":"Say you'll ask your own partner what worked for you","then":"The answer arrives later, but Tanvi's still stuck today."}],"why":"A concrete tool, not advice about her, is what actually equips her to act."},{"prompt":"A week later, Tanvi mentions she's still stuck in the same overwhelm. What do you do?","options":[{"text":"Suggest she map out everything and raise a fair split","then":"\"I could actually try that,\" Tanvi says, brightening a little.","best":true},{"text":"Say it sounds like a lot and change the subject","then":"Tanvi looks unsure what to do next."},{"text":"Tell her what you think she should demand","then":"She nods along, but it doesn't feel like her own plan."},{"text":"Say it's probably like this for everyone","then":"Tanvi's brief spark of hope quietly fades again."}],"why":"Mapping the load and raising a fair split is what makes it useful, not just visible."},{"prompt":"A month later, Tanvi says she still doesn't know how to bring any of this up with him. What do you do?","options":[{"text":"Offer to help her plan exactly what to say","then":"You practise the conversation together, and she looks steadier after.","best":true},{"text":"Tell her to just say it however feels natural","then":"Tanvi freezes when the moment comes, unsure where to start."},{"text":"Offer to talk to her husband yourself","then":"Tanvi looks uneasy. \"I'd rather do this one myself.\""},{"text":"Say she'll find the right moment eventually","then":"The right moment keeps not arriving, week after week."}],"why":"Helping her plan the words respects her pace while still moving her forward."}],"debrief":"Help a friend who feels alone by naming the load and showing her the routes.","relearn":"For a friend who feels alone, name the load as real and show her the routes that exist."},
  {"id":"ep-1350","type":"strike-rewrite","persona":"any","source":"transfer default","hook":"\"He got a transfer, so obviously she'll resign and follow.\"","myth":{"un":"He got a transfer, so obviously she resigns and follows.","re":"Whose career moves for a transfer is a fair joint decision, not an automatic default to hers.","why":"Both careers count equally; one isn't the obvious one to drop."},"relearn":"A transfer is a joint decision, not an automatic 'she follows him'.","cat":"two-careers"},
  {"id":"ep-1351","type":"strike-rewrite","persona":"any","source":"WFH default","hook":"\"One of us works from home for the maid and deliveries. That's the wife's job.\"","myth":{"un":"Whoever works from home to manage the maid and deliveries should be the wife.","re":"Who works from home to cover the house is a fair choice between two jobs, not gendered.","why":"Tying home logistics to her career quietly makes hers the one that bends."},"relearn":"Who takes the work-from-home role for the house is decided fairly, not by gender.","cat":"two-careers"},
  {"id":"ep-1352","type":"strike-rewrite","persona":"Pooja","source":"her leave first","hook":"\"When the kid's sick, she takes leave. Her work is more flexible anyway.\"","myth":{"un":"She always takes leave for a sick child; her work is more flexible.","re":"Sick-day leave should alternate between both jobs, not land on hers by habit.","why":"'Hers is flexible' often means she was simply assumed to absorb it."},"relearn":"Take turns taking leave for a sick child; don't default it to her job.","cat":"two-careers"},
  {"id":"ep-1353","type":"strike-rewrite","persona":"any","source":"side income myth","hook":"\"Her salary is just extra; the household really runs on his.\"","myth":{"un":"Her salary is just extra; the household really runs on his.","re":"Both incomes are real and the home runs on the partnership, not on his job alone.","why":"Calling hers 'extra' makes her career look optional when it isn't."},"relearn":"Both incomes are real; the household runs on the partnership, not his job alone.","cat":"two-careers"},
  {"id":"ep-1354","type":"strike-rewrite","persona":"Karthik","source":"breadwinner exemption","hook":"\"He's the main earner, so the home is mostly her department.\"","myth":{"un":"He's the main earner, so the home is mostly her department.","re":"Earning more doesn't hand the home to your partner; the load is shared regardless of pay.","why":"Income doesn't buy you out of running half the home."},"relearn":"Earning more doesn't make the home her department; the load stays shared.","cat":"two-careers"},
  {"id":"ep-1355","type":"strike-rewrite","persona":"any","source":"ambition gap","hook":"\"It's better if only one of you chases promotions, less stress at home.\"","myth":{"un":"It's better if only one of you chases promotions.","re":"Both partners can pursue ambitions; you take turns backing each other through busy stretches.","why":"Parking one person's growth isn't peace. It's one career quietly carrying the other."},"relearn":"Both can be ambitious; partners take turns backing each other, not one growing alone.","cat":"two-careers"},
  {"id":"ep-1356","type":"strike-rewrite","persona":"any","source":"degree wasted myth","hook":"\"She studied hard, but after marriage a job is optional for her.\"","myth":{"un":"After marriage, a job is optional for her even after all that study.","re":"Whether she works is her call and a joint plan, never 'optional' just because she married.","why":"Marriage doesn't downgrade one partner's career to a hobby."},"relearn":"Marriage doesn't make her career optional; it stays her choice and a joint plan.","cat":"two-careers"},
  {"id":"ep-1357","type":"strike-rewrite","persona":"any","source":"his hours sacred","hook":"\"His work calls are urgent; hers can always wait till the chores are done.\"","myth":{"un":"His work calls are urgent; hers can wait till chores are done.","re":"Both partners' work time is real; neither one's hours are the ones that always give way.","why":"Protecting only his focus time treats her job as the interruptible one."},"relearn":"Both partners' work hours are real; neither's is the one that always yields.","cat":"two-careers"},
  {"id":"ep-1358","type":"strike-rewrite","persona":"any","source":"relocation abroad","hook":"\"If he gets a posting abroad, of course she gives up her job to go.\"","myth":{"un":"If he's posted abroad, she gives up her job to go.","re":"A big move is weighed for both careers together; whose job pauses isn't fixed by gender.","why":"A posting for one shouldn't auto-erase the other's career."},"relearn":"A move abroad is weighed for both careers; whose job pauses is decided together.","cat":"two-careers"},
  {"id":"ep-1359","type":"strike-rewrite","persona":"Pooja","source":"unpaid career fuel","hook":"\"His career took off because she ran the whole house. That's a fair trade.\"","myth":{"un":"His career took off because she ran the house, a fair trade.","re":"One career fuelled by the other's unpaid work isn't a fair trade; both deserve to grow.","why":"A 'trade' where only one person advances spends the other's potential."},"relearn":"A career built on a partner's unpaid work isn't a fair trade; both deserve to grow.","cat":"two-careers"},
  {"id":"ep-1360","type":"strike-rewrite","persona":"any","source":"she earns less so","hook":"\"She earns less, so naturally her job is the one to drop when life gets busy.\"","myth":{"un":"She earns less, so her job drops first when life gets busy.","re":"Lower pay doesn't make a career disposable; the salary gap often grew from past unfair choices.","why":"Always cutting the lower earner can lock in the very gap it points to."},"relearn":"Earning less doesn't make a career the disposable one; that gap is often built unfairly.","cat":"two-careers"},
  {"id":"ep-1361","type":"strike-rewrite","persona":"Karthik","source":"helping her job","hook":"\"I 'let' my wife work. Most husbands wouldn't.\"","myth":{"un":"I let my wife work; most husbands wouldn't.","re":"Her career isn't yours to permit; equal partners back each other's work, not grant it.","why":"'Letting' her work still treats his job as the one that owns the decision."},"relearn":"A partner's career isn't yours to permit; equals back each other's work as a right.","cat":"two-careers"},
  {"id":"ep-1362","type":"strike-rewrite","persona":"any","source":"startup risk","hook":"\"Only one of you should take a risky startup leap; she should keep the safe salary.\"","myth":{"un":"She keeps the safe salary while he takes the startup leap.","re":"Who takes the risky leap and who holds steady is a fair choice you swap over time, not by gender.","why":"Defaulting the 'safe' role to her quietly caps her ambition."},"relearn":"Who takes the risky leap vs the steady salary is a fair, swappable choice, not gendered.","cat":"two-careers"},
  {"id":"ep-1363","type":"strike-rewrite","persona":"any","source":"night shift","hook":"\"Her night shifts are a problem for the home; his are just his job.\"","myth":{"un":"Her night shifts disturb the home; his are just his job.","re":"Both partners' shift work is real work; the home adapts around both, not only around hers.","why":"Treating only her shifts as a 'home problem' makes her job the negotiable one."},"relearn":"Both partners' shifts are real; the home adapts around both, not only hers.","cat":"two-careers"},
  {"id":"ep-1364","type":"strike-rewrite","persona":"any","source":"in-laws expect","hook":"\"The in-laws expect a working bahu to still do everything at home. That's just how it is.\"","myth":{"un":"A working bahu is still expected to do everything at home.","re":"A job plus the whole home is a double shift; the home load is shared no matter who's the bahu.","why":"Family expectations don't make a second unpaid shift fair."},"relearn":"A working partner doing the whole home too is a double shift, not 'just how it is'.","cat":"two-careers"},
  {"id":"ep-1365","type":"strike-rewrite","persona":"any","source":"his promotion ours","hook":"\"His promotion is the family's win; her promotion is just her thing.\"","myth":{"un":"His promotion is the family's win; hers is just her thing.","re":"Both partners' wins are the family's wins; neither one's growth belongs only to that person.","why":"Cheering only his rise tells her career it matters less to the home."},"relearn":"Both partners' career wins are the family's wins, not just 'her thing'.","cat":"two-careers"},
  {"id":"ep-1366","type":"strike-rewrite","persona":"Pooja","source":"flexible label","hook":"\"She picked a 'flexible' career so she could manage the house. That was the plan.\"","myth":{"un":"She chose a flexible career so she could manage the house.","re":"A flexible job is still a career, not a reason she alone absorbs the house.","why":"'Flexible' shouldn't become a polite word for 'she does it all.'"},"relearn":"A flexible job is still a career, not a reason one partner absorbs the whole home.","cat":"two-careers"},
  {"id":"ep-1367","type":"strike-rewrite","persona":"any","source":"course up-skill","hook":"\"He can do an evening course to up-skill; she's too busy with the house for that.\"","myth":{"un":"He can up-skill in the evenings; she's too busy with the house.","re":"Both partners deserve time to up-skill; that means sharing the evenings, not blocking hers.","why":"If only he gets growth-time, the home is quietly funding only his career."},"relearn":"Both partners deserve up-skilling time; share the evenings so neither career stalls.","cat":"two-careers"},
  {"id":"ep-1368","cat":"two-careers","type":"branch","persona":"any","source":"who relocates","hook":"You and Kavya have each landed a strong job offer, but in two different cities.","steps":[{"prompt":"Everyone around you assumes Kavya will be the one to give up her offer. What do you do?","options":[{"text":"Weigh both offers together on their real merits","then":"You sit down and compare growth, pay and fit for both roles.","best":true},{"text":"Let Kavya decide since it's her offer","then":"She starts weighing it alone, feeling the weight of everyone's expectations."},{"text":"Say your offer sounds more solid","then":"Kavya starts talking herself into staying near your city."},{"text":"Suggest postponing the decision by a year","then":"Both offers have deadlines, so the question comes back within days."}],"why":"Weighing both offers together, on merit, is what avoids the default assumption."},{"prompt":"A friend who knows both industries says Kavya's offer is clearly the bigger opportunity. What do you do?","options":[{"text":"Agree to move for her offer, as she'd do for yours","then":"\"You mean it?\" she asks, surprised and pleased.","best":true},{"text":"Ask if there's a way to make yours work instead","then":"Kavya senses you're still hoping for the other outcome."},{"text":"Suggest she try to negotiate a transfer near you","then":"The stronger offer quietly gets traded for convenience."},{"text":"Say it would be easier on both families if she stayed","then":"Kavya starts wondering if her career will always come second."}],"why":"Following the merits, even when it means you move, is what makes the decision fair."},{"prompt":"Relatives ask how you two are settling things between the two cities. What do you say?","options":[{"text":"Say both careers count, and you'll keep deciding on the merits","then":"The relatives look surprised, then nod slowly.","best":true},{"text":"Say it just made more sense this way","then":"The relatives assume it was a practical, not equal, choice."},{"text":"Change the subject quickly","then":"The question lingers, unanswered, at the next gathering too."},{"text":"Joke that you lost the toss","then":"The joke gets a laugh, and fairness never gets said out loud."}],"why":"Saying both careers count shows relatives what deciding on merit looks like."},{"prompt":"A year later, another opportunity comes up, this time for your career. What do you do?","options":[{"text":"Weigh it together honestly, on the real merits","then":"You sit down and compare the offer fairly, the way it deserves.","best":true},{"text":"Assume it's your turn now, so you take it","then":"Kavya feels the decision was made without her."},{"text":"Let it pass to avoid uprooting things again","then":"You wonder later if you gave up something real."},{"text":"Decide based on who's more tired of the current city","then":"The decision has nothing to do with either career."}],"why":"Deciding together again, not assuming it's automatically your turn, keeps it equal."}],"debrief":"When two careers pull apart, decide together on the merits: don't default to hers giving way.","relearn":"When two offers clash, weigh both and choose together, not by gender default."},
  {"id":"ep-1369","cat":"two-careers","type":"branch","persona":"Karthik","source":"her big project","hook":"Pooja's landed a three-month crunch project, and the home still runs on her usual planning.","steps":[{"prompt":"The project starts Monday, and she's already stressed about juggling both. What do you do?","options":[{"text":"Take over the home's planning for these three months","then":"Pooja exhales. \"You mean actually take it, not just help?\"","best":true},{"text":"Say you'll help more whenever she asks","then":"She nods, and ends up mostly relying on you anyway once the crunch hits."},{"text":"Suggest she cut back on the project instead of you","then":"Pooja looks torn, but decides to keep the project and lean on you at home."},{"text":"Say it'll probably work itself out","then":"Nothing changes at first, but exhaustion forces you to start covering things within days."}],"why":"Taking over the planning outright, not offering to help, is what real backing looks like."},{"prompt":"A grocery run gets missed, and the fridge is nearly empty. What do you do?","options":[{"text":"Notice it yourself and restock without being told","then":"Pooja comes home to a full fridge and doesn't have to think about it.","best":true},{"text":"Text her to ask exactly what's usually on the list","then":"She replies from a meeting, still managing it remotely."},{"text":"Wait for her to notice and handle it later","then":"She notices at 9pm, too tired to do anything about it."},{"text":"Order takeout for a few days instead","then":"It solves dinner, but the planning gap stays unfilled."}],"why":"Noticing and acting without being asked is what owning the planning actually means."},{"prompt":"The project ends, and Pooja finally gets a full weekend off. What do you do?","options":[{"text":"Let her rest, then agree a fair split together","then":"Pooja sleeps in for the first time in months. You plan the split together next week.","best":true},{"text":"Hand the planning straight back to her right away","then":"She feels the weight return before she's even caught her breath."},{"text":"Keep running everything and don't bring up the split","then":"Pooja rests, but who plans what is never actually agreed."},{"text":"Ask if she's ready to take over again","then":"The question itself becomes one more thing on her mind."}],"why":"Let her rest, then agree a fair split, so the planning doesn't default back to her."}],"debrief":"Backing a partner's big project means owning the home load for a stretch, not just helping.","relearn":"Back a partner's crunch by owning the home planning, not just helping when asked."},
  {"id":"ep-1370","cat":"two-careers","type":"branch","persona":"any","source":"daycare vs quit","hook":"A baby's on the way, and neither of you has said much about work plans.","steps":[{"prompt":"You realise you both assume Sana will be the one to cut back at work. What do you do?","options":[{"text":"Sit down and look at leave, daycare and both jobs","then":"You lay out real numbers instead of the assumption you'd been carrying.","best":true},{"text":"Leave the work question for Sana to sort out","then":"She decides alone, without really weighing your options too."},{"text":"Say your job pays more, so it makes sense","then":"Pay becomes the only factor, and the rest goes unexamined."},{"text":"Assume daycare is too expensive to even consider","then":"The option gets ruled out before either of you actually checks the cost."}],"why":"Actually looking at the real options together is what breaks the automatic assumption."},{"prompt":"A colleague mentions a daycare near both offices that's surprisingly affordable. What do you do?","options":[{"text":"Discuss both careers fairly against this new option","then":"For the first time, both your careers are genuinely on the table.","best":true},{"text":"Assume Sana will still prefer to step back","then":"The numbers change, but the old assumption doesn't."},{"text":"Quietly rule out daycare without talking it through","then":"The option closes without either of you naming why."},{"text":"Say her parents will cover it, so no need to discuss it","then":"The question of both careers is never actually discussed."}],"why":"Weighing both careers against the real numbers, not the old default, is the fair step."},{"prompt":"Sana says she doesn't want to step back right now. What do you do?","options":[{"text":"Support that fully, and look at your own flexibility","then":"You start checking what could give on your end instead.","best":true},{"text":"Ask if she's really sure about that","then":"Sana feels she has to defend a choice that should be simple."},{"text":"Say you assumed she'd want to slow down","then":"Sana sighs. \"That's exactly the assumption I mean.\""},{"text":"Suggest waiting to decide until the baby arrives","then":"The decision gets delayed, and the default quietly holds by inertia."}],"why":"Backing her choice and checking your own flexibility keeps this genuinely joint."},{"prompt":"Relatives ask who's going to manage once the baby comes. What do you say?","options":[{"text":"Say you're deciding together, based on what actually works","then":"The relatives look surprised, then curious about the plan.","best":true},{"text":"Say Sana's probably going to take it easier for a while","then":"The old assumption gets repeated, out loud, at the table."},{"text":"Say you'll figure it out when it happens","then":"The vague answer leaves the assumption unchallenged."},{"text":"Say daycare will handle most of it","then":"The relatives nod, missing that a real decision was ever made."}],"why":"Naming that it's a joint, considered decision is what actually breaks the default in public too."}],"debrief":"Whose career slows for a baby is a joint decision about real options, not an automatic 'hers'.","relearn":"Whose career slows for a baby is decided together from real options, not defaulted to hers."},
  {"id":"ep-1371","cat":"two-careers","type":"branch","persona":"any","source":"turning down travel","hook":"Radhika's new role needs frequent travel, but evenings at home have always run around her.","steps":[{"prompt":"She hesitates to take the role, worried about the gap at home. What do you do?","options":[{"text":"Reshape the evenings so you can cover them yourself","then":"Radhika looks relieved. \"You'd actually take that on?\"","best":true},{"text":"Suggest she ask for a version without travel","then":"She considers shrinking the role just to keep evenings simple."},{"text":"Say you're not sure you can manage evenings alone","then":"Radhika hesitates, but decides to take the role anyway, worried about the gap."},{"text":"Say you'll figure it out when it happens","then":"She takes the role, unsure what 'figuring it out' will actually mean."}],"why":"Reshaping the home yourself, not shrinking her role, is what makes her travel possible."},{"prompt":"Her first trip is booked for next week. What do you do?","options":[{"text":"Plan out the week's evenings in detail now","then":"You map meals, errands and everything else before she even leaves.","best":true},{"text":"Tell her you'll manage. Don't worry","then":"She leaves without knowing exactly what 'managing' will look like."},{"text":"Ask her to leave detailed instructions","then":"She spends her last evening writing lists instead of packing calmly."},{"text":"Plan to just take it day by day","then":"The first evening alone turns chaotic and improvised."}],"why":"Planning ahead yourself is what actually frees her to leave without worry."},{"prompt":"She comes home from her first trip, tired but the house is calm. What do you do?","options":[{"text":"Say you've got it. Go again whenever it's needed","then":"Radhika exhales, the last of her worry finally leaving.","best":true},{"text":"Ask how the trips are likely to go from here","then":"The question leaves the arrangement feeling temporary, not settled."},{"text":"Mention how tiring the week was for you too","then":"Radhika feels a flicker of guilt about the role she chose."},{"text":"Say it worked out fine this once","then":"The next trip feels like a gamble instead of a plan."}],"why":"Confirming it's sustainable, not a one-off, is what lets her travel with a clear mind."}],"debrief":"Make space for a partner's travel by owning the home gap, not by asking them to shrink the job.","relearn":"Enable a partner's travel by covering the home, not by shrinking their role."},
  {"id":"ep-1372","cat":"two-careers","type":"branch","persona":"any","source":"pay gap home time","hook":"A recent raise has you earning more than Farah, and you're tempted to ease off at home.","steps":[{"prompt":"You catch yourself about to skip your evening chores. What do you do?","options":[{"text":"Do them anyway. Pay doesn't change your fair share","then":"You finish up, and the evening runs the same as always.","best":true},{"text":"Skip them just this once. You're tired from work","then":"Farah notices, and quietly picks up the slack."},{"text":"Ask Farah if she minds covering tonight","then":"She agrees, but wonders if 'tonight' is becoming every night."},{"text":"Decide your bigger paycheck earns you a pass","then":"Farah says nothing, but something shifts between you."}],"why":"Doing your share regardless of pay is what keeps the split actually fair."},{"prompt":"A week later, Farah asks how you think the raise is affecting things at home. What do you say?","options":[{"text":"Say pay shouldn't change the split, then ask her view","then":"\"Thank you,\" she says, relieved you're taking it seriously.","best":true},{"text":"Say your job's just bigger right now, so things differ","then":"Farah sighs. \"So the size of it decides who does the dishes?\""},{"text":"Say you hadn't really noticed any change at home","then":"Farah feels unseen, carrying more without being acknowledged."},{"text":"Offer to make it up to her this weekend","then":"One good weekend doesn't touch the pattern during the week."}],"why":"Holding the split and asking for her view, not defending yourself, keeps it fair."},{"prompt":"A relative jokes that with your salary, Farah should be managing the home. What do you do?","options":[{"text":"Say pay has nothing to do with sharing the home","then":"The relative shrugs, but the point lands with Farah.","best":true},{"text":"Laugh it off without really addressing it","then":"The joke sits there, half agreed with by your silence."},{"text":"Say Farah doesn't seem to mind, actually","then":"Farah looks uncomfortable being spoken for like that."},{"text":"Agree, since it does make some sense","then":"The comment settles in as a quiet new expectation."}],"why":"Naming pay and home work as separate things holds the line clearly, even as a joke."},{"prompt":"Months later, your salary gap has grown even further. What do you do?","options":[{"text":"Keep the same fair split you always agreed","then":"The gap in pay never becomes a gap in what you each carry at home.","best":true},{"text":"Reconsider whether the split should shift now","then":"Farah senses the question itself changes something between you."},{"text":"Offer to pay for more outside help instead","then":"Help eases tasks, but doesn't touch who manages the home."},{"text":"Assume Farah's fine with doing a bit more now","then":"The assumption quietly becomes the new normal, unspoken."}],"why":"Holding the same fair split, whatever the pay gap becomes, is what makes it a real principle."}],"debrief":"A bigger salary isn't a pass on home work; the load stays shared regardless of who earns more.","relearn":"Earning more doesn't reduce your home share; the load is shared regardless of pay."},
  {"id":"ep-1373","cat":"two-careers","type":"branch","persona":"Pooja","source":"declined promotion","hook":"A promotion's on the table, but you're quietly thinking of turning it down for the home.","steps":[{"prompt":"The deadline to respond is close, and you haven't told Karthik yet. What do you do?","options":[{"text":"Tell him, and ask to rebalance the home together","then":"Karthik looks startled. \"Why would you even consider turning it down?\"","best":true},{"text":"Decline quietly. It's simpler that way","then":"Karthik finds out later. \"Wait, is it too late to reconsider together?\""},{"text":"Wait and see if the timing feels better later","then":"The deadline nearly passes, until Karthik notices and asks to talk about it."},{"text":"Ask Karthik if he thinks you can manage it","then":"He says sure, but later admits he hadn't really thought about what needs to change."}],"why":"Raising it together opens the real option instead of quietly capping your own career."},{"prompt":"Karthik asks what would actually need to change at home. What do you do?","options":[{"text":"Name specific things you'd need him to fully own","then":"He nods, taking mental notes on exactly what's his now.","best":true},{"text":"Say he'll just need to help out more generally","then":"Karthik nods vaguely, but ends up taking over the cooking almost by default."},{"text":"Say you'll figure it out once you're in the role","then":"You end up managing both, until Karthik notices and just starts taking over groceries."},{"text":"Say it's fine. You'll manage like you always do","then":"The promotion adds hours, until Karthik quietly starts picking up the slack at home."}],"why":"Naming specific domains for him to own is what actually frees up your time."},{"prompt":"A few weeks on, in the new role, a hard week arrives. What do you do?","options":[{"text":"Let Karthik run what he's taken on, without stepping in","then":"The house holds steady, even with you buried in the new role.","best":true},{"text":"Check in on his tasks just to be sure","then":"The checking becomes its own new job on top of the promotion."},{"text":"Take back a task or two, just this week","then":"The old pattern starts creeping back in during your busiest stretch."},{"text":"Apologise for how much has changed at home","then":"Karthik reassures you, but the apology wasn't really needed."}],"why":"Trusting him to run what he owns is what makes the rebalance actually hold."}],"debrief":"Don't shrink your own career to protect an unfair split: rebalance the home and take the offer.","relearn":"Don't quietly cap your career for the home; rebalance together and take the offer."},
  {"id":"ep-1374","cat":"two-careers","type":"branch","persona":"Karthik","source":"her late meeting","hook":"Pooja has a late client call tonight, and dinner has always quietly been her job to sort.","steps":[{"prompt":"It's approaching seven and Pooja's still on the call. What do you do?","options":[{"text":"Start dinner and own the evening without being asked","then":"You start dinner right away, well before she's anywhere near done.","best":true},{"text":"Order food and text her to sort the rest later","then":"She reads the text mid-call, and the rest lands on her anyway."},{"text":"Wait to see if she manages once she's free","then":"You wait, watching the clock, while her call drags on and on."},{"text":"Text asking what she wants for dinner","then":"She replies from the call, still the one deciding."}],"why":"Owning the evening outright is what actually spares her the second job."},{"prompt":"The call runs long, and it's clear it won't end soon. What do you do?","options":[{"text":"Handle the rest too, and let her finish her call","then":"Pooja finally logs off to a finished evening, nothing waiting for her.","best":true},{"text":"Text updates and ask her to confirm each step","then":"She answers between meeting notes, still managing dinner from her desk."},{"text":"Start feeling a bit resentful about the timing","then":"You cook, but the resentment simmers quietly through the evening."},{"text":"Assume she'll sort things once she's done","then":"You end up finishing it up last minute, just before she logs off."}],"why":"Handling it fully, without needing to report in, is what real ownership looks like."},{"prompt":"Pooja finally joins you, apologising for the late call. What do you do?","options":[{"text":"Say there's nothing to apologise for. It's handled","then":"\"Handled,\" she repeats, like she's testing whether it's true.","best":true},{"text":"Say it's fine. You managed somehow","then":"Pooja hears 'somehow' and wonders what it actually cost you."},{"text":"Mention how hectic the evening got","then":"Pooja feels she owes you for a night she couldn't control."},{"text":"Say these late calls happen a lot lately","then":"The comment lands more like a complaint than an update."}],"why":"Confirming it's genuinely handled, without a tally, is what makes owning it real."},{"prompt":"Late calls become a regular part of her week. What do you do?","options":[{"text":"Own those evenings, and agree the wider split too","then":"You both say it aloud, and set a time to review how the split is going.","best":true},{"text":"Offer to help on the nights it happens","then":"Some nights it's owned. Some nights it's negotiated, unevenly."},{"text":"Ask her to try to keep calls shorter","then":"Pooja feels her work is being blamed for the arrangement."},{"text":"Just keep taking on those evenings as the new normal","then":"The routine settles, but nobody has said what else is shared or checked."}],"why":"Owning those evenings and agreeing the wider split keeps it fair, not quietly absorbed."}],"debrief":"When a partner's work runs late, own the evening so they don't carry work plus the home.","relearn":"When a partner works late, own the evening yourself rather than handing it back."},
  {"id":"ep-1375","cat":"two-careers","type":"branch","persona":"any","source":"sabbatical turn","hook":"Meher wants to take a study sabbatical, after years of you both backing each other's work.","steps":[{"prompt":"The idea comes up over dinner, half-joking at first. What do you do?","options":[{"text":"Take it seriously and check whose turn it actually is","then":"You both realise she backed your last big move, and now it's hers.","best":true},{"text":"Say it sounds nice, but maybe not this year","then":"Meher lets it go for now, but brings it up again a few weeks later."},{"text":"Suggest it might be easier to skip hers this time","then":"Meher goes quiet, but raises it again later, unwilling to let it drop."},{"text":"Ask if she's sure she really needs it","then":"Meher second-guesses something she'd been excited about."}],"why":"Checking whose turn it is honestly is what keeps backing each other fair, not gendered."},{"prompt":"You realise finances will be tighter during her sabbatical. What do you do?","options":[{"text":"Work out a budget together and commit to backing it","then":"You both feel steadier once the plan is actually on paper.","best":true},{"text":"Suggest she shorten the sabbatical to save money","then":"Meher agrees, quietly shrinking something she'd planned carefully."},{"text":"Say the timing feels risky right now","then":"The sabbatical gets pushed back, but Meher decides to go ahead in a few months anyway."},{"text":"Leave the budgeting to her to sort out","then":"Meher plans it alone, the way she always seems to."}],"why":"Planning the budget together is what makes backing her turn real, not just words."},{"prompt":"Her sabbatical begins, and your own schedule needs to flex to cover things. What do you do?","options":[{"text":"Flex fully, the way she did for your last big step","then":"Meher settles into her sabbatical, knowing home is covered.","best":true},{"text":"Flex partway, and hope it's enough","then":"Meher spends part of her sabbatical still managing gaps at home."},{"text":"Remind her what you're giving up for her turn","then":"Meher feels her turn come with a quiet debt attached."},{"text":"Assume she'll manage both anyway","then":"The sabbatical becomes just another thing she juggles."}],"why":"Flexing fully, the way she once did for you, is what makes taking turns real."}],"debrief":"Equal partners take turns backing each other's growth; whose turn it is isn't set by gender.","relearn":"Take turns backing each other's growth; whose turn it is isn't decided by gender."},
  {"id":"ep-1376","cat":"two-careers","type":"branch","persona":"any","source":"freelance dip","hook":"Leela's freelance income has dipped this month, tempting you to call it not serious.","steps":[{"prompt":"She mentions the dip, a little anxious about it. What do you do?","options":[{"text":"Say it's a normal phase of a real career, and support it","then":"Leela relaxes slightly. \"I was worried you'd think less of it.\"","best":true},{"text":"Suggest she consider something a bit steadier for now","then":"Leela hears 'steadier' as 'not real' underneath."},{"text":"Say freelancing was always a bit of a gamble","then":"Leela feels her whole career questioned over one slow month."},{"text":"Offer to cover more bills without discussing it","then":"It solves the money, but says nothing about respecting her work."}],"why":"Naming the dip as normal, not a verdict, keeps respecting her career through the lean stretch."},{"prompt":"A relative asks when Leela's going to get a proper job. What do you do?","options":[{"text":"Say freelancing is her real career, dips and all","then":"The relative shrugs, and Leela shoots you a grateful look.","best":true},{"text":"Say she's exploring her career options currently","then":"The comment leaves her career sounding temporary, not real."},{"text":"Laugh it off without really answering","then":"The question lands, unanswered, and Leela feels a little smaller."},{"text":"Say she's actually thinking about it too","then":"Leela's startled. \"Wait, I never said that.\""}],"why":"Naming freelancing as real work, plainly, is what actually defends her career in public."},{"prompt":"The dip stretches into a third month. What do you do?","options":[{"text":"Check in on how she's feeling, not just the numbers","then":"Leela opens up about the stress she'd been hiding behind the numbers.","best":true},{"text":"Ask when she expects things to pick up","then":"Leela feels pressure to promise a timeline she can't guarantee."},{"text":"Start quietly looking at job listings for her","then":"Leela feels her career being replaced without being asked."},{"text":"Avoid the topic to keep things comfortable","then":"The stress stays unspoken, and Leela carries it alone."}],"why":"Checking on her, not just the income, is what treats the dip as a phase, not a failure."},{"prompt":"Her income picks back up a few months later. What do you do?","options":[{"text":"Note it was just a normal dip, nothing more","then":"Leela smiles. \"You actually meant that, didn't you?\"","best":true},{"text":"Say you're relieved it's over now","then":"Leela hears relief, and wonders if you'd stopped believing in it."},{"text":"Joke about how worried everyone was","then":"The joke lands a little too close to the truth for Leela."},{"text":"Move on without mentioning it at all","then":"The support during the dip goes quietly unacknowledged."}],"why":"Naming it as the normal phase it always was is what makes your support feel consistent."}],"debrief":"A lean stretch doesn't make a career less real; both partners' work deserves respect.","relearn":"An income dip doesn't make a career 'not serious'; both partners' work stays respected."},
  {"id":"ep-1377","type":"sort","persona":"any","source":"flex vs default","hook":"Sort: a fair career-flex move, or a gender default?","items":[{"id":"a","text":"Weighing both offers before deciding who moves"},{"id":"b","text":"Assuming she'll quit if he gets a transfer"},{"id":"c","text":"Taking turns on whose work flexes"},{"id":"d","text":"Treating his job as the one that can't bend"},{"id":"e","text":"Both planning leave for a sick child"},{"id":"f","text":"Defaulting school pickups to her schedule"}],"bins":[{"id":"fair","label":"Fair flex","valence":"pos"},{"id":"default","label":"Gender default","valence":"neg"}],"key":{"a":"fair","b":"default","c":"fair","d":"default","e":"fair","f":"default"},"relearn":"Weighing both, taking turns and sharing leave is fair flex; quitting-by-default and his-can't-bend is a gender default.","cat":"two-careers"},
  {"id":"ep-1378","type":"sort","persona":"any","source":"real vs backup","hook":"Sort: treats both careers as real, or one as a backup?","items":[{"id":"a","text":"Both jobs get real planning and support"},{"id":"b","text":"Calling her salary 'pocket money'"},{"id":"c","text":"Either career can be the one we prioritise"},{"id":"d","text":"Saying his is the 'real' job"},{"id":"e","text":"Both wins celebrated as the family's"},{"id":"f","text":"Treating her work as optional after marriage"}],"bins":[{"id":"real","label":"Both real","valence":"pos"},{"id":"backup","label":"One as backup","valence":"neg"}],"key":{"a":"real","b":"backup","c":"real","d":"backup","e":"real","f":"backup"},"relearn":"Real planning, either-can-be-priority and shared wins treat both as real; 'pocket money', 'real job' and 'optional' make one a backup.","cat":"two-careers"},
  {"id":"ep-1379","type":"sort","persona":"any","source":"whose hours yield","hook":"Sort: protects both careers' time, or only his?","items":[{"id":"a","text":"Guarding focus time for both partners' work"},{"id":"b","text":"Only his calls count as urgent"},{"id":"c","text":"Splitting interruptions during work hours"},{"id":"d","text":"Her meetings come second to the chores"},{"id":"e","text":"Both block evenings to up-skill"},{"id":"f","text":"She works from home so she can run the house"}],"bins":[{"id":"both","label":"Both careers' time","valence":"pos"},{"id":"his","label":"Only his time","valence":"neg"}],"key":{"a":"both","b":"his","c":"both","d":"his","e":"both","f":"his"},"relearn":"Guarding both partners' focus and sharing interruptions protects both careers; 'only his is urgent' and her-comes-second protect only his.","cat":"two-careers"},
  {"id":"ep-1380","type":"sort","persona":"any","source":"pay and load","hook":"Sort: keeps pay separate from home share, or buys out of it?","items":[{"id":"a","text":"Higher earner still does a fair home share"},{"id":"b","text":"'I earn more, so home is your job'"},{"id":"c","text":"Load split by capacity, not by salary"},{"id":"d","text":"Lower earner expected to do everything"},{"id":"e","text":"Both incomes treated as real and equal"},{"id":"f","text":"Using a bigger paycheck to skip chores"}],"bins":[{"id":"shared","label":"Pay-blind sharing","valence":"pos"},{"id":"buyout","label":"Buying out","valence":"neg"}],"key":{"a":"shared","b":"buyout","c":"shared","d":"buyout","e":"shared","f":"buyout"},"relearn":"A fair share regardless of pay and capacity-based splits share fairly; 'I earn more so it's yours' and skipping chores buy out of partnership.","cat":"two-careers"},
  {"id":"ep-1381","type":"sort","persona":"any","source":"backing growth","hook":"Sort: backs both partners' growth, or only one's?","items":[{"id":"a","text":"Taking turns on who chases the big role"},{"id":"b","text":"Only he gets evening study time"},{"id":"c","text":"Covering home so she can travel for work"},{"id":"d","text":"Her sabbatical is the one to skip"},{"id":"e","text":"Celebrating both promotions equally"},{"id":"f","text":"His ambitions always come first"}],"bins":[{"id":"both","label":"Backs both","valence":"pos"},{"id":"one","label":"Backs one","valence":"neg"}],"key":{"a":"both","b":"one","c":"both","d":"one","e":"both","f":"one"},"relearn":"Taking turns, covering home for her travel and equal cheering back both; only-his study, skipping hers and his-first back one.","cat":"two-careers"},
  {"id":"ep-1382","type":"sort","persona":"any","source":"relocation fairness","hook":"Sort: a fair way to handle a move, or an unfair default?","items":[{"id":"a","text":"Comparing both jobs' prospects in the new city"},{"id":"b","text":"Assuming she resigns to follow his posting"},{"id":"c","text":"Either partner open to being the trailing one"},{"id":"d","text":"His abroad posting auto-ends her career"},{"id":"e","text":"Planning the move around both careers"},{"id":"f","text":"Her job is the obvious one to drop"}],"bins":[{"id":"fair","label":"Fair move","valence":"pos"},{"id":"unfair","label":"Unfair default","valence":"neg"}],"key":{"a":"fair","b":"unfair","c":"fair","d":"unfair","e":"fair","f":"unfair"},"relearn":"Comparing prospects, either being the trailing one and planning around both is fair; auto-resigning and 'hers drops' is an unfair default.","cat":"two-careers"},
  {"id":"ep-1383","type":"sort","persona":"any","source":"respecting work","hook":"Sort: respects a partner's work, or quietly downgrades it?","items":[{"id":"a","text":"Treating a freelance dip as a normal phase"},{"id":"b","text":"Telling her to get a 'proper job'"},{"id":"c","text":"Taking her deadlines as seriously as yours"},{"id":"d","text":"Calling her startup a 'hobby'"},{"id":"e","text":"Asking her to walk you through her week"},{"id":"f","text":"Skipping her work events as 'not important'"}],"bins":[{"id":"respect","label":"Respects it","valence":"pos"},{"id":"downgrade","label":"Downgrades it","valence":"neg"}],"key":{"a":"respect","b":"downgrade","c":"respect","d":"downgrade","e":"respect","f":"downgrade"},"relearn":"A dip seen as normal, deadlines taken seriously and learning her week respect her work; 'proper job', 'hobby' and skipping events don't.","cat":"two-careers"},
  {"id":"ep-1384","type":"sort","persona":"any","source":"crunch support","hook":"Sort: supports a partner's crunch, or hands it back?","items":[{"id":"a","text":"Owning the home planning during her big project"},{"id":"b","text":"'Helping' only when she asks during crunch"},{"id":"c","text":"Covering dinners so she can work late"},{"id":"d","text":"Ordering food and texting her to sort the rest"},{"id":"e","text":"Taking over pickups for the busy month"},{"id":"f","text":"Leaving the calendar for her to juggle"}],"bins":[{"id":"supports","label":"Supports","valence":"pos"},{"id":"hands","label":"Hands it back","valence":"neg"}],"key":{"a":"supports","b":"hands","c":"supports","d":"hands","e":"supports","f":"hands"},"relearn":"Owning planning, covering dinners, taking pickups supports a crunch; 'help when asked', 'sort the rest' and leaving the calendar don't.","cat":"two-careers"},
  {"id":"ep-1385","type":"sort","persona":"any","source":"whose call","hook":"Sort: a joint career decision, or a unilateral default?","items":[{"id":"a","text":"Deciding the sabbatical turn together"},{"id":"b","text":"'Letting' her work as a favour"},{"id":"c","text":"Both choosing who takes the startup risk"},{"id":"d","text":"Telling her she'll stop after the baby"},{"id":"e","text":"Mapping the transfer choice as a team"},{"id":"f","text":"Assuming her promotion 'isn't worth it'"}],"bins":[{"id":"joint","label":"Decided together","valence":"pos"},{"id":"unilateral","label":"Default / decreed","valence":"neg"}],"key":{"a":"joint","b":"unilateral","c":"joint","d":"unilateral","e":"joint","f":"unilateral"},"relearn":"Deciding the turn, the risk and the transfer together is joint; 'letting' her work, decreeing she stops and dismissing her promotion are defaults.","cat":"two-careers"},
  {"id":"ep-1386","type":"spot","persona":"any","source":"transfer talk","hook":"Spot the two lines that quietly assume her career gives way.","scene":[{"id":"a","text":"\"Let's compare both our offers before deciding.\"","trick":false},{"id":"b","text":"\"You'll just resign and come with me, right?\"","trick":true},{"id":"c","text":"\"Whose growth is bigger this year?\"","trick":false},{"id":"d","text":"\"Your job's easy to find anywhere. Mine isn't.\"","trick":true},{"id":"e","text":"\"We can take turns being the one who moves.\"","trick":false}],"why":"'You'll resign and come' and 'your job's easy to find' both assume hers is the one to drop. That's the gender default to catch.","relearn":"Catch the lines that assume her career gives way; a fair move weighs both.","cat":"two-careers"},
  {"id":"ep-1387","type":"spot","persona":"any","source":"earner exemption","hook":"Spot the two lines that use pay to dodge the home load.","scene":[{"id":"a","text":"\"I earn more, so chores are really your side.\"","trick":true},{"id":"b","text":"\"Let's split the home by capacity, not salary.\"","trick":false},{"id":"c","text":"\"My bigger paycheck buys me out of cooking.\"","trick":true},{"id":"d","text":"\"Both incomes are real; the home's still shared.\"","trick":false},{"id":"e","text":"\"I'll own the bills and the school run.\"","trick":false}],"why":"'Chores are your side' and 'buys me out of cooking' both treat pay as a pass on home work. Income doesn't buy you out of partnership.","relearn":"Catch the lines that turn earning more into a pass on home work.","cat":"two-careers"},
  {"id":"ep-1388","type":"spot","persona":"any","source":"backup framing","hook":"Spot the two lines that treat her career as a backup.","scene":[{"id":"a","text":"\"Your work matters as much as mine.\"","trick":false},{"id":"b","text":"\"Your salary's just pocket money, na.\"","trick":true},{"id":"c","text":"\"Let's protect both our deadlines.\"","trick":false},{"id":"d","text":"\"My job's the real one; yours can wait.\"","trick":true},{"id":"e","text":"\"Either of us can chase the next promotion.\"","trick":false}],"why":"'Just pocket money' and 'mine's the real one' both demote her career to a backup. Both careers are real.","relearn":"Catch the lines that demote a partner's career to a backup.","cat":"two-careers"},
  {"id":"ep-1389","type":"spot","persona":"any","source":"sick day default","hook":"Spot the two lines that default the sick-day leave to her.","scene":[{"id":"a","text":"\"Let's alternate who takes leave when she's ill.\"","trick":false},{"id":"b","text":"\"You take leave. Your work's more flexible.\"","trick":true},{"id":"c","text":"\"I'll handle today; you handle next time.\"","trick":false},{"id":"d","text":"\"Sick days are kind of a mom thing, right?\"","trick":true},{"id":"e","text":"\"I'll work from home and watch her today.\"","trick":false}],"why":"'Your work's more flexible' and 'a mom thing' both park sick-leave on her by default. Leave should alternate.","relearn":"Catch the lines that park sick-child leave on her by default.","cat":"two-careers"},
  {"id":"ep-1390","type":"spot","persona":"any","source":"permission framing","hook":"Spot the two lines that treat her career as his to permit.","scene":[{"id":"a","text":"\"I back your work. It's your right, not my gift.\"","trick":false},{"id":"b","text":"\"I let you keep working after marriage.\"","trick":true},{"id":"c","text":"\"Your ambitions are yours to chase.\"","trick":false},{"id":"d","text":"\"I'll allow the job if the home runs fine.\"","trick":true},{"id":"e","text":"\"Tell me how to back your next move.\"","trick":false}],"why":"'I let you work' and 'I'll allow the job' treat her career as his to grant. A partner's work isn't yours to permit.","relearn":"Catch the lines that treat a partner's career as yours to permit.","cat":"two-careers"},
  {"id":"ep-1391","type":"spot","persona":"any","source":"flex label trap","hook":"Spot the two lines that use 'flexible' to make her do it all.","scene":[{"id":"a","text":"\"Your flexible job is still a full career.\"","trick":false},{"id":"b","text":"\"You're flexible, so the house is on you.\"","trick":true},{"id":"c","text":"\"Flexible hours don't mean you're free labour.\"","trick":false},{"id":"d","text":"\"You chose flexible work to manage the home, na.\"","trick":true},{"id":"e","text":"\"Let's still split the home down the middle.\"","trick":false}],"why":"'House is on you' and 'you chose flexible to manage the home' turn a real job into a reason she does it all. Flexible is still a career.","relearn":"Catch the lines that use 'flexible' to load the whole home on her.","cat":"two-careers"},
  {"id":"ep-1392","type":"spot","persona":"any","source":"crunch handback","hook":"Spot the two lines that hand the home back during her crunch.","scene":[{"id":"a","text":"\"I'll own dinners and pickups this month.\"","trick":false},{"id":"b","text":"\"I'll help once you tell me what to do.\"","trick":true},{"id":"c","text":"\"Focus on your project; I've got the home.\"","trick":false},{"id":"d","text":"\"I ordered food. You sort the rest, okay?\"","trick":true},{"id":"e","text":"\"I'll keep the calendar going while you're busy.\"","trick":false}],"why":"'Help once you tell me' and 'you sort the rest' hand the planning back to her mid-crunch. Owning beats waiting to be told.","relearn":"Catch the lines that hand the home's planning back during a partner's crunch.","cat":"two-careers"},
  {"id":"ep-1393","type":"reflect","persona":"any","source":"flex reflect","hook":"Lensy: when work and home collide, whose career do you both reach for first to flex?","prompt":"Sit with it a moment:","options":["Usually hers","Usually his","It varies","We haven't noticed"],"affirm":"Just noticing the default is the first move; from there you can choose who flexes on the merits, together.","relearn":"Noticing whose career you flex by default is the first step to choosing it fairly.","cat":"two-careers"},
  {"id":"ep-1394","type":"reflect","persona":"any","source":"both real reflect","hook":"Lensy: do both of your jobs get talked about as equally real at home?","prompt":"What feels true for you?","options":["Both feel equal","One feels bigger","Hard to say","Changing over time"],"affirm":"Both careers being treated as real is the ground everything fair stands on. It's worth checking in on.","relearn":"It's worth checking whether both partners' jobs are treated as equally real.","cat":"two-careers"},
  {"id":"ep-1395","type":"reflect","persona":"Pooja","source":"capped reflect","hook":"Lensy: have you ever shrunk your own work plans to keep the home easier?","prompt":"No wrong answer, just notice:","options":["Yes, more than once","Maybe a little","Not really","I'm not sure"],"affirm":"If your career has quietly bent for the home, that's worth naming. Rebalancing the home can let it un-bend.","relearn":"Noticing if your career has bent for the home is the first step to rebalancing.","cat":"two-careers"},
  {"id":"ep-1396","type":"reflect","persona":"Karthik","source":"owning crunch reflect","hook":"Lensy: in your partner's busy work weeks, do you wait to be asked or just take the home over?","prompt":"Be honest with yourself:","options":["I take it over","I wait to be asked","A bit of both","I want to do better"],"affirm":"Taking the home over during a partner's crunch, without being asked, is exactly what frees their career to run.","relearn":"Owning the home during a partner's crunch, unasked, is what frees their career.","cat":"two-careers"},
  {"id":"ep-1397","type":"reflect","persona":"any","source":"pay buyout reflect","hook":"Lensy: does the bigger earner in your home quietly do less of the housework?","prompt":"Just notice the pattern:","options":["Yes, noticeably","A little","No, it's even","Never thought about it"],"affirm":"Pay and home share are two different things; noticing if one's buying out of the other is a fair place to start.","relearn":"Noticing if the bigger earner does less at home is a fair place to start.","cat":"two-careers"},
  {"id":"ep-1398","type":"reflect","persona":"any","source":"taking turns reflect","hook":"Lensy: over the years, have you both taken turns backing each other's careers?","prompt":"Look back a moment:","options":["Yes, we trade off","Mostly one of us","Just starting to","Not really yet"],"affirm":"Taking turns, where one steps up so the other can grow and then swaps back, is what two-career equality looks like over time.","relearn":"Two-career equality is taking turns backing each other's growth over time.","cat":"two-careers"},
  {"id":"ep-1399","type":"reflect","persona":"any","source":"respect work reflect","hook":"Lensy: do you talk about your partner's work with the same seriousness you'd want for yours?","prompt":"Sit with it:","options":["Yes, equally","Sometimes less","I'm not sure","I could do better"],"affirm":"Speaking about a partner's work as seriously as your own keeps both careers feeling real, a small thing that matters.","relearn":"Talking about a partner's work as seriously as your own keeps both careers real.","cat":"two-careers"},
  {"id":"ep-1400","cat":"two-careers","type":"role-play","persona":"Karthik","source":"transfer rp","hook":"A transfer offer has just landed for you.","setup":"Your manager stops by your desk.","steps":[{"prompt":"Your manager says: \"Great, so your wife can just resign and join you?\"","options":[{"text":"\"We'll decide together. Her job isn't the default to drop.\"","then":"Your manager pauses. \"Fair enough, let me know.\"","best":true},{"text":"\"She'll sort her own job out somehow. I'm sure.\"","then":"Your manager nods, assuming it's already settled."},{"text":"\"I'll ask her tonight and confirm.\"","then":"The transfer gets treated as already decided by default."},{"text":"\"She's flexible. It shouldn't be an issue.\"","then":"The comment quietly speaks for Pooja before she's even asked."}],"why":"Naming it as a joint decision corrects the assumption before it hardens."},{"prompt":"That evening, Pooja asks: \"So what did you actually tell him?\"","options":[{"text":"\"Whatever I said, let's actually decide this together.\"","then":"Pooja exhales. \"Thank you. That's what I needed to hear.\"","best":true},{"text":"\"That you'd probably just be fine with it, honestly.\"","then":"Pooja feels the decision was half made without her."},{"text":"\"That it's mostly up to you now.\"","then":"Pooja feels the weight of the decision land entirely on her."},{"text":"\"Nothing much, just that we'd see.\"","then":"The vague answer leaves the assumption unchallenged."}],"why":"Recommitting to deciding together, whatever was said today, is what makes the promise real."},{"prompt":"Pooja asks: \"So how do we actually decide, then?\"","options":[{"text":"\"Let's weigh growth, pay and fit honestly for both.\"","then":"The comparison shows it's genuinely close, and you decide together.","best":true},{"text":"\"Lean toward the transfer, since it's already offered.\"","then":"The offer's existence quietly outweighs a fair comparison."},{"text":"\"Whatever you think is best, honestly.\"","then":"Pooja hesitates, unsure if her honest answer is welcome."},{"text":"\"Whichever city seems more convenient.\"","then":"Convenience decides, instead of either career actually being weighed."}],"why":"Actually comparing both jobs on merit is what makes the decision fair, not just fast."}],"relearn":"Make a transfer a joint decision; her career isn't the default to drop."},
  {"id":"ep-1401","cat":"two-careers","type":"role-play","persona":"Karthik","source":"her crunch rp","hook":"Pooja's brutal three-month project starts Monday, and she's dreading juggling the home too.","setup":"The night before, she looks overwhelmed already.","steps":[{"prompt":"Pooja says: \"I don't know how I'm going to manage everything.\"","options":[{"text":"\"I'll own the home and planning these three months.\"","then":"Pooja looks at you, stunned. \"You mean that?\"","best":true},{"text":"\"Just tell me whenever you need help.\"","then":"\"Okay,\" she says, knowing asking is its own extra job."},{"text":"\"You've managed worse before. You'll be fine.\"","then":"Pooja feels dismissed instead of supported."},{"text":"\"We'll figure it out as we go, like always.\"","then":"The vague plan leaves her carrying the worry alone."}],"why":"Owning the home outright, not offering help, is what real backing sounds like."},{"prompt":"A week in, Pooja asks: \"How are we actually managing everything?\"","options":[{"text":"\"I've got the home if you focus on work.\"","then":"Pooja relaxes. \"Okay. Then let me focus.\"","best":true},{"text":"\"We're managing, I think. Mostly.\"","then":"Pooja isn't sure if she can lean on it fully."},{"text":"\"Honestly, it's a lot, but I'll manage.\"","then":"Pooja feels guilty every time she thinks of the project."},{"text":"\"Ask me again once the project's done.\"","then":"Pooja spends the crunch wondering if it's really working."}],"why":"Confirming it firmly, and naming it as mutual, is what lets her actually focus."},{"prompt":"The project ends, and Pooja asks: \"How do I make this up to you?\"","options":[{"text":"\"You don't. It's my turn to back you. That's it.\"","then":"Pooja smiles. \"I like that there's no scorecard.\"","best":true},{"text":"\"Maybe cover a few things for me next month.\"","then":"The support starts to feel transactional, not mutual."},{"text":"\"Honestly, it was a lot. I won't lie.\"","then":"Pooja feels she owes you more than a thank you."},{"text":"\"You'll owe me one, for sure.\"","then":"Pooja laughs, but the comment sticks a little."}],"why":"Refusing a scorecard is what keeps backing each other genuinely mutual, not a debt."}],"relearn":"Back a partner's crunch by owning the home, not by offering help on request."},
  {"id":"ep-1402","cat":"two-careers","type":"role-play","persona":"Pooja","source":"pocket money rp","hook":"Your aunt Sudha has never taken your job very seriously.","setup":"At a family lunch, Sudha leans across the table.","steps":[{"prompt":"Sudha says: \"It's sweet you work, just pocket money though, no?\"","options":[{"text":"\"My income is real, and so is my career.\"","then":"Sudha blinks, clearly not expecting a direct answer.","best":true},{"text":"\"Haan, it's just a little extra, really.\"","then":"Sudha nods, satisfied, and the label sticks."},{"text":"\"It's more than Karthik's, actually.\"","then":"The comparison turns the table's attention into a contest."},{"text":"\"It doesn't matter what you call it.\"","then":"Sudha shrugs, and the dismissal goes unchallenged anyway."}],"why":"Naming your income and career as real, plainly, corrects the label without a fight."},{"prompt":"Sudha adds: \"Either way, Karthik's salary is the real one, no?\"","options":[{"text":"\"Both our incomes are real, equally.\"","then":"Sudha pauses, turning the idea over.","best":true},{"text":"\"His probably matters more, sure.\"","then":"Sudha nods, and the old ranking holds."},{"text":"\"That's an old-fashioned way to think.\"","then":"Sudha bristles, and the table gets tense."},{"text":"\"Depends on the month, honestly.\"","then":"The answer leaves the question basically unsettled."}],"why":"Naming both incomes as equally real is what actually corrects the ranking."},{"prompt":"Later, Karthik says: \"That got a bit much today, no?\"","options":[{"text":"\"It did. It matters that you back me on it.\"","then":"\"Always,\" he says, and means it.","best":true},{"text":"\"It's fine. I'm used to comments like that.\"","then":"Karthik nods, but doesn't realise how often it happens."},{"text":"\"I probably shouldn't let it bother me.\"","then":"\"It's fine to be bothered,\" he says, a little surprised."},{"text":"\"You could have said something too, you know.\"","then":"Karthik stiffens, and the talk turns to who should have spoken."}],"why":"Naming that his support matters too makes it a shared stand, not just yours alone."}],"relearn":"Both partners' incomes are real; neither is 'just pocket money'."},
  {"id":"ep-1403","cat":"two-careers","type":"role-play","persona":"Pooja","source":"promotion rp","hook":"A promotion's been offered, but you're worried it'll make the home load impossible to manage.","setup":"That evening, you're both winding down after dinner.","steps":[{"prompt":"Karthik asks: \"You've been quiet since this afternoon. What's up?\"","options":[{"text":"\"I want this promotion. Can we rebalance the home?\"","then":"Karthik sits up. \"Wait, why would you even hesitate?\"","best":true},{"text":"\"I'll just say no. It's easier for everyone, honestly.\"","then":"\"Wait, you're turning it down?\" he asks, surprised."},{"text":"\"Nothing, just a busy day at work.\"","then":"He nods, but the next day you raise the promotion anyway."},{"text":"\"I'm not sure I can handle everything.\"","then":"Karthik looks concerned, but doesn't offer anything specific yet."}],"why":"Naming the promotion and the rebalance together opens the real option."},{"prompt":"Karthik asks: \"What would actually need to change at home?\"","options":[{"text":"\"You'd need to fully own a few things, start to finish.\"","then":"He nods slowly. \"Okay, tell me exactly what.\"","best":true},{"text":"\"You'd just need to help out more in general, I guess.\"","then":"Karthik nods, unsure what 'more' really means day to day."},{"text":"\"I'll manage. Don't worry about it.\"","then":"The promotion adds hours onto an already full plate."},{"text":"\"We'll sort it out once I've started.\"","then":"You end up juggling both the new role and the old load."}],"why":"Naming specific things for him to fully own is what actually frees your time."},{"prompt":"You take the promotion. A month in, Karthik asks: \"How's it feeling, honestly?\"","options":[{"text":"\"Harder than I expected. Can we check in on the home load?\"","then":"Karthik puts his phone down. \"Yes. Tell me what's landing on you.\"","best":true},{"text":"\"Busy, but I'm managing somehow. Don't worry.\"","then":"Karthik doesn't realise how much you're still carrying."},{"text":"\"Great! Nothing to worry about, honestly. It's all fine.\"","then":"Karthik relaxes and tells you to enjoy the new role."},{"text":"\"Fine, I guess. Same as always, nothing new.\"","then":"The flat answer hides how the home load is actually going."}],"why":"Naming the strain and asking for a check-in keeps the home load fair."},{"prompt":"A year later, Karthik asks: \"Any big opportunities on your radar lately?\"","options":[{"text":"\"Actually yes, and I want to talk it through properly.\"","then":"You raise it, and Karthik's already asking what would need to change.","best":true},{"text":"\"Nothing worth mentioning, probably.\"","then":"The old hesitation resurfaces, and the chance goes unspoken."},{"text":"\"You'd probably offer to help anyway, right?\"","then":"He says he would help, and you see that would still leave you managing it."},{"text":"\"I'd skip it. The home would get harder again.\"","then":"You let the worry about home decide for you, and wonder later if it had to."}],"why":"Raising it openly and early keeps home fair as your career grows."}],"relearn":"Rebalance the home to take an offer; don't quietly cap your own career."},
  {"id":"ep-1404","cat":"two-careers","type":"role-play","persona":"Karthik","source":"let her work rp","hook":"Your friend Deepak has some old-fashioned ideas about marriage.","setup":"You're catching up over chai at his place.","steps":[{"prompt":"Deepak says: \"Good for you, letting her keep her job.\"","options":[{"text":"\"It's not me letting her. It's hers to keep.\"","then":"Deepak pauses. \"Fair, I guess I phrased that oddly.\"","best":true},{"text":"\"Yeah, not every husband would allow it.\"","then":"Deepak nods, and the framing settles in as normal."},{"text":"\"She's earned it, so I don't mind.\"","then":"Deepak hears permission where there shouldn't be any."},{"text":"\"It works out well for us, honestly.\"","then":"The comment slides by, unchallenged, into the next topic."}],"why":"Naming her career as hers, not yours to allow, corrects the framing directly."},{"prompt":"Deepak asks: \"But doesn't it get complicated, managing two careers?\"","options":[{"text":"\"We back each other. It's not about managing her.\"","then":"\"Back each other,\" Deepak repeats, like it's a new idea.","best":true},{"text":"\"Sometimes, but I make it work somehow.\"","then":"Deepak hears you as the one holding it all together."},{"text":"\"She handles her side. I handle mine.\"","then":"The framing keeps the two careers oddly separate, not shared."},{"text":"\"It's complicated, but worth it for her.\"","then":"The comment still frames it as something done for her."}],"why":"Naming it as mutual backing, not management, corrects the whole framing."},{"prompt":"Deepak says: \"My wife wants to go back to work too, honestly.\"","options":[{"text":"\"Then back her, the way I back Pooja.\"","then":"Deepak nods slowly, turning that over.","best":true},{"text":"\"You should probably let her then.\"","then":"Deepak still hears it as his decision to make."},{"text":"\"That's between you two, not my business.\"","then":"Deepak's left without anything useful to actually try."},{"text":"\"Depends if you two can handle it.\"","then":"Deepak's doubt about handling it grows, not shrinks."}],"why":"Modelling 'back her', not 'let her', gives him the actual reframe to use."},{"prompt":"A few months later, Deepak mentions: \"My wife's back at work now, actually.\"","options":[{"text":"\"That's great! How are you two backing each other?\"","then":"Deepak lights up, describing how they split things fairly now.","best":true},{"text":"\"Congratulations on letting her go back.\"","then":"Deepak nods, the old framing quietly slipping back in."},{"text":"\"Has it been hard to manage her schedule?\"","then":"\"Sometimes,\" Deepak says, missing the framing in the question."},{"text":"\"That's great.\"","then":"The conversation moves on before the framing actually shifts."}],"why":"Asking about backing each other keeps reinforcing the reframe, not just praising the outcome."}],"relearn":"A partner's career isn't yours to permit; you back it, you don't grant it."},
  {"id":"ep-1405","cat":"two-careers","type":"role-play","persona":"any","source":"her travel rp","hook":"Anjali's been offered a new role at work.","setup":"She brings it up over dinner.","steps":[{"prompt":"Anjali says: \"I don't know. The travel feels like a lot to ask of you.\"","options":[{"text":"\"Take it. I'll own the evenings.\"","then":"Anjali's eyes widen. \"You'd actually do that?\"","best":true},{"text":"\"Maybe ask for a version without the travel.\"","then":"Anjali considers shrinking the role just to make it simpler."},{"text":"\"It's a big ask. Are you sure it's worth it?\"","then":"Anjali starts talking herself out of an opportunity she wanted."},{"text":"\"We'll manage. However it goes, I guess.\"","then":"She takes it, unsure what 'manage' will actually look like."}],"why":"Actively offering to cover the gap is what makes her travel genuinely possible."},{"prompt":"A few days later, Anjali brings it up again: \"So, where did we land on this?\"","options":[{"text":"\"I'll own the home meanwhile.\"","then":"\"Deal,\" she says, relaxing for the first time about it.","best":true},{"text":"\"We'll figure it out as we go.\"","then":"Anjali isn't fully sure she can lean on it."},{"text":"\"Honestly, it'll be a lot, but okay.\"","then":"Anjali feels a flicker of guilt every time she leaves."},{"text":"\"Ask me again after the first trip.\"","then":"The uncertainty follows her on every trip she takes."}],"why":"Owning the home side outright, not as a sacrifice, lets her take the role without guilt."},{"prompt":"After her first trip, Anjali asks: \"How did everything actually go?\"","options":[{"text":"\"Handled, though tiring. Let's check in on how it's going.\"","then":"Anjali exhales. \"Thank you for telling me. Let's check in after each trip.\"","best":true},{"text":"\"Fine. Just remember I did this while you were away.\"","then":"Anjali laughs, then goes quiet, wondering what she now owes you."},{"text":"\"Fine, but I can't keep this up, so maybe travel less.\"","then":"Anjali hears a hint to shrink her role, and her worry about the next trip returns."},{"text":"\"Let's see how the next one goes first.\"","then":"Each trip starts to feel like a fresh negotiation."}],"why":"Owning the gap and naming the strain keeps it sustainable, so she can travel with a clear mind."}],"relearn":"Enable a partner's travel by owning the home gap, not by shrinking their role."},
  {"id":"ep-1406","cat":"two-careers","type":"role-play","persona":"Karthik","source":"earn more rp","hook":"A recent raise has you earning more than Pooja, tempting you to ease off at home.","setup":"Tonight you catch yourself skipping your evening task.","steps":[{"prompt":"Pooja notices and asks: \"Were you going to do the dishes tonight?\"","options":[{"text":"\"Yes, sorry, earning more doesn't cut my share.\"","then":"Pooja looks surprised, then quietly relieved. \"Good, I was starting to wonder.\"","best":true},{"text":"\"My job's bigger, so it's mostly yours now.\"","then":"Pooja's face falls, hearing the shift out loud."},{"text":"\"I'm exhausted from the new workload, honestly.\"","then":"Pooja does them, feeling the excuse settle into a pattern."},{"text":"\"I'll get to it in a bit, promise.\"","then":"The dishes wait, and so does Pooja, a little longer than usual."}],"why":"Naming pay and home share as separate is what stops the raise quietly buying you out."},{"prompt":"A week later, Pooja notices you eyeing the laundry pile. She asks: \"Everything okay?\"","options":[{"text":"\"Yeah, just doing the laundry now.\"","then":"The laundry gets done, and the pattern from last week doesn't repeat.","best":true},{"text":"\"Would you mind covering it again?\"","then":"She agrees, but starts to wonder if this is becoming routine."},{"text":"\"I'm just thinking about how much extra I'm earning now.\"","then":"Pooja hears the raise being used as an excuse, again."},{"text":"\"Maybe we should just hire someone for this.\"","then":"Help covers the task, but doesn't touch the question of your share."}],"why":"Just doing your share, without comment, is what actually holds the line."},{"prompt":"Pooja mentions: \"A colleague's husband stopped doing chores after his promotion.\"","options":[{"text":"\"That's not going to be us. I mean that.\"","then":"Pooja smiles. \"I was hoping you'd say that.\"","best":true},{"text":"\"Well, promotions do change things a bit.\"","then":"Pooja's smile fades slightly at the qualifier."},{"text":"\"He probably has more responsibility now.\"","then":"Pooja hears the same justification forming in your own voice."},{"text":"\"That does sound tempting, honestly.\"","then":"Pooja laughs, unsure if you're joking or not."}],"why":"Naming it plainly, firmly, reassures her the pattern won't repeat here."},{"prompt":"A relative says: \"With your salary, you shouldn't need to do chores.\"","options":[{"text":"\"Pay and home work are separate things.\"","then":"The relative shrugs, but Pooja catches your eye, pleased.","best":true},{"text":"\"I don't mind pitching in when I can.\"","then":"The comment quietly reframes your share as a favour, not a norm."},{"text":"\"True, but old habits are hard to break.\"","then":"The comment settles in as a quiet, half agreed with, new idea."},{"text":"\"Depends on the day, honestly.\"","then":"The answer leaves the assumption basically standing."}],"why":"Separating pay from home work, plainly, holds the principle even under a relative's teasing."},{"prompt":"Months later, Pooja asks: \"Has the bigger gap in pay changed how you see this?\"","options":[{"text":"\"No, the same even share we always agreed.\"","then":"Pooja smiles, relieved nothing has quietly shifted.","best":true},{"text":"\"Maybe I could just pay for more help instead.\"","then":"Help eases tasks, but the question of your own share stays open."},{"text":"\"I figured you'd be fine with me doing less now.\"","then":"Pooja's face falls, hearing the assumption out loud."},{"text":"\"I was waiting to see if it bothered you first.\"","then":"Pooja realises she'd been waiting for the same thing."}],"why":"Holding the same even share, whatever the pay gap becomes, is what makes it a real principle."}],"relearn":"Earning more doesn't cut your home share; the load stays even."},
  {"id":"ep-1407","cat":"two-careers","type":"role-play","persona":"any","source":"sick child rp","hook":"Your child is running a fever this morning, and you both have work today.","setup":"You're both getting ready when the fever's confirmed.","steps":[{"prompt":"Naina says: \"Someone needs to stay back today.\"","options":[{"text":"\"I'll take leave today. You take the next one.\"","then":"Naina looks relieved. \"Okay. Deal.\"","best":true},{"text":"\"You take it. Your job's more flexible anyway.\"","then":"Naina sighs, and points out she actually has the harder day. You end up staying home instead."},{"text":"\"Let's see whose meeting is less important.\"","then":"You compare schedules under pressure, and yours turns out lighter, so you stay."},{"text":"\"I really can't miss today, honestly.\"","then":"Naina points out she genuinely can't move her calls either. You end up staying, resentful about it."}],"why":"Alternating outright, not defaulting to her flexibility, keeps sick days fairly shared."},{"prompt":"That evening, Naina asks: \"How was today, with the fever and everything?\"","options":[{"text":"\"Tiring. Let's take turns: next one's yours, then mine.\"","then":"\"Good,\" she says, glad you said it out loud.","best":true},{"text":"\"Fine. You make it look easier than it is.\"","then":"Naina feels her usual days quietly go unacknowledged."},{"text":"\"Honestly, I don't know how you always manage it.\"","then":"The comment treats her doing it as the default, not the exception."},{"text":"\"It was a lot. I need a break tomorrow.\"","then":"Naina wonders how the next sick day will get shared."}],"why":"Agreeing to take turns out loud keeps sick days shared, not defaulted to her."},{"prompt":"A few weeks later, the fever is back. Naina asks: \"Whose turn is it?\"","options":[{"text":"\"I took the last one, so this one's yours. Then mine.\"","then":"Naina nods, moves her calls, and heads out with the day sorted.","best":true},{"text":"\"Can we see how the morning goes before we decide?\"","then":"The morning gets chaotic, and the question stays unresolved."},{"text":"\"You're already dressed. Might as well be you.\"","then":"Naina sighs, and sick days slide back to being hers."},{"text":"\"Whoever's less busy today, I guess.\"","then":"The busyness comparison replaces taking turns."}],"why":"Taking turns, not who looks less busy, is what keeps sick days fairly shared."}],"relearn":"Alternate sick-child leave; don't default it to her job."},
  {"id":"ep-1408","cat":"two-careers","type":"role-play","persona":"Pooja","source":"freelance respect rp","hook":"Your freelance income has dipped, and Karthik calls it 'your little hobby' in passing.","setup":"The comment lands harder than he probably meant it to.","steps":[{"prompt":"Karthik says: \"Maybe it's time to look for a proper job.\"","options":[{"text":"\"A slow month doesn't make it a hobby. It's my career.\"","then":"Karthik pauses. \"I didn't mean it like that, sorry.\"","best":true},{"text":"\"Maybe you're right. I'll start looking.\"","then":"Karthik nods, and the doubt settles into you instead of him."},{"text":"\"You don't understand freelancing at all.\"","then":"Karthik gets defensive instead of actually hearing you."},{"text":"\"It's fine. It was just a slow month.\"","then":"Karthik hears agreement, not correction, and the label sticks."}],"why":"Naming it plainly as your career corrects the label without needing to defend every month."},{"prompt":"Karthik asks: \"So what do you expect from the work over the next few months?\"","options":[{"text":"\"I can't promise. Every career has slow stretches.\"","then":"\"Fair,\" he says, thinking about his own rough quarters.","best":true},{"text":"\"Honestly, it may just be a side thing. I'll see.\"","then":"Karthik nods, and the word hobby feels a little more settled."},{"text":"\"I guess it just always works out?\"","then":"Karthik isn't fully convinced by the shrug."},{"text":"\"Whatever you think is best for us.\"","then":"Karthik hesitates, unsure he should be the one deciding about your work."}],"why":"Owning the uncertainty while still calling it your career keeps the hobby label off."},{"prompt":"Later, at a family lunch, a relative asks you: \"So what do you actually do for work?\"","options":[{"text":"\"I'm a freelancer. It's my career.\"","then":"Karthik nods along, backing you without missing a beat.","best":true},{"text":"\"Oh, just some freelance stuff, nothing major.\"","then":"The relative's dismissive nod confirms what you just said."},{"text":"\"It's complicated. Let's not get into it.\"","then":"The relative loses interest, and the question goes unanswered."},{"text":"\"Karthik can explain it better than me.\"","then":"Karthik's explanation comes out sounding unsure, like even he doubts it."}],"why":"Naming your own career plainly is what actually corrects how others see it."},{"prompt":"That night, Karthik says: \"I keep thinking about the hobby comment earlier.\"","options":[{"text":"\"Thank you for raising it. It matters that you see it as real.\"","then":"\"I do,\" he says. \"I just forgot for a moment.\"","best":true},{"text":"\"It's fine. I know you didn't mean it.\"","then":"The comment gets waved off, and the pattern risks repeating."},{"text":"\"You should be more careful with words like that.\"","then":"Karthik gets defensive instead of actually reflecting."},{"text":"\"It happens. Let's just move on.\"","then":"Moving on quickly means neither of you actually names why it stung."}],"why":"Thanking him and naming why it mattered keeps the correction real."},{"prompt":"A few months later, Karthik notices: \"Your income's picked back up, hasn't it?\"","options":[{"text":"\"Yes. A dip like that doesn't make it a hobby.\"","then":"Karthik smiles. \"Good. I should trust that more.\"","best":true},{"text":"\"Yes, so maybe it's a real job again now.\"","then":"Karthik hears that the slow months didn't count, and the hobby label lingers."},{"text":"\"Yes, weren't you worried there for a while?\"","then":"The joke lands close enough to the truth to feel a little pointed."},{"text":"\"I hadn't really noticed, honestly.\"","then":"The earlier doubt goes unaddressed, ready to resurface next dip."}],"why":"Calling a dip a dip, not a hobby, keeps your career's worth steady."}],"relearn":"A lean stretch doesn't make a career a hobby; both partners' work stays real."},
  {"id":"ep-1409","type":"match","persona":"any","source":"default vs fair match","hook":"Match each gender default to the fair move that replaces it.","pairs":[{"left":"She resigns when he's transferred","right":"Weigh both offers and decide together"},{"left":"Her job is the flexible 'home' one","right":"Share the home so both can work"},{"left":"He skips chores as the big earner","right":"Keep a fair share regardless of pay"},{"left":"Only his ambitions get backed","right":"Take turns backing each other"},{"left":"Her salary is 'pocket money'","right":"Treat both incomes as real"}],"relearn":"Each default has a fair replacement: decide together, share the home, share regardless of pay, take turns, value both jobs.","cat":"two-careers"},
  {"id":"ep-1410","type":"match","persona":"any","source":"myth vs truth match","hook":"Match each two-careers myth to the truth that corrects it.","pairs":[{"left":"His is the 'real' job","right":"Both careers are equally real"},{"left":"Earning more buys you out of chores","right":"The load is shared regardless of pay"},{"left":"Her career should flex by default","right":"Whose work flexes isn't set by gender"},{"left":"One person should chase promotions","right":"Both can be ambitious, taking turns"},{"left":"He 'lets' her work","right":"A career isn't a partner's to permit"}],"relearn":"Each myth meets its truth: both careers real, no buyout by pay, flex isn't gendered, both can grow, work isn't permitted.","cat":"two-careers"},
  {"id":"ep-1411","type":"match","persona":"any","source":"situation to fair move match","hook":"Match each work-home clash to the fair response.","pairs":[{"left":"She has a late client call","right":"Own the whole evening tonight"},{"left":"Child is sick and you both work","right":"Alternate who takes the leave"},{"left":"Her big project crunch starts","right":"Take over the home's planning"},{"left":"Two offers in different cities","right":"Compare both and choose together"},{"left":"Her role needs work travel","right":"Cover the home so she can go"}],"relearn":"Match each clash to its fair move: own the evening, alternate leave, take over planning, choose together, cover the home.","cat":"two-careers"},
  {"id":"ep-1412","type":"match","persona":"any","source":"helping vs owning careers match","hook":"Match each 'helping' line to the 'owning' upgrade for two careers.","pairs":[{"left":"\"Tell me what to do this crunch\"","right":"\"I'll run the home this month\""},{"left":"\"I'll allow the job for now\"","right":"\"Your work is yours; I back it\""},{"left":"\"You sort the rest after your call\"","right":"\"I've got the whole evening\""},{"left":"\"Sick days are your thing\"","right":"\"We alternate the sick leave\""},{"left":"\"My paycheck buys me out\"","right":"\"My fair home share stands\""}],"relearn":"Each helping line upgrades to owning: run the home, back her work, own the evening, alternate leave, keep your share.","cat":"two-careers"},
  {"id":"ep-1413","type":"match","persona":"any","source":"belittling vs respecting match","hook":"Match each belittling phrase to the respectful one.","pairs":[{"left":"\"It's just a hobby\"","right":"\"It's your real career\""},{"left":"\"Get a proper job\"","right":"\"A lean month is still your work\""},{"left":"\"Your meetings can wait\"","right":"\"Your work time is real too\""},{"left":"\"Yours is the backup income\"","right":"\"Both incomes count equally\""},{"left":"\"Skip your work event\"","right":"\"Your work events matter\""}],"relearn":"Each belittling phrase has a respectful version that treats a partner's work as real and equal.","cat":"two-careers"},
  {"id":"ep-1414","type":"match","persona":"any","source":"life change to renegotiate match","hook":"Match each career change to who should help decide it.","pairs":[{"left":"A study sabbatical comes up","right":"Whoever's turn it is, decided together"},{"left":"A risky startup leap","right":"Both partners weighing the risk"},{"left":"A baby is on the way","right":"A joint plan from real options"},{"left":"A posting abroad","right":"Both careers weighed as a team"},{"left":"A promotion with longer hours","right":"A home rebalance agreed by both"}],"relearn":"Every big career change is a joint decision: take turns, weigh together, plan jointly, decide as a team, rebalance together.","cat":"two-careers"},
  {"id":"ep-1415","type":"match","persona":"any","source":"who flexes match","hook":"Match each fair signal to what it shows about two careers.","pairs":[{"left":"They take turns moving cities","right":"Neither career is the default to drop"},{"left":"Both block evenings to up-skill","right":"Both get time to grow"},{"left":"Wins are celebrated equally","right":"Both careers matter to the family"},{"left":"Leave is alternated","right":"Neither job always yields"},{"left":"Capacity, not pay, sets the split","right":"Money doesn't buy out the home"}],"relearn":"Fair signals show the principle: no default career to drop, both grow, both matter, neither yields, no buyout by pay.","cat":"two-careers"},
  {"id":"ep-1416","type":"match","persona":"any","source":"label to meaning match","hook":"Match each loaded label to what it really does to her career.","pairs":[{"left":"'Flexible' career","right":"Used to load the whole home on her"},{"left":"'Pocket money' salary","right":"Demotes her income to optional"},{"left":"'Backup' job","right":"Treats her work as second-class"},{"left":"'Letting' her work","right":"Frames her career as his to grant"},{"left":"'Her department' (the home)","right":"Hands her a second unpaid shift"}],"relearn":"Each loaded label quietly downgrades her career; naming the label is the first step to dropping it.","cat":"two-careers"},
];

